/* QuantEdge — Learn page content (three languages): what each Analysis Lab analysis computes.
 * Every formula and input here describes the lab_*.py code; change both together. Loaded on demand by learn_ui.js. */
var QE_LEARN = {"cards":[{"id":"cycle_compare","number":1,"group":"fundamental","group_label":"Fundamentals","title":"Sector / cycle comparison","next":["crisis","earnings_quality","comps"],"en":{"question":"Which of these companies keeps its operating margin best through good and bad years?","idea":"Cyclical industries (steel, chemicals, cars) earn a lot in boom years and little in busts. This analysis puts 2 to 5 companies side by side and tracks the share of each dollar of sales left as operating profit over the last five fiscal years. It then asks three questions: who earns the most on average, who holds up best in its worst year, and whose margin moves around the least.","formulas":[{"name":"Operating margin (each fiscal year)","expr":"Operating margin = EBIT ÷ Revenue × 100","where":[["EBIT","earnings before interest and taxes: reported operating income; if the company reports none, pre-tax income + interest expense (USD millions)"],["Revenue","annual sales (USD millions)"],["Operating margin","percent"]]},{"name":"Average, worst and best","expr":"Average = Σ margins ÷ number of years with data; Worst = min(margins); Best = max(margins)","where":[["margins","the yearly operating margins in the 5-year window, skipping years with missing data (%)"]]},{"name":"Volatility","expr":"Volatility = √( Σ (margin − average)² ÷ N )","where":[["N","number of years with a margin (at least 2 needed)"],["Volatility","population standard deviation, in percentage points"]]},{"name":"Revenue growth per year (CAGR)","expr":"CAGR = (Last revenue ÷ First revenue)^(1 ÷ (n − 1)) − 1","where":[["First, Last revenue","the oldest and newest years this company has inside the window"],["n","number of years the company has in the window"],["CAGR","compound annual growth rate, percent; blank if either revenue is not positive"]]}],"data":[["Revenue","10-K income statement (XBRL us-gaap:RevenueFromContractWithCustomerExcludingAssessedTax, else …IncludingAssessedTax, Revenues, SalesRevenueNet or RevenuesNetOfInterestExpense); annual periods only"],["Operating income","10-K income statement (us-gaap:OperatingIncomeLoss)"],["Pre-tax income and interest expense (fallback)","10-K income statement (us-gaap:IncomeLossFromContinuingOperationsBeforeIncomeTaxes… and InterestExpense or a similar interest tag), used only when operating income is missing"],["Fiscal year ends","dates of the 10-K (or 20-F/40-F) annual periods in SEC companyfacts; foreign filers are converted to US dollars at the year-end rate"]],"steps":["Read up to six years of annual SEC data for each company and keep the five most recent fiscal-year labels found across all of them.","For each company and year compute operating margin = EBIT ÷ revenue; if operating income is not reported, use pre-tax income + interest expense and show a warning.","Per company, find the latest, average, worst (with its year) and best margin, and the population standard deviation of the yearly margins.","Compute revenue CAGR between the first and last year the company has in the window.","Report who has the highest average margin, the highest worst-year margin, and the lowest volatility, and draw the margins as lines."],"example":"Example company: revenue and EBIT for three years are 1,000 and 150, 800 and 40, 1,200 and 240 (USD millions). Margins: 150 ÷ 1,000 = 15%, 40 ÷ 800 = 5%, 240 ÷ 1,200 = 20%. Average = (15 + 5 + 20) ÷ 3 ≈ 13.3%. Worst year = 5%, best = 20%. Volatility = √(((15 − 13.3)² + (5 − 13.3)² + (20 − 13.3)²) ÷ 3) ≈ √38.9 ≈ 6.2 points. Revenue CAGR = (1,200 ÷ 1,000)^(1 ÷ 2) − 1 ≈ 9.5% a year.","read":["A high average margin suggests the company keeps more of each sale as operating profit across the cycle.","A high worst-year margin suggests resilience: even in the bad year it still earned something on its sales.","Low volatility (in percentage points) means steadier margins; a company with a lower average but much lower volatility can be the more predictable one.","Revenue CAGR shows whether the company grew its sales at the same time, which margins alone cannot tell you."],"limits":["Fiscal years are labelled by the calendar year in which they end, and companies end their years in different months, so the same label can cover slightly different periods.","When operating income is not reported, EBIT is rebuilt as pre-tax income + interest expense, which can include one-off gains or losses; the app warns when this happens.","Five years may not contain a full boom and bust, and a margin does not show the size of the company or how much debt it carries.","Past resilience describes history; it does not tell you how a company will behave in the next downturn."]},"tr":{"question":"Bu şirketlerden hangisi iyi ve kötü yıllar boyunca faaliyet marjını en iyi koruyor?","idea":"Döngüsel sektörler (çelik, kimya, otomotiv) patlama yıllarında çok, durgunlukta az kazanır. Bu analiz 2 ile 5 şirketi yan yana koyar ve son beş mali yılda her 1 dolarlık satıştan faaliyet kârı olarak ne kadar kaldığını izler. Sonra üç soru sorar: ortalamada kim en çok kazanıyor, en kötü yılında kim en iyi dayanıyor ve kimin marjı en az oynuyor.","formulas":[{"name":"Faaliyet marjı (her mali yıl)","expr":"Faaliyet marjı = FVÖK ÷ Gelir × 100","where":[["FVÖK (EBIT)","faiz ve vergi öncesi kâr: raporlanan faaliyet kârı; şirket raporlamıyorsa vergi öncesi kâr + faiz gideri (milyon USD)"],["Gelir","yıllık satışlar (milyon USD)"],["Faaliyet marjı","yüzde"]]},{"name":"Ortalama, en kötü ve en iyi","expr":"Ortalama = Σ marjlar ÷ verisi olan yıl sayısı; En kötü = min(marjlar); En iyi = maks(marjlar)","where":[["marjlar","5 yıllık penceredeki yıllık faaliyet marjları, verisi eksik yıllar atlanır (%)"]]},{"name":"Oynaklık","expr":"Oynaklık = √( Σ (marj − ortalama)² ÷ N )","where":[["N","marjı olan yıl sayısı (en az 2 gerekir)"],["Oynaklık","anakütle standart sapması, yüzde puan"]]},{"name":"Yıllık gelir büyümesi (CAGR)","expr":"CAGR = (Son gelir ÷ İlk gelir)^(1 ÷ (n − 1)) − 1","where":[["İlk, Son gelir","şirketin pencere içindeki en eski ve en yeni yılı"],["n","şirketin pencere içindeki yıl sayısı"],["CAGR","bileşik yıllık büyüme oranı, yüzde; gelirlerden biri pozitif değilse boş"]]}],"data":[["Gelir","10-K gelir tablosu (XBRL us-gaap:RevenueFromContractWithCustomerExcludingAssessedTax, yoksa …IncludingAssessedTax, Revenues, SalesRevenueNet veya RevenuesNetOfInterestExpense); sadece yıllık dönemler"],["Faaliyet kârı","10-K gelir tablosu (us-gaap:OperatingIncomeLoss)"],["Vergi öncesi kâr ve faiz gideri (yedek)","10-K gelir tablosu (us-gaap:IncomeLossFromContinuingOperationsBeforeIncomeTaxes… ve InterestExpense ya da benzeri bir faiz etiketi); sadece faaliyet kârı yoksa kullanılır"],["Mali yıl sonları","SEC companyfacts içindeki 10-K (veya 20-F/40-F) yıllık dönem tarihleri; yabancı şirketler yıl sonu kuruyla dolara çevrilir"]],"steps":["Her şirket için en fazla altı yıllık SEC yıllık verisini yükle ve hepsinde bulunan en yeni beş mali yıl etiketini tut.","Her şirket ve yıl için faaliyet marjı = FVÖK ÷ gelir hesapla; faaliyet kârı raporlanmıyorsa vergi öncesi kâr + faiz giderini kullan ve uyarı göster.","Her şirket için son, ortalama, en kötü (yılıyla birlikte) ve en iyi marjı ve yıllık marjların anakütle standart sapmasını bul.","Şirketin pencerede bulunan ilk ve son yılı arasında gelir CAGR'ını hesapla.","En yüksek ortalama marjı, en yüksek en-kötü-yıl marjını ve en düşük oynaklığı olan şirketi raporla ve marjları çizgi grafikte göster."],"example":"Örnek şirket: üç yılın gelir ve FVÖK'ü 1.000 ve 150, 800 ve 40, 1.200 ve 240 (milyon USD). Marjlar: 150 ÷ 1.000 = %15, 40 ÷ 800 = %5, 240 ÷ 1.200 = %20. Ortalama = (15 + 5 + 20) ÷ 3 ≈ %13,3. En kötü yıl = %5, en iyi = %20. Oynaklık = √(((15 − 13,3)² + (5 − 13,3)² + (20 − 13,3)²) ÷ 3) ≈ √38,9 ≈ 6,2 puan. Gelir CAGR = (1.200 ÷ 1.000)^(1 ÷ 2) − 1 ≈ yılda %9,5.","read":["Yüksek ortalama marj, şirketin döngü boyunca her satıştan daha fazlasını faaliyet kârı olarak tuttuğunu düşündürür.","Yüksek en-kötü-yıl marjı dayanıklılığa işaret eder: kötü yılda bile satışlarından bir şey kazanmış.","Düşük oynaklık (yüzde puan) daha istikrarlı marj demektir; ortalaması biraz düşük ama oynaklığı çok daha az olan şirket daha öngörülebilir olabilir.","Gelir CAGR'ı, şirketin aynı dönemde satışlarını büyütüp büyütmediğini gösterir; bunu marjlar tek başına söylemez."],"limits":["Mali yıllar bittikleri takvim yılıyla etiketlenir ve şirketler yıllarını farklı aylarda kapatır; aynı etiket biraz farklı dönemleri kapsayabilir.","Faaliyet kârı raporlanmadığında FVÖK, vergi öncesi kâr + faiz gideri olarak yeniden kurulur; bu tek seferlik kazanç veya kayıpları içerebilir. Uygulama bu durumda uyarı verir.","Beş yıl tam bir yükseliş ve düşüş döngüsünü içermeyebilir; marj, şirketin büyüklüğünü veya ne kadar borç taşıdığını göstermez.","Geçmişteki dayanıklılık tarihi anlatır; şirketin bir sonraki durgunlukta nasıl davranacağını söylemez."]},"es":{"question":"¿Cuál de estas empresas mantiene mejor su margen operativo en los años buenos y en los malos?","idea":"Los sectores cíclicos (acero, química, automóviles) ganan mucho en los años de auge y poco en las crisis. Este análisis pone de 2 a 5 empresas lado a lado y sigue, durante los últimos cinco años fiscales, qué parte de cada dólar de ventas queda como beneficio operativo. Luego hace tres preguntas: quién gana más en promedio, quién aguanta mejor en su peor año y cuyo margen se mueve menos.","formulas":[{"name":"Margen operativo (cada año fiscal)","expr":"Margen operativo = EBIT ÷ Ingresos × 100","where":[["EBIT","beneficio antes de intereses e impuestos: el resultado operativo publicado; si la empresa no lo publica, beneficio antes de impuestos + gasto por intereses (millones de USD)"],["Ingresos","ventas anuales (millones de USD)"],["Margen operativo","porcentaje"]]},{"name":"Promedio, peor y mejor","expr":"Promedio = Σ márgenes ÷ número de años con datos; Peor = mín(márgenes); Mejor = máx(márgenes)","where":[["márgenes","los márgenes operativos anuales de la ventana de 5 años, omitiendo los años sin datos (%)"]]},{"name":"Volatilidad","expr":"Volatilidad = √( Σ (margen − promedio)² ÷ N )","where":[["N","número de años con margen (se necesitan al menos 2)"],["Volatilidad","desviación típica poblacional, en puntos porcentuales"]]},{"name":"Crecimiento anual de ingresos (CAGR)","expr":"CAGR = (Ingresos finales ÷ Ingresos iniciales)^(1 ÷ (n − 1)) − 1","where":[["Ingresos iniciales, finales","el año más antiguo y el más reciente que la empresa tiene dentro de la ventana"],["n","número de años de la empresa en la ventana"],["CAGR","tasa de crecimiento anual compuesta, porcentaje; vacía si alguno de los ingresos no es positivo"]]}],"data":[["Ingresos","cuenta de resultados del 10-K (XBRL us-gaap:RevenueFromContractWithCustomerExcludingAssessedTax, o …IncludingAssessedTax, Revenues, SalesRevenueNet o RevenuesNetOfInterestExpense); solo periodos anuales"],["Resultado operativo","cuenta de resultados del 10-K (us-gaap:OperatingIncomeLoss)"],["Beneficio antes de impuestos y gasto por intereses (alternativa)","cuenta de resultados del 10-K (us-gaap:IncomeLossFromContinuingOperationsBeforeIncomeTaxes… e InterestExpense u otra etiqueta de intereses similar); solo se usan si falta el resultado operativo"],["Cierres del año fiscal","fechas de los periodos anuales del 10-K (o 20-F/40-F) en SEC companyfacts; las empresas extranjeras se convierten a dólares al tipo de cierre de año"]],"steps":["Cargar hasta seis años de datos anuales de la SEC de cada empresa y quedarse con las cinco etiquetas de año fiscal más recientes encontradas entre todas.","Para cada empresa y año calcular margen operativo = EBIT ÷ ingresos; si no se publica el resultado operativo, usar beneficio antes de impuestos + gasto por intereses y mostrar un aviso.","Para cada empresa, hallar el margen más reciente, el promedio, el peor (con su año) y el mejor, y la desviación típica poblacional de los márgenes anuales.","Calcular el CAGR de los ingresos entre el primer y el último año que la empresa tiene en la ventana.","Indicar quién tiene el mayor margen promedio, el mayor margen en su peor año y la menor volatilidad, y dibujar los márgenes como líneas."],"example":"Empresa de ejemplo: ingresos y EBIT de tres años: 1.000 y 150, 800 y 40, 1.200 y 240 (millones de USD). Márgenes: 150 ÷ 1.000 = 15 %, 40 ÷ 800 = 5 %, 240 ÷ 1.200 = 20 %. Promedio = (15 + 5 + 20) ÷ 3 ≈ 13,3 %. Peor año = 5 %, mejor = 20 %. Volatilidad = √(((15 − 13,3)² + (5 − 13,3)² + (20 − 13,3)²) ÷ 3) ≈ √38,9 ≈ 6,2 puntos. CAGR de ingresos = (1.200 ÷ 1.000)^(1 ÷ 2) − 1 ≈ 9,5 % al año.","read":["Un margen promedio alto sugiere que la empresa conserva más de cada venta como beneficio operativo a lo largo del ciclo.","Un margen alto en el peor año sugiere resistencia: incluso en el año malo siguió ganando algo con sus ventas.","Una volatilidad baja (en puntos porcentuales) significa márgenes más estables; una empresa con un promedio algo menor pero mucha menos volatilidad puede ser la más predecible.","El CAGR de ingresos muestra si la empresa hizo crecer sus ventas al mismo tiempo, algo que los márgenes solos no te dicen."],"limits":["Los años fiscales se etiquetan con el año natural en que terminan, y las empresas cierran en meses distintos, así que la misma etiqueta puede cubrir periodos algo diferentes.","Cuando no se publica el resultado operativo, el EBIT se reconstruye como beneficio antes de impuestos + gasto por intereses, que puede incluir ganancias o pérdidas puntuales; la app avisa cuando ocurre.","Cinco años pueden no contener un ciclo completo de auge y caída, y un margen no muestra el tamaño de la empresa ni cuánta deuda tiene.","La resistencia pasada describe la historia; no te dice cómo se comportará la empresa en la próxima crisis."]}},{"id":"earnings_quality","number":2,"group":"fundamental","group_label":"Fundamentals","title":"Earnings quality","next":["piotroski","capital_allocation","cash_cycle"],"en":{"question":"Does the profit a company reports actually turn into cash?","idea":"Net income follows accounting rules: a sale counts as soon as it is made, even if the customer has not paid yet. Operating cash flow counts only the cash that really came in and went out. If profit keeps running far ahead of cash, part of that profit is still only on paper, so the analysis compares the two and raises warning flags.","formulas":[{"name":"Cash conversion","expr":"Cash conversion = CFO ÷ Net income (only in years with net income > 0)","where":[["CFO","cash flow from operations, operating cash flow (USD millions)"],["Net income","profit after all costs and taxes (USD millions)"],["Cash conversion","multiple: 1.0× means cash equals profit"]]},{"name":"Average cash conversion","expr":"Average = Σ (CFO ÷ Net income) ÷ number of profitable years","where":[["profitable years","years with net income > 0 among the up to six fiscal years loaded"]]},{"name":"Accruals ratio (latest year)","expr":"Accruals ratio = (Net income − CFO) ÷ Average total assets × 100","where":[["Average total assets","(total assets at the start of the year + at the end) ÷ 2; the year-end figure alone if no prior year"],["Accruals ratio","percent; positive means profit exceeded cash"]]},{"name":"FCF to net income (latest year)","expr":"FCF ÷ Net income, where FCF = CFO − Capital expenditure","where":[["FCF","free cash flow: operating cash left after buying property, plant and equipment (USD millions)"]]}],"data":[["Net income","10-K income statement (XBRL us-gaap:NetIncomeLoss, else ProfitLoss)"],["Operating cash flow (CFO)","10-K cash-flow statement (us-gaap:NetCashProvidedByUsedInOperatingActivities)"],["Capital expenditure","10-K cash-flow statement (us-gaap:PaymentsToAcquirePropertyPlantAndEquipment, else PaymentsToAcquireProductiveAssets)"],["Total assets","10-K balance sheet at each fiscal year end (us-gaap:Assets)"]],"steps":["Read up to six fiscal years of annual SEC data for each company (1 to 8 companies).","For every year with positive net income, compute CFO ÷ net income, and average these values; loss years are skipped.","For the latest year, compute the accruals ratio = (net income − CFO) ÷ average total assets, and FCF ÷ net income.","Raise watch flags: accruals ratio above 10%; cash conversion below 0.8 in at least 2 of the last 3 profitable years; or a profit while operating cash flow is negative.","Show a table and a bar chart of average CFO as a percent of net income."],"example":"Example company: net income 100, operating cash flow 70, capital expenditure 30, total assets 400 at the start of the year and 600 at the end (USD millions). Cash conversion = 70 ÷ 100 = 0.7×. Average assets = (400 + 600) ÷ 2 = 500. Accruals ratio = (100 − 70) ÷ 500 = 0.06 = 6%, below the 10% flag. FCF = 70 − 30 = 40, so FCF ÷ net income = 0.4×.","read":["Cash conversion around or above 1.0× suggests profit is backed by cash; well below 1.0× year after year suggests profit is running ahead of cash.","A positive accruals ratio means profit was higher than operating cash; above 10% of assets the app flags it, because a large part of the profit has not turned into cash yet.","A profit with negative operating cash flow is the strongest warning sign here: the business reported earnings but used cash.","FCF ÷ net income shows how much of the profit is left after the investment the business needs; growing companies that invest heavily can show low values for good reasons."],"limits":["In loss years the cash-to-profit ratios are not computed, so a company that loses money often has few data points.","The '2 of the last 3 years' flag looks at the last three profitable years, which can skip loss years in between.","A gap between profit and cash is not proof of manipulation: fast growth (more receivables and inventory) or timing of tax payments can cause it.","Only annual figures are used, and one big payment or collection near the year end can move a single year a lot."]},"tr":{"question":"Şirketin açıkladığı kâr gerçekten nakde dönüşüyor mu?","idea":"Net kâr muhasebe kurallarına göre hesaplanır: müşteri henüz ödemese bile satış yapıldığı anda kâra yazılır. İşletme nakit akışı ise sadece gerçekten giren ve çıkan nakdi sayar. Kâr sürekli nakdin çok önünde gidiyorsa kârın bir kısmı hâlâ kâğıt üzerindedir; bu yüzden analiz ikisini karşılaştırır ve dikkat işaretleri verir.","formulas":[{"name":"Nakit dönüşümü","expr":"Nakit dönüşümü = İNA ÷ Net kâr (sadece net kâr > 0 olan yıllarda)","where":[["İNA (CFO)","işletme faaliyetlerinden nakit akışı (milyon USD)"],["Net kâr","tüm giderler ve vergiler sonrası kâr (milyon USD)"],["Nakit dönüşümü","kat: 1,0× nakdin kâra eşit olduğu anlamına gelir"]]},{"name":"Ortalama nakit dönüşümü","expr":"Ortalama = Σ (İNA ÷ Net kâr) ÷ kârlı yıl sayısı","where":[["kârlı yıllar","yüklenen en fazla altı mali yıl içinde net kârı > 0 olan yıllar"]]},{"name":"Tahakkuk oranı (son yıl)","expr":"Tahakkuk oranı = (Net kâr − İNA) ÷ Ortalama toplam varlık × 100","where":[["Ortalama toplam varlık","(yıl başı toplam varlık + yıl sonu) ÷ 2; önceki yıl yoksa sadece yıl sonu"],["Tahakkuk oranı","yüzde; pozitifse kâr nakdi aşmış demektir"]]},{"name":"SNA / net kâr (son yıl)","expr":"SNA ÷ Net kâr, burada SNA = İNA − Yatırım harcaması","where":[["SNA (FCF)","serbest nakit akışı: maddi duran varlık alımından sonra kalan işletme nakdi (milyon USD)"]]}],"data":[["Net kâr","10-K gelir tablosu (XBRL us-gaap:NetIncomeLoss, yoksa ProfitLoss)"],["İşletme nakit akışı (İNA)","10-K nakit akış tablosu (us-gaap:NetCashProvidedByUsedInOperatingActivities)"],["Yatırım harcaması","10-K nakit akış tablosu (us-gaap:PaymentsToAcquirePropertyPlantAndEquipment, yoksa PaymentsToAcquireProductiveAssets)"],["Toplam varlık","her mali yıl sonundaki 10-K bilançosu (us-gaap:Assets)"]],"steps":["Her şirket için (1 ile 8 şirket) en fazla altı mali yıllık SEC yıllık verisini yükle.","Net kârı pozitif olan her yıl için İNA ÷ net kâr hesapla ve bunların ortalamasını al; zarar yılları atlanır.","Son yıl için tahakkuk oranı = (net kâr − İNA) ÷ ortalama toplam varlık ve SNA ÷ net kâr hesapla.","Dikkat işaretleri ver: tahakkuk oranı %10'un üstünde; son 3 kârlı yılın en az 2'sinde nakit dönüşümü 0,8'in altında; ya da kâr varken işletme nakit akışı negatif.","Bir tablo ve ortalama İNA'nın net kâra yüzde oranını gösteren bir çubuk grafik göster."],"example":"Örnek şirket: net kâr 100, işletme nakit akışı 70, yatırım harcaması 30, toplam varlık yıl başında 400, yıl sonunda 600 (milyon USD). Nakit dönüşümü = 70 ÷ 100 = 0,7×. Ortalama varlık = (400 + 600) ÷ 2 = 500. Tahakkuk oranı = (100 − 70) ÷ 500 = 0,06 = %6, yani %10 sınırının altında. SNA = 70 − 30 = 40, dolayısıyla SNA ÷ net kâr = 0,4×.","read":["1,0× civarı veya üstü nakit dönüşümü kârın nakitle desteklendiğini düşündürür; yıllarca 1,0×'in çok altında kalması kârın nakdin önünde gittiğini düşündürür.","Pozitif tahakkuk oranı kârın işletme nakdinden yüksek olduğunu gösterir; varlıkların %10'unu aşarsa uygulama işaretler, çünkü kârın büyük kısmı henüz nakde dönmemiştir.","Kâr varken işletme nakit akışının negatif olması buradaki en güçlü uyarıdır: şirket kâr açıklamış ama nakit harcamış.","SNA ÷ net kâr, işin ihtiyaç duyduğu yatırımdan sonra kârın ne kadarının kaldığını gösterir; çok yatırım yapan büyüyen şirketlerde haklı nedenlerle düşük çıkabilir."],"limits":["Zarar yıllarında nakit/kâr oranları hesaplanmaz; sık zarar eden bir şirkette az veri noktası olur.","'Son 3 yılın 2'si' işareti son üç kârlı yıla bakar; aradaki zarar yıllarını atlayabilir.","Kârla nakit arasındaki fark manipülasyon kanıtı değildir: hızlı büyüme (daha fazla alacak ve stok) veya vergi ödemelerinin zamanlaması da buna yol açabilir.","Sadece yıllık rakamlar kullanılır; yıl sonuna yakın tek bir büyük ödeme veya tahsilat bir yılı çok oynatabilir."]},"es":{"question":"¿El beneficio que publica la empresa se convierte de verdad en efectivo?","idea":"El beneficio neto sigue reglas contables: una venta cuenta en cuanto se hace, aunque el cliente aún no haya pagado. El flujo de caja operativo cuenta solo el efectivo que realmente entró y salió. Si el beneficio va siempre muy por delante del efectivo, parte de ese beneficio sigue solo en papel; por eso el análisis compara ambos y muestra señales de alerta.","formulas":[{"name":"Conversión en caja","expr":"Conversión en caja = FCO ÷ Beneficio neto (solo en años con beneficio neto > 0)","where":[["FCO (CFO)","flujo de caja de las operaciones (millones de USD)"],["Beneficio neto","beneficio tras todos los costes e impuestos (millones de USD)"],["Conversión en caja","múltiplo: 1,0× significa que el efectivo iguala al beneficio"]]},{"name":"Conversión en caja promedio","expr":"Promedio = Σ (FCO ÷ Beneficio neto) ÷ número de años con beneficio","where":[["años con beneficio","años con beneficio neto > 0 entre los hasta seis años fiscales cargados"]]},{"name":"Ratio de devengos (último año)","expr":"Ratio de devengos = (Beneficio neto − FCO) ÷ Activo total promedio × 100","where":[["Activo total promedio","(activo total al inicio del año + al final) ÷ 2; solo el de cierre si no hay año anterior"],["Ratio de devengos","porcentaje; positivo significa que el beneficio superó al efectivo"]]},{"name":"FCF sobre beneficio neto (último año)","expr":"FCF ÷ Beneficio neto, donde FCF = FCO − Inversión en capital (capex)","where":[["FCF","flujo de caja libre: el efectivo operativo que queda tras comprar inmuebles, planta y equipo (millones de USD)"]]}],"data":[["Beneficio neto","cuenta de resultados del 10-K (XBRL us-gaap:NetIncomeLoss, o ProfitLoss)"],["Flujo de caja operativo (FCO)","estado de flujos de efectivo del 10-K (us-gaap:NetCashProvidedByUsedInOperatingActivities)"],["Inversión en capital (capex)","estado de flujos de efectivo del 10-K (us-gaap:PaymentsToAcquirePropertyPlantAndEquipment, o PaymentsToAcquireProductiveAssets)"],["Activo total","balance del 10-K en cada cierre fiscal (us-gaap:Assets)"]],"steps":["Cargar hasta seis años fiscales de datos anuales de la SEC de cada empresa (de 1 a 8 empresas).","Para cada año con beneficio neto positivo, calcular FCO ÷ beneficio neto y promediar esos valores; los años con pérdidas se omiten.","Para el último año, calcular el ratio de devengos = (beneficio neto − FCO) ÷ activo total promedio, y FCF ÷ beneficio neto.","Mostrar alertas: ratio de devengos superior al 10 %; conversión en caja inferior a 0,8 en al menos 2 de los últimos 3 años con beneficio; o beneficio con flujo de caja operativo negativo.","Mostrar una tabla y un gráfico de barras del FCO promedio como porcentaje del beneficio neto."],"example":"Empresa de ejemplo: beneficio neto 100, flujo de caja operativo 70, capex 30, activo total 400 al inicio del año y 600 al final (millones de USD). Conversión en caja = 70 ÷ 100 = 0,7×. Activo promedio = (400 + 600) ÷ 2 = 500. Ratio de devengos = (100 − 70) ÷ 500 = 0,06 = 6 %, por debajo de la alerta del 10 %. FCF = 70 − 30 = 40, así que FCF ÷ beneficio neto = 0,4×.","read":["Una conversión en caja cercana o superior a 1,0× sugiere que el beneficio está respaldado por efectivo; muy por debajo de 1,0× año tras año sugiere que el beneficio va por delante del efectivo.","Un ratio de devengos positivo significa que el beneficio fue mayor que el efectivo operativo; por encima del 10 % del activo la app lo marca, porque gran parte del beneficio aún no se ha convertido en efectivo.","Un beneficio con flujo de caja operativo negativo es la alerta más fuerte aquí: la empresa publicó ganancias pero consumió efectivo.","FCF ÷ beneficio neto muestra cuánto del beneficio queda tras la inversión que el negocio necesita; las empresas en crecimiento que invierten mucho pueden mostrar valores bajos por buenas razones."],"limits":["En los años con pérdidas no se calculan los ratios efectivo/beneficio, así que una empresa que pierde dinero a menudo tiene pocos datos.","La alerta '2 de los últimos 3 años' mira los últimos tres años con beneficio, que pueden saltarse años con pérdidas intermedios.","Una diferencia entre beneficio y efectivo no prueba manipulación: un crecimiento rápido (más cuentas por cobrar e inventario) o el calendario de pagos de impuestos pueden causarla.","Solo se usan cifras anuales, y un gran pago o cobro cerca del cierre puede mover mucho un solo año."]}},{"id":"segments","number":3,"group":"fundamental","group_label":"Fundamentals","title":"Segment analysis","next":["quarterly","cycle_compare","dcf"],"en":{"question":"Which businesses, products or regions bring in the company's revenue, and which of them are growing?","idea":"A big company is often several businesses under one name. Its 10-K usually splits revenue by business segment, by product or service, and by geography, and tags those numbers in machine-readable XBRL. This analysis reads those tags from the latest 10-K, keeps only splits that really add up to total revenue, and shows each part's size, share and growth over the three years the filing covers.","formulas":[{"name":"Share of revenue","expr":"Share = Segment revenue ÷ Total revenue × 100 (latest fiscal year)","where":[["Segment revenue","revenue tagged for one member of the breakdown (USD millions)"],["Total revenue","the company's reported total revenue for the same year"],["Share","percent"]]},{"name":"Share change","expr":"Share change = Share (latest year) − Share (first year)","where":[["first year","the oldest of the (up to) three fiscal years in the 10-K"],["Share change","percentage points"]]},{"name":"Revenue growth per year","expr":"Growth = (Revenue latest ÷ Revenue first)^(1 ÷ (years − 1)) − 1","where":[["years","number of fiscal years in the filing, normally 3, so 2 growth periods"],["Growth","compound annual growth rate, percent"]]},{"name":"Segment operating margin","expr":"Segment margin = Segment operating income ÷ Segment revenue × 100 (latest year)","where":[["Segment operating income","operating income the company tags for that segment, by its own definition (USD millions)"]]}],"data":[["Segment, product and geographic revenue","the latest 10-K's own XBRL instance file on SEC EDGAR: revenue tags (us-gaap:RevenueFromContractWithCustomerExcludingAssessedTax, …IncludingAssessedTax, Revenues, SalesRevenueNet, RevenuesNetOfInterestExpense) with the dimension StatementBusinessSegmentsAxis, ProductOrServiceAxis or StatementGeographicalAxis"],["Total revenue","the same revenue tag in the same file with no dimension"],["Segment operating income","us-gaap:OperatingIncomeLoss in the same file on the same axis, when the company tags it"],["Segment names","the filing's label file (MetaLinks.json or the _lab.xml linkbase)"]],"steps":["Find the latest 10-K behind the company's latest annual revenue and download its XBRL instance and labels from SEC EDGAR (an SEC contact email is required; the result is cached per filing).","Keep only full-year revenue and operating-income facts that sit on exactly one of the three axes: business segments, products and services, or geography.","For each axis, find the largest set of lines (up to the 14 biggest) whose revenues add up to total revenue within ±1.5%; if two sets fit, prefer the one that also adds up in earlier years. Axes with no fitting set are not shown.","Try each revenue tag that has a total and keep the one that gives the most valid breakdowns.","For each line compute revenue per year, share of total, share change, growth per year, and, if tagged, segment operating income and margin.","Report the largest line, the fastest and slowest growers (among lines with at least 2% share), a share shift of 1 point or more, and the most profitable segment."],"example":"Example company: total revenue rose from 1,000 to 1,440 over three fiscal years (USD millions). Its Cloud segment went from 200 to 450. Latest share = 450 ÷ 1,440 ≈ 31.3%; first-year share = 200 ÷ 1,000 = 20%, so the share change is about +11.3 points. Growth = (450 ÷ 200)^(1 ÷ 2) − 1 = 1.5 − 1 = 50% a year. If Cloud's operating income is 135, its margin = 135 ÷ 450 = 30%.","read":["A line with a large share is where most of the revenue comes from today; a rising share shows where the mix is moving.","Growth per year shows momentum, but a fast-growing small line (the app ignores lines under 2% share for this) moves the total much less than a slow-growing big one.","Segment operating margins hint at which businesses are more profitable, within the company's own way of allocating costs.","Comparing the business, product and geography views can show, for example, whether growth comes from one product or from one region."],"limits":["Only one 10-K is read, so the history is at most three fiscal years; growth over two years can be noisy.","A breakdown is shown only if it adds up to total revenue within ±1.5%; partial or overlapping lists are dropped, and single-segment companies or untagged splits give no result.","Segment operating income follows the company's own definition; shared costs such as R&D or headquarters may be left unallocated, so segment margins can look higher than the company total.","If the company redefined its segments, earlier years in the filing are restated to the new definition, so they may not match older reports; filings without inline XBRL (before about 2019) are not supported."]},"tr":{"question":"Şirketin gelirini hangi iş kolları, ürünler veya bölgeler getiriyor ve hangileri büyüyor?","idea":"Büyük bir şirket çoğu zaman tek isim altında birkaç ayrı iştir. 10-K raporu genelde geliri iş kollarına (bölümlere), ürün ve hizmetlere ve coğrafyaya göre böler ve bu rakamları makinece okunabilir XBRL etiketleriyle işaretler. Bu analiz son 10-K'daki bu etiketleri okur, sadece toplam gelire gerçekten denk gelen kırılımları tutar ve her parçanın büyüklüğünü, payını ve raporun kapsadığı üç yıldaki büyümesini gösterir.","formulas":[{"name":"Gelir payı","expr":"Pay = Bölüm geliri ÷ Toplam gelir × 100 (son mali yıl)","where":[["Bölüm geliri","kırılımdaki tek bir kalem için etiketlenen gelir (milyon USD)"],["Toplam gelir","aynı yıl için şirketin raporladığı toplam gelir"],["Pay","yüzde"]]},{"name":"Pay değişimi","expr":"Pay değişimi = Pay (son yıl) − Pay (ilk yıl)","where":[["ilk yıl","10-K'daki (en fazla) üç mali yılın en eskisi"],["Pay değişimi","yüzde puan"]]},{"name":"Yıllık gelir büyümesi","expr":"Büyüme = (Son yıl geliri ÷ İlk yıl geliri)^(1 ÷ (yıl sayısı − 1)) − 1","where":[["yıl sayısı","rapordaki mali yıl sayısı, normalde 3, yani 2 büyüme dönemi"],["Büyüme","bileşik yıllık büyüme oranı, yüzde"]]},{"name":"Bölüm faaliyet marjı","expr":"Bölüm marjı = Bölüm faaliyet kârı ÷ Bölüm geliri × 100 (son yıl)","where":[["Bölüm faaliyet kârı","şirketin o bölüm için kendi tanımıyla etiketlediği faaliyet kârı (milyon USD)"]]}],"data":[["Bölüm, ürün ve coğrafya gelirleri","SEC EDGAR'daki son 10-K'nın kendi XBRL dosyası: StatementBusinessSegmentsAxis, ProductOrServiceAxis veya StatementGeographicalAxis boyutunu taşıyan gelir etiketleri (us-gaap:RevenueFromContractWithCustomerExcludingAssessedTax, …IncludingAssessedTax, Revenues, SalesRevenueNet, RevenuesNetOfInterestExpense)"],["Toplam gelir","aynı dosyada, boyutsuz aynı gelir etiketi"],["Bölüm faaliyet kârı","şirket etiketlemişse aynı dosyada aynı eksende us-gaap:OperatingIncomeLoss"],["Bölüm adları","raporun etiket dosyası (MetaLinks.json veya _lab.xml)"]],"steps":["Şirketin son yıllık gelirinin geldiği 10-K'yı bul ve XBRL dosyasıyla etiketlerini SEC EDGAR'dan indir (SEC iletişim e-postası gerekir; sonuç her rapor için saklanır).","Sadece üç eksenden tam olarak birinde duran tam yıllık gelir ve faaliyet kârı verilerini tut: iş kolları, ürün ve hizmetler veya coğrafya.","Her eksen için gelirleri toplam gelire ±%1,5 içinde denk gelen en büyük kalem kümesini bul (en büyük 14 kaleme kadar); iki küme uyarsa önceki yıllarda da tutanı seç. Uyan küme yoksa o eksen gösterilmez.","Toplamı olan her gelir etiketini dene ve en çok geçerli kırılım vereni tut.","Her kalem için yıllara göre gelir, toplamdaki pay, pay değişimi, yıllık büyüme ve etiketlenmişse bölüm faaliyet kârı ile marjını hesapla.","En büyük kalemi, en hızlı ve en yavaş büyüyenleri (payı en az %2 olanlar arasında), 1 puan veya daha fazla pay kaymasını ve en kârlı bölümü raporla."],"example":"Örnek şirket: toplam gelir üç mali yılda 1.000'den 1.440'a çıktı (milyon USD). Bulut bölümü 200'den 450'ye çıktı. Son pay = 450 ÷ 1.440 ≈ %31,3; ilk yıl payı = 200 ÷ 1.000 = %20, yani pay değişimi yaklaşık +11,3 puan. Büyüme = (450 ÷ 200)^(1 ÷ 2) − 1 = 1,5 − 1 = yılda %50. Bulutun faaliyet kârı 135 ise marjı = 135 ÷ 450 = %30.","read":["Payı büyük olan kalem bugün gelirin çoğunun geldiği yerdir; artan pay, gelir karmasının nereye kaydığını gösterir.","Yıllık büyüme ivmeyi gösterir, ama hızlı büyüyen küçük bir kalem (uygulama bunun için payı %2'nin altındakileri dikkate almaz) toplamı yavaş büyüyen büyük bir kalemden çok daha az etkiler.","Bölüm faaliyet marjları, şirketin kendi gider dağıtım yöntemi içinde hangi işlerin daha kârlı olduğuna dair ipucu verir.","İş kolu, ürün ve coğrafya görünümlerini karşılaştırmak, örneğin büyümenin tek bir üründen mi yoksa tek bir bölgeden mi geldiğini gösterebilir."],"limits":["Sadece bir 10-K okunur; geçmiş en fazla üç mali yıldır ve iki yıllık büyüme gürültülü olabilir.","Bir kırılım ancak toplam gelire ±%1,5 içinde denk gelirse gösterilir; eksik veya iç içe listeler atılır, tek bölümlü şirketler veya etiketlenmemiş kırılımlar sonuç vermez.","Bölüm faaliyet kârı şirketin kendi tanımına göredir; Ar-Ge veya merkez gibi ortak giderler dağıtılmamış olabilir, bu yüzden bölüm marjları şirket toplamından yüksek görünebilir.","Şirket bölümlerini yeniden tanımladıysa rapordaki önceki yıllar yeni tanıma göre düzenlenmiştir ve eski raporlarla uyuşmayabilir; inline XBRL'i olmayan raporlar (yaklaşık 2019 öncesi) desteklenmez."]},"es":{"question":"¿Qué negocios, productos o regiones generan los ingresos de la empresa y cuáles están creciendo?","idea":"Una gran empresa suele ser varios negocios bajo un mismo nombre. Su 10-K normalmente divide los ingresos por segmento de negocio, por producto o servicio y por geografía, y etiqueta esas cifras en XBRL legible por máquina. Este análisis lee esas etiquetas del último 10-K, se queda solo con los desgloses que de verdad suman los ingresos totales y muestra el tamaño, la cuota y el crecimiento de cada parte en los tres años que cubre el informe.","formulas":[{"name":"Cuota de ingresos","expr":"Cuota = Ingresos del segmento ÷ Ingresos totales × 100 (último año fiscal)","where":[["Ingresos del segmento","ingresos etiquetados para un miembro del desglose (millones de USD)"],["Ingresos totales","los ingresos totales publicados por la empresa para el mismo año"],["Cuota","porcentaje"]]},{"name":"Cambio de cuota","expr":"Cambio de cuota = Cuota (último año) − Cuota (primer año)","where":[["primer año","el más antiguo de los (hasta) tres años fiscales del 10-K"],["Cambio de cuota","puntos porcentuales"]]},{"name":"Crecimiento anual de ingresos","expr":"Crecimiento = (Ingresos último ÷ Ingresos primero)^(1 ÷ (años − 1)) − 1","where":[["años","número de años fiscales del informe, normalmente 3, es decir 2 periodos de crecimiento"],["Crecimiento","tasa de crecimiento anual compuesta, porcentaje"]]},{"name":"Margen operativo del segmento","expr":"Margen del segmento = Resultado operativo del segmento ÷ Ingresos del segmento × 100 (último año)","where":[["Resultado operativo del segmento","resultado operativo que la empresa etiqueta para ese segmento, según su propia definición (millones de USD)"]]}],"data":[["Ingresos por segmento, producto y geografía","el propio archivo XBRL del último 10-K en SEC EDGAR: etiquetas de ingresos (us-gaap:RevenueFromContractWithCustomerExcludingAssessedTax, …IncludingAssessedTax, Revenues, SalesRevenueNet, RevenuesNetOfInterestExpense) con la dimensión StatementBusinessSegmentsAxis, ProductOrServiceAxis o StatementGeographicalAxis"],["Ingresos totales","la misma etiqueta de ingresos en el mismo archivo, sin dimensión"],["Resultado operativo del segmento","us-gaap:OperatingIncomeLoss en el mismo archivo y el mismo eje, cuando la empresa lo etiqueta"],["Nombres de los segmentos","el archivo de etiquetas del informe (MetaLinks.json o el linkbase _lab.xml)"]],"steps":["Encontrar el último 10-K detrás de los ingresos anuales más recientes y descargar de SEC EDGAR su archivo XBRL y sus etiquetas (se necesita un email de contacto para la SEC; el resultado se guarda por informe).","Quedarse solo con los datos de ingresos y resultado operativo de año completo que estén en exactamente uno de los tres ejes: segmentos de negocio, productos y servicios, o geografía.","Para cada eje, buscar el mayor conjunto de líneas (hasta las 14 más grandes) cuyos ingresos sumen los ingresos totales con un margen de ±1,5 %; si encajan dos conjuntos, preferir el que también suma en años anteriores. Los ejes sin un conjunto válido no se muestran.","Probar cada etiqueta de ingresos que tenga un total y quedarse con la que da más desgloses válidos.","Para cada línea calcular ingresos por año, cuota del total, cambio de cuota, crecimiento anual y, si está etiquetado, resultado operativo y margen del segmento.","Indicar la línea más grande, la de mayor y menor crecimiento (entre las que tienen al menos un 2 % de cuota), un cambio de cuota de 1 punto o más y el segmento más rentable."],"example":"Empresa de ejemplo: los ingresos totales pasaron de 1.000 a 1.440 en tres años fiscales (millones de USD). Su segmento Nube pasó de 200 a 450. Cuota final = 450 ÷ 1.440 ≈ 31,3 %; cuota del primer año = 200 ÷ 1.000 = 20 %, así que el cambio de cuota es de unos +11,3 puntos. Crecimiento = (450 ÷ 200)^(1 ÷ 2) − 1 = 1,5 − 1 = 50 % al año. Si el resultado operativo de Nube es 135, su margen = 135 ÷ 450 = 30 %.","read":["Una línea con gran cuota es de donde viene hoy la mayor parte de los ingresos; una cuota creciente muestra hacia dónde se mueve la mezcla.","El crecimiento anual muestra el impulso, pero una línea pequeña que crece rápido (la app ignora para esto las líneas con menos del 2 % de cuota) mueve el total mucho menos que una grande que crece despacio.","Los márgenes operativos por segmento dan pistas sobre qué negocios son más rentables, dentro de la forma propia de la empresa de repartir costes.","Comparar las vistas por negocio, producto y geografía puede mostrar, por ejemplo, si el crecimiento viene de un producto o de una región."],"limits":["Solo se lee un 10-K, así que la historia es de tres años fiscales como máximo; el crecimiento en dos años puede ser ruidoso.","Un desglose solo se muestra si suma los ingresos totales con un margen de ±1,5 %; las listas parciales o solapadas se descartan, y las empresas de un solo segmento o los desgloses sin etiquetar no dan resultado.","El resultado operativo del segmento sigue la definición propia de la empresa; los costes compartidos como I+D o la sede pueden quedar sin repartir, así que los márgenes por segmento pueden parecer mayores que el total de la empresa.","Si la empresa redefinió sus segmentos, los años anteriores del informe están reexpresados con la nueva definición y pueden no coincidir con informes antiguos; los informes sin XBRL en línea (antes de 2019 aproximadamente) no están soportados."]}},{"id":"reverse_dcf","number":4,"group":"valuation","group_label":"Valuation","title":"Reverse DCF","next":["dcf","scenarios","comps"],"en":{"question":"What yearly revenue growth does today's market price already assume?","idea":"A normal DCF (discounted cash flow) starts from your guesses and gives a value. A reverse DCF runs it backwards: it takes the value the market puts on the whole business today and finds the growth rate that would justify it. You then judge whether that growth sounds easy, plausible or heroic.","formulas":[{"name":"Model enterprise value for a growth rate g","expr":"EV(g) = Σₜ₌₁¹⁰ R₀ × (1 + g)ᵗ × m ÷ (1 + WACC)ᵗ + [R₀ × (1 + g)¹⁰ × (1 + gT) × m ÷ (WACC − gT)] ÷ (1 + WACC)¹⁰","where":[["R₀","starting revenue: trailing twelve months (TTM) if available, else latest fiscal year, USD millions"],["g","constant annual revenue growth for 10 years (what we solve for), %"],["m","free-cash-flow margin, kept constant, %"],["WACC","weighted average cost of capital, the discount rate (default 9%)"],["gT","terminal (forever) growth after year 10 (default 3%)"],["t","year 1 to 10; cash arrives at the end of each year"]]},{"name":"Free-cash-flow margin (default)","expr":"m = average over the last 3 fiscal years of (CFO − capex − SBC) ÷ revenue","where":[["CFO","cash from operations, USD millions"],["capex","spending on property, plant and equipment, USD millions"],["SBC","stock-based compensation, taken out again because it is a real cost to shareholders"]]},{"name":"Today's enterprise value (the target)","expr":"EV = price × shares outstanding + debt − cash","where":[["EV","enterprise value: what the market pays for the whole business, USD millions"],["debt","long-term debt + current debt (latest 10-K)"],["cash","cash and cash equivalents (latest 10-K)"]]},{"name":"Implied growth","expr":"find g such that EV(g) = EV, by bisection between −50% and +150%","where":[["bisection","repeatedly halving the search interval (200 times) until the model value matches"]]}],"data":[["Share price","Yahoo Finance latest adjusted close (in a past-date run: the split-adjusted close on that day)"],["Shares outstanding","10-K/10-Q cover page (XBRL dei:EntityCommonStockSharesOutstanding), else diluted weighted average (us-gaap:WeightedAverageNumberOfDilutedSharesOutstanding); restated for later stock splits; divided by the ADR ratio if you enter one"],["Debt","latest 10-K balance sheet: us-gaap:LongTermDebtNoncurrent (else LongTermDebt) + LongTermDebtCurrent (else DebtCurrent / ShortTermBorrowings)"],["Cash","latest 10-K: us-gaap:CashAndCashEquivalentsAtCarryingValue"],["Revenue","TTM = sum of the last four 10-Q quarters (Q4 = annual − Q1 to Q3), else latest 10-K (us-gaap:RevenueFromContractWithCustomerExcludingAssessedTax, Revenues …)"],["CFO, capex, SBC","10-K cash-flow statement: us-gaap:NetCashProvidedByUsedInOperatingActivities, PaymentsToAcquirePropertyPlantAndEquipment, ShareBasedCompensation"],["WACC, terminal growth, margin","your inputs (defaults 9% and 3%; margin from history if blank)"]],"steps":["Compute today's enterprise value from price, shares, debt and cash.","Compute the free-cash-flow margin after stock-based pay as the 3-year average (or use your margin); stop if it is not positive.","Search for the single growth rate g that makes the 10-year model value equal today's EV.","Compare g with the company's own past revenue growth (compound annual growth over up to 5 years).","Show a grid: model EV at −5%, 0%, 5%, 10%, 15%, 20% and 30% growth, and how far each is from today's EV."],"example":"Example company: revenue 100, cash flow after capex and SBC 20, so m = 20%. Market value 380 + debt 40 − cash 20 = EV 400. WACC 9%, gT 3%. At g = 0% the model gives about 273, too low. At g = 5%: year-1 cash flow = 100 × 1.05 × 20% = 21; summing ten discounted years plus the discounted terminal value gives about 400. So today's price implies about 5% growth a year for 10 years, and year-10 revenue of about 100 × 1.05¹⁰ ≈ 163.","read":["Implied growth well above the company's past growth means the price assumes an acceleration; below it means the market expects a slowdown or doubts the margin.","Use the grid: if model EV rises steeply between growth rows, the price is very sensitive to the growth story.","\"No solution\" means no growth between −50% and +150% matches the price with these inputs; change the margin or WACC.","Implied growth is an assumption made visible, not a forecast."],"limits":["The answer moves a lot with WACC, terminal growth and margin; a 1-point change in WACC can change implied growth noticeably.","The margin is held constant for 10 years and growth is the same every year; real companies change both.","Cash flow is operating cash flow minus capex, which is already after interest paid, yet it is compared with enterprise value; for indebted firms this understates firm cash flow. Marketable securities are not counted as cash.","The code's on-screen note says FCF = CFO − capex, but the margin it actually uses also subtracts stock-based compensation. It needs a positive margin, so loss-making or cash-burning firms need a margin you type in."]},"tr":{"question":"Bugünkü piyasa fiyatı, yılda ne kadar gelir büyümesini zaten varsayıyor?","idea":"Normal bir DCF (indirgenmiş nakit akışı) senin tahminlerinle başlar ve bir değer verir. Ters DCF bunu tersinden çalıştırır: piyasanın bugün tüm işletmeye biçtiği değeri alır ve bu değeri haklı çıkaracak büyüme oranını bulur. Sonra o büyümenin kolay mı, makul mü, yoksa çok iddialı mı olduğuna sen karar verirsin.","formulas":[{"name":"Bir g büyüme oranı için model firma değeri","expr":"FD(g) = Σₜ₌₁¹⁰ R₀ × (1 + g)ᵗ × m ÷ (1 + WACC)ᵗ + [R₀ × (1 + g)¹⁰ × (1 + gT) × m ÷ (WACC − gT)] ÷ (1 + WACC)¹⁰","where":[["R₀","başlangıç geliri: varsa son 12 ay (TTM), yoksa son mali yıl, milyon USD"],["g","10 yıl boyunca sabit yıllık gelir büyümesi (aradığımız sayı), %"],["m","serbest nakit akışı marjı, sabit tutulur, %"],["WACC","ağırlıklı ortalama sermaye maliyeti, iskonto oranı (varsayılan %9)"],["gT","10. yıldan sonra sonsuza kadar süren uç (terminal) büyüme (varsayılan %3)"],["t","1’den 10’a yıl; nakit her yılın sonunda gelir"]]},{"name":"Serbest nakit akışı marjı (varsayılan)","expr":"m = son 3 mali yılın (CFO − yatırım harcaması − SBC) ÷ gelir ortalaması","where":[["CFO","işletme faaliyetlerinden nakit, milyon USD"],["yatırım harcaması (capex)","maddi duran varlık alımları, milyon USD"],["SBC","hisse bazlı ücretler; hissedar için gerçek bir maliyet olduğu için yeniden düşülür"]]},{"name":"Bugünkü firma değeri (hedef)","expr":"FD = fiyat × dolaşımdaki hisse + borç − nakit","where":[["FD (EV)","firma değeri: piyasanın tüm işletmeye ödediği tutar, milyon USD"],["borç","uzun vadeli borç + kısa vadeli borç (son 10-K)"],["nakit","nakit ve nakit benzerleri (son 10-K)"]]},{"name":"İma edilen büyüme","expr":"FD(g) = FD olacak g’yi bul; −%50 ile +%150 arasında ikiye bölme yöntemiyle","where":[["ikiye bölme","arama aralığını tekrar tekrar (200 kez) yarıya indirip model değerini piyasaya eşitlemek"]]}],"data":[["Hisse fiyatı","Yahoo Finance son düzeltilmiş kapanış (geçmiş tarihli çalıştırmada o günün bölünmeye göre düzeltilmiş kapanışı)"],["Dolaşımdaki hisse","10-K/10-Q kapak sayfası (XBRL dei:EntityCommonStockSharesOutstanding), yoksa seyreltilmiş ağırlıklı ortalama (us-gaap:WeightedAverageNumberOfDilutedSharesOutstanding); sonraki bölünmelere göre düzeltilir; ADR oranı girersen ona bölünür"],["Borç","son 10-K bilançosu: us-gaap:LongTermDebtNoncurrent (yoksa LongTermDebt) + LongTermDebtCurrent (yoksa DebtCurrent / ShortTermBorrowings)"],["Nakit","son 10-K: us-gaap:CashAndCashEquivalentsAtCarryingValue"],["Gelir","TTM = son dört 10-Q çeyreğinin toplamı (4. çeyrek = yıllık − ilk üç çeyrek), yoksa son 10-K (us-gaap:RevenueFromContractWithCustomerExcludingAssessedTax, Revenues …)"],["CFO, yatırım harcaması, SBC","10-K nakit akış tablosu: us-gaap:NetCashProvidedByUsedInOperatingActivities, PaymentsToAcquirePropertyPlantAndEquipment, ShareBasedCompensation"],["WACC, uç büyüme, marj","senin girdilerin (varsayılan %9 ve %3; marj boş bırakılırsa geçmişten)"]],"steps":["Fiyat, hisse sayısı, borç ve nakitten bugünkü firma değerini hesapla.","Hisse bazlı ücretler düşülmüş serbest nakit marjını 3 yıllık ortalama olarak bul (ya da senin marjını kullan); pozitif değilse dur.","10 yıllık model değerini bugünkü firma değerine eşitleyen tek g büyüme oranını ara.","g’yi şirketin kendi geçmiş gelir büyümesiyle (en fazla 5 yıllık yıllık bileşik büyüme) karşılaştır.","Tablo göster: −%5, %0, %5, %10, %15, %20 ve %30 büyümede model firma değeri ve bugünkü değerden farkı."],"example":"Örnek şirket: gelir 100, yatırım ve SBC sonrası nakit akışı 20, yani m = %20. Piyasa değeri 380 + borç 40 − nakit 20 = firma değeri 400. WACC %9, gT %3. g = %0’da model yaklaşık 273 verir, düşük kalır. g = %5’te: 1. yıl nakit akışı = 100 × 1,05 × %20 = 21; on yılın indirgenmiş toplamı ve indirgenmiş uç değer birlikte yaklaşık 400 eder. Yani bugünkü fiyat 10 yıl boyunca yılda yaklaşık %5 büyüme varsayıyor; 10. yıl geliri yaklaşık 100 × 1,05¹⁰ ≈ 163 olur.","read":["İma edilen büyüme şirketin geçmiş büyümesinin çok üstündeyse fiyat bir hızlanma varsayıyor; altındaysa piyasa yavaşlama bekliyor ya da marja güvenmiyor.","Tabloya bak: büyüme satırları arasında model değeri hızla artıyorsa fiyat, büyüme hikâyesine çok duyarlıdır.","“Çözüm yok” demek, bu girdilerle −%50 ile +%150 arasında hiçbir büyümenin fiyatı açıklamadığı demektir; marjı veya WACC’yi değiştir.","İma edilen büyüme görünür kılınmış bir varsayımdır, tahmin değildir."],"limits":["Sonuç WACC, uç büyüme ve marjla çok oynar; WACC’de 1 puanlık değişim ima edilen büyümeyi belirgin biçimde değiştirebilir.","Marj 10 yıl sabit, büyüme her yıl aynı tutulur; gerçek şirketlerde ikisi de değişir.","Nakit akışı işletme nakdi eksi yatırımdır, yani ödenen faizden sonradır; buna rağmen firma değeriyle karşılaştırılır. Borcu yüksek şirkette bu, firmanın nakit akışını olduğundan düşük gösterir. Menkul kıymetler nakde sayılmaz.","Ekrandaki not FCF = CFO − yatırım harcaması diyor, ama kodun kullandığı marjdan hisse bazlı ücretler de düşülüyor. Marj pozitif olmalı; zarar eden veya nakit yakan şirkette marjı kendin girmelisin."]},"es":{"question":"¿Qué crecimiento anual de ingresos da ya por hecho el precio de mercado de hoy?","idea":"Un DCF (flujo de caja descontado) normal parte de tus supuestos y da un valor. Un DCF inverso lo hace al revés: toma el valor que el mercado da hoy a toda la empresa y busca la tasa de crecimiento que lo justificaría. Después tú juzgas si ese crecimiento parece fácil, razonable o heroico.","formulas":[{"name":"Valor de empresa del modelo para un crecimiento g","expr":"EV(g) = Σₜ₌₁¹⁰ R₀ × (1 + g)ᵗ × m ÷ (1 + WACC)ᵗ + [R₀ × (1 + g)¹⁰ × (1 + gT) × m ÷ (WACC − gT)] ÷ (1 + WACC)¹⁰","where":[["R₀","ingresos iniciales: últimos doce meses (TTM) si existen, si no el último ejercicio, millones de USD"],["g","crecimiento anual constante de ingresos durante 10 años (lo que buscamos), %"],["m","margen de flujo de caja libre, constante, %"],["WACC","coste medio ponderado del capital, la tasa de descuento (por defecto 9%)"],["gT","crecimiento terminal (para siempre) después del año 10 (por defecto 3%)"],["t","año 1 a 10; el dinero llega al final de cada año"]]},{"name":"Margen de flujo de caja libre (por defecto)","expr":"m = media de los últimos 3 ejercicios de (CFO − capex − SBC) ÷ ingresos","where":[["CFO","flujo de caja de operaciones, millones de USD"],["capex","inversión en inmovilizado material, millones de USD"],["SBC","remuneración en acciones; se vuelve a restar porque es un coste real para el accionista"]]},{"name":"Valor de empresa de hoy (el objetivo)","expr":"EV = precio × acciones en circulación + deuda − caja","where":[["EV","valor de empresa: lo que el mercado paga por todo el negocio, millones de USD"],["deuda","deuda a largo plazo + deuda a corto plazo (último 10-K)"],["caja","efectivo y equivalentes (último 10-K)"]]},{"name":"Crecimiento implícito","expr":"buscar g tal que EV(g) = EV, por bisección entre −50% y +150%","where":[["bisección","partir el intervalo de búsqueda por la mitad una y otra vez (200 veces) hasta que el valor del modelo coincide"]]}],"data":[["Precio de la acción","Yahoo Finance, último cierre ajustado (en una ejecución a fecha pasada: el cierre ajustado solo por splits de ese día)"],["Acciones en circulación","portada del 10-K/10-Q (XBRL dei:EntityCommonStockSharesOutstanding), si no la media ponderada diluida (us-gaap:WeightedAverageNumberOfDilutedSharesOutstanding); reexpresadas por splits posteriores; divididas por el ratio ADR si lo introduces"],["Deuda","balance del último 10-K: us-gaap:LongTermDebtNoncurrent (si no LongTermDebt) + LongTermDebtCurrent (si no DebtCurrent / ShortTermBorrowings)"],["Caja","último 10-K: us-gaap:CashAndCashEquivalentsAtCarryingValue"],["Ingresos","TTM = suma de los últimos cuatro trimestres 10-Q (4.º trimestre = anual − T1 a T3), si no el último 10-K (us-gaap:RevenueFromContractWithCustomerExcludingAssessedTax, Revenues …)"],["CFO, capex, SBC","estado de flujos de caja del 10-K: us-gaap:NetCashProvidedByUsedInOperatingActivities, PaymentsToAcquirePropertyPlantAndEquipment, ShareBasedCompensation"],["WACC, crecimiento terminal, margen","tus datos (por defecto 9% y 3%; el margen sale del histórico si lo dejas vacío)"]],"steps":["Calcula el valor de empresa de hoy con precio, acciones, deuda y caja.","Calcula el margen de flujo de caja libre después de la remuneración en acciones como media de 3 años (o usa tu margen); se detiene si no es positivo.","Busca el único crecimiento g que hace que el valor del modelo a 10 años sea igual al EV de hoy.","Compara g con el crecimiento histórico de ingresos de la empresa (crecimiento anual compuesto de hasta 5 años).","Muestra una tabla: EV del modelo con crecimientos de −5%, 0%, 5%, 10%, 15%, 20% y 30%, y su diferencia con el EV de hoy."],"example":"Empresa de ejemplo: ingresos 100, flujo de caja después de capex y SBC 20, así que m = 20%. Capitalización 380 + deuda 40 − caja 20 = EV 400. WACC 9%, gT 3%. Con g = 0% el modelo da unos 273, demasiado bajo. Con g = 5%: flujo del año 1 = 100 × 1,05 × 20% = 21; la suma de los diez años descontados más el valor terminal descontado da unos 400. Así que el precio de hoy implica alrededor de un 5% de crecimiento anual durante 10 años, con ingresos en el año 10 de unos 100 × 1,05¹⁰ ≈ 163.","read":["Si el crecimiento implícito está muy por encima del crecimiento pasado, el precio supone una aceleración; si está por debajo, el mercado espera una desaceleración o duda del margen.","Usa la tabla: si el EV del modelo sube mucho entre filas de crecimiento, el precio es muy sensible a la historia de crecimiento.","\"Sin solución\" significa que ningún crecimiento entre −50% y +150% explica el precio con estos datos; cambia el margen o el WACC.","El crecimiento implícito es un supuesto hecho visible, no una previsión."],"limits":["El resultado cambia mucho con el WACC, el crecimiento terminal y el margen; mover el WACC 1 punto puede cambiar bastante el crecimiento implícito.","El margen se mantiene fijo 10 años y el crecimiento es igual cada año; en empresas reales ambos cambian.","El flujo de caja es el flujo operativo menos capex, que ya va después de los intereses pagados, y aun así se compara con el valor de empresa; en empresas endeudadas esto subestima el flujo de la empresa. Los valores negociables no cuentan como caja.","La nota en pantalla dice FCF = CFO − capex, pero el margen que usa el código también resta la remuneración en acciones. Necesita un margen positivo: en empresas con pérdidas o que queman caja tienes que escribir tú el margen."]}},{"id":"scenarios","number":5,"group":"valuation","group_label":"Valuation","title":"Scenarios and sensitivity","next":["dcf","reverse_dcf","valuation_summary"],"en":{"question":"How much does a DCF value per share change when the assumptions change?","idea":"A valuation is only as good as its assumptions. This analysis builds one simple 5-year cash-flow model, then reruns it with gloomier (bear) and sunnier (bull) assumptions, and with a grid of discount rates and long-run growth rates. A wide spread tells you the answer depends heavily on what you believe.","formulas":[{"name":"Free cash flow to the firm each year","expr":"FCFFₜ = EBITₜ × (1 − tax) + D&Aₜ − capexₜ − 5% × (Revenueₜ − Revenueₜ₋₁)","where":[["FCFF","free cash flow to the firm (before paying lenders or shareholders), USD millions"],["EBIT","operating income = revenue × operating margin"],["tax","effective tax rate, 0–35%"],["D&A, capex","depreciation and amortization, capital spending: each a fixed % of revenue"],["5% × revenue change","extra working capital (NWC) needed to grow"]]},{"name":"Enterprise value","expr":"EV = Σₜ₌₁⁵ FCFFₜ ÷ (1 + WACC)ᵗ + [FCFF₅ × (1 + g) ÷ (WACC − g)] ÷ (1 + WACC)⁵","where":[["WACC","discount rate, default 9%"],["g","terminal growth, default 3%"],["t","year 1–5, cash at year end (no mid-year adjustment)"]]},{"name":"Value per share","expr":"Value per share = (EV − debt + cash) ÷ shares outstanding","where":[["debt","long-term + current debt, latest 10-K"],["cash","cash and equivalents, latest 10-K"],["shares","cover-page shares outstanding (else diluted average)"]]},{"name":"Scenario shifts","expr":"Bear: growth − 10 pts, margin − 5 pts, capex + 2 pts.  Bull: growth + 8 pts, margin + 3 pts.","where":[["pts","percentage points, applied to every forecast year"]]}],"data":[["Revenue (latest fiscal year)","10-K income statement (us-gaap:RevenueFromContractWithCustomerExcludingAssessedTax, Revenues …)"],["Operating income","us-gaap:OperatingIncomeLoss; if missing, pre-tax income + InterestExpense"],["Tax rate","us-gaap:IncomeTaxExpenseBenefit ÷ pre-tax income, latest year"],["D&A, capex","us-gaap:DepreciationDepletionAndAmortization, PaymentsToAcquirePropertyPlantAndEquipment (latest year, as % of revenue)"],["Past growth","compound annual revenue growth over up to the last 6 fiscal years in the 10-Ks"],["Debt, cash, shares, price","latest 10-K balance sheet, cover page shares (dei:EntityCommonStockSharesOutstanding), Yahoo Finance latest close"],["WACC, terminal growth, growth","your inputs (defaults 9%, 3%, growth from history)"]],"steps":["Take the latest year's operating margin, tax, D&A and capex ratios, and year-1 growth = past compound growth limited to −10%…30% (5% if unknown), unless you type a growth rate.","Fade growth in straight steps over the 5 years towards the terminal growth rate (year 5 gets 80% of the way there).","Run the base case, then the bear and bull cases with the fixed shifts.","For each case compute FCFF, discount it, add the terminal value, subtract debt, add cash and divide by shares.","Build a 5 × 5 table of value per share for WACC ±2 points and terminal growth ±1 point around your inputs."],"example":"Example company: revenue 1,000, growth fading 10% → 4.4%, EBIT margin 20%, tax 20%, D&A 4%, capex 5%. Year 1: revenue 1,100, EBIT 220, after tax 176, + D&A 44 − capex 55 − NWC 5% × 100 = 5, so FCFF = 160, worth 160 ÷ 1.09 ≈ 147 today. Five years together ≈ 716; terminal value ≈ 209 × 1.03 ÷ 0.06 ≈ 3,591, today ≈ 2,334; EV ≈ 3,050. Minus debt 200 plus cash 100 = 2,950, over 100 shares ≈ 29.5 per share. Bear ≈ 11.4, bull ≈ 47.3.","read":["The bear-to-bull range is the main result: the wider it is, the more the value depends on your story.","If the terminal value share is above about 70%, most of the value comes after year 5, so long-run assumptions dominate.","In the sensitivity table, cells that change a lot along a row or column show which input matters most.","A large gap between price and base case does not mean cheap or expensive; the market may assume different growth, margins or discount rate."],"limits":["WACC is a fixed 9% default here, not built from market data (the DCF analysis builds it); bear and bull shifts are fixed rules, not forecasts.","Inputs come from one fiscal year only, and working capital is always 5% of the revenue increase.","If any case has a negative year-5 cash flow, the model cannot compute a terminal value and the whole analysis stops with an error.","Cash excludes marketable securities and minority interests are not subtracted (the DCF analysis subtracts them), so results can differ from the DCF."]},"tr":{"question":"Varsayımlar değiştiğinde DCF’nin verdiği hisse başına değer ne kadar değişiyor?","idea":"Bir değerleme ancak varsayımları kadar iyidir. Bu analiz basit bir 5 yıllık nakit akışı modeli kurar, sonra onu daha kötümser (kötü senaryo) ve daha iyimser (iyi senaryo) varsayımlarla ve bir iskonto oranı × uzun vadeli büyüme tablosuyla yeniden çalıştırır. Aralık genişse sonuç büyük ölçüde neye inandığına bağlıdır.","formulas":[{"name":"Her yıl firmaya serbest nakit akışı","expr":"FCFFₜ = FVÖKₜ × (1 − vergi) + amortismanₜ − yatırımₜ − %5 × (Gelirₜ − Gelirₜ₋₁)","where":[["FCFF","firmaya serbest nakit akışı (borç verenlere ve hissedarlara ödemeden önce), milyon USD"],["FVÖK (EBIT)","faaliyet kârı = gelir × faaliyet marjı"],["vergi","efektif vergi oranı, %0–35"],["amortisman, yatırım","amortisman ve yatırım harcaması: her biri gelirin sabit bir yüzdesi"],["%5 × gelir artışı","büyümek için gereken ek işletme sermayesi (NWC)"]]},{"name":"Firma değeri","expr":"FD = Σₜ₌₁⁵ FCFFₜ ÷ (1 + WACC)ᵗ + [FCFF₅ × (1 + g) ÷ (WACC − g)] ÷ (1 + WACC)⁵","where":[["WACC","iskonto oranı (sermaye maliyeti), varsayılan %9"],["g","uç (terminal) büyüme, varsayılan %3"],["t","1–5. yıl, nakit yıl sonunda (yıl ortası düzeltmesi yok)"]]},{"name":"Hisse başına değer","expr":"Hisse başına değer = (FD − borç + nakit) ÷ dolaşımdaki hisse","where":[["borç","uzun + kısa vadeli borç, son 10-K"],["nakit","nakit ve nakit benzerleri, son 10-K"],["hisse","kapak sayfasındaki dolaşımdaki hisse (yoksa seyreltilmiş ortalama)"]]},{"name":"Senaryo kaydırmaları","expr":"Kötü: büyüme − 10 puan, marj − 5 puan, yatırım + 2 puan.  İyi: büyüme + 8 puan, marj + 3 puan.","where":[["puan","yüzde puanı; her tahmin yılına uygulanır"]]}],"data":[["Gelir (son mali yıl)","10-K gelir tablosu (us-gaap:RevenueFromContractWithCustomerExcludingAssessedTax, Revenues …)"],["Faaliyet kârı","us-gaap:OperatingIncomeLoss; yoksa vergi öncesi kâr + InterestExpense"],["Vergi oranı","us-gaap:IncomeTaxExpenseBenefit ÷ vergi öncesi kâr, son yıl"],["Amortisman, yatırım","us-gaap:DepreciationDepletionAndAmortization, PaymentsToAcquirePropertyPlantAndEquipment (son yıl, gelirin yüzdesi olarak)"],["Geçmiş büyüme","10-K’lardaki en fazla son 6 mali yılın yıllık bileşik gelir büyümesi"],["Borç, nakit, hisse, fiyat","son 10-K bilançosu, kapak sayfası hisse sayısı (dei:EntityCommonStockSharesOutstanding), Yahoo Finance son kapanış"],["WACC, uç büyüme, büyüme","senin girdilerin (varsayılan %9, %3, büyüme geçmişten)"]],"steps":["Son yılın faaliyet marjını, vergi, amortisman ve yatırım oranlarını al; 1. yıl büyümesi = geçmiş bileşik büyüme, −%10…%30 ile sınırlı (bilinmiyorsa %5), büyüme girmediysen.","Büyümeyi 5 yıl boyunca eşit adımlarla uç büyümeye doğru indir (5. yıl yolun %80’ine gelir).","Baz senaryoyu, sonra sabit kaydırmalarla kötü ve iyi senaryoları çalıştır.","Her senaryoda FCFF’yi hesapla, indirge, uç değeri ekle, borcu düş, nakdi ekle ve hisse sayısına böl.","Girdilerinin çevresinde WACC ±2 puan ve uç büyüme ±1 puan için 5 × 5’lik hisse başına değer tablosu kur."],"example":"Örnek şirket: gelir 1.000, büyüme %10 → %4,4’e iniyor, FVÖK marjı %20, vergi %20, amortisman %4, yatırım %5. 1. yıl: gelir 1.100, FVÖK 220, vergi sonrası 176, + amortisman 44 − yatırım 55 − işletme sermayesi %5 × 100 = 5, yani FCFF = 160; bugünkü değeri 160 ÷ 1,09 ≈ 147. Beş yılın toplamı ≈ 716; uç değer ≈ 209 × 1,03 ÷ 0,06 ≈ 3.591, bugünkü değeri ≈ 2.334; firma değeri ≈ 3.050. Borç 200 düşülüp nakit 100 eklenince 2.950; 100 hisseye bölünce hisse başına ≈ 29,5. Kötü senaryo ≈ 11,4, iyi senaryo ≈ 47,3.","read":["Asıl sonuç kötü–iyi aralığıdır: ne kadar genişse değer o kadar senin hikâyene bağlıdır.","Uç değerin payı yaklaşık %70’in üstündeyse değerin çoğu 5. yıldan sonra gelir; uzun vadeli varsayımlar belirleyicidir.","Duyarlılık tablosunda bir satır ya da sütun boyunca çok değişen hücreler, hangi girdinin en önemli olduğunu gösterir.","Fiyat ile baz senaryo arasında büyük fark “ucuz” ya da “pahalı” demek değildir; piyasa farklı büyüme, marj veya iskonto oranı varsayıyor olabilir."],"limits":["WACC burada sabit %9 varsayılandır, piyasa verisinden kurulmaz (DCF analizi kurar); kötü ve iyi kaydırmaları sabit kurallardır, tahmin değildir.","Girdiler tek bir mali yıldan gelir ve işletme sermayesi her zaman gelir artışının %5’idir.","Herhangi bir senaryoda 5. yıl nakit akışı negatifse uç değer hesaplanamaz ve analizin tamamı hatayla durur.","Nakde menkul kıymetler dahil değildir ve azınlık payları düşülmez (DCF analizi düşer); bu yüzden sonuç DCF’den farklı çıkabilir."]},"es":{"question":"¿Cuánto cambia el valor por acción de un DCF cuando cambian los supuestos?","idea":"Una valoración vale lo que valen sus supuestos. Este análisis construye un modelo sencillo de flujos de caja a 5 años y lo vuelve a calcular con supuestos más pesimistas (bajista) y más optimistas (alcista), y con una tabla de tasas de descuento y crecimientos a largo plazo. Un rango amplio te dice que el resultado depende mucho de lo que creas.","formulas":[{"name":"Flujo de caja libre de la empresa cada año","expr":"FCFFₜ = EBITₜ × (1 − impuesto) + D&Aₜ − capexₜ − 5% × (Ingresosₜ − Ingresosₜ₋₁)","where":[["FCFF","flujo de caja libre de la empresa (antes de pagar a acreedores o accionistas), millones de USD"],["EBIT","beneficio operativo = ingresos × margen operativo"],["impuesto","tipo impositivo efectivo, 0–35%"],["D&A, capex","amortizaciones e inversión en activos: cada una un % fijo de los ingresos"],["5% × aumento de ingresos","capital circulante (NWC) adicional necesario para crecer"]]},{"name":"Valor de empresa","expr":"EV = Σₜ₌₁⁵ FCFFₜ ÷ (1 + WACC)ᵗ + [FCFF₅ × (1 + g) ÷ (WACC − g)] ÷ (1 + WACC)⁵","where":[["WACC","tasa de descuento (coste del capital), por defecto 9%"],["g","crecimiento terminal, por defecto 3%"],["t","año 1–5, dinero al final del año (sin ajuste de mitad de año)"]]},{"name":"Valor por acción","expr":"Valor por acción = (EV − deuda + caja) ÷ acciones en circulación","where":[["deuda","deuda a largo + corto plazo, último 10-K"],["caja","efectivo y equivalentes, último 10-K"],["acciones","acciones en circulación de la portada (si no, media diluida)"]]},{"name":"Cambios de escenario","expr":"Bajista: crecimiento − 10 pts, margen − 5 pts, capex + 2 pts.  Alcista: crecimiento + 8 pts, margen + 3 pts.","where":[["pts","puntos porcentuales, aplicados a todos los años de la previsión"]]}],"data":[["Ingresos (último ejercicio)","cuenta de resultados del 10-K (us-gaap:RevenueFromContractWithCustomerExcludingAssessedTax, Revenues …)"],["Beneficio operativo","us-gaap:OperatingIncomeLoss; si falta, beneficio antes de impuestos + InterestExpense"],["Tipo impositivo","us-gaap:IncomeTaxExpenseBenefit ÷ beneficio antes de impuestos, último año"],["D&A, capex","us-gaap:DepreciationDepletionAndAmortization, PaymentsToAcquirePropertyPlantAndEquipment (último año, en % de ingresos)"],["Crecimiento pasado","crecimiento anual compuesto de ingresos de hasta los últimos 6 ejercicios de los 10-K"],["Deuda, caja, acciones, precio","balance del último 10-K, acciones de la portada (dei:EntityCommonStockSharesOutstanding), último cierre de Yahoo Finance"],["WACC, crecimiento terminal, crecimiento","tus datos (por defecto 9%, 3% y crecimiento histórico)"]],"steps":["Toma el margen operativo, el impuesto, D&A y capex del último año, y crecimiento del año 1 = crecimiento compuesto pasado limitado a −10%…30% (5% si no se conoce), salvo que escribas uno.","Reduce el crecimiento en pasos iguales durante 5 años hacia el crecimiento terminal (el año 5 llega al 80% del camino).","Calcula el caso base y luego los casos bajista y alcista con los cambios fijos.","En cada caso calcula el FCFF, descuéntalo, suma el valor terminal, resta la deuda, suma la caja y divide entre las acciones.","Construye una tabla 5 × 5 de valor por acción con WACC ±2 puntos y crecimiento terminal ±1 punto alrededor de tus datos."],"example":"Empresa de ejemplo: ingresos 1.000, crecimiento que baja de 10% a 4,4%, margen EBIT 20%, impuesto 20%, D&A 4%, capex 5%. Año 1: ingresos 1.100, EBIT 220, después de impuestos 176, + D&A 44 − capex 55 − circulante 5% × 100 = 5, así que FCFF = 160, que hoy vale 160 ÷ 1,09 ≈ 147. Los cinco años suman ≈ 716; valor terminal ≈ 209 × 1,03 ÷ 0,06 ≈ 3.591, hoy ≈ 2.334; EV ≈ 3.050. Menos deuda 200 más caja 100 = 2.950, entre 100 acciones ≈ 29,5 por acción. Bajista ≈ 11,4, alcista ≈ 47,3.","read":["El rango bajista–alcista es el resultado principal: cuanto más amplio, más depende el valor de tu historia.","Si el peso del valor terminal supera un 70% aproximadamente, la mayor parte del valor llega después del año 5: mandan los supuestos de largo plazo.","En la tabla de sensibilidad, las celdas que cambian mucho a lo largo de una fila o columna muestran qué dato importa más.","Una gran diferencia entre el precio y el caso base no significa barato ni caro; el mercado puede suponer otro crecimiento, margen o tasa de descuento."],"limits":["Aquí el WACC es un 9% fijo por defecto, no calculado con datos de mercado (el análisis DCF sí lo calcula); los cambios bajista y alcista son reglas fijas, no previsiones.","Los datos salen de un solo ejercicio y el capital circulante es siempre el 5% del aumento de ingresos.","Si algún caso tiene un flujo del año 5 negativo, no se puede calcular el valor terminal y todo el análisis se detiene con un error.","La caja no incluye valores negociables y no se restan los intereses minoritarios (el análisis DCF sí los resta), así que el resultado puede diferir del DCF."]}},{"id":"piotroski","number":6,"group":"quant","group_label":"Quant","title":"Piotroski F-score","next":["earnings_quality","credit_altman","dupont"],"en":{"question":"Is the company's financial health getting better or worse compared with last year?","idea":"The F-score runs nine simple yes/no checks on the annual report: is the company profitable, does it bring in cash, is debt falling, are margins and efficiency improving? Each \"yes\" earns 1 point. A high score means most things moved in the right direction this year; a low score means most moved the wrong way.","formulas":[{"name":"F-score","expr":"F = Σ of the tests that pass (each test = 1 if true, 0 if false); shown as F / number of tests with data","where":[["tests","1) ROA > 0  2) operating cash flow > 0  3) ROA higher than last year  4) operating cash flow > net income  5) long-term debt ÷ assets lower than or equal to last year  6) current ratio higher  7) diluted shares not higher  8) gross margin higher  9) asset turnover higher"],["number of tests with data","a test whose inputs are missing in the filing is skipped, not counted as 0"]]},{"name":"Return on assets (ROA)","expr":"ROA = net income of the year ÷ total assets at the end of the previous year","where":[["net income","profit for the fiscal year, US dollars"],["total assets (opening)","balance-sheet total at the start of the year, US dollars"]]},{"name":"Leverage, liquidity, efficiency","expr":"Leverage = long-term debt ÷ ((opening assets + closing assets) ÷ 2);  Current ratio = current assets ÷ current liabilities;  Asset turnover = revenue ÷ opening assets","where":[["long-term debt","debt due after more than one year, at year end"],["current assets / liabilities","items due or usable within a year, at year end"],["revenue","sales of the year"]]},{"name":"Gross margin","expr":"Gross margin = gross profit ÷ revenue  (if gross profit is not reported: (revenue − cost of revenue) ÷ revenue)","where":[["gross profit","revenue minus the direct cost of what was sold"],["revenue","sales of the year"]]}],"data":[["Net income, operating cash flow, revenue, gross profit or cost of revenue","annual 10-K figures from SEC XBRL company facts (tags such as NetIncomeLoss, NetCashProvidedByUsedInOperatingActivities, Revenues, GrossProfit, CostOfRevenue)"],["Total assets, current assets, current liabilities, long-term debt","year-end balance sheet from the same 10-K filings (Assets, AssetsCurrent, LiabilitiesCurrent, LongTermDebtNoncurrent or LongTermDebt)"],["Diluted shares","weighted-average diluted shares (WeightedAverageNumberOfDilutedSharesOutstanding), restated to today's split basis"],["Foreign filers","20-F reports (US GAAP or IFRS tags) converted to US dollars at the FRED period-end exchange rate"]],"steps":["Load the last fiscal years from the company's SEC annual reports; at least three years are needed, because last year's ROA needs the assets from the year before it.","Compute each ratio for the latest year and for the year before.","Run the nine yes/no tests; a test with a missing figure is skipped and shown as \"–\".","Add up the passed tests and show the score next to how many tests could be run.","Label the score: 7 or more \"strong\", 3 or less \"weak\", otherwise \"middle\", and rank the companies."],"example":"Example company: net income 50 and opening assets 1,000 give ROA = 50 ÷ 1,000 = 5% > 0 (1 point). Operating cash flow 80 > 0 (1). Last year ROA was 4%, now 5% (1). Cash flow 80 > net income 50 (1). Long-term debt ÷ average assets fell from 22% to 20% (1). Current ratio rose from 1.4 to 1.5 (1). Diluted shares fell from 102 to 100 (1). Gross margin fell from 40% to 38% (0). Asset turnover fell from 0.92 to 0.90 (0). F = 7 of 9 → labelled \"strong\".","read":["7–9: most measures improved this year; 0–3: most got worse; 4–6: mixed.","Always read the score next to \"criteria tested\": 5 of 6 is not the same as 5 of 9.","Look at which tests failed: a falling gross margin tells a different story than new shares being issued.","The score compares only the latest year with the year before, so one unusual year can move it a lot."],"limits":["The score looks backwards at reported numbers; it does not predict future returns (the app says so too).","The 7/3 labels are applied to the raw score even when fewer than 9 tests had data, so a company with missing tags can look weaker.","The tests were designed for ordinary industrial companies; banks, insurers and young growth companies often fit them badly.","\"No dilution\" uses diluted weighted-average shares, and the debt test passes when debt is unchanged (for example zero both years); both are small simplifications to keep in mind."]},"tr":{"question":"Şirketin finansal sağlığı geçen yıla göre iyileşiyor mu, kötüleşiyor mu?","idea":"F-skoru yıllık rapor üzerinde dokuz basit evet/hayır testi yapar: şirket kâr ediyor mu, nakit getiriyor mu, borç azalıyor mu, marjlar ve verimlilik iyileşiyor mu? Her \"evet\" 1 puan getirir. Yüksek skor, bu yıl çoğu şeyin doğru yöne gittiğini; düşük skor çoğunun yanlış yöne gittiğini gösterir.","formulas":[{"name":"F-skoru","expr":"F = geçen testlerin toplamı (her test doğruysa 1, değilse 0); F / verisi olan test sayısı olarak gösterilir","where":[["testler","1) ROA > 0  2) faaliyet nakit akışı > 0  3) ROA geçen yıldan yüksek  4) faaliyet nakit akışı > net kâr  5) uzun vadeli borç ÷ varlıklar geçen yıldan düşük veya eşit  6) cari oran yükseldi  7) sulandırılmış hisse sayısı artmadı  8) brüt marj yükseldi  9) varlık devir hızı yükseldi"],["verisi olan test sayısı","girdisi raporda olmayan test atlanır, 0 sayılmaz"]]},{"name":"Aktif kârlılığı (ROA, return on assets)","expr":"ROA = yılın net kârı ÷ bir önceki yıl sonundaki toplam varlıklar","where":[["net kâr","mali yılın kârı, ABD doları"],["toplam varlıklar (açılış)","yıl başındaki bilanço toplamı, ABD doları"]]},{"name":"Borçluluk, likidite, verimlilik","expr":"Borçluluk = uzun vadeli borç ÷ ((açılış varlıkları + kapanış varlıkları) ÷ 2);  Cari oran = dönen varlıklar ÷ kısa vadeli yükümlülükler;  Varlık devir hızı = hasılat ÷ açılış varlıkları","where":[["uzun vadeli borç","bir yıldan sonra ödenecek borç, yıl sonu"],["dönen varlıklar / kısa vadeli yükümlülükler","bir yıl içinde kullanılabilecek veya ödenecek kalemler, yıl sonu"],["hasılat","yılın satışları"]]},{"name":"Brüt marj","expr":"Brüt marj = brüt kâr ÷ hasılat  (brüt kâr raporlanmamışsa: (hasılat − satışların maliyeti) ÷ hasılat)","where":[["brüt kâr","hasılattan satılan malın doğrudan maliyeti düşülünce kalan"],["hasılat","yılın satışları"]]}],"data":[["Net kâr, faaliyet nakit akışı, hasılat, brüt kâr veya satışların maliyeti","SEC XBRL company facts’teki yıllık 10-K rakamları (NetIncomeLoss, NetCashProvidedByUsedInOperatingActivities, Revenues, GrossProfit, CostOfRevenue gibi etiketler)"],["Toplam varlıklar, dönen varlıklar, kısa vadeli yükümlülükler, uzun vadeli borç","aynı 10-K raporlarındaki yıl sonu bilançosu (Assets, AssetsCurrent, LiabilitiesCurrent, LongTermDebtNoncurrent veya LongTermDebt)"],["Sulandırılmış hisse sayısı","ağırlıklı ortalama sulandırılmış hisse (WeightedAverageNumberOfDilutedSharesOutstanding), bugünkü bölünme bazına çevrilmiş"],["Yabancı şirketler","20-F raporları (US GAAP veya IFRS etiketleri), FRED dönem sonu kuruyla dolara çevrilir"]],"steps":["Şirketin SEC yıllık raporlarından son mali yılları yükle; en az üç yıl gerekir, çünkü geçen yılın ROA’sı için bir önceki yılın varlıkları lazım.","Her oranı son yıl ve bir önceki yıl için hesapla.","Dokuz evet/hayır testini çalıştır; rakamı eksik olan test atlanır ve \"–\" görünür.","Geçen testleri topla ve skoru kaç testin yapılabildiğiyle birlikte göster.","Skoru etiketle: 7 ve üstü \"güçlü\", 3 ve altı \"zayıf\", arası \"orta\"; şirketleri sırala."],"example":"Örnek şirket: net kâr 50, açılış varlıkları 1.000 → ROA = 50 ÷ 1.000 = %5 > 0 (1 puan). Faaliyet nakit akışı 80 > 0 (1). Geçen yıl ROA %4’tü, şimdi %5 (1). Nakit akışı 80 > net kâr 50 (1). Uzun vadeli borç ÷ ortalama varlıklar %22’den %20’ye indi (1). Cari oran 1,4’ten 1,5’e çıktı (1). Sulandırılmış hisse 102’den 100’e indi (1). Brüt marj %40’tan %38’e düştü (0). Varlık devir hızı 0,92’den 0,90’a düştü (0). F = 9 testten 7 → \"güçlü\".","read":["7–9: bu yıl ölçütlerin çoğu iyileşmiş; 0–3: çoğu kötüleşmiş; 4–6: karışık.","Skoru her zaman \"test edilen kriter\" sayısıyla birlikte oku: 6’da 5, 9’da 5 ile aynı şey değil.","Hangi testlerin geçmediğine bak: düşen brüt marj, yeni hisse ihracından farklı bir hikâye anlatır.","Skor yalnızca son yılı bir önceki yılla karşılaştırır; tek bir sıra dışı yıl skoru çok oynatabilir."],"limits":["Skor raporlanmış rakamlara geriye doğru bakar; gelecekteki getiriyi tahmin etmez (uygulama da bunu söyler).","7/3 etiketleri, 9’dan az test yapılabilse bile ham skora uygulanır; etiketi eksik olan şirket olduğundan zayıf görünebilir.","Testler sıradan sanayi şirketleri için tasarlandı; bankalar, sigortacılar ve genç büyüme şirketleri bu testlere çoğu zaman iyi uymaz.","\"Sulandırma yok\" testi sulandırılmış ağırlıklı ortalama hisseyi kullanır; borç testi borç değişmediğinde de (ör. iki yıl da sıfır) geçer. İkisi de akılda tutulması gereken küçük basitleştirmeler."]},"es":{"question":"¿La salud financiera de la empresa mejora o empeora respecto al año pasado?","idea":"El F-score aplica nueve pruebas sencillas de sí/no al informe anual: ¿la empresa gana dinero, genera caja, baja su deuda, mejoran sus márgenes y su eficiencia? Cada \"sí\" suma 1 punto. Una puntuación alta indica que este año casi todo fue en la buena dirección; una baja, que casi todo fue en la mala.","formulas":[{"name":"F-score","expr":"F = Σ de las pruebas superadas (cada prueba = 1 si se cumple, 0 si no); se muestra como F / número de pruebas con datos","where":[["pruebas","1) ROA > 0  2) flujo de caja operativo > 0  3) ROA mayor que el año anterior  4) flujo de caja operativo > beneficio neto  5) deuda a largo plazo ÷ activos menor o igual que el año anterior  6) ratio de liquidez corriente mayor  7) acciones diluidas no aumentan  8) margen bruto mayor  9) rotación de activos mayor"],["número de pruebas con datos","una prueba sin datos en el informe se omite, no cuenta como 0"]]},{"name":"Rentabilidad sobre activos (ROA, return on assets)","expr":"ROA = beneficio neto del año ÷ activos totales al cierre del año anterior","where":[["beneficio neto","beneficio del ejercicio, dólares"],["activos totales (iniciales)","total del balance al inicio del año, dólares"]]},{"name":"Endeudamiento, liquidez, eficiencia","expr":"Endeudamiento = deuda a largo plazo ÷ ((activos iniciales + activos finales) ÷ 2);  Liquidez corriente = activo corriente ÷ pasivo corriente;  Rotación de activos = ingresos ÷ activos iniciales","where":[["deuda a largo plazo","deuda que vence en más de un año, al cierre"],["activo / pasivo corriente","partidas utilizables o exigibles en menos de un año, al cierre"],["ingresos","ventas del año"]]},{"name":"Margen bruto","expr":"Margen bruto = beneficio bruto ÷ ingresos  (si no se informa el beneficio bruto: (ingresos − coste de ventas) ÷ ingresos)","where":[["beneficio bruto","ingresos menos el coste directo de lo vendido"],["ingresos","ventas del año"]]}],"data":[["Beneficio neto, flujo de caja operativo, ingresos, beneficio bruto o coste de ventas","cifras anuales del 10-K en SEC XBRL company facts (etiquetas como NetIncomeLoss, NetCashProvidedByUsedInOperatingActivities, Revenues, GrossProfit, CostOfRevenue)"],["Activos totales, activo corriente, pasivo corriente, deuda a largo plazo","balance de cierre de los mismos 10-K (Assets, AssetsCurrent, LiabilitiesCurrent, LongTermDebtNoncurrent o LongTermDebt)"],["Acciones diluidas","media ponderada de acciones diluidas (WeightedAverageNumberOfDilutedSharesOutstanding), ajustada a la base actual de splits"],["Emisores extranjeros","informes 20-F (etiquetas US GAAP o IFRS) convertidos a dólares con el tipo de cambio de cierre de FRED"]],"steps":["Carga los últimos ejercicios de los informes anuales en la SEC; hacen falta al menos tres años, porque el ROA del año anterior necesita los activos del año previo.","Calcula cada ratio para el último año y para el anterior.","Aplica las nueve pruebas de sí/no; una prueba con una cifra faltante se omite y aparece como \"–\".","Suma las pruebas superadas y muestra la puntuación junto al número de pruebas que se pudieron hacer.","Etiqueta la puntuación: 7 o más \"fuerte\", 3 o menos \"débil\", el resto \"intermedio\", y ordena las empresas."],"example":"Empresa de ejemplo: beneficio neto 50 y activos iniciales 1.000 dan ROA = 50 ÷ 1.000 = 5 % > 0 (1 punto). Flujo de caja operativo 80 > 0 (1). El ROA del año anterior era 4 %, ahora 5 % (1). Flujo de caja 80 > beneficio neto 50 (1). Deuda a largo plazo ÷ activos medios baja de 22 % a 20 % (1). Liquidez corriente sube de 1,4 a 1,5 (1). Acciones diluidas bajan de 102 a 100 (1). Margen bruto baja de 40 % a 38 % (0). Rotación de activos baja de 0,92 a 0,90 (0). F = 7 de 9 → \"fuerte\".","read":["7–9: la mayoría de las medidas mejoró este año; 0–3: la mayoría empeoró; 4–6: mixto.","Lee siempre la puntuación junto a \"criterios evaluados\": 5 de 6 no es lo mismo que 5 de 9.","Mira qué pruebas fallaron: un margen bruto en caída cuenta una historia distinta a la emisión de nuevas acciones.","La puntuación solo compara el último año con el anterior, así que un año atípico puede moverla mucho."],"limits":["La puntuación mira hacia atrás, a cifras ya publicadas; no predice rentabilidades futuras (la app también lo dice).","Las etiquetas 7/3 se aplican a la puntuación bruta aunque se hayan podido hacer menos de 9 pruebas, así que una empresa con etiquetas XBRL faltantes puede parecer más débil.","Las pruebas se diseñaron para empresas industriales corrientes; bancos, aseguradoras y empresas jóvenes de crecimiento suelen encajar mal.","\"Sin dilución\" usa la media ponderada de acciones diluidas, y la prueba de deuda se supera si la deuda no cambia (por ejemplo, cero ambos años); son pequeñas simplificaciones a tener en cuenta."]}},{"id":"event_study","number":7,"group":"quant","group_label":"Quant","title":"Earnings reaction (event study)","next":["beta","implied_move","quarterly"],"en":{"question":"How has the stock moved, compared with the whole market, right after the company published its results?","idea":"On results day a stock moves partly because the whole market moved and partly because of the news. Subtracting the market's move (the S&P 500 fund SPY) on the same days leaves the \"abnormal\" part, the reaction that is specific to the company. Doing this for the last dozen releases shows how big and how one-sided the typical reaction has been.","formulas":[{"name":"Cumulative move from the last close before the news","expr":"Rₖ = Pₖ ÷ P₋₁ − 1   (k = 0, +1, +3 trading days)","where":[["P₋₁","adjusted closing price on the trading day before the reaction day"],["Pₖ","adjusted close k trading days after it; day 0 is the first trading day that could react"],["Rₖ","simple return in %"]]},{"name":"Abnormal return (market-adjusted)","expr":"ARₖ = Rₖ(stock) − Rₖ(SPY)","where":[["Rₖ(stock)","the stock's cumulative move to day k, %"],["Rₖ(SPY)","the S&P 500 ETF's move over exactly the same days, %"],["ARₖ","abnormal return in percentage points; the market is assumed to move the stock one-for-one (no beta)"]]},{"name":"Summary across releases","expr":"Average absolute reaction = Σ |AR₀| ÷ N","where":[["N","number of releases with enough prices (at most 12)"],["|AR₀|","size of the day-0 abnormal return, ignoring its sign"]]}],"data":[["Release dates and times","SEC EDGAR filing index: 8-K filings with Item 2.02 \"Results of Operations\", with the SEC acceptance time (US Eastern) to tell before-open from after-close"],["Stock prices","daily adjusted closing prices for the last 5 years (Yahoo Finance; latest close cross-checked with Stooq)"],["Market prices","daily adjusted closes of SPY, the S&P 500 ETF, same source"]],"steps":["Find up to the 12 most recent 8-K Item 2.02 filings; keep one per day.","Pick the reaction day: if the filing was accepted at 4 pm or later, the next trading day; otherwise the filing day (or the next trading day if the market was closed).","Measure the stock's and SPY's cumulative returns from the close before the reaction day to day 0, day +1 and day +3.","Subtract SPY's return to get the abnormal return; skip releases without 3 trading days of prices afterwards.","Report the average size of the day-0 reaction, how often it was positive, and the largest one."],"example":"Example company releases results after the close. The last close before the reaction is 100; on day 0 it closes at 106, so R₀ = 106 ÷ 100 − 1 = +6%. SPY goes from 400 to 404, +1%. Abnormal day-0 return = 6 − 1 = +5 points. On day +1 the stock is at 105 (+5% from 100) and SPY at 402 (+0.5%), so the abnormal return to day +1 = 5 − 0.5 = +4.5 points.","read":["A large average absolute reaction means results days have usually been big events for this stock; a small one means they rarely surprised the market.","Count the signs: 9 positive out of 12 says past results mostly beat what was expected, but it does not say the next one will.","Compare day 0 with day +3: if the abnormal return keeps growing, the price kept adjusting; if it shrinks, part of the first move reversed."],"limits":["Twelve events is a small sample, and the code runs no significance test; one huge reaction can dominate the average.","The model just subtracts the market move one-for-one; it does not estimate a beta, so a high-beta stock on a big market day can show an \"abnormal\" move that is really market exposure.","Other news on the same day (guidance, a deal, sector news) is mixed into the reaction, as the app warns.","Before/during-market releases use the filing day as day 0; if results came out mid-session, part of that day's move happened before the news."]},"tr":{"question":"Şirket sonuçlarını açıkladıktan hemen sonra hisse, piyasanın geneline göre nasıl hareket etmiş?","idea":"Bilanço gününde hisse kısmen tüm piyasa hareket ettiği için, kısmen de haberden dolayı hareket eder. Aynı günlerde piyasanın (S&P 500 fonu SPY) hareketini çıkarınca geriye \"olağandışı\" kısım, yani şirkete özgü tepki kalır. Bunu son düzine açıklama için yapmak, tipik tepkinin ne kadar büyük ve ne kadar tek yönlü olduğunu gösterir.","formulas":[{"name":"Haberden önceki son kapanıştan itibaren birikimli hareket","expr":"Rₖ = Pₖ ÷ P₋₁ − 1   (k = 0, +1, +3 işlem günü)","where":[["P₋₁","tepki gününden önceki işlem gününün düzeltilmiş kapanış fiyatı"],["Pₖ","k işlem günü sonraki düzeltilmiş kapanış; 0. gün tepki verebilecek ilk işlem günü"],["Rₖ","basit getiri, %"]]},{"name":"Olağandışı getiri (piyasaya göre düzeltilmiş)","expr":"OGₖ = Rₖ(hisse) − Rₖ(SPY)","where":[["Rₖ(hisse)","hissenin k. güne kadarki birikimli hareketi, %"],["Rₖ(SPY)","S&P 500 ETF’sinin tam aynı günlerdeki hareketi, %"],["OGₖ","olağandışı getiri, yüzde puan; piyasanın hisseyi bire bir etkilediği varsayılır (beta yok)"]]},{"name":"Açıklamalar genelinde özet","expr":"Ortalama mutlak tepki = Σ |OG₀| ÷ N","where":[["N","yeterli fiyatı olan açıklama sayısı (en fazla 12)"],["|OG₀|","0. gün olağandışı getirisinin işaretten bağımsız büyüklüğü"]]}],"data":[["Açıklama tarihleri ve saatleri","SEC EDGAR dosya listesi: Item 2.02 \"Faaliyet Sonuçları\" içeren 8-K’lar; açılış öncesi/kapanış sonrası ayrımı için SEC kabul saati (ABD Doğu saati)"],["Hisse fiyatları","son 5 yılın günlük düzeltilmiş kapanış fiyatları (Yahoo Finance; son kapanış Stooq ile karşılaştırılır)"],["Piyasa fiyatları","S&P 500 ETF’si SPY’nin günlük düzeltilmiş kapanışları, aynı kaynak"]],"steps":["En son 12 adede kadar 8-K Item 2.02 dosyasını bul; her gün için bir tane tut.","Tepki gününü seç: dosya saat 16:00 veya sonrasında kabul edildiyse ertesi işlem günü; değilse dosya günü (piyasa kapalıysa sonraki işlem günü).","Hissenin ve SPY’nin, tepki gününden önceki kapanıştan 0., +1. ve +3. güne kadarki birikimli getirilerini ölç.","SPY getirisini çıkararak olağandışı getiriyi bul; sonrasında 3 işlem günü fiyatı olmayan açıklamaları atla.","0. gün tepkisinin ortalama büyüklüğünü, kaç kez pozitif olduğunu ve en büyüğünü raporla."],"example":"Örnek şirket sonuçlarını kapanıştan sonra açıklıyor. Tepkiden önceki son kapanış 100; 0. gün 106’dan kapanıyor, yani R₀ = 106 ÷ 100 − 1 = +%6. SPY 400’den 404’e çıkıyor, +%1. 0. gün olağandışı getiri = 6 − 1 = +5 puan. +1. gün hisse 105’te (100’e göre +%5), SPY 402’de (+%0,5); +1. güne kadar olağandışı getiri = 5 − 0,5 = +4,5 puan.","read":["Ortalama mutlak tepki büyükse bilanço günleri bu hisse için genelde büyük olaylar olmuş; küçükse sonuçlar piyasayı nadiren şaşırtmış.","İşaretleri say: 12’de 9 pozitif, geçmiş sonuçların çoğunlukla beklentiyi aştığını söyler ama bir sonrakinin de öyle olacağını söylemez.","0. günü +3. günle karşılaştır: olağandışı getiri büyümeye devam ediyorsa fiyat uyum sağlamayı sürdürmüş; küçülüyorsa ilk hareketin bir kısmı geri dönmüş."],"limits":["On iki olay küçük bir örneklem ve kod anlamlılık testi yapmıyor; tek bir çok büyük tepki ortalamayı domine edebilir.","Model piyasa hareketini bire bir çıkarır; beta tahmin etmez. Yüksek betalı bir hisse, piyasanın çok oynadığı bir günde aslında piyasa etkisi olan bir \"olağandışı\" hareket gösterebilir.","Aynı gündeki başka haberler (beklenti güncellemesi, satın alma, sektör haberi) tepkiye karışır; uygulama da bunu uyarır.","Açılış öncesi/seans içi açıklamalarda 0. gün dosya günüdür; sonuç seans ortasında geldiyse o günün hareketinin bir kısmı haberden önce olmuştur."]},"es":{"question":"¿Cómo se ha movido la acción, frente al mercado en conjunto, justo después de que la empresa publicara sus resultados?","idea":"El día de resultados una acción se mueve en parte porque se movió todo el mercado y en parte por la noticia. Si restas el movimiento del mercado (el fondo del S&P 500, SPY) en los mismos días, queda la parte \"anormal\", la reacción propia de la empresa. Hacerlo con la última docena de publicaciones muestra lo grande y lo unidireccional que ha sido la reacción típica.","formulas":[{"name":"Movimiento acumulado desde el último cierre antes de la noticia","expr":"Rₖ = Pₖ ÷ P₋₁ − 1   (k = 0, +1, +3 sesiones)","where":[["P₋₁","precio de cierre ajustado de la sesión anterior al día de reacción"],["Pₖ","cierre ajustado k sesiones después; el día 0 es la primera sesión que pudo reaccionar"],["Rₖ","rentabilidad simple, %"]]},{"name":"Rentabilidad anormal (ajustada por mercado)","expr":"RAₖ = Rₖ(acción) − Rₖ(SPY)","where":[["Rₖ(acción)","movimiento acumulado de la acción hasta el día k, %"],["Rₖ(SPY)","movimiento del ETF del S&P 500 en exactamente los mismos días, %"],["RAₖ","rentabilidad anormal en puntos porcentuales; se supone que el mercado mueve la acción uno a uno (sin beta)"]]},{"name":"Resumen de todas las publicaciones","expr":"Reacción absoluta media = Σ |RA₀| ÷ N","where":[["N","número de publicaciones con precios suficientes (máximo 12)"],["|RA₀|","tamaño de la rentabilidad anormal del día 0, sin signo"]]}],"data":[["Fechas y horas de publicación","índice de documentos de SEC EDGAR: 8-K con el Item 2.02 \"Results of Operations\", con la hora de aceptación de la SEC (hora del Este de EE. UU.) para distinguir antes de la apertura y después del cierre"],["Precios de la acción","precios de cierre diarios ajustados de los últimos 5 años (Yahoo Finance; el último cierre se contrasta con Stooq)"],["Precios del mercado","cierres diarios ajustados de SPY, el ETF del S&P 500, misma fuente"]],"steps":["Busca hasta los 12 8-K con Item 2.02 más recientes; conserva uno por día.","Elige el día de reacción: si la SEC aceptó el documento a las 16:00 o más tarde, la sesión siguiente; si no, el mismo día (o la siguiente sesión si el mercado estaba cerrado).","Mide la rentabilidad acumulada de la acción y de SPY desde el cierre anterior al día de reacción hasta el día 0, el +1 y el +3.","Resta la rentabilidad de SPY para obtener la anormal; descarta publicaciones sin 3 sesiones de precios posteriores.","Informa del tamaño medio de la reacción del día 0, cuántas veces fue positiva y cuál fue la mayor."],"example":"La empresa de ejemplo publica resultados tras el cierre. El último cierre antes de la reacción es 100; el día 0 cierra en 106, así que R₀ = 106 ÷ 100 − 1 = +6 %. SPY pasa de 400 a 404, +1 %. Rentabilidad anormal del día 0 = 6 − 1 = +5 puntos. El día +1 la acción está en 105 (+5 % desde 100) y SPY en 402 (+0,5 %), así que la anormal hasta el día +1 = 5 − 0,5 = +4,5 puntos.","read":["Una reacción absoluta media grande indica que los días de resultados suelen ser grandes eventos para esta acción; una pequeña, que rara vez sorprendieron al mercado.","Cuenta los signos: 9 positivas de 12 dice que los resultados pasados casi siempre superaron lo esperado, pero no que el próximo también lo hará.","Compara el día 0 con el +3: si la anormal sigue creciendo, el precio siguió ajustándose; si se reduce, parte del primer movimiento se revirtió."],"limits":["Doce eventos son una muestra pequeña y el código no hace ninguna prueba de significación; una sola reacción enorme puede dominar la media.","El modelo solo resta el movimiento del mercado uno a uno; no estima una beta, así que una acción de beta alta en un día de gran movimiento puede mostrar un movimiento \"anormal\" que en realidad es exposición al mercado.","Otras noticias del mismo día (previsiones, una compra, noticias del sector) se mezclan con la reacción, como advierte la app.","En publicaciones antes o durante la sesión el día 0 es el día del documento; si los resultados salieron a media sesión, parte del movimiento de ese día ocurrió antes de la noticia."]}},{"id":"strategy_multi","number":8,"group":"quant","group_label":"Quant","title":"Honest strategy test","next":["portfolio","factors","crisis"],"en":{"question":"Does one simple trading rule beat just buying and holding, across many stocks and on data it was not tuned on?","idea":"It is easy to find a rule that looked great on one stock by luck. This test applies the same rule, with trading costs, to up to ten stocks, and checks each one on the last part of the history (out-of-sample) as well as the whole period. If the rule wins on only a few stocks, the \"great\" result was probably luck.","formulas":[{"name":"Signal (in the market or in cash)","expr":"SMA crossover: sₜ = 1 if SMA₁₅(t) > SMA₅₀(t), else 0.   Momentum: sₜ = 1 if Pₜ ÷ Pₜ₋₂₀ − 1 > 0, else 0","where":[["SMAₙ(t)","average of the last n daily adjusted closes"],["Pₜ","adjusted close on day t"],["15, 50, 20","default window lengths in trading days (you can change them)"]]},{"name":"Daily strategy return with costs","expr":"rₜ(strategy) = eₜ × rₜ − |eₜ − eₜ₋₁| × (fee + slippage) ÷ 10,000,   with eₜ = sₜ₋₂","where":[["eₜ","exposure: the signal from two closes earlier (decided at close t, traded at close t+1, earns from t+1 to t+2)"],["rₜ","stock's simple daily return"],["fee + slippage","default 5 + 5 = 10 basis points per position change (0.10%)"],["out of the market","earns 0%: no interest on cash"]]},{"name":"Scoring","expr":"Total return = Vₑₙ𝒹 ÷ Vₛₜₐᵣₜ − 1;   Sharpe = mean(daily return) ÷ σ(daily return) × √252;   Beat = 1 if strategy total return > buy-and-hold total return","where":[["V","value of the equity curve"],["√252","annualisation with 252 trading days; no risk-free rate is subtracted"],["out-of-sample","the last 30% of days (default split 70/30), curve restarted at the split"]]}],"data":[["Prices","5 years of daily adjusted closing prices per stock, including dividends (Yahoo Finance; latest close cross-checked with Stooq)"],["Rule settings","chosen by you: rule (SMA crossover or Momentum), windows, fee and slippage in basis points, training share (50–90%)"]],"steps":["For each stock, compute the daily in/out signal from the chosen rule.","Lag it: a signal seen at today's close is traded at tomorrow's close, so it first earns the day after.","Charge fee + slippage each time the position changes; buy-and-hold is charged nothing.","Compare the strategy with buy-and-hold over the full 5 years and over the out-of-sample part after the split date.","Count on how many stocks the rule beat buy-and-hold out-of-sample."],"example":"Example company: on a day the rule switches from cash into the stock and the stock gains 1%, the strategy earns 1 × 1% − 1 × 10 ÷ 10,000 = 1% − 0.10% = 0.90%. After the split date the rule ends at +12% while buy-and-hold gains +18%, so this stock counts as \"did not beat\". If the rule beats buy-and-hold out-of-sample on 3 of 10 stocks, the result reads \"3 of 10\".","read":["The key line is the out-of-sample win count: winning on most stocks is more convincing than a big win on one.","Look at the chart of out-of-sample strategy minus buy-and-hold: bars mostly below zero mean the rule mostly cost money compared with doing nothing.","Many position changes means costs matter a lot; try higher fees to see how fragile the result is.","A rule that sits in cash during a crash can win on drawdown but lose on total return in rising markets."],"limits":["A backtest is not a forecast: a rule that worked in these 5 years may not work in the next.","Nothing is fitted on the \"training\" part; the windows are the ones you picked. If you keep changing them until the out-of-sample result looks good, you have tuned on the test data (the code warns that repeated optimisation biases results).","The stocks are ones that trade today; companies that failed or delisted are missing (survivorship bias), so the test can look better than reality.","No significance test is run, cash earns no interest, buy-and-hold pays no costs, and taxes are ignored."]},"tr":{"question":"Tek bir basit al-sat kuralı, birçok hissede ve ayarlanmadığı veride, al-ve-tut stratejisini geçiyor mu?","idea":"Bir hissede şans eseri harika görünen bir kural bulmak kolaydır. Bu test aynı kuralı, işlem maliyetleriyle birlikte, en fazla on hisseye uygular ve her birini hem tüm dönemde hem de geçmişin son kısmında (test dışı, out-of-sample) kontrol eder. Kural sadece birkaç hissede kazanıyorsa, o \"harika\" sonuç muhtemelen şanstı.","formulas":[{"name":"Sinyal (piyasada ya da nakitte)","expr":"Hareketli ortalama kesişimi: sₜ = 1, eğer HO₁₅(t) > HO₅₀(t), değilse 0.   Momentum: sₜ = 1, eğer Pₜ ÷ Pₜ₋₂₀ − 1 > 0, değilse 0","where":[["HOₙ(t)","son n günlük düzeltilmiş kapanışın ortalaması (SMA, simple moving average)"],["Pₜ","t günündeki düzeltilmiş kapanış"],["15, 50, 20","işlem günü olarak varsayılan pencere uzunlukları (değiştirebilirsin)"]]},{"name":"İşlem maliyetli günlük strateji getirisi","expr":"rₜ(strateji) = eₜ × rₜ − |eₜ − eₜ₋₁| × (komisyon + kayma) ÷ 10.000,   eₜ = sₜ₋₂","where":[["eₜ","pozisyon: iki kapanış önceki sinyal (t kapanışında karar, t+1 kapanışında işlem, t+1’den t+2’ye getiri)"],["rₜ","hissenin basit günlük getirisi"],["komisyon + kayma","varsayılan 5 + 5 = pozisyon değişikliği başına 10 baz puan (%0,10)"],["piyasa dışında","%0 kazanır: nakde faiz yok"]]},{"name":"Puanlama","expr":"Toplam getiri = V_son ÷ V_ilk − 1;   Sharpe = ortalama(günlük getiri) ÷ σ(günlük getiri) × √252;   Geçti = 1, eğer strateji toplam getirisi > al-ve-tut toplam getirisi","where":[["V","sermaye eğrisinin değeri"],["√252","252 işlem günüyle yıllıklandırma; risksiz faiz çıkarılmaz"],["test dışı dönem","günlerin son %30’u (varsayılan 70/30 ayrımı), eğri ayrım tarihinde yeniden başlatılır"]]}],"data":[["Fiyatlar","her hisse için 5 yıllık günlük düzeltilmiş kapanışlar, temettüler dahil (Yahoo Finance; son kapanış Stooq ile karşılaştırılır)"],["Kural ayarları","senin seçtiklerin: kural (hareketli ortalama kesişimi veya Momentum), pencereler, baz puan olarak komisyon ve kayma, eğitim payı (%50–90)"]],"steps":["Her hisse için seçilen kuraldan günlük içeride/dışarıda sinyalini hesapla.","Sinyali geciktir: bugünkü kapanışta görülen sinyal yarınki kapanışta işleme dönüşür, getiriyi ilk kez ertesi gün kazanır.","Pozisyon her değiştiğinde komisyon + kayma maliyeti düş; al-ve-tut’a hiç maliyet yazılmaz.","Stratejiyi al-ve-tut ile hem 5 yılın tamamında hem de ayrım tarihinden sonraki test dışı dönemde karşılaştır.","Kuralın test dışı dönemde kaç hisse için al-ve-tut stratejisini geçtiğini say."],"example":"Örnek şirket: kuralın nakitten hisseye geçtiği ve hissenin %1 kazandığı bir günde strateji 1 × %1 − 1 × 10 ÷ 10.000 = %1 − %0,10 = %0,90 kazanır. Ayrım tarihinden sonra kural +%12’de, al-ve-tut +%18’de bitiyor; bu hisse \"geçemedi\" sayılır. Kural test dışı dönemde 10 hissenin 3’ünde al-ve-tut’u geçerse sonuç \"10’da 3\" olur.","read":["En önemli satır test dışı kazanma sayısıdır: çoğu hissede kazanmak, tek bir hissede büyük kazançtan daha ikna edicidir.","Test dışı \"strateji eksi al-ve-tut\" grafiğine bak: çubuklar çoğunlukla sıfırın altındaysa kural, hiçbir şey yapmamaya göre çoğu zaman para kaybettirmiş.","Pozisyon değişikliği çoksa maliyetler çok önemlidir; sonucun ne kadar kırılgan olduğunu görmek için komisyonu yükselt.","Çöküşte nakitte kalan bir kural düşüşte iyi görünüp yükselen piyasada toplam getiride kaybedebilir."],"limits":["Geriye dönük test (backtest) tahmin değildir: bu 5 yılda işe yarayan kural sonraki yıllarda yaramayabilir.","\"Eğitim\" kısmında hiçbir şey ayarlanmaz; pencereler senin seçtiklerin. Test dışı sonuç iyi görünene kadar onları değiştirirsen test verisine göre ayar yapmış olursun (kod da tekrarlı optimizasyonun sonuçları saptırdığını uyarır).","Hisseler bugün işlem görenler; batan veya borsadan çıkan şirketler yok (hayatta kalma yanılgısı), bu yüzden test gerçekte olduğundan iyi görünebilir.","Anlamlılık testi yapılmaz, nakit faiz kazanmaz, al-ve-tut maliyet ödemez ve vergiler yok sayılır."]},"es":{"question":"¿Una regla de trading sencilla supera a comprar y mantener, en muchas acciones y en datos con los que no se ajustó?","idea":"Es fácil encontrar una regla que pareció genial en una acción por pura suerte. Esta prueba aplica la misma regla, con costes de operación, a hasta diez acciones, y comprueba cada una en el último tramo de la historia (fuera de muestra) y en el periodo completo. Si la regla gana solo en unas pocas acciones, el resultado \"genial\" probablemente fue suerte.","formulas":[{"name":"Señal (dentro del mercado o en liquidez)","expr":"Cruce de medias: sₜ = 1 si MM₁₅(t) > MM₅₀(t), si no 0.   Momentum: sₜ = 1 si Pₜ ÷ Pₜ₋₂₀ − 1 > 0, si no 0","where":[["MMₙ(t)","media de los últimos n cierres diarios ajustados (SMA, simple moving average)"],["Pₜ","cierre ajustado del día t"],["15, 50, 20","longitudes de ventana por defecto, en sesiones (puedes cambiarlas)"]]},{"name":"Rentabilidad diaria de la estrategia con costes","expr":"rₜ(estrategia) = eₜ × rₜ − |eₜ − eₜ₋₁| × (comisión + deslizamiento) ÷ 10.000,   con eₜ = sₜ₋₂","where":[["eₜ","exposición: la señal de dos cierres antes (se decide al cierre t, se opera al cierre t+1, gana de t+1 a t+2)"],["rₜ","rentabilidad diaria simple de la acción"],["comisión + deslizamiento","por defecto 5 + 5 = 10 puntos básicos por cambio de posición (0,10 %)"],["fuera del mercado","gana 0 %: la liquidez no cobra intereses"]]},{"name":"Puntuación","expr":"Rentabilidad total = V_final ÷ V_inicial − 1;   Sharpe = media(rentabilidad diaria) ÷ σ(rentabilidad diaria) × √252;   Supera = 1 si la rentabilidad total de la estrategia > la de comprar y mantener","where":[["V","valor de la curva de capital"],["√252","anualización con 252 sesiones; no se resta tipo libre de riesgo"],["fuera de muestra","el último 30 % de los días (división 70/30 por defecto), con la curva reiniciada en la fecha de corte"]]}],"data":[["Precios","5 años de cierres diarios ajustados por acción, con dividendos (Yahoo Finance; el último cierre se contrasta con Stooq)"],["Ajustes de la regla","los eliges tú: regla (cruce de medias o Momentum), ventanas, comisión y deslizamiento en puntos básicos, proporción de entrenamiento (50–90 %)"]],"steps":["Para cada acción, calcula la señal diaria dentro/fuera según la regla elegida.","Retrásala: una señal vista al cierre de hoy se opera al cierre de mañana, y gana por primera vez al día siguiente.","Cobra comisión + deslizamiento cada vez que cambia la posición; comprar y mantener no paga nada.","Compara la estrategia con comprar y mantener en los 5 años completos y en el tramo fuera de muestra tras la fecha de corte.","Cuenta en cuántas acciones la regla superó a comprar y mantener fuera de muestra."],"example":"Empresa de ejemplo: un día en que la regla pasa de liquidez a la acción y esta sube un 1 %, la estrategia gana 1 × 1 % − 1 × 10 ÷ 10.000 = 1 % − 0,10 % = 0,90 %. Tras la fecha de corte la regla termina en +12 % y comprar y mantener en +18 %, así que esta acción cuenta como \"no superó\". Si la regla supera a comprar y mantener fuera de muestra en 3 de 10 acciones, el resultado es \"3 de 10\".","read":["La línea clave es el recuento de victorias fuera de muestra: ganar en la mayoría de las acciones convence más que una gran victoria en una sola.","Mira el gráfico de estrategia menos comprar y mantener fuera de muestra: si las barras están casi siempre bajo cero, la regla costó dinero frente a no hacer nada.","Muchos cambios de posición significan que los costes pesan mucho; sube la comisión para ver lo frágil que es el resultado.","Una regla que se queda en liquidez durante un desplome puede ganar en caída máxima pero perder en rentabilidad total en mercados alcistas."],"limits":["Un backtest (prueba histórica) no es una previsión: una regla que funcionó en estos 5 años puede no funcionar en los siguientes.","En el tramo de \"entrenamiento\" no se ajusta nada; las ventanas son las que tú eliges. Si las cambias hasta que el resultado fuera de muestra se ve bien, has ajustado con los datos de prueba (el código advierte que optimizar repetidamente sesga los resultados).","Las acciones son las que cotizan hoy; faltan las empresas que quebraron o dejaron de cotizar (sesgo de supervivencia), así que la prueba puede parecer mejor que la realidad.","No se hace prueba de significación, la liquidez no cobra intereses, comprar y mantener no paga costes y se ignoran los impuestos."]}},{"id":"portfolio","number":9,"group":"quant","group_label":"Quant","title":"Portfolio construction","next":["strategy_multi","beta","crisis"],"en":{"question":"Which way of mixing these stocks gave the most return for each unit of risk?","idea":"Stocks that do not move together can cancel out part of each other's ups and downs, so a mix can be calmer than its parts. The analysis compares three mixes: equal amounts in each stock, the mix that had the lowest volatility in the first half of the data, and a classic 60% stocks / 40% bonds fund mix. To be fair, the low-volatility mix is chosen on the first half and judged on the second half it has never seen.","formulas":[{"name":"Minimum-variance weights (long-only)","expr":"w = Σ⁻¹·1 ÷ (1ᵀ·Σ⁻¹·1); if a weight is negative, drop that stock and solve again until all weights ≥ 0","where":[["Σ","covariance matrix of daily returns in the FIRST half only, × 252 (annual)"],["1","a column of ones"],["w","portfolio weights that add up to 100%, no short selling"]]},{"name":"Daily portfolio return","expr":"r_p = Σ wᵢ × rᵢ   (equal weight: wᵢ = 1 ÷ N;  60/40: 0.6 × r_SPY + 0.4 × r_AGG)","where":[["rᵢ","daily simple return of stock i"],["wᵢ","fixed weight; using it every day means the mix is rebalanced daily"]]},{"name":"Annual return, volatility, Sharpe","expr":"Annual return = (Π(1 + r_p))^(252 ÷ N) − 1;   Volatility = σ(r_p) × √252;   Sharpe = (annual return − r_f) ÷ volatility","where":[["N","number of trading days in the period"],["σ(r_p)","standard deviation of daily returns"],["r_f","risk-free rate you enter; default 0%"],["Max drawdown","largest fall from a running peak of the growth curve"]]}],"data":[["Stock prices","5 years of daily adjusted closing prices, dividends included (Yahoo Finance; latest close cross-checked with Stooq), only days where every series has a price"],["Benchmark funds","SPY (S&P 500 ETF) and AGG (US aggregate bond ETF), same source"],["Risk-free rate","optional number you type in; 0% by default"]],"steps":["Download prices for your 2–10 stocks plus SPY and AGG and turn them into daily returns.","Split the days in half; estimate the covariance matrix from the first half only.","Find the long-only minimum-variance weights from that first-half covariance.","Build the three portfolios with fixed weights and compute their daily returns.","Report annual return, volatility, Sharpe and max drawdown for the second half (out-of-sample) and for the full period."],"example":"Example portfolio of two stocks with equal weights: one day stock A gains 2% and stock B loses 1%, so the portfolio return is 0.5 × 2% + 0.5 × (−1%) = 0.5%. Over 504 trading days the portfolio grows by a factor 1.21, so annual return = 1.21^(252 ÷ 504) − 1 = 1.1 − 1 = 10%. With volatility 20% and r_f = 0, Sharpe = (10% − 0) ÷ 20% = 0.5.","read":["Focus on the out-of-sample rows: the full-period rows include the half used to pick the weights, so they flatter the minimum-variance mix.","A higher Sharpe means more return per unit of volatility; differences of a few hundredths are noise.","Minimum variance should usually show the lowest volatility; if it does not out-of-sample, the past correlations did not hold.","If one stock gets more than 40% of the minimum-variance weight, the app flags concentration risk."],"limits":["A backtest is not a forecast; volatilities and correlations change, especially in crises.","Only 2.5 years of out-of-sample data: one bull or bear market can decide the ranking.","No trading costs, and daily rebalancing is assumed for every mix; real rebalancing costs money.","The stocks are ones that trade today; companies that failed or delisted are missing (survivorship bias), which the app warns about."]},"tr":{"question":"Bu hisseleri karıştırmanın hangi yolu, her birim risk için en fazla getiriyi verdi?","idea":"Birlikte hareket etmeyen hisseler birbirlerinin iniş çıkışlarını kısmen dengeleyebilir, bu yüzden bir karışım parçalarından daha sakin olabilir. Analiz üç karışımı karşılaştırır: her hisseye eşit para, verinin ilk yarısında en düşük oynaklığı veren karışım ve klasik %60 hisse / %40 tahvil fonu karışımı. Adil olsun diye düşük oynaklıklı karışım ilk yarıda seçilir ve hiç görmediği ikinci yarıda değerlendirilir.","formulas":[{"name":"Minimum varyans ağırlıkları (açığa satış yok)","expr":"w = Σ⁻¹·1 ÷ (1ᵀ·Σ⁻¹·1); bir ağırlık negatifse o hisseyi çıkar ve tüm ağırlıklar ≥ 0 olana kadar yeniden çöz","where":[["Σ","günlük getirilerin kovaryans matrisi, YALNIZCA ilk yarıdan, × 252 (yıllık)"],["1","birlerden oluşan sütun"],["w","toplamı %100 olan portföy ağırlıkları, açığa satış yok"]]},{"name":"Günlük portföy getirisi","expr":"r_p = Σ wᵢ × rᵢ   (eşit ağırlık: wᵢ = 1 ÷ N;  60/40: 0,6 × r_SPY + 0,4 × r_AGG)","where":[["rᵢ","i hissesinin basit günlük getirisi"],["wᵢ","sabit ağırlık; her gün kullanılması karışımın her gün yeniden dengelendiği anlamına gelir"]]},{"name":"Yıllık getiri, oynaklık, Sharpe oranı","expr":"Yıllık getiri = (Π(1 + r_p))^(252 ÷ N) − 1;   Oynaklık = σ(r_p) × √252;   Sharpe = (yıllık getiri − r_f) ÷ oynaklık","where":[["N","dönemdeki işlem günü sayısı"],["σ(r_p)","günlük getirilerin standart sapması"],["r_f","girdiğin risksiz faiz; varsayılan %0"],["Maksimum düşüş","büyüme eğrisinin o güne kadarki zirvesinden en büyük düşüş"]]}],"data":[["Hisse fiyatları","5 yıllık günlük düzeltilmiş kapanışlar, temettüler dahil (Yahoo Finance; son kapanış Stooq ile karşılaştırılır); yalnızca tüm serilerin fiyatı olan günler"],["Karşılaştırma fonları","SPY (S&P 500 ETF’si) ve AGG (ABD tahvil endeksi ETF’si), aynı kaynak"],["Risksiz faiz","isteğe bağlı olarak yazdığın sayı; varsayılan %0"]],"steps":["2–10 hissenin yanında SPY ve AGG fiyatlarını indir ve günlük getirilere çevir.","Günleri ikiye böl; kovaryans matrisini yalnızca ilk yarıdan tahmin et.","Bu ilk yarı kovaryansından açığa satışsız minimum varyans ağırlıklarını bul.","Üç portföyü sabit ağırlıklarla kur ve günlük getirilerini hesapla.","İkinci yarı (test dışı) ve tüm dönem için yıllık getiri, oynaklık, Sharpe oranı ve maksimum düşüşü raporla."],"example":"İki hisseli, eşit ağırlıklı örnek portföy: bir gün A hissesi %2 kazanıyor, B hissesi %1 kaybediyor; portföy getirisi 0,5 × %2 + 0,5 × (−%1) = %0,5. 504 işlem gününde portföy 1,21 katına çıkıyor; yıllık getiri = 1,21^(252 ÷ 504) − 1 = 1,1 − 1 = %10. Oynaklık %20 ve r_f = 0 ise Sharpe = (%10 − 0) ÷ %20 = 0,5.","read":["Test dışı satırlara odaklan: tüm dönem satırları ağırlıkları seçmek için kullanılan yarıyı da içerir, bu yüzden minimum varyans karışımını olduğundan iyi gösterir.","Daha yüksek Sharpe oranı, birim oynaklık başına daha fazla getiri demektir; birkaç yüzdelik fark gürültüdür.","Minimum varyans genelde en düşük oynaklığı göstermeli; test dışında göstermiyorsa geçmişteki korelasyonlar devam etmemiştir.","Bir hisse minimum varyans ağırlığının %40’ından fazlasını alırsa uygulama yoğunlaşma riski uyarısı verir."],"limits":["Geriye dönük test tahmin değildir; oynaklıklar ve korelasyonlar, özellikle krizlerde, değişir.","Test dışı veri yalnızca 2,5 yıl: tek bir yükseliş ya da düşüş piyasası sıralamayı belirleyebilir.","İşlem maliyeti yok ve her karışım için günlük yeniden dengeleme varsayılır; gerçekte yeniden dengelemenin maliyeti vardır.","Hisseler bugün işlem görenler; batan veya borsadan çıkan şirketler yok (hayatta kalma yanılgısı); uygulama bunu uyarır."]},"es":{"question":"¿Qué forma de combinar estas acciones dio más rentabilidad por cada unidad de riesgo?","idea":"Las acciones que no se mueven juntas pueden compensar en parte sus subidas y bajadas, así que una mezcla puede ser más tranquila que sus partes. El análisis compara tres mezclas: la misma cantidad en cada acción, la mezcla que tuvo la menor volatilidad en la primera mitad de los datos y la clásica 60 % acciones / 40 % bonos. Para ser justos, la mezcla de baja volatilidad se elige con la primera mitad y se juzga en la segunda, que nunca ha visto.","formulas":[{"name":"Pesos de mínima varianza (sin ventas en corto)","expr":"w = Σ⁻¹·1 ÷ (1ᵀ·Σ⁻¹·1); si un peso es negativo, se quita esa acción y se resuelve de nuevo hasta que todos los pesos sean ≥ 0","where":[["Σ","matriz de covarianzas de las rentabilidades diarias SOLO de la primera mitad, × 252 (anual)"],["1","una columna de unos"],["w","pesos de la cartera que suman 100 %, sin ventas en corto"]]},{"name":"Rentabilidad diaria de la cartera","expr":"r_p = Σ wᵢ × rᵢ   (pesos iguales: wᵢ = 1 ÷ N;  60/40: 0,6 × r_SPY + 0,4 × r_AGG)","where":[["rᵢ","rentabilidad diaria simple de la acción i"],["wᵢ","peso fijo; aplicarlo cada día significa que la mezcla se reequilibra a diario"]]},{"name":"Rentabilidad anual, volatilidad, Sharpe","expr":"Rentabilidad anual = (Π(1 + r_p))^(252 ÷ N) − 1;   Volatilidad = σ(r_p) × √252;   Sharpe = (rentabilidad anual − r_f) ÷ volatilidad","where":[["N","número de sesiones del periodo"],["σ(r_p)","desviación típica de las rentabilidades diarias"],["r_f","tipo libre de riesgo que introduces; 0 % por defecto"],["Caída máxima","mayor caída desde un máximo previo de la curva de crecimiento"]]}],"data":[["Precios de las acciones","5 años de cierres diarios ajustados, con dividendos (Yahoo Finance; el último cierre se contrasta con Stooq), solo días en que todas las series tienen precio"],["Fondos de referencia","SPY (ETF del S&P 500) y AGG (ETF de bonos agregados de EE. UU.), misma fuente"],["Tipo libre de riesgo","número opcional que escribes tú; 0 % por defecto"]],"steps":["Descarga precios de tus 2–10 acciones más SPY y AGG y conviértelos en rentabilidades diarias.","Divide los días por la mitad; estima la matriz de covarianzas solo con la primera mitad.","Calcula los pesos de mínima varianza sin cortos a partir de esa covarianza.","Construye las tres carteras con pesos fijos y calcula sus rentabilidades diarias.","Informa de rentabilidad anual, volatilidad, Sharpe y caída máxima en la segunda mitad (fuera de muestra) y en el periodo completo."],"example":"Cartera de ejemplo con dos acciones a pesos iguales: un día la acción A sube un 2 % y la B baja un 1 %, así que la cartera gana 0,5 × 2 % + 0,5 × (−1 %) = 0,5 %. En 504 sesiones la cartera crece un factor 1,21, así que la rentabilidad anual = 1,21^(252 ÷ 504) − 1 = 1,1 − 1 = 10 %. Con volatilidad del 20 % y r_f = 0, Sharpe = (10 % − 0) ÷ 20 % = 0,5.","read":["Céntrate en las filas fuera de muestra: las del periodo completo incluyen la mitad usada para elegir los pesos, así que favorecen a la mezcla de mínima varianza.","Un Sharpe más alto significa más rentabilidad por unidad de volatilidad; diferencias de unas centésimas son ruido.","La mínima varianza debería mostrar normalmente la menor volatilidad; si fuera de muestra no lo hace, las correlaciones pasadas no se mantuvieron.","Si una acción recibe más del 40 % del peso de mínima varianza, la app avisa del riesgo de concentración."],"limits":["Un backtest no es una previsión; las volatilidades y correlaciones cambian, sobre todo en crisis.","Solo 2,5 años fuera de muestra: un único mercado alcista o bajista puede decidir la clasificación.","Sin costes de operación, y se supone reequilibrio diario en todas las mezclas; reequilibrar de verdad cuesta dinero.","Las acciones son las que cotizan hoy; faltan las que quebraron o dejaron de cotizar (sesgo de supervivencia), como avisa la app."]}},{"id":"turkey_fx","number":10,"group":"quant","group_label":"Quant","title":"Turkey: lira vs dollar returns","next":["crisis","beta","factors"],"en":{"question":"How much of a Turkish stock's lira gain is left after converting it to dollars, and how does the stock react when the lira weakens?","idea":"When the lira loses value, lira prices of many things rise, stocks included, even if nothing really improved. Dividing the lira price by the dollar exchange rate shows the return a dollar-based investor actually got. The \"FX beta\" measures how much the stock's lira price tends to rise in months when the dollar gets more expensive.","formulas":[{"name":"Dollar price and returns","expr":"P_USD = P_TRY ÷ USDTRY;   Return = P_end ÷ P_start − 1;   Annual = (1 + Return)^(1 ÷ years) − 1","where":[["P_TRY","adjusted closing price in lira"],["USDTRY","lira per dollar on the same day (last rate carried over Turkish holidays)"],["years","1, 3 or 5"]]},{"name":"FX beta (monthly)","expr":"β_FX = cov(r_stock, r_FX) ÷ var(r_FX)","where":[["r_stock","monthly lira return of the stock, month-end to month-end"],["r_FX","monthly % change of USD/TRY"],["β_FX","about 1: the stock rises with the dollar, so it is roughly flat in dollars; about 0: it ignores the exchange rate"]]},{"name":"Real return (only with a TCMB EVDS key)","expr":"Real return = (1 + lira return) ÷ (1 + CPI change) − 1","where":[["CPI change","change in the Turkish consumer price index (TCMB EVDS, TP.FG.J0) between the start and end months"]]}],"data":[["Stock and index prices","daily adjusted closes over 5 years for each BIST stock (Yahoo symbols ending in .IS) and the BIST 100 index (XU100.IS), adjusted for bonus issues and dividends"],["Exchange rate","USD/TRY daily rate from Yahoo Finance (USDTRY=X); latest value checked against the TCMB indicative rate if you have an EVDS key"],["Inflation (optional)","Turkish CPI from TCMB EVDS with your free personal key"],["Context","Damodaran's country risk premium for Turkey; optional foreign-currency revenue share you take from the company's KAP annual report"]],"steps":["Download 5 years of lira prices for your stocks, the BIST 100 and USD/TRY; carry the last exchange rate over Turkish holidays.","Convert every price to dollars by dividing by that day's USD/TRY.","Compute 1-, 3- and 5-year returns in lira and in dollars, the dollar return per year, and whether each stock beat the BIST 100 in dollars.","Compute the FX beta from monthly returns over the whole window (at least 24 months).","If an EVDS key is set, add CPI-adjusted real returns and the official-rate check; if you enter a foreign-currency revenue share, compare it with the beta."],"example":"Example company: over 3 years the lira price goes from 10 to 30, a +200% lira return. USD/TRY goes from 10 to 25 (+150%). The dollar price goes from 10 ÷ 10 = 1.00 to 30 ÷ 25 = 1.20, so the dollar return is +20%, or 1.2^(1 ÷ 3) − 1 ≈ 6.3% a year. If CPI rose 170%, the real return is 3.0 ÷ 2.7 − 1 ≈ 11.1%.","read":["A big lira return with a small or negative dollar return means most of the gain was the currency, not the business.","FX beta at 0.7 or above: in months the lira weakened the stock usually rose in lira (typical for exporters); near 0: it follows domestic conditions; below 0: it fell even in lira when the rate jumped (risk-off).","Check the correlation next to the beta: with a low correlation the beta is noisy and only a rough guide.","The real-return column says whether the lira gain beat Turkish inflation."],"limits":["Five years of monthly data is about 60 points, and the beta is one average over very different periods.","Without an EVDS key there is no inflation adjustment; the dollar view is only a rough check.","Exporters versus domestic companies is a rule of thumb; debt in foreign currency, costs and expectations also move the beta.","Past returns do not predict future returns; small, thinly traded BIST stocks can have noisy prices."]},"tr":{"question":"Bir Türk hissesinin TL kazancının ne kadarı dolara çevrildiğinde kalıyor ve TL değer kaybettiğinde hisse nasıl tepki veriyor?","idea":"TL değer kaybettiğinde, hisseler dahil pek çok şeyin TL fiyatı gerçekte hiçbir şey iyileşmese de yükselir. TL fiyatını dolar kuruna bölmek, dolar bazlı bir yatırımcının gerçekte ne kazandığını gösterir. \"Kur betası\", dolar pahalandığı aylarda hissenin TL fiyatının ne kadar yükselme eğiliminde olduğunu ölçer.","formulas":[{"name":"Dolar fiyatı ve getiriler","expr":"P_USD = P_TL ÷ USDTRY;   Getiri = P_son ÷ P_ilk − 1;   Yıllık = (1 + Getiri)^(1 ÷ yıl) − 1","where":[["P_TL","TL cinsinden düzeltilmiş kapanış fiyatı"],["USDTRY","aynı gün 1 doların TL karşılığı (Türkiye tatillerinde son kur taşınır)"],["yıl","1, 3 veya 5"]]},{"name":"Kur betası (aylık)","expr":"β_kur = kov(r_hisse, r_kur) ÷ var(r_kur)","where":[["r_hisse","hissenin ay sonundan ay sonuna aylık TL getirisi"],["r_kur","USD/TRY’nin aylık yüzde değişimi"],["β_kur","1’e yakın: hisse dolarla birlikte yükselir, dolar bazında kabaca yatay kalır; 0’a yakın: kura aldırmaz"]]},{"name":"Reel getiri (yalnızca TCMB EVDS anahtarıyla)","expr":"Reel getiri = (1 + TL getirisi) ÷ (1 + TÜFE değişimi) − 1","where":[["TÜFE değişimi","başlangıç ve bitiş ayları arasında Türkiye tüketici fiyat endeksindeki değişim (TCMB EVDS, TP.FG.J0)"]]}],"data":[["Hisse ve endeks fiyatları","her BIST hissesi (.IS ile biten Yahoo kodları) ve BIST 100 endeksi (XU100.IS) için 5 yıllık günlük düzeltilmiş kapanışlar; bedelsiz ve temettüye göre düzeltilmiş"],["Döviz kuru","Yahoo Finance’ten günlük USD/TRY kuru (USDTRY=X); EVDS anahtarın varsa son değer TCMB gösterge kuruyla karşılaştırılır"],["Enflasyon (isteğe bağlı)","ücretsiz kişisel anahtarınla TCMB EVDS’den Türkiye TÜFE’si"],["Bağlam","Damodaran’ın Türkiye ülke risk primi; şirketin KAP faaliyet raporundan alacağın isteğe bağlı döviz gelir payı"]],"steps":["Hisselerin, BIST 100’ün ve USD/TRY’nin 5 yıllık TL fiyatlarını indir; Türkiye tatillerinde son kuru taşı.","Her fiyatı o günün USD/TRY kuruna bölerek dolara çevir.","1, 3 ve 5 yıllık TL ve dolar getirilerini, yıllık dolar getirisini ve her hissenin dolar bazında BIST 100’ü geçip geçmediğini hesapla.","Kur betasını tüm pencere boyunca aylık getirilerden hesapla (en az 24 ay).","EVDS anahtarı varsa TÜFE’ye göre reel getiriyi ve resmî kur kontrolünü ekle; döviz gelir payı girersen onu beta ile karşılaştır."],"example":"Örnek şirket: 3 yılda TL fiyatı 10’dan 30’a çıkıyor, yani +%200 TL getirisi. USD/TRY 10’dan 25’e çıkıyor (+%150). Dolar fiyatı 10 ÷ 10 = 1,00’den 30 ÷ 25 = 1,20’ye çıkıyor; dolar getirisi +%20, yani yılda 1,2^(1 ÷ 3) − 1 ≈ %6,3. TÜFE %170 arttıysa reel getiri 3,0 ÷ 2,7 − 1 ≈ %11,1.","read":["Büyük bir TL getirisi küçük ya da negatif bir dolar getirisiyle birlikteyse, kazancın çoğu işin kendisinden değil kurdan gelmiş demektir.","Kur betası 0,7 ve üstü: TL’nin değer kaybettiği aylarda hisse genelde TL bazında yükselmiş (ihracatçılarda tipik); 0’a yakın: iç piyasa koşullarını izliyor; 0’ın altı: kur sıçradığında TL bazında bile düşmüş (risk-off).","Betanın yanındaki korelasyona bak: korelasyon düşükse beta gürültülüdür ve sadece kaba bir rehberdir.","Reel getiri sütunu, TL kazancının Türkiye enflasyonunu geçip geçmediğini söyler."],"limits":["Beş yıllık aylık veri yaklaşık 60 noktadır ve beta, çok farklı dönemlerin tek bir ortalamasıdır.","EVDS anahtarı olmadan enflasyon düzeltmesi yapılmaz; dolar bazı yalnızca kaba bir kontroldür.","İhracatçı / iç pazar ayrımı bir genel kuraldır; döviz borcu, maliyetler ve beklentiler de betayı etkiler.","Geçmiş getiriler gelecekteki getirileri göstermez; küçük, az işlem gören BIST hisselerinin fiyatları gürültülü olabilir."]},"es":{"question":"¿Cuánto de la ganancia en liras de una acción turca queda al pasarla a dólares, y cómo reacciona la acción cuando la lira se debilita?","idea":"Cuando la lira pierde valor, el precio en liras de muchas cosas sube, acciones incluidas, aunque nada haya mejorado de verdad. Dividir el precio en liras entre el tipo de cambio del dólar muestra lo que ganó realmente un inversor en dólares. La \"beta cambiaria\" mide cuánto suele subir el precio en liras de la acción en los meses en que el dólar se encarece.","formulas":[{"name":"Precio en dólares y rentabilidades","expr":"P_USD = P_TRY ÷ USDTRY;   Rentabilidad = P_final ÷ P_inicial − 1;   Anual = (1 + Rentabilidad)^(1 ÷ años) − 1","where":[["P_TRY","precio de cierre ajustado en liras"],["USDTRY","liras por dólar el mismo día (en festivos turcos se usa el último tipo)"],["años","1, 3 o 5"]]},{"name":"Beta cambiaria (mensual)","expr":"β_FX = cov(r_acción, r_FX) ÷ var(r_FX)","where":[["r_acción","rentabilidad mensual en liras de la acción, de fin de mes a fin de mes"],["r_FX","variación mensual en % del USD/TRY"],["β_FX","cerca de 1: la acción sube con el dólar, así que en dólares queda más o menos plana; cerca de 0: ignora el tipo de cambio"]]},{"name":"Rentabilidad real (solo con clave de TCMB EVDS)","expr":"Rentabilidad real = (1 + rentabilidad en liras) ÷ (1 + variación del IPC) − 1","where":[["variación del IPC","cambio del índice de precios al consumo turco (TCMB EVDS, TP.FG.J0) entre el mes inicial y el final"]]}],"data":[["Precios de acciones e índice","cierres diarios ajustados de 5 años para cada acción de BIST (símbolos de Yahoo terminados en .IS) y el índice BIST 100 (XU100.IS), ajustados por ampliaciones liberadas y dividendos"],["Tipo de cambio","USD/TRY diario de Yahoo Finance (USDTRY=X); si tienes clave de EVDS, el último valor se contrasta con el tipo indicativo del TCMB"],["Inflación (opcional)","IPC turco de TCMB EVDS con tu clave personal gratuita"],["Contexto","prima de riesgo país de Damodaran para Turquía; cuota opcional de ingresos en divisas que tomas del informe anual en KAP"]],"steps":["Descarga 5 años de precios en liras de tus acciones, del BIST 100 y del USD/TRY; en festivos turcos usa el último tipo de cambio.","Convierte cada precio a dólares dividiéndolo entre el USD/TRY de ese día.","Calcula rentabilidades a 1, 3 y 5 años en liras y en dólares, la rentabilidad anual en dólares y si cada acción batió al BIST 100 en dólares.","Calcula la beta cambiaria con rentabilidades mensuales de toda la ventana (al menos 24 meses).","Con clave de EVDS añade la rentabilidad real ajustada por IPC y el contraste con el tipo oficial; si introduces la cuota de ingresos en divisas, se compara con la beta."],"example":"Empresa de ejemplo: en 3 años el precio en liras pasa de 10 a 30, una rentabilidad de +200 % en liras. El USD/TRY pasa de 10 a 25 (+150 %). El precio en dólares va de 10 ÷ 10 = 1,00 a 30 ÷ 25 = 1,20, así que la rentabilidad en dólares es +20 %, o 1,2^(1 ÷ 3) − 1 ≈ 6,3 % al año. Si el IPC subió un 170 %, la rentabilidad real es 3,0 ÷ 2,7 − 1 ≈ 11,1 %.","read":["Una gran rentabilidad en liras con una rentabilidad en dólares pequeña o negativa significa que casi toda la ganancia vino de la divisa, no del negocio.","Beta cambiaria de 0,7 o más: en los meses en que la lira se debilitó, la acción solía subir en liras (típico de exportadoras); cerca de 0: sigue la situación interna; por debajo de 0: cayó incluso en liras cuando el tipo saltó (aversión al riesgo).","Mira la correlación junto a la beta: con una correlación baja la beta es ruidosa y solo sirve de guía aproximada.","La columna de rentabilidad real indica si la ganancia en liras superó a la inflación turca."],"limits":["Cinco años de datos mensuales son unos 60 puntos, y la beta es una sola media de periodos muy distintos.","Sin clave de EVDS no hay ajuste por inflación; la vista en dólares es solo un control aproximado.","Exportadora frente a empresa doméstica es una regla general; la deuda en divisas, los costes y las expectativas también mueven la beta.","Las rentabilidades pasadas no predicen las futuras; las acciones pequeñas y poco negociadas de BIST pueden tener precios ruidosos."]}},{"id":"dupont","number":11,"group":"fundamental","group_label":"Fundamentals","title":"DuPont analysis","next":["roic_wacc","credit_altman","earnings_quality"],"en":{"question":"Is the company's return on equity driven by its profit margin, by how efficiently it uses its assets, or by debt?","idea":"ROE (return on equity) tells you how much profit the company makes for each dollar its shareholders have in the business. The DuPont method splits ROE into three parts that multiply together: how much of each sale is profit, how many sales each dollar of assets produces, and how many dollars of assets are financed by each dollar of equity (the rest is debt and other liabilities). The same ROE can come from very different businesses, and this split shows which part is doing the work.","formulas":[{"name":"DuPont identity","expr":"ROE = Net margin × Asset turnover × Equity multiplier","where":[["ROE","return on equity, percent"]]},{"name":"The three parts","expr":"Net margin = Net income ÷ Revenue; Asset turnover = Revenue ÷ Average total assets; Equity multiplier = Average total assets ÷ Average equity","where":[["Net margin","percent of revenue left as net profit"],["Asset turnover","dollars of revenue per dollar of assets (×)"],["Equity multiplier","dollars of assets per dollar of shareholders' equity (×); higher means more financed by liabilities"]]},{"name":"Averages","expr":"Average X = (X at the end of the previous fiscal year + X at the end of this fiscal year) ÷ 2","where":[["X","total assets or shareholders' equity (USD millions)"]]},{"name":"Result","expr":"ROE = Net income ÷ Average equity × 100","where":[["Net income","this fiscal year's profit (USD millions)"]]}],"data":[["Net income","10-K income statement (XBRL us-gaap:NetIncomeLoss, else ProfitLoss)"],["Revenue","10-K income statement (us-gaap:RevenueFromContractWithCustomerExcludingAssessedTax, else …IncludingAssessedTax, Revenues, SalesRevenueNet or RevenuesNetOfInterestExpense)"],["Total assets","10-K balance sheet at each fiscal year end (us-gaap:Assets)"],["Shareholders' equity","10-K balance sheet at each fiscal year end (us-gaap:StockholdersEquity, else StockholdersEquityIncludingPortionAttributableToNoncontrollingInterest)"]],"steps":["Read up to six fiscal years of annual SEC data for one company.","For each year that has a previous year, average the opening and closing total assets and equity.","Compute net margin, asset turnover and equity multiplier, and multiply them to get ROE.","Compare the first and last years with a full breakdown, report how ROE changed, and name the part whose value changed the most in relative terms.","Add a note if the latest equity multiplier is above 4, since part of a high ROE may then come from leverage."],"example":"Example company: net income 100, revenue 1,000, total assets 1,800 last year and 2,200 this year, equity 450 last year and 550 this year (USD millions). Average assets = 2,000; average equity = 500. Net margin = 100 ÷ 1,000 = 10%. Asset turnover = 1,000 ÷ 2,000 = 0.5×. Equity multiplier = 2,000 ÷ 500 = 4.0×. ROE = 10% × 0.5 × 4.0 = 20%, the same as 100 ÷ 500.","read":["A rising ROE driven by net margin suggests the business is keeping more profit from each sale.","A rising ROE driven by asset turnover suggests the company is getting more sales out of the same assets.","A rising ROE driven by the equity multiplier means more of the business is financed by debt and other liabilities; it lifts ROE but also adds risk, and the app adds a note when the multiplier is above 4.","Typical values differ by industry: retailers often have thin margins and high turnover, software firms the reverse, so compare a company with its own past or with close peers."],"limits":["With negative or very small equity (for example after large share buybacks) the multiplier and ROE lose their meaning; the code still prints the numbers, so check the equity figure.","The first loaded year has no opening balance, so it gets no row; missing assets or equity in a year leave that row blank.","Net income includes one-off items (asset sales, write-downs, tax changes), which can move ROE in a single year.","The 'biggest driver' compares only the first and last full years and ignores what happened in between."]},"tr":{"question":"Şirketin özkaynak kârlılığı kâr marjından mı, varlıkları ne kadar verimli kullandığından mı, yoksa borçtan mı geliyor?","idea":"ROE (özkaynak kârlılığı), hissedarların işe koyduğu her 1 dolar için şirketin ne kadar kâr ettiğini söyler. DuPont yöntemi ROE'yi birbiriyle çarpılan üç parçaya ayırır: her satışın ne kadarı kâr, her 1 dolarlık varlık ne kadar satış üretiyor ve her 1 dolarlık özkaynağa karşılık kaç dolarlık varlık var (gerisi borç ve diğer yükümlülüklerle finanse edilir). Aynı ROE çok farklı işlerden gelebilir; bu ayrıştırma işi hangi parçanın yaptığını gösterir.","formulas":[{"name":"DuPont eşitliği","expr":"ROE = Net kâr marjı × Varlık devir hızı × Özkaynak çarpanı","where":[["ROE","özkaynak kârlılığı, yüzde"]]},{"name":"Üç parça","expr":"Net kâr marjı = Net kâr ÷ Gelir; Varlık devir hızı = Gelir ÷ Ortalama toplam varlık; Özkaynak çarpanı = Ortalama toplam varlık ÷ Ortalama özkaynak","where":[["Net kâr marjı","gelirin net kâr olarak kalan yüzdesi"],["Varlık devir hızı","1 dolarlık varlık başına gelir (×)"],["Özkaynak çarpanı","1 dolarlık özkaynak başına varlık (×); yüksekse varlıkların daha çoğu yükümlülüklerle finanse edilmiştir"]]},{"name":"Ortalamalar","expr":"Ortalama X = (önceki mali yıl sonundaki X + bu mali yıl sonundaki X) ÷ 2","where":[["X","toplam varlık veya özkaynak (milyon USD)"]]},{"name":"Sonuç","expr":"ROE = Net kâr ÷ Ortalama özkaynak × 100","where":[["Net kâr","bu mali yılın kârı (milyon USD)"]]}],"data":[["Net kâr","10-K gelir tablosu (XBRL us-gaap:NetIncomeLoss, yoksa ProfitLoss)"],["Gelir","10-K gelir tablosu (us-gaap:RevenueFromContractWithCustomerExcludingAssessedTax, yoksa …IncludingAssessedTax, Revenues, SalesRevenueNet veya RevenuesNetOfInterestExpense)"],["Toplam varlık","her mali yıl sonundaki 10-K bilançosu (us-gaap:Assets)"],["Özkaynak","her mali yıl sonundaki 10-K bilançosu (us-gaap:StockholdersEquity, yoksa StockholdersEquityIncludingPortionAttributableToNoncontrollingInterest)"]],"steps":["Bir şirket için en fazla altı mali yıllık SEC yıllık verisini yükle.","Önceki yılı olan her yıl için yıl başı ve yıl sonu toplam varlık ile özkaynağın ortalamasını al.","Net kâr marjını, varlık devir hızını ve özkaynak çarpanını hesapla ve çarparak ROE'yi bul.","Tam ayrıştırması olan ilk ve son yılı karşılaştır, ROE'nin nasıl değiştiğini ve göreli olarak en çok değişen parçayı raporla.","Son yılın özkaynak çarpanı 4'ün üstündeyse not ekle; bu durumda yüksek ROE'nin bir kısmı borçtan geliyor olabilir."],"example":"Örnek şirket: net kâr 100, gelir 1.000, toplam varlık geçen yıl 1.800 ve bu yıl 2.200, özkaynak geçen yıl 450 ve bu yıl 550 (milyon USD). Ortalama varlık = 2.000; ortalama özkaynak = 500. Net kâr marjı = 100 ÷ 1.000 = %10. Varlık devir hızı = 1.000 ÷ 2.000 = 0,5×. Özkaynak çarpanı = 2.000 ÷ 500 = 4,0×. ROE = %10 × 0,5 × 4,0 = %20; bu, 100 ÷ 500 ile aynıdır.","read":["Net kâr marjının sürüklediği bir ROE artışı, işin her satıştan daha fazla kâr tuttuğunu düşündürür.","Varlık devir hızının sürüklediği bir ROE artışı, şirketin aynı varlıklardan daha fazla satış çıkardığını düşündürür.","Özkaynak çarpanının sürüklediği bir ROE artışı, işin daha büyük kısmının borç ve diğer yükümlülüklerle finanse edildiği anlamına gelir; ROE'yi yükseltir ama riski de artırır. Çarpan 4'ün üstündeyse uygulama not ekler.","Tipik değerler sektöre göre değişir: perakendecilerde marj düşük, devir hızı yüksek olur; yazılım şirketlerinde tersi. Şirketi kendi geçmişiyle veya yakın rakipleriyle karşılaştır."],"limits":["Özkaynak negatif veya çok küçükse (ör. büyük hisse geri alımlarından sonra) çarpan ve ROE anlamını yitirir; kod yine de rakamları yazar, bu yüzden özkaynak rakamını kontrol et.","Yüklenen ilk yılın yıl başı bakiyesi olmadığı için satırı yoktur; bir yılda varlık veya özkaynak eksikse o satır boş kalır.","Net kâr tek seferlik kalemleri (varlık satışı, değer düşüklüğü, vergi değişikliği) içerir; bunlar tek bir yılda ROE'yi oynatabilir.","'En büyük kaynak' sadece tam verili ilk ve son yılı karşılaştırır, aradakileri dikkate almaz."]},"es":{"question":"¿La rentabilidad sobre el patrimonio de la empresa viene de su margen, de lo eficiente que usa sus activos o de la deuda?","idea":"El ROE (rentabilidad sobre el patrimonio) te dice cuánto beneficio obtiene la empresa por cada dólar que sus accionistas tienen en el negocio. El método DuPont divide el ROE en tres partes que se multiplican: cuánto de cada venta es beneficio, cuántas ventas produce cada dólar de activos y cuántos dólares de activos se financian con cada dólar de patrimonio (el resto es deuda y otros pasivos). El mismo ROE puede venir de negocios muy distintos, y esta división muestra qué parte hace el trabajo.","formulas":[{"name":"Identidad DuPont","expr":"ROE = Margen neto × Rotación de activos × Multiplicador del patrimonio","where":[["ROE","rentabilidad sobre el patrimonio, porcentaje"]]},{"name":"Las tres partes","expr":"Margen neto = Beneficio neto ÷ Ingresos; Rotación de activos = Ingresos ÷ Activo total promedio; Multiplicador del patrimonio = Activo total promedio ÷ Patrimonio promedio","where":[["Margen neto","porcentaje de los ingresos que queda como beneficio neto"],["Rotación de activos","dólares de ingresos por dólar de activos (×)"],["Multiplicador del patrimonio","dólares de activos por dólar de patrimonio (×); más alto significa más financiación con pasivos"]]},{"name":"Promedios","expr":"X promedio = (X al cierre del año fiscal anterior + X al cierre de este año fiscal) ÷ 2","where":[["X","activo total o patrimonio de los accionistas (millones de USD)"]]},{"name":"Resultado","expr":"ROE = Beneficio neto ÷ Patrimonio promedio × 100","where":[["Beneficio neto","beneficio de este año fiscal (millones de USD)"]]}],"data":[["Beneficio neto","cuenta de resultados del 10-K (XBRL us-gaap:NetIncomeLoss, o ProfitLoss)"],["Ingresos","cuenta de resultados del 10-K (us-gaap:RevenueFromContractWithCustomerExcludingAssessedTax, o …IncludingAssessedTax, Revenues, SalesRevenueNet o RevenuesNetOfInterestExpense)"],["Activo total","balance del 10-K en cada cierre fiscal (us-gaap:Assets)"],["Patrimonio de los accionistas","balance del 10-K en cada cierre fiscal (us-gaap:StockholdersEquity, o StockholdersEquityIncludingPortionAttributableToNoncontrollingInterest)"]],"steps":["Cargar hasta seis años fiscales de datos anuales de la SEC de una empresa.","Para cada año que tenga un año anterior, promediar el activo total y el patrimonio de apertura y de cierre.","Calcular el margen neto, la rotación de activos y el multiplicador del patrimonio, y multiplicarlos para obtener el ROE.","Comparar el primer y el último año con desglose completo, indicar cómo cambió el ROE y nombrar la parte que más cambió en términos relativos.","Añadir una nota si el último multiplicador del patrimonio supera 4, porque entonces parte de un ROE alto puede venir del apalancamiento."],"example":"Empresa de ejemplo: beneficio neto 100, ingresos 1.000, activo total 1.800 el año pasado y 2.200 este año, patrimonio 450 el año pasado y 550 este año (millones de USD). Activo promedio = 2.000; patrimonio promedio = 500. Margen neto = 100 ÷ 1.000 = 10 %. Rotación de activos = 1.000 ÷ 2.000 = 0,5×. Multiplicador del patrimonio = 2.000 ÷ 500 = 4,0×. ROE = 10 % × 0,5 × 4,0 = 20 %, igual que 100 ÷ 500.","read":["Un ROE que sube por el margen neto sugiere que el negocio retiene más beneficio de cada venta.","Un ROE que sube por la rotación de activos sugiere que la empresa saca más ventas de los mismos activos.","Un ROE que sube por el multiplicador del patrimonio significa que una parte mayor del negocio se financia con deuda y otros pasivos; eleva el ROE pero también añade riesgo, y la app añade una nota cuando el multiplicador supera 4.","Los valores típicos varían según el sector: los minoristas suelen tener márgenes finos y rotación alta, las empresas de software lo contrario; compara la empresa con su propio pasado o con competidores cercanos."],"limits":["Con un patrimonio negativo o muy pequeño (por ejemplo, tras grandes recompras de acciones) el multiplicador y el ROE pierden sentido; el código igualmente muestra las cifras, así que revisa el patrimonio.","El primer año cargado no tiene saldo de apertura, así que no tiene fila; si faltan activos o patrimonio en un año, esa fila queda vacía.","El beneficio neto incluye partidas puntuales (ventas de activos, deterioros, cambios fiscales), que pueden mover el ROE en un solo año.","El 'factor principal' compara solo el primer y el último año completos e ignora lo que pasó en medio."]}},{"id":"cash_cycle","number":12,"group":"fundamental","group_label":"Fundamentals","title":"Cash conversion cycle","next":["earnings_quality","capital_allocation","dupont"],"en":{"question":"How many days is a company's cash tied up between paying for its goods and getting paid by its customers?","idea":"A shop buys stock, keeps it on the shelf for a while, sells it, and then may wait for the customer to pay. Meanwhile it can delay paying its own suppliers. The cash conversion cycle adds up the days cash is stuck in unpaid customer bills and in inventory, and subtracts the days the company itself takes to pay suppliers. Fewer days means less cash is needed to run the business; a negative number means customers pay before suppliers have to be paid.","formulas":[{"name":"Days sales outstanding (DSO)","expr":"DSO = Average receivables ÷ Revenue × 365","where":[["Average receivables","(accounts receivable at the start + at the end of the latest fiscal year) ÷ 2 (USD millions)"],["Revenue","latest fiscal year's sales (USD millions)"],["DSO","days it takes on average to collect from customers"]]},{"name":"Days inventory outstanding (DIO)","expr":"DIO = Average inventory ÷ Cost of sales × 365","where":[["Cost of sales","cost of goods or services sold in the latest fiscal year (USD millions)"],["DIO","days goods sit in inventory"]]},{"name":"Days payables outstanding (DPO)","expr":"DPO = Average payables ÷ Cost of sales × 365","where":[["Average payables","average accounts payable to suppliers (USD millions)"],["DPO","days the company takes to pay its suppliers"]]},{"name":"Cash conversion cycle (CCC)","expr":"CCC = DSO + DIO − DPO","where":[["CCC","days; computed only when all three parts are available"]]}],"data":[["Revenue","10-K income statement (XBRL us-gaap:RevenueFromContractWithCustomerExcludingAssessedTax, else …IncludingAssessedTax, Revenues, SalesRevenueNet or RevenuesNetOfInterestExpense)"],["Cost of sales","10-K income statement (us-gaap:CostOfRevenue, else CostOfGoodsAndServicesSold, CostOfGoodsSold or CostOfGoodsAndServiceExcludingDepreciationDepletionAndAmortization)"],["Receivables","10-K balance sheet, last two year ends (us-gaap:AccountsReceivableNetCurrent, else ReceivablesNetCurrent)"],["Inventory","10-K balance sheet, last two year ends (us-gaap:InventoryNet)"],["Payables","10-K balance sheet, last two year ends (us-gaap:AccountsPayableCurrent, else AccountsPayableAndAccruedLiabilitiesCurrent)"]],"steps":["Load annual SEC data for 1 to 5 companies and take the latest fiscal year.","Average receivables, inventory and payables over the previous and latest year ends (the latest figure alone if there is no previous year).","Compute DSO from revenue, and DIO and DPO from cost of sales, each times 365.","Add DSO and DIO and subtract DPO to get the cash conversion cycle; if any piece is missing, the cycle is left blank and the app says why.","Show the days in a table and the cycles in a bar chart, explaining any negative cycle."],"example":"Example company: revenue 3,650, cost of sales 2,920, average receivables 300, average inventory 400, average payables 480 (USD millions). DSO = 300 ÷ 3,650 × 365 = 30 days. DIO = 400 ÷ 2,920 × 365 = 50 days. DPO = 480 ÷ 2,920 × 365 = 60 days. CCC = 30 + 50 − 60 = 20 days.","read":["A shorter cycle means less cash is locked up in running the business; a lengthening cycle over time means more working capital is needed for the same sales.","A negative cycle (common in big-box retail and some online sellers) means the company collects from customers before it pays suppliers, so suppliers partly finance its operations.","Look at which part moves: rising DSO can mean slower-paying customers, rising DIO can mean unsold stock, rising DPO can mean the company is stretching its suppliers.","Compare companies in the same industry; a grocer and a machinery maker naturally have very different cycles."],"limits":["Only the latest fiscal year is calculated; year-end balances may not represent the rest of the year, especially for seasonal businesses.","DSO uses total revenue, not only sales made on credit, and the payables fallback tag (AccountsPayableAndAccruedLiabilitiesCurrent) includes other accrued bills, which makes DPO look longer.","Service and software companies carry little or no inventory; if inventory or cost of sales is not reported, the cycle is not computed at all.","A very negative cycle is not automatically good: it can also mean the company is paying suppliers slowly in a way that may not last."]},"tr":{"question":"Şirketin nakdi, mallarının parasını ödemesiyle müşterilerinden tahsilat yapması arasında kaç gün bağlı kalıyor?","idea":"Bir mağaza stok alır, bir süre rafta tutar, satar ve sonra müşterinin ödemesini bekleyebilir. Bu arada kendi tedarikçilerine ödemeyi geciktirebilir. Nakit dönüşüm döngüsü, nakdin ödenmemiş müşteri faturalarında ve stokta takılı kaldığı günleri toplar ve şirketin tedarikçilerine ödemek için aldığı günleri çıkarır. Daha az gün, işi döndürmek için daha az nakit gerekmesi demektir; negatif sayı ise müşterilerin, tedarikçilere ödeme yapılmadan önce ödediğini gösterir.","formulas":[{"name":"Alacak tahsil süresi (DSO)","expr":"DSO = Ortalama alacaklar ÷ Gelir × 365","where":[["Ortalama alacaklar","(son mali yıl başındaki ticari alacaklar + yıl sonundaki) ÷ 2 (milyon USD)"],["Gelir","son mali yılın satışları (milyon USD)"],["DSO","müşterilerden tahsilatın ortalama kaç gün sürdüğü"]]},{"name":"Stok devir süresi (DIO)","expr":"DIO = Ortalama stok ÷ Satılan malın maliyeti × 365","where":[["Satılan malın maliyeti","son mali yılda satılan mal veya hizmetin maliyeti (milyon USD)"],["DIO","malların stokta kaldığı gün sayısı"]]},{"name":"Borç ödeme süresi (DPO)","expr":"DPO = Ortalama ticari borçlar ÷ Satılan malın maliyeti × 365","where":[["Ortalama ticari borçlar","tedarikçilere olan ortalama borç (milyon USD)"],["DPO","şirketin tedarikçilerine ödemek için aldığı gün sayısı"]]},{"name":"Nakit dönüşüm döngüsü (CCC)","expr":"CCC = DSO + DIO − DPO","where":[["CCC","gün; sadece üç parçanın hepsi varsa hesaplanır"]]}],"data":[["Gelir","10-K gelir tablosu (XBRL us-gaap:RevenueFromContractWithCustomerExcludingAssessedTax, yoksa …IncludingAssessedTax, Revenues, SalesRevenueNet veya RevenuesNetOfInterestExpense)"],["Satılan malın maliyeti","10-K gelir tablosu (us-gaap:CostOfRevenue, yoksa CostOfGoodsAndServicesSold, CostOfGoodsSold veya CostOfGoodsAndServiceExcludingDepreciationDepletionAndAmortization)"],["Ticari alacaklar","10-K bilançosu, son iki yıl sonu (us-gaap:AccountsReceivableNetCurrent, yoksa ReceivablesNetCurrent)"],["Stoklar","10-K bilançosu, son iki yıl sonu (us-gaap:InventoryNet)"],["Ticari borçlar","10-K bilançosu, son iki yıl sonu (us-gaap:AccountsPayableCurrent, yoksa AccountsPayableAndAccruedLiabilitiesCurrent)"]],"steps":["1 ile 5 şirket için SEC yıllık verisini yükle ve son mali yılı al.","Alacakların, stokların ve ticari borçların önceki ve son yıl sonu ortalamasını al (önceki yıl yoksa sadece son rakam).","DSO'yu gelirden, DIO ve DPO'yu satılan malın maliyetinden hesapla; her birini 365 ile çarp.","DSO ile DIO'yu topla, DPO'yu çıkar ve nakit dönüşüm döngüsünü bul; bir parça eksikse döngü boş kalır ve uygulama nedenini söyler.","Günleri tabloda ve döngüleri çubuk grafikte göster; negatif bir döngüyü açıkla."],"example":"Örnek şirket: gelir 3.650, satılan malın maliyeti 2.920, ortalama alacak 300, ortalama stok 400, ortalama ticari borç 480 (milyon USD). DSO = 300 ÷ 3.650 × 365 = 30 gün. DIO = 400 ÷ 2.920 × 365 = 50 gün. DPO = 480 ÷ 2.920 × 365 = 60 gün. CCC = 30 + 50 − 60 = 20 gün.","read":["Daha kısa döngü, işi döndürmek için daha az nakdin bağlandığı anlamına gelir; zamanla uzayan döngü aynı satış için daha fazla işletme sermayesi gerektiğini gösterir.","Negatif döngü (büyük perakendecilerde ve bazı internet satıcılarında yaygın), şirketin tedarikçilere ödemeden önce müşteriden tahsil ettiği anlamına gelir; yani tedarikçiler faaliyetleri kısmen finanse eder.","Hangi parçanın değiştiğine bak: artan DSO müşterilerin daha geç ödediğini, artan DIO satılmayan stoğu, artan DPO şirketin tedarikçilerini beklettiğini gösterebilir.","Aynı sektördeki şirketleri karşılaştır; bir market zinciriyle bir makine üreticisinin döngüleri doğal olarak çok farklıdır."],"limits":["Sadece son mali yıl hesaplanır; yıl sonu bakiyeleri, özellikle mevsimsel işlerde, yılın geri kalanını temsil etmeyebilir.","DSO sadece vadeli satışları değil toplam geliri kullanır; ticari borç için yedek etiket (AccountsPayableAndAccruedLiabilitiesCurrent) diğer tahakkuk etmiş giderleri de içerir ve DPO'yu uzun gösterir.","Hizmet ve yazılım şirketlerinde stok çok azdır veya yoktur; stok veya satılan malın maliyeti raporlanmıyorsa döngü hiç hesaplanmaz.","Çok negatif bir döngü otomatik olarak iyi değildir: şirketin tedarikçilere sürdürülemeyecek kadar geç ödediği anlamına da gelebilir."]},"es":{"question":"¿Cuántos días queda atrapado el efectivo de una empresa entre pagar sus mercancías y cobrar a sus clientes?","idea":"Una tienda compra existencias, las tiene un tiempo en la estantería, las vende y luego puede esperar a que el cliente pague. Mientras tanto puede retrasar el pago a sus propios proveedores. El ciclo de conversión de efectivo suma los días que el efectivo está atrapado en facturas de clientes sin cobrar y en inventario, y resta los días que la empresa tarda en pagar a sus proveedores. Menos días significa que se necesita menos efectivo para funcionar; un número negativo significa que los clientes pagan antes de que haya que pagar a los proveedores.","formulas":[{"name":"Periodo medio de cobro (DSO)","expr":"DSO = Cuentas por cobrar promedio ÷ Ingresos × 365","where":[["Cuentas por cobrar promedio","(cuentas por cobrar al inicio + al final del último año fiscal) ÷ 2 (millones de USD)"],["Ingresos","ventas del último año fiscal (millones de USD)"],["DSO","días que tarda en promedio en cobrar a los clientes"]]},{"name":"Días de inventario (DIO)","expr":"DIO = Inventario promedio ÷ Coste de ventas × 365","where":[["Coste de ventas","coste de los bienes o servicios vendidos en el último año fiscal (millones de USD)"],["DIO","días que la mercancía pasa en inventario"]]},{"name":"Periodo medio de pago (DPO)","expr":"DPO = Cuentas por pagar promedio ÷ Coste de ventas × 365","where":[["Cuentas por pagar promedio","deuda promedio con proveedores (millones de USD)"],["DPO","días que la empresa tarda en pagar a sus proveedores"]]},{"name":"Ciclo de conversión de efectivo (CCC)","expr":"CCC = DSO + DIO − DPO","where":[["CCC","días; solo se calcula cuando están las tres partes"]]}],"data":[["Ingresos","cuenta de resultados del 10-K (XBRL us-gaap:RevenueFromContractWithCustomerExcludingAssessedTax, o …IncludingAssessedTax, Revenues, SalesRevenueNet o RevenuesNetOfInterestExpense)"],["Coste de ventas","cuenta de resultados del 10-K (us-gaap:CostOfRevenue, o CostOfGoodsAndServicesSold, CostOfGoodsSold o CostOfGoodsAndServiceExcludingDepreciationDepletionAndAmortization)"],["Cuentas por cobrar","balance del 10-K, últimos dos cierres (us-gaap:AccountsReceivableNetCurrent, o ReceivablesNetCurrent)"],["Inventario","balance del 10-K, últimos dos cierres (us-gaap:InventoryNet)"],["Cuentas por pagar","balance del 10-K, últimos dos cierres (us-gaap:AccountsPayableCurrent, o AccountsPayableAndAccruedLiabilitiesCurrent)"]],"steps":["Cargar los datos anuales de la SEC de 1 a 5 empresas y tomar el último año fiscal.","Promediar cuentas por cobrar, inventario y cuentas por pagar entre el cierre anterior y el último (solo la última cifra si no hay año anterior).","Calcular el DSO con los ingresos, y el DIO y el DPO con el coste de ventas, cada uno multiplicado por 365.","Sumar DSO y DIO y restar DPO para obtener el ciclo de conversión de efectivo; si falta alguna pieza, el ciclo queda vacío y la app explica por qué.","Mostrar los días en una tabla y los ciclos en un gráfico de barras, explicando cualquier ciclo negativo."],"example":"Empresa de ejemplo: ingresos 3.650, coste de ventas 2.920, cuentas por cobrar promedio 300, inventario promedio 400, cuentas por pagar promedio 480 (millones de USD). DSO = 300 ÷ 3.650 × 365 = 30 días. DIO = 400 ÷ 2.920 × 365 = 50 días. DPO = 480 ÷ 2.920 × 365 = 60 días. CCC = 30 + 50 − 60 = 20 días.","read":["Un ciclo más corto significa que hay menos efectivo inmovilizado en el negocio; un ciclo que se alarga con el tiempo significa que hace falta más capital de trabajo para las mismas ventas.","Un ciclo negativo (habitual en grandes superficies y algunos vendedores online) significa que la empresa cobra a los clientes antes de pagar a los proveedores, así que los proveedores financian en parte sus operaciones.","Mira qué parte se mueve: un DSO creciente puede indicar clientes que pagan más tarde, un DIO creciente existencias sin vender, un DPO creciente que la empresa estira los pagos a proveedores.","Compara empresas del mismo sector; un supermercado y un fabricante de maquinaria tienen ciclos naturalmente muy distintos."],"limits":["Solo se calcula el último año fiscal; los saldos de cierre pueden no representar el resto del año, sobre todo en negocios estacionales.","El DSO usa los ingresos totales, no solo las ventas a crédito, y la etiqueta alternativa de cuentas por pagar (AccountsPayableAndAccruedLiabilitiesCurrent) incluye otros gastos devengados, lo que alarga el DPO.","Las empresas de servicios y software tienen poco o ningún inventario; si no se publica el inventario o el coste de ventas, el ciclo no se calcula.","Un ciclo muy negativo no es automáticamente bueno: también puede significar que la empresa paga tarde a sus proveedores de una forma que quizá no dure."]}},{"id":"capital_allocation","number":13,"group":"fundamental","group_label":"Fundamentals","title":"Capital allocation","next":["roic_wacc","earnings_quality","dcf"],"en":{"question":"Over the last five years, where did the cash the company generated actually go?","idea":"A business that makes cash from its operations has to decide what to do with it: invest in new equipment, buy other companies, pay down debt, or hand it back to shareholders as dividends or share buybacks. The cash-flow statement records the cash actually paid for each of these. This analysis adds them up over five years and compares each one with the operating cash flow that funded it.","formulas":[{"name":"Free cash flow (FCF)","expr":"FCF = CFO − Capital expenditure (each year), then summed over 5 years","where":[["CFO","cash flow from operations (USD millions)"],["Capital expenditure","cash paid for property, plant and equipment, capex (USD millions)"],["FCF","free cash flow (USD millions)"]]},{"name":"Share of operating cash flow","expr":"Share of CFO = 5-year total of a use ÷ 5-year total CFO × 100","where":[["use","capex, share buybacks, dividends, acquisitions or debt repaid (USD millions)"],["Share of CFO","percent; the shares can add up to more or less than 100%"]]},{"name":"Returned to shareholders","expr":"Returned = Buybacks + Dividends; Returned ÷ FCF × 100 (only when FCF > 0)","where":[["Returned","5-year total cash paid to shareholders (USD millions)"]]},{"name":"Change in share count","expr":"Share change = (Diluted shares, last year ÷ Diluted shares, first year − 1) × 100","where":[["Diluted shares","weighted average diluted shares, adjusted for stock splits"],["Share change","percent; negative means fewer shares"]]}],"data":[["Operating cash flow","10-K cash-flow statement (XBRL us-gaap:NetCashProvidedByUsedInOperatingActivities)"],["Capital expenditure","10-K cash-flow statement (us-gaap:PaymentsToAcquirePropertyPlantAndEquipment, else PaymentsToAcquireProductiveAssets)"],["Share buybacks","10-K cash-flow statement (us-gaap:PaymentsForRepurchaseOfCommonStock)"],["Dividends","10-K cash-flow statement (us-gaap:PaymentsOfDividends, else PaymentsOfDividendsCommonStock)"],["Acquisitions","10-K cash-flow statement (us-gaap:PaymentsToAcquireBusinessesNetOfCashAcquired)"],["Debt repaid","10-K cash-flow statement (us-gaap:RepaymentsOfLongTermDebt)"],["Diluted shares","10-K income statement (us-gaap:WeightedAverageNumberOfDilutedSharesOutstanding)"]],"steps":["Take the last five fiscal years of annual SEC data for one company.","Compute free cash flow each year as CFO − capex.","Add up each item over the five years, using only the years in which it was reported; an item never reported shows as “—”.","Divide each use by the total operating cash flow, and buybacks + dividends by total free cash flow when FCF is positive.","Compare the diluted share count in the last year with the first, after restating older years when a jump looks like a stock split.","Show a 5-year table, a year-by-year table and a bar chart of the uses."],"example":"Example company, 5-year totals (USD millions): CFO 1,000, capex 300, buybacks 350, dividends 210. FCF = 1,000 − 300 = 700. Capex = 300 ÷ 1,000 = 30% of CFO, buybacks 35%, dividends 21%. Returned to shareholders = 350 + 210 = 560, which is 560 ÷ 700 = 80% of FCF. Diluted shares went from 100 to 95 million: 95 ÷ 100 − 1 = −5%.","read":["A high capex share suggests a business that needs heavy reinvestment to keep running or to grow.","Large buybacks and dividends relative to FCF show a company returning most of its spare cash; above 100% means it also used cash on hand or borrowing.","A falling diluted share count means buybacks more than offset new shares issued (for example to employees); a rising one means existing owners are being diluted.","Big acquisitions can explain a jump in debt or goodwill elsewhere in the accounts."],"limits":["Only the listed items are tracked: new borrowing, share issuance, investments in securities and changes in cash are not shown, so the uses need not add up to 100% of CFO.","Items are summed over the years they were reported, so a tag that is missing in some years makes that total smaller than reality.","Buybacks and dividends are cash actually paid, not announced programmes; buybacks partly used to offset employee share grants still count in full.","The split adjustment for share counts is a rule of thumb (a jump close to 2×, 3×, 4×, … is treated as a split) and could misread an unusual change."]},"tr":{"question":"Son beş yılda şirketin ürettiği nakit gerçekte nereye gitti?","idea":"Faaliyetlerinden nakit üreten bir şirket bu nakitle ne yapacağına karar vermek zorundadır: yeni ekipmana yatırım, başka şirketleri satın alma, borç ödeme ya da temettü veya hisse geri alımıyla hissedarlara geri verme. Nakit akış tablosu bunların her biri için gerçekten ödenen nakdi kaydeder. Bu analiz bunları beş yıl boyunca toplar ve her birini onu finanse eden işletme nakit akışıyla karşılaştırır.","formulas":[{"name":"Serbest nakit akışı (SNA)","expr":"SNA = İNA − Yatırım harcaması (her yıl), sonra 5 yıl boyunca toplanır","where":[["İNA (CFO)","işletme faaliyetlerinden nakit akışı (milyon USD)"],["Yatırım harcaması","maddi duran varlıklar için ödenen nakit, capex (milyon USD)"],["SNA (FCF)","serbest nakit akışı (milyon USD)"]]},{"name":"İşletme nakit akışı içindeki pay","expr":"İNA payı = Bir kullanımın 5 yıllık toplamı ÷ 5 yıllık toplam İNA × 100","where":[["kullanım","yatırım harcaması, hisse geri alımı, temettü, satın almalar veya borç geri ödemesi (milyon USD)"],["İNA payı","yüzde; paylar toplamda %100'den fazla veya az olabilir"]]},{"name":"Hissedarlara dönen","expr":"Dönen = Geri alım + Temettü; Dönen ÷ SNA × 100 (sadece SNA > 0 ise)","where":[["Dönen","hissedarlara ödenen 5 yıllık toplam nakit (milyon USD)"]]},{"name":"Hisse sayısındaki değişim","expr":"Hisse değişimi = (Son yılın seyreltilmiş hisse sayısı ÷ İlk yılınki − 1) × 100","where":[["Seyreltilmiş hisse","ağırlıklı ortalama seyreltilmiş hisse sayısı, hisse bölünmelerine göre düzeltilmiş"],["Hisse değişimi","yüzde; negatifse hisse sayısı azalmış"]]}],"data":[["İşletme nakit akışı","10-K nakit akış tablosu (XBRL us-gaap:NetCashProvidedByUsedInOperatingActivities)"],["Yatırım harcaması","10-K nakit akış tablosu (us-gaap:PaymentsToAcquirePropertyPlantAndEquipment, yoksa PaymentsToAcquireProductiveAssets)"],["Hisse geri alımı","10-K nakit akış tablosu (us-gaap:PaymentsForRepurchaseOfCommonStock)"],["Temettü","10-K nakit akış tablosu (us-gaap:PaymentsOfDividends, yoksa PaymentsOfDividendsCommonStock)"],["Satın almalar","10-K nakit akış tablosu (us-gaap:PaymentsToAcquireBusinessesNetOfCashAcquired)"],["Borç geri ödemesi","10-K nakit akış tablosu (us-gaap:RepaymentsOfLongTermDebt)"],["Seyreltilmiş hisse sayısı","10-K gelir tablosu (us-gaap:WeightedAverageNumberOfDilutedSharesOutstanding)"]],"steps":["Bir şirketin son beş mali yıllık SEC yıllık verisini al.","Her yıl serbest nakit akışını İNA − yatırım harcaması olarak hesapla.","Her kalemi beş yıl boyunca, sadece raporlandığı yılları kullanarak topla; hiç raporlanmayan kalem “—” görünür.","Her kullanımı toplam işletme nakit akışına, SNA pozitifse geri alım + temettüyü toplam serbest nakit akışına böl.","Bir sıçrama hisse bölünmesine benziyorsa eski yılları buna göre düzelttikten sonra son yılın seyreltilmiş hisse sayısını ilk yılınkiyle karşılaştır.","5 yıllık bir tablo, yıl yıl bir tablo ve kullanımların çubuk grafiğini göster."],"example":"Örnek şirket, 5 yıllık toplamlar (milyon USD): İNA 1.000, yatırım harcaması 300, geri alım 350, temettü 210. SNA = 1.000 − 300 = 700. Yatırım harcaması = 300 ÷ 1.000 = İNA'nın %30'u, geri alım %35, temettü %21. Hissedarlara dönen = 350 + 210 = 560, yani SNA'nın 560 ÷ 700 = %80'i. Seyreltilmiş hisse 100 milyondan 95 milyona indi: 95 ÷ 100 − 1 = %−5.","read":["Yüksek yatırım harcaması payı, ayakta kalmak veya büyümek için yoğun yeniden yatırım gereken bir işe işaret eder.","SNA'ya göre büyük geri alım ve temettü, şirketin boştaki nakdinin çoğunu geri verdiğini gösterir; %100'ün üstü, eldeki nakdi veya borçlanmayı da kullandığı anlamına gelir.","Azalan seyreltilmiş hisse sayısı, geri alımların yeni ihraç edilen hisseleri (ör. çalışanlara verilenler) aştığını gösterir; artan sayı mevcut ortakların payının sulandığı anlamına gelir.","Büyük satın almalar, hesapların başka yerlerindeki borç veya şerefiye artışını açıklayabilir."],"limits":["Sadece listelenen kalemler izlenir: yeni borçlanma, hisse ihracı, menkul kıymet yatırımları ve nakit değişimi gösterilmez; bu yüzden kullanımların İNA'nın %100'üne denk gelmesi gerekmez.","Kalemler raporlandıkları yıllar üzerinden toplanır; bazı yıllarda eksik olan bir etiket o toplamı gerçekte olduğundan küçük gösterir.","Geri alım ve temettü gerçekten ödenen nakittir, açıklanan program değildir; çalışan hisse ödüllerini dengelemek için yapılan geri alımlar da tam olarak sayılır.","Hisse sayısı için bölünme düzeltmesi bir pratik kuraldır (2×, 3×, 4×… civarı bir sıçrama bölünme sayılır) ve olağan dışı bir değişimi yanlış yorumlayabilir."]},"es":{"question":"En los últimos cinco años, ¿adónde fue realmente el efectivo que generó la empresa?","idea":"Una empresa que genera efectivo con sus operaciones tiene que decidir qué hacer con él: invertir en equipos nuevos, comprar otras empresas, pagar deuda o devolverlo a los accionistas como dividendos o recompras de acciones. El estado de flujos de efectivo registra el efectivo realmente pagado en cada una de estas cosas. Este análisis las suma durante cinco años y compara cada una con el flujo de caja operativo que la financió.","formulas":[{"name":"Flujo de caja libre (FCF)","expr":"FCF = FCO − Inversión en capital (cada año), luego sumado en 5 años","where":[["FCO (CFO)","flujo de caja de las operaciones (millones de USD)"],["Inversión en capital","efectivo pagado por inmuebles, planta y equipo, capex (millones de USD)"],["FCF","flujo de caja libre (millones de USD)"]]},{"name":"Parte del flujo de caja operativo","expr":"Parte del FCO = Total en 5 años de un uso ÷ FCO total en 5 años × 100","where":[["uso","capex, recompras de acciones, dividendos, adquisiciones o deuda devuelta (millones de USD)"],["Parte del FCO","porcentaje; las partes pueden sumar más o menos del 100 %"]]},{"name":"Devuelto a los accionistas","expr":"Devuelto = Recompras + Dividendos; Devuelto ÷ FCF × 100 (solo si FCF > 0)","where":[["Devuelto","efectivo total pagado a los accionistas en 5 años (millones de USD)"]]},{"name":"Cambio en el número de acciones","expr":"Cambio de acciones = (Acciones diluidas del último año ÷ Acciones diluidas del primer año − 1) × 100","where":[["Acciones diluidas","promedio ponderado de acciones diluidas, ajustado por desdoblamientos (splits)"],["Cambio de acciones","porcentaje; negativo significa menos acciones"]]}],"data":[["Flujo de caja operativo","estado de flujos de efectivo del 10-K (XBRL us-gaap:NetCashProvidedByUsedInOperatingActivities)"],["Inversión en capital","estado de flujos de efectivo del 10-K (us-gaap:PaymentsToAcquirePropertyPlantAndEquipment, o PaymentsToAcquireProductiveAssets)"],["Recompras de acciones","estado de flujos de efectivo del 10-K (us-gaap:PaymentsForRepurchaseOfCommonStock)"],["Dividendos","estado de flujos de efectivo del 10-K (us-gaap:PaymentsOfDividends, o PaymentsOfDividendsCommonStock)"],["Adquisiciones","estado de flujos de efectivo del 10-K (us-gaap:PaymentsToAcquireBusinessesNetOfCashAcquired)"],["Deuda devuelta","estado de flujos de efectivo del 10-K (us-gaap:RepaymentsOfLongTermDebt)"],["Acciones diluidas","cuenta de resultados del 10-K (us-gaap:WeightedAverageNumberOfDilutedSharesOutstanding)"]],"steps":["Tomar los últimos cinco años fiscales de datos anuales de la SEC de una empresa.","Calcular cada año el flujo de caja libre como FCO − capex.","Sumar cada partida en los cinco años usando solo los años en que se publicó; una partida nunca publicada aparece como “—”.","Dividir cada uso entre el flujo de caja operativo total, y recompras + dividendos entre el flujo de caja libre total cuando el FCF es positivo.","Comparar las acciones diluidas del último año con las del primero, tras reexpresar los años antiguos cuando un salto parece un desdoblamiento.","Mostrar una tabla de 5 años, una tabla año por año y un gráfico de barras de los usos."],"example":"Empresa de ejemplo, totales en 5 años (millones de USD): FCO 1.000, capex 300, recompras 350, dividendos 210. FCF = 1.000 − 300 = 700. Capex = 300 ÷ 1.000 = 30 % del FCO, recompras 35 %, dividendos 21 %. Devuelto a los accionistas = 350 + 210 = 560, es decir 560 ÷ 700 = 80 % del FCF. Las acciones diluidas pasaron de 100 a 95 millones: 95 ÷ 100 − 1 = −5 %.","read":["Una parte alta de capex sugiere un negocio que necesita mucha reinversión para seguir funcionando o para crecer.","Recompras y dividendos grandes frente al FCF muestran una empresa que devuelve la mayor parte de su efectivo sobrante; por encima del 100 % significa que también usó caja disponible o deuda.","Un número de acciones diluidas que baja significa que las recompras superaron a las nuevas acciones emitidas (por ejemplo, para empleados); uno que sube significa que los accionistas actuales se diluyen.","Las grandes adquisiciones pueden explicar un salto de la deuda o del fondo de comercio en otras partes de las cuentas."],"limits":["Solo se siguen las partidas de la lista: no se muestran el nuevo endeudamiento, la emisión de acciones, las inversiones en valores ni la variación de caja, así que los usos no tienen por qué sumar el 100 % del FCO.","Las partidas se suman en los años en que se publicaron, así que una etiqueta que falta en algunos años hace que ese total sea menor que la realidad.","Las recompras y los dividendos son efectivo realmente pagado, no programas anunciados; las recompras que en parte compensan acciones dadas a empleados cuentan igualmente completas.","El ajuste por desdoblamientos del número de acciones es una regla práctica (un salto cercano a 2×, 3×, 4×… se trata como split) y podría malinterpretar un cambio inusual."]}},{"id":"roic_wacc","number":14,"group":"fundamental","group_label":"Fundamentals","title":"ROIC vs WACC","next":["beta","dupont","dcf"],"en":{"question":"Does the company earn more on the money invested in it than that money costs, or does it just grow?","idea":"Shareholders and lenders who fund a company expect a minimum return, called the cost of capital or WACC (weighted average cost of capital). ROIC (return on invested capital) measures the after-tax operating profit the company earns on the equity and debt it uses. If ROIC is above WACC, growth adds value; if it is below, the company can grow and still destroy value. Here you choose the WACC yourself.","formulas":[{"name":"Tax rate used","expr":"Tax rate = Income tax expense ÷ Pre-tax income, kept between 0% and 35%; 21% if it cannot be computed","where":[["Tax rate","effective tax rate of that fiscal year (%)"]]},{"name":"NOPAT","expr":"NOPAT = EBIT × (1 − Tax rate)","where":[["NOPAT","net operating profit after tax (USD millions)"],["EBIT","reported operating income; if missing, pre-tax income + interest expense (USD millions)"]]},{"name":"Invested capital","expr":"Invested capital = Equity + Long-term debt + Current debt − Cash; then (opening + closing) ÷ 2","where":[["Equity","shareholders' equity at year end (USD millions)"],["Long-term debt, Current debt","borrowings due after / within one year; counted as 0 if not reported"],["Cash","cash and cash equivalents; counted as 0 if not reported"]]},{"name":"ROIC and spread","expr":"ROIC = NOPAT ÷ Average invested capital × 100; Spread = ROIC − WACC","where":[["ROIC","return on invested capital (%), only when invested capital > 0"],["WACC","your assumed cost of capital, default 9%, allowed 2–25%"],["Spread","percentage points"]]}],"data":[["Operating income (EBIT)","10-K income statement (XBRL us-gaap:OperatingIncomeLoss; fallback pre-tax income + InterestExpense or a similar interest tag)"],["Income tax and pre-tax income","10-K income statement (us-gaap:IncomeTaxExpenseBenefit and IncomeLossFromContinuingOperationsBeforeIncomeTaxes…)"],["Equity","10-K balance sheet (us-gaap:StockholdersEquity, else StockholdersEquityIncludingPortionAttributableToNoncontrollingInterest)"],["Debt","10-K balance sheet (long-term: us-gaap:LongTermDebtNoncurrent, else LongTermDebt or LongTermDebtAndCapitalLeaseObligations; current: LongTermDebtCurrent, else DebtCurrent or ShortTermBorrowings) If only total long-term debt (LongTermDebt) is reported, its current portion is moved to current debt so it is counted once."],["Cash","10-K balance sheet (us-gaap:CashAndCashEquivalentsAtCarryingValue, else CashCashEquivalentsRestrictedCashAndRestrictedCashEquivalents)"],["WACC","your own input (default 9%); the Beta analysis can help you estimate it"]],"steps":["Check that your WACC is between 2% and 25% and read up to six fiscal years of annual SEC data for one company.","For each year that has a previous year, compute the effective tax rate, clamp it to 0–35% (21% if missing), and NOPAT = EBIT × (1 − tax rate).","Compute invested capital at both year ends as equity + debt − cash and average them.","Compute ROIC = NOPAT ÷ average invested capital, but only if invested capital is positive.","Subtract your WACC to get the spread, count the years with a positive spread, and chart ROIC against the flat WACC line."],"example":"Example company: EBIT 200, income tax 40 on pre-tax income 200, so the tax rate is 20% and NOPAT = 200 × (1 − 0.20) = 160 (USD millions). Invested capital last year = 500 equity + 300 debt − 100 cash = 700; this year = 600 + 400 − 100 = 900; average = 800. ROIC = 160 ÷ 800 = 20%. With a WACC of 9%, the spread is 20 − 9 = +11 points.","read":["A positive spread (ROIC above WACC) suggests each dollar invested earned more than it costs, so growth added value in that year.","A negative spread suggests the business earned less than investors require; growing such a business can reduce value.","A spread that stays positive in most years is more telling than one good year; the app counts how many years beat WACC.","Because WACC is your assumption, try a few values to see how sensitive the conclusion is."],"limits":["WACC is not measured here; a different reasonable WACC can flip the conclusion for companies near the line.","Invested capital is a simple book-value measure: lease liabilities are not added, short-term investments are not subtracted (only cash and equivalents), and if a company reports only some of its borrowing lines, part of its debt can be missed.","When invested capital is zero or negative (lots of cash, or negative equity after buybacks) ROIC is not shown; very small invested capital gives extreme ROIC values.","The tax rate is clamped to 0–35% and set to 21% when it cannot be computed, and EBIT can include one-off items, so a single year can be distorted."]},"tr":{"question":"Şirket kendisine yatırılan paradan, o paranın maliyetinden fazlasını mı kazanıyor, yoksa sadece büyüyor mu?","idea":"Bir şirketi finanse eden hissedarlar ve kredi verenler asgari bir getiri bekler; buna sermaye maliyeti veya WACC (ağırlıklı ortalama sermaye maliyeti) denir. ROIC (yatırılan sermaye getirisi), şirketin kullandığı özkaynak ve borç üzerinden kazandığı vergi sonrası faaliyet kârını ölçer. ROIC WACC'ın üstündeyse büyüme değer katar; altındaysa şirket büyürken bile değer kaybettirebilir. Burada WACC'ı sen seçersin.","formulas":[{"name":"Kullanılan vergi oranı","expr":"Vergi oranı = Gelir vergisi gideri ÷ Vergi öncesi kâr, %0 ile %35 arasında tutulur; hesaplanamazsa %21","where":[["Vergi oranı","o mali yılın efektif vergi oranı (%)"]]},{"name":"NOPAT","expr":"NOPAT = FVÖK × (1 − Vergi oranı)","where":[["NOPAT","vergi sonrası net faaliyet kârı (milyon USD)"],["FVÖK (EBIT)","raporlanan faaliyet kârı; yoksa vergi öncesi kâr + faiz gideri (milyon USD)"]]},{"name":"Yatırılan sermaye","expr":"Yatırılan sermaye = Özkaynak + Uzun vadeli borç + Kısa vadeli borç − Nakit; sonra (yıl başı + yıl sonu) ÷ 2","where":[["Özkaynak","yıl sonundaki özkaynak (milyon USD)"],["Uzun vadeli borç, Kısa vadeli borç","bir yıldan sonra / bir yıl içinde vadesi gelen borçlanmalar; raporlanmazsa 0 sayılır"],["Nakit","nakit ve nakit benzerleri; raporlanmazsa 0 sayılır"]]},{"name":"ROIC ve fark","expr":"ROIC = NOPAT ÷ Ortalama yatırılan sermaye × 100; Fark = ROIC − WACC","where":[["ROIC","yatırılan sermaye getirisi (%), sadece yatırılan sermaye > 0 ise"],["WACC","senin varsaydığın sermaye maliyeti, varsayılan %9, izin verilen %2–25"],["Fark","yüzde puan"]]}],"data":[["Faaliyet kârı (FVÖK)","10-K gelir tablosu (XBRL us-gaap:OperatingIncomeLoss; yedek: vergi öncesi kâr + InterestExpense veya benzeri bir faiz etiketi)"],["Gelir vergisi ve vergi öncesi kâr","10-K gelir tablosu (us-gaap:IncomeTaxExpenseBenefit ve IncomeLossFromContinuingOperationsBeforeIncomeTaxes…)"],["Özkaynak","10-K bilançosu (us-gaap:StockholdersEquity, yoksa StockholdersEquityIncludingPortionAttributableToNoncontrollingInterest)"],["Borç","10-K bilançosu (uzun vadeli: us-gaap:LongTermDebtNoncurrent, yoksa LongTermDebt veya LongTermDebtAndCapitalLeaseObligations; kısa vadeli: LongTermDebtCurrent, yoksa DebtCurrent veya ShortTermBorrowings) Yalnızca toplam uzun vadeli borç (LongTermDebt) raporlanmışsa, kısa vadeli kısmı kısa vadeli borca taşınır; böylece bir kez sayılır."],["Nakit","10-K bilançosu (us-gaap:CashAndCashEquivalentsAtCarryingValue, yoksa CashCashEquivalentsRestrictedCashAndRestrictedCashEquivalents)"],["WACC","senin girdin (varsayılan %9); Beta analizi tahmin etmene yardımcı olabilir"]],"steps":["WACC'ının %2 ile %25 arasında olduğunu kontrol et ve bir şirket için en fazla altı mali yıllık SEC yıllık verisini yükle.","Önceki yılı olan her yıl için efektif vergi oranını hesapla, %0–35 aralığına sınırla (yoksa %21) ve NOPAT = FVÖK × (1 − vergi oranı) bul.","Her iki yıl sonunda yatırılan sermayeyi özkaynak + borç − nakit olarak hesapla ve ortalamasını al.","ROIC = NOPAT ÷ ortalama yatırılan sermaye hesapla; ama sadece yatırılan sermaye pozitifse.","WACC'ını çıkararak farkı bul, farkın pozitif olduğu yılları say ve ROIC'i sabit WACC çizgisine karşı grafikte göster."],"example":"Örnek şirket: FVÖK 200, vergi öncesi kâr 200 üzerinden gelir vergisi 40; vergi oranı %20 ve NOPAT = 200 × (1 − 0,20) = 160 (milyon USD). Geçen yılın yatırılan sermayesi = 500 özkaynak + 300 borç − 100 nakit = 700; bu yıl = 600 + 400 − 100 = 900; ortalama = 800. ROIC = 160 ÷ 800 = %20. WACC %9 ise fark 20 − 9 = +11 puan.","read":["Pozitif fark (ROIC WACC'ın üstünde), yatırılan her doların maliyetinden fazlasını kazandığını, yani o yıl büyümenin değer kattığını düşündürür.","Negatif fark, işin yatırımcıların beklediğinden az kazandığını düşündürür; böyle bir işi büyütmek değeri azaltabilir.","Yılların çoğunda pozitif kalan bir fark, tek bir iyi yıldan daha anlamlıdır; uygulama kaç yılın WACC'ı geçtiğini sayar.","WACC senin varsayımın olduğu için birkaç değer dene ve sonucun ne kadar hassas olduğunu gör."],"limits":["WACC burada ölçülmez; makul ama farklı bir WACC, çizgiye yakın şirketlerde sonucu tersine çevirebilir.","Yatırılan sermaye basit bir defter değeri ölçüsüdür: kira yükümlülükleri eklenmez, kısa vadeli yatırımlar düşülmez (sadece nakit ve nakit benzerleri) ve şirket borç kalemlerinin yalnızca bir kısmını raporlarsa borcun bir bölümü gözden kaçabilir.","Yatırılan sermaye sıfır veya negatifse (çok nakit ya da geri alımlar sonrası negatif özkaynak) ROIC gösterilmez; çok küçük yatırılan sermaye aşırı ROIC değerleri verir.","Vergi oranı %0–35'e sınırlanır ve hesaplanamazsa %21 kullanılır; FVÖK tek seferlik kalemler içerebilir, bu yüzden tek bir yıl bozulabilir."]},"es":{"question":"¿La empresa gana con el dinero invertido en ella más de lo que ese dinero cuesta, o solo crece?","idea":"Los accionistas y prestamistas que financian una empresa esperan un rendimiento mínimo, llamado coste del capital o WACC (coste medio ponderado del capital). El ROIC (rentabilidad sobre el capital invertido) mide el beneficio operativo después de impuestos que la empresa obtiene con el patrimonio y la deuda que usa. Si el ROIC supera al WACC, crecer añade valor; si queda por debajo, la empresa puede crecer y aun así destruir valor. Aquí eliges tú el WACC.","formulas":[{"name":"Tipo impositivo usado","expr":"Tipo impositivo = Gasto por impuesto sobre beneficios ÷ Beneficio antes de impuestos, limitado entre 0 % y 35 %; 21 % si no se puede calcular","where":[["Tipo impositivo","tipo efectivo de ese año fiscal (%)"]]},{"name":"NOPAT","expr":"NOPAT = EBIT × (1 − Tipo impositivo)","where":[["NOPAT","beneficio operativo neto después de impuestos (millones de USD)"],["EBIT","resultado operativo publicado; si falta, beneficio antes de impuestos + gasto por intereses (millones de USD)"]]},{"name":"Capital invertido","expr":"Capital invertido = Patrimonio + Deuda a largo plazo + Deuda a corto plazo − Efectivo; luego (apertura + cierre) ÷ 2","where":[["Patrimonio","patrimonio de los accionistas al cierre (millones de USD)"],["Deuda a largo plazo, Deuda a corto plazo","préstamos con vencimiento después / dentro de un año; cuentan como 0 si no se publican"],["Efectivo","efectivo y equivalentes; cuenta como 0 si no se publica"]]},{"name":"ROIC y diferencial","expr":"ROIC = NOPAT ÷ Capital invertido promedio × 100; Diferencial = ROIC − WACC","where":[["ROIC","rentabilidad sobre el capital invertido (%), solo si el capital invertido > 0"],["WACC","tu coste del capital supuesto, por defecto 9 %, permitido 2–25 %"],["Diferencial","puntos porcentuales"]]}],"data":[["Resultado operativo (EBIT)","cuenta de resultados del 10-K (XBRL us-gaap:OperatingIncomeLoss; alternativa: beneficio antes de impuestos + InterestExpense u otra etiqueta de intereses similar)"],["Impuesto y beneficio antes de impuestos","cuenta de resultados del 10-K (us-gaap:IncomeTaxExpenseBenefit e IncomeLossFromContinuingOperationsBeforeIncomeTaxes…)"],["Patrimonio","balance del 10-K (us-gaap:StockholdersEquity, o StockholdersEquityIncludingPortionAttributableToNoncontrollingInterest)"],["Deuda","balance del 10-K (largo plazo: us-gaap:LongTermDebtNoncurrent, o LongTermDebt o LongTermDebtAndCapitalLeaseObligations; corto plazo: LongTermDebtCurrent, o DebtCurrent o ShortTermBorrowings) Si solo se informa de la deuda a largo plazo total (LongTermDebt), su parte corriente se pasa a la deuda a corto plazo para contarla una sola vez."],["Efectivo","balance del 10-K (us-gaap:CashAndCashEquivalentsAtCarryingValue, o CashCashEquivalentsRestrictedCashAndRestrictedCashEquivalents)"],["WACC","tu propio dato (por defecto 9 %); el análisis Beta puede ayudarte a estimarlo"]],"steps":["Comprobar que tu WACC está entre 2 % y 25 % y cargar hasta seis años fiscales de datos anuales de la SEC de una empresa.","Para cada año que tenga un año anterior, calcular el tipo impositivo efectivo, limitarlo a 0–35 % (21 % si falta) y NOPAT = EBIT × (1 − tipo impositivo).","Calcular el capital invertido en ambos cierres como patrimonio + deuda − efectivo y promediarlos.","Calcular ROIC = NOPAT ÷ capital invertido promedio, pero solo si el capital invertido es positivo.","Restar tu WACC para obtener el diferencial, contar los años con diferencial positivo y graficar el ROIC frente a la línea plana del WACC."],"example":"Empresa de ejemplo: EBIT 200, impuesto 40 sobre un beneficio antes de impuestos de 200, así que el tipo es 20 % y NOPAT = 200 × (1 − 0,20) = 160 (millones de USD). Capital invertido el año pasado = 500 de patrimonio + 300 de deuda − 100 de efectivo = 700; este año = 600 + 400 − 100 = 900; promedio = 800. ROIC = 160 ÷ 800 = 20 %. Con un WACC del 9 %, el diferencial es 20 − 9 = +11 puntos.","read":["Un diferencial positivo (ROIC por encima del WACC) sugiere que cada dólar invertido ganó más de lo que cuesta, así que crecer añadió valor ese año.","Un diferencial negativo sugiere que el negocio ganó menos de lo que exigen los inversores; hacer crecer un negocio así puede reducir valor.","Un diferencial positivo en la mayoría de los años dice más que un solo buen año; la app cuenta cuántos años superaron al WACC.","Como el WACC es tu supuesto, prueba varios valores para ver cuán sensible es la conclusión."],"limits":["El WACC no se mide aquí; otro WACC razonable puede invertir la conclusión en empresas cercanas a la línea.","El capital invertido es una medida contable simple: no se suman los pasivos por arrendamiento, no se restan las inversiones a corto plazo (solo efectivo y equivalentes) y, si la empresa solo informa de algunas de sus líneas de deuda, parte de la deuda puede quedar fuera.","Cuando el capital invertido es cero o negativo (mucho efectivo, o patrimonio negativo tras recompras) el ROIC no se muestra; un capital invertido muy pequeño da valores de ROIC extremos.","El tipo impositivo se limita a 0–35 % y se fija en 21 % cuando no se puede calcular, y el EBIT puede incluir partidas puntuales, así que un año concreto puede salir distorsionado."]}},{"id":"comps","number":15,"group":"valuation","group_label":"Valuation","title":"Comparable company multiples","next":["reverse_dcf","valuation_summary","roic_wacc"],"en":{"question":"Is the company priced high or low compared with similar companies?","idea":"Instead of forecasting cash flows, you compare prices per unit of something: per dollar of earnings, of sales, of book value. These ratios are called multiples. If similar companies trade at 20 times earnings and yours at 30, the market is paying more for each dollar of its profit, and you then ask why.","formulas":[{"name":"Market value and enterprise value","expr":"Market value = price × shares outstanding;  EV = market value + debt − cash","where":[["EV","enterprise value: price of the whole business including its debt, USD millions"],["debt","long-term + current debt, latest 10-K"],["cash","cash and cash equivalents, latest 10-K"]]},{"name":"The multiples","expr":"P/E = market value ÷ net income;  EV/EBITDA = EV ÷ (EBIT + D&A);  EV/Sales = EV ÷ revenue;  P/B = market value ÷ equity","where":[["P/E","price-to-earnings; net income is trailing twelve months (TTM) when quarterly data exist, else latest fiscal year"],["EBITDA","operating income + depreciation and amortization, latest fiscal year"],["revenue","TTM when available, else latest fiscal year"],["P/B","price-to-book; equity is shareholders' equity at the latest fiscal year end"],["blank","shown only when the denominator is positive (no P/E for loss-makers)"]]},{"name":"Free-cash-flow yield after stock-based pay","expr":"FCF yield = (CFO − capex − SBC) ÷ market value × 100","where":[["CFO − capex − SBC","operating cash flow minus capital spending minus stock-based compensation, latest fiscal year"],["%","can be negative"]]},{"name":"Gap to peers","expr":"Gap = subject multiple ÷ median of peer multiples − 1","where":[["subject","the first ticker you enter"],["peer median","median of the other companies only, not including the subject"]]}],"data":[["Share price","Yahoo Finance latest adjusted close"],["Shares outstanding","10-K/10-Q cover page (dei:EntityCommonStockSharesOutstanding), else diluted weighted average; restated for later splits"],["Net income","us-gaap:NetIncomeLoss (else ProfitLoss); TTM = last four 10-Q quarters, with Q4 = annual − Q1 to Q3"],["Revenue","us-gaap:RevenueFromContractWithCustomerExcludingAssessedTax, Revenues …; TTM if available"],["EBIT, D&A","us-gaap:OperatingIncomeLoss (else pre-tax income + interest), DepreciationDepletionAndAmortization; latest 10-K"],["Equity, debt, cash","us-gaap:StockholdersEquity; LongTermDebtNoncurrent + LongTermDebtCurrent; CashAndCashEquivalentsAtCarryingValue; latest 10-K"],["CFO, capex, SBC","us-gaap:NetCashProvidedByUsedInOperatingActivities, PaymentsToAcquirePropertyPlantAndEquipment, ShareBasedCompensation"],["Peers","your tickers (1–8, first = subject); with one ticker, up to 5 companies with the same SEC industry code (SIC)"]],"steps":["Treat the first ticker as the subject and the rest as peers; with only one ticker, pick up to 5 peers from the same SEC industry code.","For each company compute market value, EV and the five measures; skip a company that has no price or share count.","Leave a multiple blank when its denominator (earnings, EBITDA, sales, equity) is zero or negative.","Compute the median of each multiple across the peers only.","Report how far the subject's P/E, EV/EBITDA and EV/Sales sit above or below the peer median."],"example":"Example company: price 50 × 20 shares = market value 1,000; debt 200 − cash 100 gives EV 1,100. TTM net income 40, so P/E = 1,000 ÷ 40 = 25. EBITDA 110, so EV/EBITDA = 1,100 ÷ 110 = 10. Peers' P/Es are 15, 20 and 30, median 20. Gap = 25 ÷ 20 − 1 = +25%: the market pays 25% more per dollar of this company's earnings than for the typical peer.","read":["A multiple above the peer median means investors pay more per unit of earnings or sales; that can reflect faster expected growth, higher margins or lower risk, not just overpricing.","Look at several multiples together: P/E can be distorted by one-off items, EV/EBITDA ignores capital spending, P/B suits banks and asset-heavy firms.","A high FCF yield means a lot of cash generated per dollar of market value; a negative one means the company spent more cash than it produced.","Then test the reason for a gap with the Reverse DCF."],"limits":["The answer depends on the peer group. Automatic peers come from a broad industry code and can be poor matches; choose real competitors.","Periods are mixed: P/E and EV/Sales use TTM when available, EV/EBITDA, P/B and FCF yield use the latest fiscal year.","EV here counts only reported debt and cash: marketable securities, leases and minority interests are not included, which can make EV too high or too low.","There is no ADR-ratio input in this analysis, so for foreign companies it assumes one ADR equals one ordinary share; check the multiples for such companies."]},"tr":{"question":"Şirket benzer şirketlere göre yüksek mi, düşük mü fiyatlanıyor?","idea":"Nakit akışı tahmin etmek yerine, bir birim şey başına fiyatı karşılaştırırsın: bir dolar kâr, satış ya da defter değeri başına. Bu oranlara çarpan denir. Benzer şirketler kârlarının 20 katından, seninki 30 katından işlem görüyorsa piyasa onun her dolar kârına daha fazla ödüyordur; sonra nedenini sorarsın.","formulas":[{"name":"Piyasa değeri ve firma değeri","expr":"Piyasa değeri = fiyat × dolaşımdaki hisse;  FD = piyasa değeri + borç − nakit","where":[["FD (EV)","firma değeri: borcu dahil tüm işletmenin fiyatı, milyon USD"],["borç","uzun + kısa vadeli borç, son 10-K"],["nakit","nakit ve nakit benzerleri, son 10-K"]]},{"name":"Çarpanlar","expr":"F/K = piyasa değeri ÷ net kâr;  FD/FAVÖK = FD ÷ (FVÖK + amortisman);  FD/Satış = FD ÷ gelir;  PD/DD = piyasa değeri ÷ özkaynak","where":[["F/K (P/E)","fiyat/kazanç; net kâr çeyrek veri varsa son 12 ay (TTM), yoksa son mali yıl"],["FAVÖK (EBITDA)","faaliyet kârı + amortisman, son mali yıl"],["gelir","varsa TTM, yoksa son mali yıl"],["PD/DD (P/B)","piyasa değeri/defter değeri; özkaynak son mali yıl sonundaki özkaynak"],["boş","payda pozitif değilse gösterilmez (zarar edende F/K yok)"]]},{"name":"Hisse bazlı ücret sonrası serbest nakit verimi","expr":"FCF verimi = (CFO − yatırım − SBC) ÷ piyasa değeri × 100","where":[["CFO − yatırım − SBC","işletme nakdi eksi yatırım harcaması eksi hisse bazlı ücretler, son mali yıl"],["%","negatif olabilir"]]},{"name":"Rakiplere göre fark","expr":"Fark = konu şirket çarpanı ÷ rakip çarpanlarının ortancası − 1","where":[["konu şirket","yazdığın ilk hisse"],["rakip ortancası","konu şirket hariç, sadece diğer şirketlerin ortancası (medyanı)"]]}],"data":[["Hisse fiyatı","Yahoo Finance son düzeltilmiş kapanış"],["Dolaşımdaki hisse","10-K/10-Q kapak sayfası (dei:EntityCommonStockSharesOutstanding), yoksa seyreltilmiş ağırlıklı ortalama; sonraki bölünmelere göre düzeltilir"],["Net kâr","us-gaap:NetIncomeLoss (yoksa ProfitLoss); TTM = son dört 10-Q çeyreği, 4. çeyrek = yıllık − ilk üç çeyrek"],["Gelir","us-gaap:RevenueFromContractWithCustomerExcludingAssessedTax, Revenues …; varsa TTM"],["FVÖK, amortisman","us-gaap:OperatingIncomeLoss (yoksa vergi öncesi kâr + faiz), DepreciationDepletionAndAmortization; son 10-K"],["Özkaynak, borç, nakit","us-gaap:StockholdersEquity; LongTermDebtNoncurrent + LongTermDebtCurrent; CashAndCashEquivalentsAtCarryingValue; son 10-K"],["CFO, yatırım, SBC","us-gaap:NetCashProvidedByUsedInOperatingActivities, PaymentsToAcquirePropertyPlantAndEquipment, ShareBasedCompensation"],["Rakipler","senin hisselerin (1–8, ilki = konu şirket); tek hisse yazarsan aynı SEC sektör kodundan (SIC) en fazla 5 şirket"]],"steps":["İlk hisseyi konu şirket, diğerlerini rakip say; tek hisse varsa aynı SEC sektör kodundan en fazla 5 rakip seç.","Her şirket için piyasa değerini, firma değerini ve beş ölçüyü hesapla; fiyatı veya hisse sayısı olmayanı atla.","Paydası (kâr, FAVÖK, satış, özkaynak) sıfır veya negatifse çarpanı boş bırak.","Her çarpanın sadece rakipler arasındaki ortancasını hesapla.","Konu şirketin F/K, FD/FAVÖK ve FD/Satış çarpanlarının rakip ortancasının ne kadar üstünde ya da altında olduğunu yaz."],"example":"Örnek şirket: fiyat 50 × 20 hisse = piyasa değeri 1.000; borç 200 − nakit 100 ile firma değeri 1.100. Son 12 ay net kârı 40, yani F/K = 1.000 ÷ 40 = 25. FAVÖK 110, yani FD/FAVÖK = 1.100 ÷ 110 = 10. Rakiplerin F/K’ları 15, 20 ve 30; ortanca 20. Fark = 25 ÷ 20 − 1 = +%25: piyasa bu şirketin her dolar kârına tipik rakibe göre %25 daha fazla ödüyor.","read":["Rakip ortancasının üstündeki bir çarpan, yatırımcıların birim kâr veya satış başına daha çok ödediğini gösterir; bu sadece aşırı fiyat değil, daha hızlı büyüme, daha yüksek marj veya daha düşük risk beklentisi de olabilir.","Birkaç çarpana birlikte bak: F/K tek seferlik kalemlerle bozulabilir, FD/FAVÖK yatırım harcamasını görmez, PD/DD bankalara ve varlığı ağır şirketlere uyar.","Yüksek FCF verimi, piyasa değerinin her doları başına çok nakit üretildiğini; negatif değer, şirketin ürettiğinden fazla nakit harcadığını gösterir.","Farkın nedenini sonra Ters DCF ile sına."],"limits":["Sonuç rakip grubuna bağlıdır. Otomatik rakipler geniş bir sektör kodundan gelir ve kötü eşleşebilir; gerçek rakipleri seç.","Dönemler karışıktır: F/K ve FD/Satış varsa TTM, FD/FAVÖK, PD/DD ve FCF verimi son mali yılı kullanır.","Buradaki firma değeri sadece raporlanan borç ve nakdi sayar: menkul kıymetler, kiralamalar ve azınlık payları dahil değildir; bu, firma değerini olduğundan yüksek veya düşük gösterebilir.","Bu analizde ADR oranı girişi yok; yabancı şirketlerde 1 ADR = 1 asıl hisse varsayılır, bu şirketlerin çarpanlarını kontrol et."]},"es":{"question":"¿La empresa cotiza cara o barata frente a empresas parecidas?","idea":"En lugar de prever flujos de caja, comparas precios por unidad de algo: por dólar de beneficio, de ventas o de valor contable. Estas razones se llaman múltiplos. Si empresas parecidas cotizan a 20 veces beneficios y la tuya a 30, el mercado paga más por cada dólar de su beneficio, y entonces te preguntas por qué.","formulas":[{"name":"Capitalización y valor de empresa","expr":"Capitalización = precio × acciones en circulación;  EV = capitalización + deuda − caja","where":[["EV","valor de empresa: precio de todo el negocio incluida su deuda, millones de USD"],["deuda","deuda a largo + corto plazo, último 10-K"],["caja","efectivo y equivalentes, último 10-K"]]},{"name":"Los múltiplos","expr":"P/E = capitalización ÷ beneficio neto;  EV/EBITDA = EV ÷ (EBIT + D&A);  EV/Ventas = EV ÷ ingresos;  P/B = capitalización ÷ patrimonio","where":[["P/E","precio/beneficio (PER); beneficio neto de los últimos doce meses (TTM) si hay datos trimestrales, si no el último ejercicio"],["EBITDA","beneficio operativo + amortizaciones, último ejercicio"],["ingresos","TTM si existe, si no el último ejercicio"],["P/B","precio/valor contable; patrimonio neto al cierre del último ejercicio"],["vacío","solo se muestra si el denominador es positivo (sin P/E si hay pérdidas)"]]},{"name":"Rentabilidad por flujo de caja libre después de remuneración en acciones","expr":"FCF yield = (CFO − capex − SBC) ÷ capitalización × 100","where":[["CFO − capex − SBC","flujo operativo menos inversión menos remuneración en acciones, último ejercicio"],["%","puede ser negativa"]]},{"name":"Diferencia con los comparables","expr":"Diferencia = múltiplo de la empresa ÷ mediana de los múltiplos de los comparables − 1","where":[["empresa","el primer ticker que escribes"],["mediana de comparables","mediana solo de las demás empresas, sin incluir la principal"]]}],"data":[["Precio de la acción","Yahoo Finance, último cierre ajustado"],["Acciones en circulación","portada del 10-K/10-Q (dei:EntityCommonStockSharesOutstanding), si no la media ponderada diluida; reexpresadas por splits posteriores"],["Beneficio neto","us-gaap:NetIncomeLoss (si no ProfitLoss); TTM = últimos cuatro trimestres 10-Q, con T4 = anual − T1 a T3"],["Ingresos","us-gaap:RevenueFromContractWithCustomerExcludingAssessedTax, Revenues …; TTM si existe"],["EBIT, D&A","us-gaap:OperatingIncomeLoss (si no, beneficio antes de impuestos + intereses), DepreciationDepletionAndAmortization; último 10-K"],["Patrimonio, deuda, caja","us-gaap:StockholdersEquity; LongTermDebtNoncurrent + LongTermDebtCurrent; CashAndCashEquivalentsAtCarryingValue; último 10-K"],["CFO, capex, SBC","us-gaap:NetCashProvidedByUsedInOperatingActivities, PaymentsToAcquirePropertyPlantAndEquipment, ShareBasedCompensation"],["Comparables","tus tickers (1–8, el primero es la empresa principal); con un solo ticker, hasta 5 empresas con el mismo código sectorial de la SEC (SIC)"]],"steps":["Toma el primer ticker como empresa principal y el resto como comparables; con un solo ticker elige hasta 5 comparables del mismo código sectorial de la SEC.","Para cada empresa calcula capitalización, EV y las cinco medidas; omite la que no tenga precio o número de acciones.","Deja vacío un múltiplo si su denominador (beneficio, EBITDA, ventas, patrimonio) es cero o negativo.","Calcula la mediana de cada múltiplo solo entre los comparables.","Indica cuánto está el P/E, EV/EBITDA y EV/Ventas de la empresa por encima o por debajo de la mediana de los comparables."],"example":"Empresa de ejemplo: precio 50 × 20 acciones = capitalización 1.000; deuda 200 − caja 100 da EV 1.100. Beneficio neto TTM 40, así que P/E = 1.000 ÷ 40 = 25. EBITDA 110, así que EV/EBITDA = 1.100 ÷ 110 = 10. Los P/E de los comparables son 15, 20 y 30; mediana 20. Diferencia = 25 ÷ 20 − 1 = +25%: el mercado paga un 25% más por cada dólar de beneficio de esta empresa que por el del comparable típico.","read":["Un múltiplo por encima de la mediana significa que los inversores pagan más por unidad de beneficio o ventas; puede reflejar mayor crecimiento esperado, márgenes más altos o menor riesgo, no solo sobreprecio.","Mira varios múltiplos juntos: el P/E se distorsiona con partidas puntuales, el EV/EBITDA ignora la inversión en activos y el P/B sirve para bancos y empresas con muchos activos.","Una FCF yield alta significa mucha caja generada por cada dólar de capitalización; una negativa, que la empresa gastó más caja de la que produjo.","Después comprueba la causa de la diferencia con el DCF inverso."],"limits":["El resultado depende del grupo de comparables. Los automáticos salen de un código sectorial amplio y pueden no parecerse; elige competidores reales.","Se mezclan periodos: P/E y EV/Ventas usan TTM si existe; EV/EBITDA, P/B y FCF yield usan el último ejercicio.","Aquí el EV solo cuenta la deuda y la caja declaradas: no incluye valores negociables, arrendamientos ni minoritarios, lo que puede inflar o reducir el EV.","Este análisis no tiene campo de ratio ADR, así que para empresas extranjeras supone que 1 ADR = 1 acción ordinaria; revisa sus múltiplos."]}},{"id":"deal_case","number":16,"group":"valuation","group_label":"Valuation","title":"M&A case study","next":["event_study","capital_allocation","segments"],"en":{"question":"When a company announced an acquisition, how did its stock react, what premium did it offer, and how did its reported numbers change afterwards?","idea":"Buying another company is a big bet. The stock's move on announcement shows what investors thought of the deal on the day, after removing what the whole market did. The premium shows how much more than the market price the buyer offered. The before/after 10-K figures show what the deal (and everything else) did to revenue, margins, goodwill, debt and share count.","formulas":[{"name":"Return over a window","expr":"R = close on last day of window ÷ close on the day before the window starts − 1","where":[["windows","day 0; days −1 to +1; 0 to +5; 0 to +20; 0 to +120 (trading days)"],["day 0","first trading day on or after the announcement date you enter"],["close","Yahoo Finance close adjusted for dividends and splits"]]},{"name":"Abnormal return","expr":"Abnormal return = R(acquirer) − R(SPY)","where":[["SPY","an S&P 500 index fund, used as \"the market\""],["note","a simple difference, not adjusted for beta"]]},{"name":"Offer premium","expr":"Premium = offer price per share ÷ target's last close before day 0 − 1","where":[["offer price","what the buyer offered per target share (your input)"],["target close","from Yahoo if the target symbol still trades, else the close you type from the merger proxy (DEFM14A)"]]},{"name":"Before/after changes","expr":"Revenue growth = (Revenue_last ÷ Revenue_before)^(1/years) − 1;  Goodwill share = goodwill ÷ total assets;  Share change = diluted shares_last ÷ diluted shares_before − 1","where":[["before","the last fiscal year ending before the announcement"],["goodwill","price paid above the fair value of the target's identifiable net assets"]]}],"data":[["Acquirer and SPY prices","Yahoo Finance daily closes adjusted for splits and dividends"],["Announcement date, offer price","your inputs (from the press release or merger proxy)"],["Target close before announcement","Yahoo Finance if the target symbol you give still trades, else your input"],["Revenue, operating income","acquirer's 10-Ks: us-gaap:RevenueFromContractWithCustomerExcludingAssessedTax / Revenues, OperatingIncomeLoss"],["Goodwill, total assets","us-gaap:Goodwill, Assets (fiscal year end)"],["Debt","us-gaap:LongTermDebtNoncurrent (else LongTermDebt) + LongTermDebtCurrent (else DebtCurrent / ShortTermBorrowings)"],["Diluted shares","us-gaap:WeightedAverageNumberOfDilutedSharesOutstanding, adjusted for stock splits"],["Cash paid for acquisitions","us-gaap:PaymentsToAcquireBusinessesNetOfCashAcquired (cash-flow statement)"]],"steps":["Find day 0, the first trading day on or after the date you enter (the date must be after mid-2009 and not in the future).","Compute the acquirer's and SPY's returns over each window and their difference (abnormal return).","If you give an offer price and a target close (fetched or typed), compute the premium.","Take the acquirer's last 10-K before the announcement and every 10-K after it, and tabulate revenue, operating margin, goodwill, goodwill ÷ assets, debt, diluted shares and acquisition cash.","Summarise: revenue growth per year, the biggest goodwill jump (if over 10% of starting goodwill), share-count change (over 3% flagged as dilution), and the largest acquisition payment.","Draw a growth-of-100 chart from 30 trading days before to 250 after day 0."],"example":"Example company closes at 100 the day before the announcement and 97 on day 0, so R = 97 ÷ 100 − 1 = −3%. SPY goes from 400 to 404, +1%. Abnormal return = −3% − 1% = −4%: investors liked the deal less than the market's mood. The buyer offers 95 per share for a target that closed at 65: premium = 95 ÷ 65 − 1 ≈ 46%.","read":["A negative abnormal return on day 0 suggests investors thought the buyer overpaid or the deal is risky; a positive one suggests they welcomed it.","Short windows isolate the news best; the 120-day window mixes in many other events.","A big goodwill jump in one year usually marks when the deal closed; goodwill that is a large share of assets means much of the balance sheet rests on the price paid.","Rising diluted shares mean the buyer paid partly in stock or issued more stock-based pay; rising debt means it borrowed."],"limits":["If the announcement came after the market closed, enter the next day, otherwise day 0 misses the reaction.","If rumours moved the target's price earlier, the true premium is larger. The fetched target close is dividend-adjusted, so for a dividend payer it can be slightly below the actual close and the premium slightly overstated.","The before/after table is the acquirer's whole 10-K: other deals, currencies and the business cycle are mixed in; it does not prove what the deal caused.","The acquisition-cash column uses the standard tag only and stays blank for companies with their own tag (for example Microsoft); operating margin is blank when operating income is not reported."]},"tr":{"question":"Bir şirket satın alma açıkladığında hissesi nasıl tepki verdi, ne kadar prim teklif etti ve raporladığı rakamlar sonrasında nasıl değişti?","idea":"Başka bir şirketi satın almak büyük bir bahistir. Duyuru günündeki hareket, tüm piyasanın yaptığı çıkarıldıktan sonra yatırımcıların anlaşma hakkında o gün ne düşündüğünü gösterir. Prim, alıcının piyasa fiyatının ne kadar üstünde teklif verdiğini gösterir. 10-K’daki öncesi/sonrası rakamlar, anlaşmanın (ve diğer her şeyin) gelire, marja, şerefiyeye, borca ve hisse sayısına ne yaptığını gösterir.","formulas":[{"name":"Bir penceredeki getiri","expr":"R = pencerenin son günündeki kapanış ÷ pencere başlamadan önceki günün kapanışı − 1","where":[["pencereler","0. gün; −1 ile +1; 0 ile +5; 0 ile +20; 0 ile +120 (işlem günü)"],["0. gün","girdiğin duyuru tarihindeki ya da sonraki ilk işlem günü"],["kapanış","temettü ve bölünmeye göre düzeltilmiş Yahoo Finance kapanışı"]]},{"name":"Anormal getiri","expr":"Anormal getiri = R(alıcı) − R(SPY)","where":[["SPY","S&P 500 endeks fonu, “piyasa” olarak kullanılır"],["not","basit fark; betaya göre düzeltilmez"]]},{"name":"Teklif primi","expr":"Prim = hisse başına teklif fiyatı ÷ hedefin 0. günden önceki son kapanışı − 1","where":[["teklif fiyatı","alıcının hedefin her hissesi için teklif ettiği tutar (senin girdin)"],["hedef kapanış","hedef sembol hâlâ işlem görüyorsa Yahoo’dan, yoksa birleşme bildiriminden (DEFM14A) senin yazdığın kapanış"]]},{"name":"Öncesi/sonrası değişimler","expr":"Gelir büyümesi = (Gelir_son ÷ Gelir_önce)^(1/yıl) − 1;  Şerefiye payı = şerefiye ÷ toplam varlık;  Hisse değişimi = seyreltilmiş hisse_son ÷ seyreltilmiş hisse_önce − 1","where":[["önce","duyurudan önce biten son mali yıl"],["şerefiye","hedefin tanımlanabilir net varlıklarının gerçeğe uygun değerinin üstünde ödenen kısım"]]}],"data":[["Alıcı ve SPY fiyatları","Yahoo Finance günlük kapanışlar, bölünme ve temettüye göre düzeltilmiş"],["Duyuru tarihi, teklif fiyatı","senin girdilerin (basın bülteni veya birleşme bildiriminden)"],["Hedefin duyuru öncesi kapanışı","verdiğin hedef sembol hâlâ işlem görüyorsa Yahoo Finance, yoksa senin girdin"],["Gelir, faaliyet kârı","alıcının 10-K’ları: us-gaap:RevenueFromContractWithCustomerExcludingAssessedTax / Revenues, OperatingIncomeLoss"],["Şerefiye, toplam varlık","us-gaap:Goodwill, Assets (mali yıl sonu)"],["Borç","us-gaap:LongTermDebtNoncurrent (yoksa LongTermDebt) + LongTermDebtCurrent (yoksa DebtCurrent / ShortTermBorrowings)"],["Seyreltilmiş hisse","us-gaap:WeightedAverageNumberOfDilutedSharesOutstanding, hisse bölünmelerine göre düzeltilmiş"],["Satın almalara ödenen nakit","us-gaap:PaymentsToAcquireBusinessesNetOfCashAcquired (nakit akış tablosu)"]],"steps":["0. günü bul: girdiğin tarihteki ya da sonraki ilk işlem günü (tarih 2009 ortasından sonra olmalı ve gelecekte olmamalı).","Her pencere için alıcının ve SPY’ın getirisini ve farkını (anormal getiri) hesapla.","Teklif fiyatı ve hedef kapanışı (indirilen ya da yazılan) varsa primi hesapla.","Alıcının duyurudan önceki son 10-K’sını ve sonraki tüm 10-K’larını al; gelir, faaliyet marjı, şerefiye, şerefiye ÷ varlık, borç, seyreltilmiş hisse ve satın alma nakdini tabloya koy.","Özetle: yıllık gelir büyümesi, en büyük şerefiye artışı (başlangıç şerefiyesinin %10’undan büyükse), hisse sayısı değişimi (%3’ün üstü sulandırma olarak işaretlenir) ve en büyük satın alma ödemesi.","0. günden 30 işlem günü önce ile 250 gün sonrası arasında 100’ün büyümesi grafiğini çiz."],"example":"Örnek şirket duyurudan önceki gün 100’den, 0. gün 97’den kapanıyor: R = 97 ÷ 100 − 1 = −%3. SPY 400’den 404’e çıkıyor: +%1. Anormal getiri = −%3 − %1 = −%4: yatırımcılar anlaşmayı piyasanın genel havasından daha az beğendi. Alıcı, 65’ten kapanmış bir hedefe hisse başına 95 teklif ediyor: prim = 95 ÷ 65 − 1 ≈ %46.","read":["0. gündeki negatif anormal getiri, yatırımcıların alıcının fazla ödediğini veya anlaşmanın riskli olduğunu düşündüğünü; pozitif getiri anlaşmayı olumlu karşıladıklarını düşündürür.","Kısa pencereler haberi en iyi ayırır; 120 günlük pencereye başka birçok olay karışır.","Bir yıldaki büyük şerefiye artışı genelde anlaşmanın kapandığı yılı gösterir; varlıkların büyük kısmı şerefiyeyse bilançonun çoğu ödenen fiyata dayanıyordur.","Seyreltilmiş hisse artıyorsa alıcı kısmen hisseyle ödemiş ya da daha çok hisse bazlı ücret vermiştir; borç artıyorsa borçlanmıştır."],"limits":["Duyuru borsa kapandıktan sonra yapıldıysa ertesi günü gir; yoksa 0. gün tepkiyi kaçırır.","Söylentiler hedefin fiyatını önceden yükselttiyse gerçek prim daha büyüktür. İndirilen hedef kapanışı temettüye göre düzeltilmiştir; temettü ödeyen bir hedefte gerçek kapanıştan biraz düşük olabilir ve primi biraz büyük gösterebilir.","Öncesi/sonrası tablosu alıcının tüm 10-K’sıdır: başka satın almalar, kur ve döngü etkileri de içindedir; anlaşmanın neye yol açtığını kanıtlamaz.","Satın alma nakdi sütunu sadece standart etiketi kullanır, kendi etiketini kullanan şirketlerde (ör. Microsoft) boş kalır; faaliyet kârı raporlanmadıysa faaliyet marjı da boştur."]},"es":{"question":"Cuando una empresa anunció una adquisición, ¿cómo reaccionó su acción, qué prima ofreció y cómo cambiaron después sus cifras publicadas?","idea":"Comprar otra empresa es una gran apuesta. El movimiento de la acción en el anuncio muestra lo que pensaron los inversores ese día, después de quitar lo que hizo todo el mercado. La prima muestra cuánto por encima del precio de mercado ofreció el comprador. Las cifras del 10-K antes y después muestran qué hizo la operación (y todo lo demás) con los ingresos, márgenes, fondo de comercio, deuda y número de acciones.","formulas":[{"name":"Rentabilidad en una ventana","expr":"R = cierre del último día de la ventana ÷ cierre del día anterior al inicio de la ventana − 1","where":[["ventanas","día 0; días −1 a +1; 0 a +5; 0 a +20; 0 a +120 (sesiones bursátiles)"],["día 0","primera sesión en o después de la fecha de anuncio que introduces"],["cierre","cierre de Yahoo Finance ajustado por dividendos y splits"]]},{"name":"Rentabilidad anormal","expr":"Rentabilidad anormal = R(comprador) − R(SPY)","where":[["SPY","un fondo del índice S&P 500, usado como \"el mercado\""],["nota","una resta simple, no ajustada por beta"]]},{"name":"Prima de la oferta","expr":"Prima = precio ofrecido por acción ÷ último cierre del objetivo antes del día 0 − 1","where":[["precio ofrecido","lo que el comprador ofreció por cada acción del objetivo (tu dato)"],["cierre del objetivo","de Yahoo si el símbolo aún cotiza; si no, el cierre que escribes desde el folleto de fusión (DEFM14A)"]]},{"name":"Cambios antes/después","expr":"Crecimiento de ingresos = (Ingresos_último ÷ Ingresos_antes)^(1/años) − 1;  Peso del fondo de comercio = fondo de comercio ÷ activos totales;  Cambio de acciones = acciones diluidas_último ÷ acciones diluidas_antes − 1","where":[["antes","el último ejercicio cerrado antes del anuncio"],["fondo de comercio","lo pagado por encima del valor razonable de los activos netos identificables del objetivo"]]}],"data":[["Precios del comprador y de SPY","cierres diarios de Yahoo Finance ajustados por splits y dividendos"],["Fecha de anuncio, precio ofrecido","tus datos (del comunicado o del folleto de fusión)"],["Cierre del objetivo antes del anuncio","Yahoo Finance si el símbolo que das aún cotiza; si no, tu dato"],["Ingresos, beneficio operativo","10-K del comprador: us-gaap:RevenueFromContractWithCustomerExcludingAssessedTax / Revenues, OperatingIncomeLoss"],["Fondo de comercio, activos totales","us-gaap:Goodwill, Assets (cierre del ejercicio)"],["Deuda","us-gaap:LongTermDebtNoncurrent (si no LongTermDebt) + LongTermDebtCurrent (si no DebtCurrent / ShortTermBorrowings)"],["Acciones diluidas","us-gaap:WeightedAverageNumberOfDilutedSharesOutstanding, ajustadas por splits"],["Caja pagada por adquisiciones","us-gaap:PaymentsToAcquireBusinessesNetOfCashAcquired (estado de flujos de caja)"]],"steps":["Encuentra el día 0, la primera sesión en o después de la fecha que introduces (debe ser posterior a mediados de 2009 y no futura).","Calcula la rentabilidad del comprador y de SPY en cada ventana y su diferencia (rentabilidad anormal).","Si das un precio de oferta y un cierre del objetivo (descargado o escrito), calcula la prima.","Toma el último 10-K del comprador antes del anuncio y todos los posteriores, y tabula ingresos, margen operativo, fondo de comercio, fondo de comercio ÷ activos, deuda, acciones diluidas y caja de adquisiciones.","Resume: crecimiento anual de ingresos, el mayor salto del fondo de comercio (si supera el 10% del inicial), el cambio de acciones (más de 3% se marca como dilución) y el mayor pago por adquisiciones.","Dibuja un gráfico de crecimiento de 100 desde 30 sesiones antes hasta 250 después del día 0."],"example":"La empresa de ejemplo cierra a 100 el día antes del anuncio y a 97 el día 0: R = 97 ÷ 100 − 1 = −3%. SPY pasa de 400 a 404: +1%. Rentabilidad anormal = −3% − 1% = −4%: a los inversores la operación les gustó menos que el ánimo del mercado. El comprador ofrece 95 por acción por un objetivo que cerró a 65: prima = 95 ÷ 65 − 1 ≈ 46%.","read":["Una rentabilidad anormal negativa el día 0 sugiere que los inversores creen que el comprador pagó de más o que la operación es arriesgada; una positiva, que la recibieron bien.","Las ventanas cortas aíslan mejor la noticia; la de 120 días mezcla muchos otros sucesos.","Un gran salto del fondo de comercio en un año suele marcar cuándo se cerró la operación; si el fondo de comercio es gran parte de los activos, mucho del balance descansa en el precio pagado.","Si suben las acciones diluidas, el comprador pagó en parte con acciones o dio más remuneración en acciones; si sube la deuda, se endeudó."],"limits":["Si el anuncio fue después del cierre del mercado, introduce el día siguiente; si no, el día 0 no recoge la reacción.","Si los rumores movieron antes el precio del objetivo, la prima real es mayor. El cierre descargado del objetivo está ajustado por dividendos, así que en una empresa que paga dividendos puede quedar algo por debajo del cierre real y exagerar un poco la prima.","La tabla antes/después es todo el 10-K del comprador: incluye otras operaciones, divisas y el ciclo económico; no demuestra qué causó la operación.","La columna de caja por adquisiciones usa solo la etiqueta estándar y queda vacía en empresas con etiqueta propia (por ejemplo Microsoft); el margen operativo queda vacío si no se publica el beneficio operativo."]}},{"id":"credit_altman","number":17,"group":"risk","group_label":"Risk and credit","title":"Credit check and Altman Z","next":["piotroski","earnings_quality","capital_allocation"],"en":{"question":"Can the company carry its debt, judged by Altman Z scores and a few simple debt ratios?","idea":"Economist Edward Altman combined a handful of balance-sheet ratios into one number that, in his data, was low for companies that later got into trouble. The app computes two versions: Z'' (Z double prime) from book values for every year, and the classic Z, which uses today's stock-market value, for the latest year. Next to them it shows plain debt checks such as how many times operating profit covers the interest bill.","formulas":[{"name":"Altman Z'' (book values, every year)","expr":"Z'' = 6.56·(WC ÷ TA) + 3.26·(RE ÷ TA) + 6.72·(EBIT ÷ TA) + 1.05·(Equity ÷ TL)","where":[["WC","working capital = current assets − current liabilities, $ millions"],["TA","total assets, $ millions"],["RE","retained earnings (profits kept over the years), $ millions"],["EBIT","operating income (earnings before interest and tax), $ millions"],["Equity","book shareholders' equity, $ millions"],["TL","total liabilities, $ millions"],["zones","above 2.6 safe, 1.1 to 2.6 grey, below 1.1 distress"]]},{"name":"Classic Altman Z (latest year, with market value)","expr":"Z = 1.2·(WC ÷ TA) + 1.4·(RE ÷ TA) + 3.3·(EBIT ÷ TA) + 0.6·(MV ÷ TL) + 1.0·(Sales ÷ TA)","where":[["MV","market value of the shares = last closing price × shares outstanding, $ millions"],["Sales","revenue of the latest fiscal year, $ millions"],["zones","above 2.99 safe, 1.81 to 2.99 grey, below 1.81 distress"]]},{"name":"Interest coverage","expr":"Coverage = EBIT ÷ interest expense","where":[["Coverage","times (×) operating profit covers the interest bill"]]},{"name":"Net debt to EBITDA","expr":"Net debt ÷ EBITDA = (long-term debt + current debt − cash) ÷ (EBIT + depreciation and amortization)","where":[["EBITDA","EBIT plus depreciation and amortization; the ratio is shown only when EBITDA > 0"],["result","years of operating cash profit needed to pay off net debt"]]}],"data":[["Total assets, total liabilities, equity, current assets and liabilities, cash, retained earnings, debt","the company's annual 10-K balance sheets, read from SEC XBRL data (up to 6 fiscal years)"],["Operating income, revenue, interest expense, depreciation and amortization","the 10-K income and cash-flow statements in SEC XBRL; if operating income is missing, EBIT = pre-tax income + interest expense"],["Shares outstanding","the cover page of the latest 10-K or 10-Q (SEC), else the latest diluted average share count"],["Share price","the latest adjusted closing price (Yahoo Finance)"]],"steps":["Read up to 6 fiscal years of 10-K figures from SEC data (amounts in other currencies are converted to dollars).","For each year compute Z'' and its zone, interest coverage, net debt ÷ EBITDA, the current ratio and debt ÷ assets.","For the latest year only, compute the classic Z using today's market value (last close × shares outstanding).","If an input is missing, that score is left blank instead of being treated as zero.","Show the table and a Z'' chart over time, and warn when current assets or operating income are not reported (typical of banks and insurers)."],"example":"Example company, in $ millions: total assets 1,000; current assets 400 and current liabilities 200, so WC = 200; retained earnings 300; EBIT 100; equity 400; total liabilities 600; sales 1,200; market value 900; interest 20. Z'' = 6.56×0.20 + 3.26×0.30 + 6.72×0.10 + 1.05×(400 ÷ 600 ≈ 0.667) = 1.312 + 0.978 + 0.672 + 0.700 ≈ 3.66, above 2.6, so the safe zone. Classic Z = 1.2×0.20 + 1.4×0.30 + 3.3×0.10 + 0.6×(900 ÷ 600 = 1.5) + 1.0×(1,200 ÷ 1,000 = 1.2) = 0.24 + 0.42 + 0.33 + 0.90 + 1.20 = 3.09, above 2.99, safe. Interest coverage = 100 ÷ 20 = 5×.","read":["A higher score means a stronger balance sheet; the trend over the years usually says more than one value.","The grey zone means the score cannot tell; it is a band, not a verdict.","Interest coverage near or below 1× means operating profit barely covers interest; a negative value means an operating loss.","Net debt ÷ EBITDA below zero means the company holds more cash than debt."],"limits":["The scores do not predict bankruptcy; they are statistical summaries of balance-sheet strength (the app says this in its notes).","Both formulas are applied to every company: Z'' was built for non-manufacturers and the classic Z for manufacturers, so read the one that fits. The classic Z mixes today's share price with the last annual balance sheet, so it moves with the market.","Banks and insurers do not report current assets or operating income, so Altman scores do not apply to them.","Debt counts only the reported loan lines (long-term and current debt), not lease liabilities; this analysis does not assign a credit rating."]},"tr":{"question":"Şirket borcunu taşıyabilir mi? Altman Z skorlarına ve birkaç basit borç oranına göre bakar.","idea":"İktisatçı Edward Altman birkaç bilanço oranını tek bir sayıda birleştirdi; onun verilerinde bu sayı, sonradan zor duruma düşen şirketlerde düşüktü. Uygulama iki sürüm hesaplar: her yıl için defter değerleriyle Z'' (Z çift üssü) ve son yıl için bugünkü borsa değerini kullanan klasik Z. Yanında faaliyet kârının faiz giderini kaç kez karşıladığı gibi basit borç ölçülerini de gösterir.","formulas":[{"name":"Altman Z'' (defter değerleri, her yıl)","expr":"Z'' = 6,56·(İS ÷ TV) + 3,26·(DK ÷ TV) + 6,72·(FVÖK ÷ TV) + 1,05·(Özkaynak ÷ TY)","where":[["İS","işletme sermayesi = dönen varlıklar − kısa vadeli yükümlülükler, milyon $"],["TV","toplam varlıklar, milyon $"],["DK","dağıtılmamış kârlar (yıllar içinde şirkette bırakılan kâr), milyon $"],["FVÖK","faaliyet kârı (faiz ve vergi öncesi kâr), milyon $"],["Özkaynak","defter değeriyle özkaynak, milyon $"],["TY","toplam yükümlülükler, milyon $"],["bölgeler","2,6 üstü güvenli, 1,1–2,6 gri, 1,1 altı riskli"]]},{"name":"Klasik Altman Z (son yıl, piyasa değeriyle)","expr":"Z = 1,2·(İS ÷ TV) + 1,4·(DK ÷ TV) + 3,3·(FVÖK ÷ TV) + 0,6·(PD ÷ TY) + 1,0·(Satışlar ÷ TV)","where":[["PD","hisselerin piyasa değeri = son kapanış fiyatı × dolaşımdaki hisse sayısı, milyon $"],["Satışlar","son mali yılın hasılatı, milyon $"],["bölgeler","2,99 üstü güvenli, 1,81–2,99 gri, 1,81 altı riskli"]]},{"name":"Faiz karşılama oranı","expr":"Karşılama = FVÖK ÷ faiz gideri","where":[["Karşılama","faaliyet kârının faiz giderini kaç kez (×) karşıladığı"]]},{"name":"Net borç / FAVÖK","expr":"Net borç ÷ FAVÖK = (uzun vadeli borç + kısa vadeli borç − nakit) ÷ (FVÖK + amortisman)","where":[["FAVÖK","FVÖK artı amortisman; oran yalnızca FAVÖK > 0 ise gösterilir"],["sonuç","net borcu ödemek için gereken faaliyet nakit kârı, yıl olarak"]]}],"data":[["Toplam varlık, toplam yükümlülük, özkaynak, dönen varlık ve kısa vadeli yükümlülük, nakit, dağıtılmamış kâr, borç","şirketin yıllık 10-K bilançoları, SEC XBRL verisinden (en fazla 6 mali yıl)"],["Faaliyet kârı, hasılat, faiz gideri, amortisman","SEC XBRL'deki 10-K gelir ve nakit akış tabloları; faaliyet kârı yoksa FVÖK = vergi öncesi kâr + faiz gideri"],["Dolaşımdaki hisse sayısı","son 10-K veya 10-Q'nun kapak sayfası (SEC), yoksa son seyreltilmiş ortalama hisse sayısı"],["Hisse fiyatı","son düzeltilmiş kapanış fiyatı (Yahoo Finance)"]],"steps":["SEC verisinden en fazla 6 mali yılın 10-K rakamlarını yükler (başka para birimindeki tutarlar dolara çevrilir).","Her yıl için Z'' ve bölgesini, faiz karşılama oranını, net borç ÷ FAVÖK'ü, cari oranı ve borç ÷ varlık oranını hesaplar.","Yalnızca son yıl için bugünkü piyasa değeriyle (son kapanış × hisse sayısı) klasik Z'yi hesaplar.","Bir girdi eksikse o skor sıfır sayılmaz, boş bırakılır.","Tabloyu ve yıllara göre Z'' grafiğini gösterir; dönen varlık veya faaliyet kârı raporlanmamışsa (bankalarda ve sigortacılarda olduğu gibi) uyarır."],"example":"Örnek şirket, milyon $: toplam varlık 1.000; dönen varlık 400 ve kısa vadeli yükümlülük 200, yani İS = 200; dağıtılmamış kâr 300; FVÖK 100; özkaynak 400; toplam yükümlülük 600; satışlar 1.200; piyasa değeri 900; faiz 20. Z'' = 6,56×0,20 + 3,26×0,30 + 6,72×0,10 + 1,05×(400 ÷ 600 ≈ 0,667) = 1,312 + 0,978 + 0,672 + 0,700 ≈ 3,66; 2,6'nın üstünde, yani güvenli bölge. Klasik Z = 1,2×0,20 + 1,4×0,30 + 3,3×0,10 + 0,6×(900 ÷ 600 = 1,5) + 1,0×(1.200 ÷ 1.000 = 1,2) = 0,24 + 0,42 + 0,33 + 0,90 + 1,20 = 3,09; 2,99'un üstünde, güvenli. Faiz karşılama = 100 ÷ 20 = 5×.","read":["Skor yükseldikçe bilanço güçlüdür; tek bir değerden çok yıllar içindeki eğilim önemlidir.","Gri bölge, skorun karar veremediği anlamına gelir; bir hüküm değil, bir aralıktır.","Faiz karşılama 1× civarında veya altındaysa faaliyet kârı faizi zor karşılıyor demektir; negatifse faaliyet zararı vardır.","Net borç ÷ FAVÖK sıfırın altındaysa şirketin nakdi borcundan fazladır."],"limits":["Skorlar iflası tahmin etmez; bilanço gücünü özetleyen istatistiksel göstergelerdir (uygulama notlarda bunu söyler).","İki formül de her şirkete uygulanır: Z'' imalat dışı şirketler, klasik Z imalatçılar için kurulmuştur; sana uyanı oku. Klasik Z bugünkü hisse fiyatını son yıllık bilançoyla karıştırır, bu yüzden piyasayla birlikte oynar.","Bankalar ve sigorta şirketleri dönen varlık veya faaliyet kârı raporlamaz; Altman skorları bunlara uygulanmaz.","Borç yalnızca raporlanan kredi kalemlerini (uzun ve kısa vadeli borç) sayar, kira yükümlülüklerini saymaz; bu analiz kredi notu vermez."]},"es":{"question":"¿Puede la empresa soportar su deuda, según las puntuaciones Z de Altman y unas pocas ratios de deuda sencillas?","idea":"El economista Edward Altman combinó unas pocas ratios del balance en un solo número que, en sus datos, era bajo en las empresas que luego tuvieron problemas. La app calcula dos versiones: Z'' (Z doble prima) con valores contables para cada año y la Z clásica, que usa el valor de mercado actual de las acciones, para el último año. Al lado muestra comprobaciones de deuda sencillas, como cuántas veces el beneficio operativo cubre los intereses.","formulas":[{"name":"Z'' de Altman (valores contables, cada año)","expr":"Z'' = 6,56·(CT ÷ AT) + 3,26·(BR ÷ AT) + 6,72·(EBIT ÷ AT) + 1,05·(Patrimonio ÷ PT)","where":[["CT","capital de trabajo = activo corriente − pasivo corriente, millones de $"],["AT","activo total, millones de $"],["BR","beneficios retenidos (beneficios acumulados que se quedaron en la empresa), millones de $"],["EBIT","beneficio operativo (antes de intereses e impuestos), millones de $"],["Patrimonio","patrimonio neto contable, millones de $"],["PT","pasivo total, millones de $"],["zonas","más de 2,6 segura, de 1,1 a 2,6 gris, menos de 1,1 de riesgo"]]},{"name":"Z clásica de Altman (último año, con valor de mercado)","expr":"Z = 1,2·(CT ÷ AT) + 1,4·(BR ÷ AT) + 3,3·(EBIT ÷ AT) + 0,6·(VM ÷ PT) + 1,0·(Ventas ÷ AT)","where":[["VM","valor de mercado de las acciones = último cierre × acciones en circulación, millones de $"],["Ventas","ingresos del último ejercicio, millones de $"],["zonas","más de 2,99 segura, de 1,81 a 2,99 gris, menos de 1,81 de riesgo"]]},{"name":"Cobertura de intereses","expr":"Cobertura = EBIT ÷ gasto por intereses","where":[["Cobertura","veces (×) que el beneficio operativo cubre los intereses"]]},{"name":"Deuda neta sobre EBITDA","expr":"Deuda neta ÷ EBITDA = (deuda a largo plazo + deuda a corto plazo − efectivo) ÷ (EBIT + depreciación y amortización)","where":[["EBITDA","EBIT más depreciación y amortización; la ratio solo se muestra si EBITDA > 0"],["resultado","años de beneficio operativo en efectivo necesarios para pagar la deuda neta"]]}],"data":[["Activo total, pasivo total, patrimonio, activo y pasivo corriente, efectivo, beneficios retenidos, deuda","los balances anuales del 10-K de la empresa, leídos de los datos XBRL de la SEC (hasta 6 ejercicios)"],["Beneficio operativo, ingresos, gasto por intereses, depreciación y amortización","las cuentas de resultados y de flujos de efectivo del 10-K en XBRL de la SEC; si falta el beneficio operativo, EBIT = beneficio antes de impuestos + intereses"],["Acciones en circulación","la portada del último 10-K o 10-Q (SEC); si no, el último promedio diluido de acciones"],["Precio de la acción","el último cierre ajustado (Yahoo Finance)"]],"steps":["Carga hasta 6 ejercicios de cifras del 10-K de la SEC (los importes en otras monedas se pasan a dólares).","Para cada año calcula Z'' y su zona, la cobertura de intereses, la deuda neta ÷ EBITDA, la ratio corriente y la deuda ÷ activo.","Solo para el último año calcula la Z clásica con el valor de mercado actual (último cierre × acciones en circulación).","Si falta un dato, esa puntuación queda en blanco en vez de contarse como cero.","Muestra la tabla y un gráfico de Z'' a lo largo del tiempo, y avisa cuando no se informa el activo corriente o el beneficio operativo (típico de bancos y aseguradoras)."],"example":"Empresa de ejemplo, en millones de $: activo total 1.000; activo corriente 400 y pasivo corriente 200, así que CT = 200; beneficios retenidos 300; EBIT 100; patrimonio 400; pasivo total 600; ventas 1.200; valor de mercado 900; intereses 20. Z'' = 6,56×0,20 + 3,26×0,30 + 6,72×0,10 + 1,05×(400 ÷ 600 ≈ 0,667) = 1,312 + 0,978 + 0,672 + 0,700 ≈ 3,66; más de 2,6, zona segura. Z clásica = 1,2×0,20 + 1,4×0,30 + 3,3×0,10 + 0,6×(900 ÷ 600 = 1,5) + 1,0×(1.200 ÷ 1.000 = 1,2) = 0,24 + 0,42 + 0,33 + 0,90 + 1,20 = 3,09; más de 2,99, segura. Cobertura de intereses = 100 ÷ 20 = 5×.","read":["Una puntuación más alta indica un balance más sólido; la tendencia de varios años dice más que un solo valor.","La zona gris significa que la puntuación no lo aclara; es una franja, no un veredicto.","Una cobertura cercana o inferior a 1× significa que el beneficio operativo apenas cubre los intereses; un valor negativo indica pérdida operativa.","Una deuda neta ÷ EBITDA negativa significa que la empresa tiene más efectivo que deuda."],"limits":["Las puntuaciones no predicen la quiebra; son resúmenes estadísticos de la solidez del balance (la app lo dice en sus notas).","Las dos fórmulas se aplican a todas las empresas: Z'' se creó para empresas no manufactureras y la Z clásica para manufactureras; lee la que corresponda. La Z clásica mezcla el precio actual con el último balance anual, así que se mueve con el mercado.","Bancos y aseguradoras no informan activo corriente ni beneficio operativo, así que las puntuaciones de Altman no se les aplican.","La deuda solo incluye las partidas de préstamos informadas (largo y corto plazo), no los pasivos por arrendamiento; este análisis no asigna una calificación crediticia."]}},{"id":"beta","number":18,"group":"risk","group_label":"Risk and credit","title":"Beta and CAPM","next":["factors","crisis","dcf"],"en":{"question":"How much does the stock tend to move when the whole market moves, and what return does CAPM then ask for?","idea":"Beta compares the stock's returns with those of SPY, a fund that tracks the S&P 500 index of large US companies. A beta of 1 means it moved with the market on average; 1.5 means about 1.5% for each 1% market move. CAPM (Capital Asset Pricing Model) turns beta into a cost of equity: the yearly return investors demand, equal to a safe interest rate plus beta times the extra return the stock market is expected to pay.","formulas":[{"name":"Beta","expr":"β = Cov(Rₛ, Rₘ) ÷ Var(Rₘ)","where":[["Rₛ","the stock's simple return each week or month, from adjusted closes"],["Rₘ","SPY's return over the same weeks or months"],["Cov, Var","covariance and variance of those returns"]]},{"name":"Alpha (annual)","expr":"α = (mean Rₛ − β × mean Rₘ) × periods per year × 100","where":[["periods per year","52 for weekly returns, 12 for monthly returns"],["α","% a year; computed on raw returns, not on returns above the risk-free rate"]]},{"name":"R squared","expr":"R² = Corr(Rₛ, Rₘ)²","where":[["R²","share of the stock's ups and downs that moved in line with the market, 0 to 1"]]},{"name":"CAPM cost of equity","expr":"Cost of equity = r_f + β × ERP","where":[["r_f","risk-free rate, % a year (10-year US Treasury yield by default)"],["ERP","equity risk premium, % a year (Damodaran's implied premium for the S&P 500 by default)"]]}],"data":[["Stock and SPY prices","5 years of daily closes adjusted for splits and dividends, Yahoo Finance"],["Risk-free rate r_f","your input, else the 10-year US Treasury yield from FRED (series DGS10), else the Treasury yield curve, else a labelled 4% assumption"],["Equity risk premium ERP","your input, else Aswath Damodaran's implied premium for the S&P 500 (NYU Stern), else a labelled 5% assumption"]],"steps":["Download 5 years of adjusted daily closes for each symbol (1 to 5) and for SPY.","Turn them into returns three ways: weekly (Friday closes) over 5 years, weekly over the last 2 years, and monthly (month-end closes) over 5 years.","For each window regress the stock on SPY: beta, annual alpha, R², annual volatility and a Newey–West t-statistic (a version robust to volatility clusters); at least 20 returns are needed.","Compute the CAPM cost of equity for each window.","Use the 5-year monthly beta for the headline (above 1.1 more volatile than the market, below 0.9 less) and chart the growth of 100 over 2 years against SPY."],"example":"Example company: over 60 months the covariance of its monthly returns with the market is 0.0024 and the market's variance is 0.0020, so β = 0.0024 ÷ 0.0020 = 1.2. A 1% market move went with about a 1.2% move on average. With r_f = 4% and ERP = 5%, the cost of equity = 4% + 1.2 × 5% = 10% a year.","read":["Beta above 1 amplifies market moves, below 1 dampens them, near 0 means little link, negative means it tended to move the other way.","A low R² means company news drives most moves, so beta says less about the stock's total risk.","A t-statistic beyond about ±2 means beta is clearly different from zero.","Compare the three windows: if they disagree a lot, beta is unstable and any single number is shaky."],"limits":["Beta changes with the window and the return frequency; there is no single true beta (the app says so).","It describes past co-movement; a change in the business, its debt or the market can change it.","Alpha here is computed on raw returns, not on returns above the risk-free rate, so it is a rough gap and not a measure of skill.","The cost of equity depends heavily on the r_f and ERP you choose; the app accepts 0–10% and 2–9%."]},"tr":{"question":"Tüm piyasa hareket ettiğinde hisse ne kadar hareket etme eğiliminde ve CAPM buna göre ne getiri ister?","idea":"Beta, hissenin getirilerini ABD'nin büyük şirketlerinden oluşan S&P 500 endeksini izleyen SPY fonunun getirileriyle karşılaştırır. Beta 1 ise hisse ortalamada piyasayla birlikte hareket etmiş demektir; 1,5 ise piyasanın her %1'lik hareketinde yaklaşık %1,5. CAPM (Sermaye Varlıklarını Fiyatlama Modeli) betayı özkaynak maliyetine çevirir: yatırımcının istediği yıllık getiri = risksiz faiz + beta × borsanın beklenen ek getirisi.","formulas":[{"name":"Beta","expr":"β = Kov(Rₕ, Rₚ) ÷ Var(Rₚ)","where":[["Rₕ","hissenin haftalık veya aylık basit getirisi, düzeltilmiş kapanışlardan"],["Rₚ","aynı hafta veya aylarda SPY'nin getirisi"],["Kov, Var","bu getirilerin kovaryansı ve varyansı"]]},{"name":"Alfa (yıllık)","expr":"α = (ort. Rₕ − β × ort. Rₚ) × yıldaki dönem sayısı × 100","where":[["yıldaki dönem sayısı","haftalık getiride 52, aylık getiride 12"],["α","yıllık %; risksiz faizin üstündeki getiriyle değil, ham getirilerle hesaplanır"]]},{"name":"R kare","expr":"R² = Kor(Rₕ, Rₚ)²","where":[["R²","hissenin iniş çıkışlarının piyasayla uyumlu hareket eden kısmı, 0 ile 1 arası"]]},{"name":"CAPM özkaynak maliyeti","expr":"Özkaynak maliyeti = r_f + β × HRP","where":[["r_f","risksiz faiz, yıllık % (varsayılan: 10 yıllık ABD tahvil faizi)"],["HRP","hisse risk primi, yıllık % (varsayılan: Damodaran'ın S&P 500 için ima edilen primi)"]]}],"data":[["Hisse ve SPY fiyatları","bölünme ve temettüye göre düzeltilmiş 5 yıllık günlük kapanışlar, Yahoo Finance"],["Risksiz faiz r_f","senin girdin; yoksa FRED'den 10 yıllık ABD tahvil faizi (DGS10 serisi); yoksa Hazine getiri eğrisi; o da yoksa etiketli %4 varsayımı"],["Hisse risk primi HRP","senin girdin; yoksa Aswath Damodaran'ın S&P 500 için ima edilen primi (NYU Stern); yoksa etiketli %5 varsayımı"]],"steps":["Her sembol (1 ile 5 arası) ve SPY için 5 yıllık düzeltilmiş günlük kapanışları indirir.","Bunları üç şekilde getiriye çevirir: 5 yıl boyunca haftalık (cuma kapanışları), son 2 yılda haftalık ve 5 yıl boyunca aylık (ay sonu kapanışları).","Her pencerede hisseyi SPY'ye göre regresyonla inceler: beta, yıllık alfa, R², yıllık oynaklık ve Newey–West t istatistiği (oynaklık kümelenmesine dayanıklı bir sürüm); en az 20 getiri gerekir.","Her pencere için CAPM özkaynak maliyetini hesaplar.","Başlık bulgusunda 5 yıllık aylık betayı kullanır (1,1 üstü piyasadan oynak, 0,9 altı daha az oynak) ve SPY'ye karşı 2 yıllık 100'ün büyümesi grafiğini çizer."],"example":"Örnek şirket: 60 ay boyunca aylık getirilerinin piyasayla kovaryansı 0,0024, piyasanın varyansı 0,0020; yani β = 0,0024 ÷ 0,0020 = 1,2. Piyasanın %1'lik hareketine ortalama %1,2'lik hareket eşlik etmiş. r_f = %4 ve HRP = %5 ise özkaynak maliyeti = %4 + 1,2 × %5 = yıllık %10.","read":["Beta 1'in üstündeyse piyasa hareketlerini büyütür, altındaysa yumuşatır; 0'a yakınsa bağ zayıftır, negatifse ters yönde hareket etme eğilimindedir.","R² düşükse hareketlerin çoğunu şirket haberleri belirler; o zaman beta hissenin toplam riski hakkında daha az şey söyler.","t istatistiği yaklaşık ±2'nin ötesindeyse beta sıfırdan belirgin şekilde farklıdır.","Üç pencereyi karşılaştır: birbirinden çok farklıysa beta istikrarsızdır ve tek bir sayıya güvenmek zordur."],"limits":["Beta pencereye ve getiri sıklığına göre değişir; tek bir “doğru” beta yoktur (uygulama da bunu söyler).","Geçmişteki birlikte hareketi anlatır; işin, borcun veya piyasanın değişmesi onu değiştirebilir.","Buradaki alfa risksiz faizin üstündeki getiriyle değil ham getirilerle hesaplanır; kaba bir farktır, beceri ölçüsü değildir.","Özkaynak maliyeti seçtiğin r_f ve HRP'ye çok bağlıdır; uygulama %0–10 ve %2–9 aralıklarını kabul eder."]},"es":{"question":"¿Cuánto suele moverse la acción cuando se mueve todo el mercado, y qué rentabilidad pide entonces el CAPM?","idea":"La beta compara las rentabilidades de la acción con las de SPY, un fondo que sigue el índice S&P 500 de grandes empresas de EE. UU. Una beta de 1 significa que en promedio se movió con el mercado; 1,5 significa alrededor de 1,5% por cada 1% del mercado. El CAPM (modelo de valoración de activos de capital) convierte la beta en un coste del capital propio: la rentabilidad anual que exigen los inversores, igual a un tipo sin riesgo más beta por la rentabilidad extra que se espera de la bolsa.","formulas":[{"name":"Beta","expr":"β = Cov(Rₐ, Rₘ) ÷ Var(Rₘ)","where":[["Rₐ","rentabilidad simple semanal o mensual de la acción, con cierres ajustados"],["Rₘ","rentabilidad de SPY en las mismas semanas o meses"],["Cov, Var","covarianza y varianza de esas rentabilidades"]]},{"name":"Alfa (anual)","expr":"α = (media Rₐ − β × media Rₘ) × periodos por año × 100","where":[["periodos por año","52 con rentabilidades semanales, 12 con mensuales"],["α","% anual; se calcula con rentabilidades brutas, no con las que superan el tipo sin riesgo"]]},{"name":"R cuadrado","expr":"R² = Corr(Rₐ, Rₘ)²","where":[["R²","parte de las subidas y bajadas de la acción que fue en línea con el mercado, de 0 a 1"]]},{"name":"Coste del capital propio (CAPM)","expr":"Coste del capital propio = r_f + β × PRM","where":[["r_f","tipo sin riesgo, % anual (por defecto, rendimiento del bono del Tesoro de EE. UU. a 10 años)"],["PRM","prima de riesgo del mercado de acciones, % anual (por defecto, la prima implícita del S&P 500 de Damodaran)"]]}],"data":[["Precios de la acción y de SPY","5 años de cierres diarios ajustados por splits y dividendos, Yahoo Finance"],["Tipo sin riesgo r_f","tu dato; si no, el rendimiento del Tesoro de EE. UU. a 10 años de FRED (serie DGS10); si no, la curva del Tesoro; si no, un supuesto etiquetado de 4%"],["Prima de riesgo PRM","tu dato; si no, la prima implícita del S&P 500 de Aswath Damodaran (NYU Stern); si no, un supuesto etiquetado de 5%"]],"steps":["Descarga 5 años de cierres diarios ajustados de cada símbolo (de 1 a 5) y de SPY.","Los convierte en rentabilidades de tres formas: semanales (cierres del viernes) en 5 años, semanales en los últimos 2 años y mensuales (cierres de fin de mes) en 5 años.","En cada ventana hace la regresión de la acción sobre SPY: beta, alfa anual, R², volatilidad anual y un estadístico t de Newey–West (una versión robusta a los grupos de volatilidad); hacen falta al menos 20 rentabilidades.","Calcula el coste del capital propio del CAPM para cada ventana.","Usa la beta mensual de 5 años en el titular (más de 1,1 más volátil que el mercado, menos de 0,9 menos volátil) y dibuja el crecimiento de 100 en 2 años frente a SPY."],"example":"Empresa de ejemplo: en 60 meses la covarianza de sus rentabilidades mensuales con el mercado es 0,0024 y la varianza del mercado 0,0020, así que β = 0,0024 ÷ 0,0020 = 1,2. Un movimiento del mercado de 1% fue acompañado en promedio de un 1,2%. Con r_f = 4% y PRM = 5%, el coste del capital propio = 4% + 1,2 × 5% = 10% anual.","read":["Una beta mayor que 1 amplifica los movimientos del mercado, menor que 1 los suaviza, cerca de 0 indica poca relación y negativa que tendía a moverse al revés.","Un R² bajo significa que las noticias de la empresa explican la mayor parte de los movimientos, así que la beta dice menos sobre el riesgo total.","Un estadístico t más allá de ±2 aproximadamente indica que la beta es claramente distinta de cero.","Compara las tres ventanas: si difieren mucho, la beta es inestable y un solo número es poco fiable."],"limits":["La beta cambia con la ventana y la frecuencia de las rentabilidades; no existe una única beta “verdadera” (la app lo dice).","Describe el comovimiento pasado; un cambio en el negocio, en su deuda o en el mercado puede cambiarla.","Aquí la alfa se calcula con rentabilidades brutas, no con las que superan el tipo sin riesgo; es una diferencia aproximada, no una medida de habilidad.","El coste del capital propio depende mucho del r_f y la PRM que elijas; la app acepta 0–10% y 2–9%."]}},{"id":"crisis","number":19,"group":"quant","group_label":"Quant","title":"Crisis behaviour","next":["beta","portfolio","uncertainty"],"en":{"question":"How far did the stock fall in two recent market crises, and how long did it take to get back to its pre-crisis price?","idea":"Crises show how a stock behaves under stress. The analysis takes two fixed periods, the 2020 COVID crash and the 2022 rate shock, and for each stock measures the deepest drop from the price at the start of the period and how many days it took from the bottom to climb back. The S&P 500 fund SPY is always added so you can compare with the market.","formulas":[{"name":"Largest fall","expr":"Fall = min(P in window) ÷ P_start − 1","where":[["P_start","adjusted close on the first trading day of the window (19 Feb 2020 or 3 Jan 2022)"],["min(P in window)","lowest adjusted close up to 23 Mar 2020 or 12 Oct 2022"],["Fall","%, negative; a fall smaller than 0.5% is shown as \"never fell below its starting level\""]]},{"name":"Recovery time","expr":"Days to recover = date of first close ≥ P_start after the bottom − date of the bottom","where":[["bottom","day of the lowest close in the window"],["days","calendar days, not trading days; empty if the price has not come back yet"]]},{"name":"Return over the window","expr":"Window return = P_last ÷ P_start − 1","where":[["P_last","adjusted close on the last trading day of the window"]]}],"data":[["Prices","10 years of daily adjusted closing prices, dividends included (Yahoo Finance; latest close cross-checked with Stooq)"],["Benchmark","SPY (S&P 500 ETF), added automatically"],["Crisis windows","fixed in the code: 19 Feb – 23 Mar 2020 (S&P 500 peak to trough) and 3 Jan – 12 Oct 2022"]],"steps":["Download prices for your 1–8 symbols and SPY.","For each crisis window, take the first close as the starting level and find the lowest close and its date.","Compute the fall from the starting level and the return over the whole window.","Search after the bottom for the first close back at or above the starting level, and count the calendar days.","Compare symbols: smallest and largest fall, who never fell, who has not recovered yet."],"example":"Example company: on 19 Feb 2020 it closes at 200. Its lowest close in the window is 140 on 16 Mar 2020, so the fall is 140 ÷ 200 − 1 = −30%. It first closes at 200 or above again on 10 Jun 2020, so days to recover = 31 + 30 + 25 = 86 calendar days.","read":["A smaller fall than SPY means the stock held up better than the market in that crisis; a bigger fall means it was hit harder.","Short recovery times show resilience; an empty recovery date means it is still below its pre-crisis price.","Compare the two crises: a stock can be calm in a health shock and hit hard in a rate shock, or the other way round."],"limits":["Only two crises, with dates fixed in the code; the next crisis can look completely different, and past crises do not predict it.","The fall is measured from the window's first day, not from the stock's own peak; a stock that peaked earlier or later can look better or worse than its true worst drop.","Adjusted prices include dividends, so \"recovered\" means total return came back, not necessarily the quoted price.","The stocks are ones that trade today; companies that did not survive a crisis are missing (survivorship bias), which the app warns about."]},"tr":{"question":"Hisse yakın geçmişteki iki piyasa krizinde ne kadar düştü ve kriz öncesi fiyatına dönmesi ne kadar sürdü?","idea":"Krizler bir hissenin baskı altında nasıl davrandığını gösterir. Analiz iki sabit dönemi, 2020 COVID çöküşünü ve 2022 faiz şokunu ele alır; her hisse için dönem başındaki fiyattan en derin düşüşü ve dipten geri çıkmanın kaç gün sürdüğünü ölçer. Piyasayla karşılaştırabilmen için S&P 500 fonu SPY her zaman eklenir.","formulas":[{"name":"En büyük düşüş","expr":"Düşüş = min(penceredeki P) ÷ P_başlangıç − 1","where":[["P_başlangıç","pencerenin ilk işlem günündeki düzeltilmiş kapanış (19 Şub 2020 veya 3 Oca 2022)"],["min(penceredeki P)","23 Mar 2020 veya 12 Eki 2022’ye kadarki en düşük düzeltilmiş kapanış"],["Düşüş","%, negatif; %0,5’ten küçük düşüş \"başlangıç seviyesinin altına düşmedi\" olarak gösterilir"]]},{"name":"Toparlanma süresi","expr":"Toparlanma günü = dipten sonra ilk kez P_başlangıç’a ulaşan kapanışın tarihi − dip tarihi","where":[["dip","penceredeki en düşük kapanışın günü"],["gün","takvim günü, işlem günü değil; fiyat henüz geri dönmediyse boş"]]},{"name":"Pencere boyunca getiri","expr":"Pencere getirisi = P_son ÷ P_başlangıç − 1","where":[["P_son","pencerenin son işlem günündeki düzeltilmiş kapanış"]]}],"data":[["Fiyatlar","10 yıllık günlük düzeltilmiş kapanışlar, temettüler dahil (Yahoo Finance; son kapanış Stooq ile karşılaştırılır)"],["Karşılaştırma","SPY (S&P 500 ETF’si), otomatik eklenir"],["Kriz pencereleri","kodda sabit: 19 Şub – 23 Mar 2020 (S&P 500 zirve-dip) ve 3 Oca – 12 Eki 2022"]],"steps":["1–8 sembolün ve SPY’nin fiyatlarını indir.","Her kriz penceresi için ilk kapanışı başlangıç seviyesi al; en düşük kapanışı ve tarihini bul.","Başlangıç seviyesinden düşüşü ve tüm pencere boyunca getiriyi hesapla.","Dipten sonra başlangıç seviyesine veya üstüne dönen ilk kapanışı ara ve takvim günlerini say.","Sembolleri karşılaştır: en az ve en çok düşen, hiç düşmeyen, henüz toparlanmayan."],"example":"Örnek şirket: 19 Şub 2020’de 200’den kapanıyor. Penceredeki en düşük kapanışı 16 Mar 2020’de 140; düşüş 140 ÷ 200 − 1 = −%30. İlk kez 10 Haz 2020’de yeniden 200 veya üstünde kapanıyor; toparlanma süresi = 31 + 30 + 25 = 86 takvim günü.","read":["SPY’den küçük bir düşüş, hissenin o krizde piyasadan iyi dayandığını; daha büyük bir düşüş daha sert etkilendiğini gösterir.","Kısa toparlanma süreleri dayanıklılığı gösterir; boş bir toparlanma tarihi, hissenin hâlâ kriz öncesi fiyatının altında olduğu anlamına gelir.","İki krizi karşılaştır: bir hisse sağlık şokunda sakin kalıp faiz şokunda sert etkilenebilir, ya da tersi."],"limits":["Yalnızca iki kriz var ve tarihleri kodda sabit; bir sonraki kriz bambaşka görünebilir ve geçmiş krizler onu tahmin etmez.","Düşüş hissenin kendi zirvesinden değil pencerenin ilk gününden ölçülür; daha önce veya sonra zirve yapan bir hisse gerçek en kötü düşüşünden daha iyi ya da kötü görünebilir.","Düzeltilmiş fiyatlar temettüleri içerir; \"toparlandı\" toplam getirinin geri geldiği anlamına gelir, kote fiyatın değil.","Hisseler bugün işlem görenler; krizden sağ çıkamayan şirketler yok (hayatta kalma yanılgısı); uygulama bunu uyarır."]},"es":{"question":"¿Cuánto cayó la acción en dos crisis recientes del mercado y cuánto tardó en volver a su precio previo a la crisis?","idea":"Las crisis muestran cómo se comporta una acción bajo presión. El análisis toma dos periodos fijos, el desplome por la COVID de 2020 y el choque de tipos de 2022, y para cada acción mide la mayor caída desde el precio del inicio del periodo y cuántos días tardó en recuperarse desde el mínimo. Siempre se añade el fondo del S&P 500, SPY, para comparar con el mercado.","formulas":[{"name":"Mayor caída","expr":"Caída = mín(P en la ventana) ÷ P_inicio − 1","where":[["P_inicio","cierre ajustado de la primera sesión de la ventana (19 feb 2020 o 3 ene 2022)"],["mín(P en la ventana)","cierre ajustado más bajo hasta el 23 mar 2020 o el 12 oct 2022"],["Caída","%, negativa; una caída menor del 0,5 % se muestra como \"no bajó de su nivel inicial\""]]},{"name":"Tiempo de recuperación","expr":"Días para recuperarse = fecha del primer cierre ≥ P_inicio tras el mínimo − fecha del mínimo","where":[["mínimo","día del cierre más bajo de la ventana"],["días","días naturales, no sesiones; vacío si el precio aún no ha vuelto"]]},{"name":"Rentabilidad en la ventana","expr":"Rentabilidad de la ventana = P_último ÷ P_inicio − 1","where":[["P_último","cierre ajustado de la última sesión de la ventana"]]}],"data":[["Precios","10 años de cierres diarios ajustados, con dividendos (Yahoo Finance; el último cierre se contrasta con Stooq)"],["Referencia","SPY (ETF del S&P 500), añadido automáticamente"],["Ventanas de crisis","fijas en el código: 19 feb – 23 mar 2020 (máximo a mínimo del S&P 500) y 3 ene – 12 oct 2022"]],"steps":["Descarga los precios de tus 1–8 símbolos y de SPY.","En cada ventana de crisis, toma el primer cierre como nivel inicial y busca el cierre más bajo y su fecha.","Calcula la caída desde el nivel inicial y la rentabilidad de toda la ventana.","Busca después del mínimo el primer cierre igual o superior al nivel inicial y cuenta los días naturales.","Compara los símbolos: menor y mayor caída, quién no cayó, quién aún no se ha recuperado."],"example":"Empresa de ejemplo: el 19 feb 2020 cierra en 200. Su cierre más bajo en la ventana es 140, el 16 mar 2020, así que la caída es 140 ÷ 200 − 1 = −30 %. Vuelve a cerrar en 200 o más por primera vez el 10 jun 2020, así que tarda 31 + 30 + 25 = 86 días naturales en recuperarse.","read":["Una caída menor que la de SPY indica que la acción aguantó mejor que el mercado en esa crisis; una mayor, que sufrió más.","Tiempos de recuperación cortos muestran resistencia; una fecha de recuperación vacía significa que sigue por debajo de su precio previo.","Compara las dos crisis: una acción puede aguantar bien un choque sanitario y sufrir mucho con un choque de tipos, o al revés."],"limits":["Solo hay dos crisis, con fechas fijas en el código; la próxima puede ser muy distinta y las pasadas no la predicen.","La caída se mide desde el primer día de la ventana, no desde el máximo propio de la acción; una acción que tocó techo antes o después puede parecer mejor o peor que su peor caída real.","Los precios ajustados incluyen dividendos, así que \"recuperada\" significa que volvió la rentabilidad total, no necesariamente el precio cotizado.","Las acciones son las que cotizan hoy; faltan las empresas que no sobrevivieron a una crisis (sesgo de supervivencia), como avisa la app."]}},{"id":"uncertainty","number":20,"group":"risk","group_label":"Risk and credit","title":"Range of outcomes (Monte Carlo)","next":["implied_move","ito","crisis"],"en":{"question":"How wide could the price range be over the coming months, and how much do earnings days add to that uncertainty?","idea":"The app lets the computer play out 10,000 possible futures for the price, each one a random walk whose daily wobble matches the stock's last three years. It assumes no edge: on average the price ends where it is today. For US companies, the bigger moves of past results days are replayed on the days when the next results are expected, so you can see how much of the spread comes from those few days.","formulas":[{"name":"One simulated day","expr":"ln(Sₜ₊₁ ÷ Sₜ) = −σ²/2 + σ·Z  (+ J on a projected results day)","where":[["S","share price"],["σ","standard deviation of daily log returns on normal (non-results) days over 3 years"],["Z","random shock with variance 1: Student-t when fat tails are on, else normal"],["−σ²/2","drift chosen so the expected price stays equal to today's (zero edge)"],["J","an earnings jump drawn at random from the stock's own past results days"]]},{"name":"Earnings jump","expr":"J = (results-day log return − mean normal-day log return), then shifted by −ln(mean(e^J))","where":[["shift","makes the average jump add no expected return"]]},{"name":"Fat tails","expr":"ν = 4 + 6 ÷ (excess kurtosis), kept between 4.5 and 30","where":[["ν","degrees of freedom of the Student-t shocks; normal shocks if excess kurtosis ≤ 0.2"],["excess kurtosis","how often extreme days happen compared with a bell curve (0 for a bell curve)"]]},{"name":"Share of uncertainty from results days","expr":"Share = n·Var(J) ÷ (n·Var(J) + T·σ²)","where":[["n","projected results days inside the horizon"],["T","trading days in the horizon (21 per month)"]]}],"data":[["Daily prices","the last 3 years of finished-session closes adjusted for splits and dividends, Yahoo Finance; at least 250 daily returns"],["Results dates and times","SEC EDGAR 8-K filings with Item 2.02 (results announcements), including whether they were filed after the 4 pm close; US companies only"],["Your choices","horizon 6, 12 or 24 months (default 12); earnings jumps on or off (default on); fat tails on or off (default on)"]],"steps":["Take 3 years of daily closes and compute daily log returns.","Find each results reaction day (the first trading day on or after the 8-K, or the next one if filed after the close) and take those days out of the normal-day sample; with fewer than 4 of them, run without jumps.","Set σ from normal days, the drift to −σ²/2, and the shape of the shocks from the fat-tail measure.","Project the next results dates from the usual spacing between past ones (60–120 days, else 91) and place a resampled jump on each.","Simulate 10,000 daily paths with a fixed seed (same input gives the same output).","Report the 5th, 25th, 50th, 75th and 95th percentiles, the mean, the chance of ending below today, the chance of touching −20% at any close, and the share of variance from results days."],"example":"Example company: price 100, σ = 2% a day, 12 months = 252 trading days, no jumps. σ√T = 0.02 × √252 ≈ 0.318 and −σ²T/2 = −0.0004 × 252 ÷ 2 ≈ −0.050. Median ≈ 100 × e^(−0.050) ≈ 95.1; 5th percentile ≈ 100 × e^(−0.050 − 1.645 × 0.318) ≈ 56.4; 95th ≈ 100 × e^(−0.050 + 0.522) ≈ 160.3; the mean stays 100. If 4 results days fall in the year with Var(J) = 0.0025: share = 0.01 ÷ (0.01 + 252 × 0.0004) = 0.01 ÷ 0.1108 ≈ 9%.","read":["90% of simulated outcomes lie between the 5th and 95th percentiles; the middle half between the 25th and 75th.","The median sits below today's price even with zero edge, because volatility pulls the typical path below the average; a chance of ending below today above 50% is not a predicted fall.","The −20% touch probability is how often a path closes at least 20% below today at some point, even if it recovers later.","The variance share and the results-day ÷ normal-day ratio show how much of the risk is packed into results days."],"limits":["It is a model range, not a forecast, a price target or advice.","One constant σ is used, while real markets have calm and stormy spells and more extreme days; read the 5% and 95% ends as points the real outcome can go beyond (the app shows kurtosis, clustering and the last 63 days' volatility to help).","The past 3 years may not represent the future if the company, rates or the market change.","Results jumps need SEC 8-K dates, so Borsa Istanbul stocks, indices and currencies run without them (BIST results are in lira); holidays are ignored and the touch test uses daily closes only."]},"tr":{"question":"Önümüzdeki aylarda fiyat aralığı ne kadar geniş olabilir ve bilanço günleri bu belirsizliğe ne kadar ekler?","idea":"Uygulama bilgisayara fiyat için 10.000 olası gelecek oynatır; her biri, günlük dalgalanması hissenin son üç yılına uyan bir rastgele yürüyüştür. Hiçbir avantaj varsaymaz: fiyat ortalamada bugünkü yerinde biter. ABD şirketlerinde geçmiş bilanço günlerinin büyük hareketleri, sıradaki bilançoların beklendiği günlerde yeniden oynatılır; böylece yayılımın ne kadarının bu birkaç günden geldiğini görürsün.","formulas":[{"name":"Simüle edilen bir gün","expr":"ln(Sₜ₊₁ ÷ Sₜ) = −σ²/2 + σ·Z  (+ tahmini bilanço gününde J)","where":[["S","hisse fiyatı"],["σ","son 3 yılda normal (bilanço dışı) günlerin günlük log getirilerinin standart sapması"],["Z","varyansı 1 olan rastgele şok: kalın kuyruklar açıksa Student-t, değilse normal"],["−σ²/2","beklenen fiyat bugünküne eşit kalsın diye seçilen sürüklenme (sıfır avantaj)"],["J","hissenin kendi geçmiş bilanço günlerinden rastgele çekilen sıçrama"]]},{"name":"Bilanço sıçraması","expr":"J = (bilanço günü log getirisi − normal gün ortalama log getirisi), sonra −ln(ort(e^J)) kadar kaydırılır","where":[["kaydırma","ortalama sıçramanın beklenen getiri eklememesini sağlar"]]},{"name":"Kalın kuyruklar","expr":"ν = 4 + 6 ÷ (fazla basıklık), 4,5 ile 30 arasında tutulur","where":[["ν","Student-t şoklarının serbestlik derecesi; fazla basıklık ≤ 0,2 ise normal şok"],["fazla basıklık","uç günlerin çan eğrisine göre ne sıklıkta olduğu (çan eğrisinde 0)"]]},{"name":"Belirsizliğin bilanço günlerinden gelen payı","expr":"Pay = n·Var(J) ÷ (n·Var(J) + T·σ²)","where":[["n","ufuk içindeki tahmini bilanço günü sayısı"],["T","ufuktaki işlem günü (ayda 21)"]]}],"data":[["Günlük fiyatlar","bölünme ve temettüye göre düzeltilmiş, tamamlanmış seansların son 3 yıllık kapanışları, Yahoo Finance; en az 250 günlük getiri"],["Bilanço tarihleri ve saatleri","SEC EDGAR'daki Item 2.02 içeren 8-K dosyaları (sonuç açıklamaları), saat 16:00 kapanışından sonra verilip verilmediği dahil; yalnızca ABD şirketleri"],["Senin seçimlerin","ufuk 6, 12 veya 24 ay (varsayılan 12); bilanço sıçramaları açık/kapalı (varsayılan açık); kalın kuyruklar açık/kapalı (varsayılan açık)"]],"steps":["3 yıllık günlük kapanışları alır ve günlük log getirileri hesaplar.","Her bilanço tepki gününü bulur (8-K'dan itibaren ilk işlem günü; kapanıştan sonra verildiyse ertesi gün) ve bu günleri normal gün örneğinden çıkarır; 4'ten azsa sıçramasız çalışır.","σ'yı normal günlerden, sürüklenmeyi −σ²/2 olarak, şokların biçimini de kalın kuyruk ölçüsünden belirler.","Sıradaki bilanço tarihlerini geçmiş tarihler arasındaki olağan aralıktan (60–120 gün, yoksa 91) tahmin eder ve her birine yeniden örneklenmiş bir sıçrama koyar.","Sabit tohumla 10.000 günlük yol simüle eder (aynı girdi aynı sonucu verir).","%5, %25, %50, %75 ve %95 yüzdeliklerini, ortalamayı, bugünün altında bitme olasılığını, herhangi bir kapanışta −%20'ye dokunma olasılığını ve varyansın bilanço günlerinden gelen payını raporlar."],"example":"Örnek şirket: fiyat 100, σ = günlük %2, 12 ay = 252 işlem günü, sıçrama yok. σ√T = 0,02 × √252 ≈ 0,318 ve −σ²T/2 = −0,0004 × 252 ÷ 2 ≈ −0,050. Medyan ≈ 100 × e^(−0,050) ≈ 95,1; %5 yüzdelik ≈ 100 × e^(−0,050 − 1,645 × 0,318) ≈ 56,4; %95 ≈ 100 × e^(−0,050 + 0,522) ≈ 160,3; ortalama 100'de kalır. Yıl içinde Var(J) = 0,0025 olan 4 bilanço günü varsa: pay = 0,01 ÷ (0,01 + 252 × 0,0004) = 0,01 ÷ 0,1108 ≈ %9.","read":["Simüle edilen sonuçların %90'ı %5 ile %95 yüzdelikleri arasında, ortadaki yarısı %25 ile %75 arasındadır.","Sıfır avantajda bile medyan bugünkü fiyatın altındadır, çünkü oynaklık tipik yolu ortalamanın altına çeker; bugünün altında bitme olasılığının %50'yi geçmesi bir düşüş tahmini değildir.","−%20'ye dokunma olasılığı, bir yolun herhangi bir anda bugünün en az %20 altında kapanma sıklığıdır; sonra toparlansa bile sayılır.","Varyans payı ve bilanço günü ÷ normal gün oranı, riskin ne kadarının bilanço günlerine sıkıştığını gösterir."],"limits":["Bu bir model aralığıdır; tahmin, hedef fiyat veya tavsiye değildir.","Tek ve sabit bir σ kullanılır; gerçek piyasada sakin ve fırtınalı dönemler kümelenir ve uç günler daha sık olur. %5 ve %95 uçlarını gerçek sonucun aşabileceği noktalar olarak oku (uygulama yardımcı olsun diye basıklığı, kümelenmeyi ve son 63 günün oynaklığını gösterir).","Şirket, faizler veya piyasa değişirse geçmiş 3 yıl geleceği temsil etmeyebilir.","Bilanço sıçramaları SEC 8-K tarihlerine ihtiyaç duyar; Borsa İstanbul hisseleri, endeksler ve dövizler onlarsız çalışır (BIST sonuçları TL cinsindendir). Tatiller yok sayılır, dokunma testi yalnızca günlük kapanışlara bakar."]},"es":{"question":"¿Qué amplitud podría tener el rango de precios en los próximos meses, y cuánto añaden los días de resultados a esa incertidumbre?","idea":"La app hace que el ordenador juegue 10.000 futuros posibles del precio, cada uno un paseo aleatorio cuyo vaivén diario coincide con el de los últimos tres años de la acción. No supone ninguna ventaja: en promedio el precio termina donde está hoy. En empresas de EE. UU., los movimientos grandes de los días de resultados pasados se repiten en los días en que se esperan los próximos resultados, para que veas cuánta dispersión viene de esos pocos días.","formulas":[{"name":"Un día simulado","expr":"ln(Sₜ₊₁ ÷ Sₜ) = −σ²/2 + σ·Z  (+ J en un día de resultados previsto)","where":[["S","precio de la acción"],["σ","desviación típica de las rentabilidades logarítmicas diarias en días normales (sin resultados) de 3 años"],["Z","choque aleatorio de varianza 1: t de Student si las colas gruesas están activadas, normal si no"],["−σ²/2","deriva elegida para que el precio esperado siga igual al de hoy (ventaja cero)"],["J","un salto de resultados elegido al azar entre los días de resultados pasados de la propia acción"]]},{"name":"Salto de resultados","expr":"J = (rentabilidad log del día de resultados − media log de los días normales), luego desplazado en −ln(media(e^J))","where":[["desplazamiento","hace que el salto medio no añada rentabilidad esperada"]]},{"name":"Colas gruesas","expr":"ν = 4 + 6 ÷ (curtosis en exceso), limitado entre 4,5 y 30","where":[["ν","grados de libertad de los choques t de Student; choques normales si la curtosis en exceso ≤ 0,2"],["curtosis en exceso","cuántas veces ocurren días extremos frente a una campana de Gauss (0 en la campana)"]]},{"name":"Parte de la incertidumbre de los días de resultados","expr":"Parte = n·Var(J) ÷ (n·Var(J) + T·σ²)","where":[["n","días de resultados previstos dentro del horizonte"],["T","días hábiles del horizonte (21 por mes)"]]}],"data":[["Precios diarios","los cierres de sesiones terminadas de los últimos 3 años, ajustados por splits y dividendos, Yahoo Finance; al menos 250 rentabilidades diarias"],["Fechas y horas de resultados","formularios 8-K de SEC EDGAR con el Item 2.02 (anuncios de resultados), incluido si se presentaron después del cierre de las 16:00; solo empresas de EE. UU."],["Tus elecciones","horizonte de 6, 12 o 24 meses (12 por defecto); saltos de resultados sí/no (sí por defecto); colas gruesas sí/no (sí por defecto)"]],"steps":["Toma 3 años de cierres diarios y calcula las rentabilidades logarítmicas diarias.","Busca cada día de reacción a resultados (la primera sesión en o después del 8-K, o la siguiente si se presentó tras el cierre) y saca esos días de la muestra de días normales; si hay menos de 4, funciona sin saltos.","Fija σ con los días normales, la deriva en −σ²/2 y la forma de los choques con la medida de colas gruesas.","Proyecta las próximas fechas de resultados con la separación habitual entre las anteriores (60–120 días, si no 91) y coloca en cada una un salto remuestreado.","Simula 10.000 trayectorias diarias con una semilla fija (la misma entrada da el mismo resultado).","Informa los percentiles 5, 25, 50, 75 y 95, la media, la probabilidad de terminar por debajo de hoy, la de tocar −20% en algún cierre y la parte de la varianza que viene de los días de resultados."],"example":"Empresa de ejemplo: precio 100, σ = 2% diario, 12 meses = 252 días hábiles, sin saltos. σ√T = 0,02 × √252 ≈ 0,318 y −σ²T/2 = −0,0004 × 252 ÷ 2 ≈ −0,050. Mediana ≈ 100 × e^(−0,050) ≈ 95,1; percentil 5 ≈ 100 × e^(−0,050 − 1,645 × 0,318) ≈ 56,4; percentil 95 ≈ 100 × e^(−0,050 + 0,522) ≈ 160,3; la media sigue en 100. Si caen 4 días de resultados en el año con Var(J) = 0,0025: parte = 0,01 ÷ (0,01 + 252 × 0,0004) = 0,01 ÷ 0,1108 ≈ 9%.","read":["El 90% de los resultados simulados está entre los percentiles 5 y 95; la mitad central, entre el 25 y el 75.","La mediana queda por debajo del precio de hoy incluso sin ventaja, porque la volatilidad empuja la trayectoria típica por debajo de la media; una probabilidad de acabar por debajo de hoy mayor que 50% no es una caída prevista.","La probabilidad de tocar −20% es la frecuencia con que una trayectoria cierra al menos 20% por debajo de hoy en algún momento, aunque luego se recupere.","La parte de la varianza y la ratio día de resultados ÷ día normal muestran cuánto riesgo se concentra en los días de resultados."],"limits":["Es un rango de un modelo, no una previsión, un precio objetivo ni un consejo.","Se usa una sola σ constante, mientras que los mercados reales tienen rachas tranquilas y agitadas y más días extremos; lee los extremos del 5% y 95% como puntos que el resultado real puede superar (la app muestra la curtosis, la agrupación y la volatilidad de los últimos 63 días para ayudarte).","Los últimos 3 años pueden no representar el futuro si cambian la empresa, los tipos o el mercado.","Los saltos de resultados necesitan fechas 8-K de la SEC, así que las acciones de Borsa Istanbul, los índices y las divisas funcionan sin ellos (los resultados de BIST están en liras); se ignoran los festivos y la prueba de tocar −20% usa solo cierres diarios."]}},{"id":"dcf","number":21,"group":"valuation","group_label":"Valuation","title":"DCF valuation","next":["scenarios","reverse_dcf","beta"],"en":{"question":"What is one share worth if the company's future cash flows turn out as I assume, and how sensitive is that answer?","idea":"A business is worth the cash it will produce in the future, but money later is worth less than money now, so future cash is shrunk (discounted) at a rate that reflects risk. This DCF (discounted cash flow) forecasts five years of free cash flow, adds a value for all the years after, and turns the total into a value per share. Every input is labelled as reported, calculated, your assumption or model output.","formulas":[{"name":"Free cash flow to the firm","expr":"FCFFₜ = Revenueₜ × EBIT margin × (1 − tax) + D&Aₜ − capexₜ − NWC% × (Revenueₜ − Revenueₜ₋₁)","where":[["FCFF","cash the business generates before paying lenders and shareholders, USD millions"],["EBIT margin","operating income ÷ revenue, 3-year average (stock-based pay is already a cost inside it)"],["tax","3-year average effective tax, limited to 0–35% (21% if unknown)"],["D&A, capex","3-year average % of revenue"],["NWC%","extra working capital per extra dollar of revenue: 3-year median, limited to 0–25% (5% if unknown)"]]},{"name":"Discount rate (WACC)","expr":"WACC = E ÷ (D + E) × (rf + β × ERP) + D ÷ (D + E) × Rd × (1 − tax);  β = 0.67 × raw β + 0.33","where":[["E","market value of equity (price × shares)"],["D","debt from the latest 10-K"],["rf","risk-free rate: 10-year US Treasury yield"],["β","beta, Blume-adjusted from a 5-year monthly regression against SPY (1.0 if unavailable)"],["ERP","equity risk premium: Damodaran's implied premium for the S&P 500"],["Rd","cost of debt: interest expense ÷ average debt if 1–20%, else risk-free + a credit spread for a rating implied by EBIT ÷ interest, else risk-free + 1.5 pts"]]},{"name":"Enterprise value","expr":"EV = Σₜ₌₁⁵ FCFFₜ ÷ (1 + WACC)ᵗ + [FCFF₅ × (1 + g) ÷ (WACC − g)] ÷ (1 + WACC)⁵","where":[["g","terminal growth, your input (default 3%, allowed −2% to 5%)"],["timing","each year's cash is discounted at the end of the year (no mid-year convention)"]]},{"name":"Value per share","expr":"Value per share = (EV − debt − minority interests + cash) ÷ shares outstanding","where":[["minority interests","parts of subsidiaries owned by others"],["cash","cash and cash equivalents"],["shares","cover-page shares outstanding (else diluted average), ÷ ADR ratio if you enter one"]]}],"data":[["Revenue, operating income, tax, pre-tax income","10-K income statements, last 3 years (us-gaap:Revenues…, OperatingIncomeLoss, IncomeTaxExpenseBenefit)"],["D&A, capex","10-K cash-flow statements (us-gaap:DepreciationDepletionAndAmortization, PaymentsToAcquirePropertyPlantAndEquipment)"],["Working capital","us-gaap:AssetsCurrent, LiabilitiesCurrent, CashAndCashEquivalentsAtCarryingValue, LongTermDebtCurrent"],["Debt, cash, minority interests, interest expense","latest 10-K: LongTermDebtNoncurrent + LongTermDebtCurrent, CashAndCashEquivalentsAtCarryingValue, MinorityInterest, InterestExpense"],["Price, shares","Yahoo Finance latest close; cover page dei:EntityCommonStockSharesOutstanding"],["Risk-free rate","FRED series DGS10 (10-year Treasury), else the Treasury yield curve, else 4% assumed"],["Equity risk premium","Damodaran (NYU Stern) implied ERP for the S&P 500, else 5% assumed"],["Beta","5 years of monthly returns of the stock vs SPY, from Yahoo Finance adjusted closes"],["Credit spread (fallback)","ICE BofA US corporate option-adjusted spreads on FRED"]],"steps":["Stop if the company looks like a bank or insurer (it reports deposits, interest income or policy liabilities); use the bank model instead.","Set the assumptions from the last 3 years unless you type your own: growth path (past growth limited to −10%…30%, fading in a straight line towards terminal growth), margin, tax, D&A, capex, working capital.","Build WACC from CAPM (rf + β × ERP) and the cost of debt, weighted by market value of equity and debt; or use your own WACC. WACC must be at least 1 point above terminal growth.","Forecast and discount five years of FCFF, add the discounted terminal value, and bridge from EV to equity value and value per share; stop if year-5 FCFF is not positive.","Show a sensitivity table (WACC ±2 pts × terminal growth ±1 pt), the range from the WACC ±1 × growth ±0.5 cells, the implied exit multiple (terminal value ÷ year-5 EBITDA) and industry averages."],"example":"Example company: risk-free 4%, raw beta 1.15 → adjusted 0.67 × 1.15 + 0.33 ≈ 1.10, ERP 5%: cost of equity ≈ 4% + 1.10 × 5% = 9.5%. Equity is 90% of capital, debt 10% at 5% × (1 − 20%) = 4%: WACC ≈ 0.9 × 9.5% + 0.1 × 4% ≈ 9%. Revenue 1,000, growth 10% fading to 4.4%, margin 20%: year-1 FCFF = 220 × 0.8 + 44 − 55 − 5 = 160, today 160 ÷ 1.09 ≈ 147. Five years ≈ 716, terminal value today ≈ 2,334, EV ≈ 3,050; minus debt 200 plus cash 100 = 2,950; ÷ 100 shares ≈ 29.5 per share. Terminal value is about 77% of EV.","read":["Read the range, not the single number: moving WACC by 1 point and terminal growth by 0.5 point often shifts the value a lot.","If the terminal value is more than about 70% of EV, or WACC is less than 3 points above terminal growth, the result rests on long-run assumptions; treat it with caution.","Compare the implied exit multiple with peers' EV/EBITDA in Comps; a much higher multiple means the terminal assumptions are generous.","A gap between model value and price means the market assumes different growth, margins or risk than you; the Reverse DCF shows which growth the price implies."],"limits":["Past averages are not the future; growth, margin and the fade path are assumptions you should challenge.","Cash flows are discounted at year end (slightly conservative); unexercised options are not deducted (value can be a bit high); operating leases are not treated as debt.","Cash means cash and equivalents only, so large holdings of marketable securities are left out of the bridge.","Beta from 5 years of monthly data can be noisy; the code falls back to 1.0 when it cannot estimate it, and to assumed rates (4% risk-free, 5% ERP) when the data sources cannot be reached."]},"tr":{"question":"Şirketin gelecekteki nakit akışları benim varsaydığım gibi olursa bir hisse ne eder ve bu sonuç ne kadar hassas?","idea":"Bir işletme gelecekte üreteceği nakit kadar eder; ama sonraki para bugünkü paradan daha az değerlidir, bu yüzden gelecekteki nakit riski yansıtan bir oranla küçültülür (iskonto edilir). Bu DCF (indirgenmiş nakit akışı) beş yıllık serbest nakit akışını tahmin eder, sonraki tüm yıllar için bir değer ekler ve toplamı hisse başına değere çevirir. Her girdi raporlanan, hesaplanan, senin varsayımın veya model çıktısı olarak etiketlenir.","formulas":[{"name":"Firmaya serbest nakit akışı","expr":"FCFFₜ = Gelirₜ × FVÖK marjı × (1 − vergi) + amortismanₜ − yatırımₜ − NWC% × (Gelirₜ − Gelirₜ₋₁)","where":[["FCFF","işletmenin borç verenlere ve hissedarlara ödemeden önce ürettiği nakit, milyon USD"],["FVÖK (EBIT) marjı","faaliyet kârı ÷ gelir, 3 yıllık ortalama (hisse bazlı ücretler zaten içinde gider olarak var)"],["vergi","3 yıllık ortalama efektif vergi, %0–35 ile sınırlı (bilinmiyorsa %21)"],["amortisman, yatırım","gelirin 3 yıllık ortalama yüzdesi"],["NWC%","her ek dolar gelir için gereken ek işletme sermayesi: 3 yıllık medyan, %0–25 ile sınırlı (bilinmiyorsa %5)"]]},{"name":"İskonto oranı (WACC, ağırlıklı ortalama sermaye maliyeti)","expr":"WACC = Ö ÷ (B + Ö) × (rf + β × ERP) + B ÷ (B + Ö) × Rb × (1 − vergi);  β = 0,67 × ham β + 0,33","where":[["Ö","özkaynağın piyasa değeri (fiyat × hisse)"],["B","son 10-K’daki borç"],["rf","risksiz faiz: 10 yıllık ABD tahvil faizi"],["β","beta; SPY’a karşı 5 yıllık aylık regresyondan Blume düzeltmesiyle (hesaplanamazsa 1,0)"],["ERP","hisse risk primi: Damodaran’ın S&P 500 için ima edilen primi"],["Rb","borç maliyeti: faiz gideri ÷ ortalama borç (%1–20 arasındaysa); değilse risksiz faiz + FVÖK ÷ faizden çıkan kredi notunun spread’i; o da yoksa risksiz faiz + 1,5 puan"]]},{"name":"Firma değeri","expr":"FD = Σₜ₌₁⁵ FCFFₜ ÷ (1 + WACC)ᵗ + [FCFF₅ × (1 + g) ÷ (WACC − g)] ÷ (1 + WACC)⁵","where":[["g","uç (terminal) büyüme, senin girdin (varsayılan %3, izin verilen −%2 ile %5)"],["zamanlama","her yılın nakdi yıl sonunda iskonto edilir (yıl ortası düzeltmesi yok)"]]},{"name":"Hisse başına değer","expr":"Hisse başına değer = (FD − borç − azınlık payları + nakit) ÷ dolaşımdaki hisse","where":[["azınlık payları","bağlı ortaklıklarda başkalarına ait paylar"],["nakit","nakit ve nakit benzerleri"],["hisse","kapak sayfasındaki dolaşımdaki hisse (yoksa seyreltilmiş ortalama); ADR oranı girersen ona bölünür"]]}],"data":[["Gelir, faaliyet kârı, vergi, vergi öncesi kâr","son 3 yılın 10-K gelir tabloları (us-gaap:Revenues…, OperatingIncomeLoss, IncomeTaxExpenseBenefit)"],["Amortisman, yatırım","10-K nakit akış tabloları (us-gaap:DepreciationDepletionAndAmortization, PaymentsToAcquirePropertyPlantAndEquipment)"],["İşletme sermayesi","us-gaap:AssetsCurrent, LiabilitiesCurrent, CashAndCashEquivalentsAtCarryingValue, LongTermDebtCurrent"],["Borç, nakit, azınlık payları, faiz gideri","son 10-K: LongTermDebtNoncurrent + LongTermDebtCurrent, CashAndCashEquivalentsAtCarryingValue, MinorityInterest, InterestExpense"],["Fiyat, hisse sayısı","Yahoo Finance son kapanış; kapak sayfası dei:EntityCommonStockSharesOutstanding"],["Risksiz faiz","FRED DGS10 serisi (10 yıllık tahvil), yoksa Hazine getiri eğrisi, o da yoksa %4 varsayım"],["Hisse risk primi","Damodaran (NYU Stern) S&P 500 ima edilen primi, yoksa %5 varsayım"],["Beta","Yahoo Finance düzeltilmiş kapanışlarından hisse ve SPY’ın 5 yıllık aylık getirileri"],["Kredi spread’i (yedek)","FRED’deki ICE BofA ABD kurumsal tahvil opsiyon düzeltmeli spreadleri"]],"steps":["Şirket bir banka ya da sigortacı gibi görünüyorsa (mevduat, faiz geliri veya poliçe yükümlülüğü raporluyorsa) dur; onun yerine banka modelini kullan.","Kendi değerlerini girmediysen varsayımları son 3 yıldan kur: büyüme yolu (geçmiş büyüme −%10…%30 ile sınırlı, uç büyümeye doğru doğrusal iner), marj, vergi, amortisman, yatırım, işletme sermayesi.","WACC’yi CAPM (rf + β × ERP) ve borç maliyetinden, özkaynağın piyasa değeri ve borçla ağırlıklandırarak kur ya da kendi WACC’ni kullan. WACC uç büyümeden en az 1 puan yüksek olmalı.","Beş yıllık FCFF’yi tahmin edip indirge, indirgenmiş uç değeri ekle; firma değerinden özkaynak değerine ve hisse başına değere geç. 5. yıl FCFF pozitif değilse dur.","Duyarlılık tablosu (WACC ±2 puan × uç büyüme ±1 puan), WACC ±1 × büyüme ±0,5 hücrelerinden aralık, ima edilen çıkış çarpanı (uç değer ÷ 5. yıl FAVÖK) ve sektör ortalamalarını göster."],"example":"Örnek şirket: risksiz faiz %4, ham beta 1,15 → düzeltilmiş 0,67 × 1,15 + 0,33 ≈ 1,10, ERP %5: özkaynak maliyeti ≈ %4 + 1,10 × %5 = %9,5. Sermayenin %90’ı özkaynak, %10’u borç; borç maliyeti %5 × (1 − %20) = %4: WACC ≈ 0,9 × %9,5 + 0,1 × %4 ≈ %9. Gelir 1.000, büyüme %10’dan %4,4’e iniyor, marj %20: 1. yıl FCFF = 220 × 0,8 + 44 − 55 − 5 = 160; bugünkü değeri 160 ÷ 1,09 ≈ 147. Beş yıl ≈ 716, uç değerin bugünkü değeri ≈ 2.334, firma değeri ≈ 3.050; borç 200 düşülüp nakit 100 eklenince 2.950; 100 hisseye bölünce hisse başına ≈ 29,5. Uç değer, firma değerinin yaklaşık %77’si.","read":["Tek rakamı değil aralığı oku: WACC’yi 1 puan, uç büyümeyi 0,5 puan oynatmak değeri çoğu zaman çok değiştirir.","Uç değer firma değerinin yaklaşık %70’inden fazlaysa ya da WACC uç büyümeden 3 puandan az yüksekse sonuç uzun vadeli varsayımlara dayanır; temkinli oku.","İma edilen çıkış çarpanını Çarpanlar analizindeki rakiplerin FD/FAVÖK’üyle karşılaştır; çok daha yüksekse uç varsayımlar cömerttir.","Model değeri ile fiyat arasındaki fark, piyasanın senden farklı büyüme, marj veya risk varsaydığını gösterir; fiyatın ima ettiği büyümeyi Ters DCF gösterir."],"limits":["Geçmiş ortalamalar gelecek değildir; büyüme, marj ve iniş yolu sorgulaman gereken varsayımlardır.","Nakit akışları yıl sonunda iskonto edilir (biraz temkinli); kullanılmamış hisse opsiyonları düşülmez (değer biraz yüksek çıkabilir); faaliyet kiralamaları borç sayılmaz.","Nakit sadece nakit ve nakit benzerleridir; büyük menkul kıymet portföyleri köprüde yer almaz.","5 yıllık aylık veriden beta gürültülü olabilir; kod tahmin edemezse 1,0’a, veri kaynaklarına ulaşamazsa varsayılan oranlara (risksiz %4, ERP %5) döner."]},"es":{"question":"¿Cuánto vale una acción si los flujos de caja futuros de la empresa salen como supongo, y qué tan sensible es esa respuesta?","idea":"Una empresa vale el dinero que producirá en el futuro, pero el dinero de mañana vale menos que el de hoy, así que el dinero futuro se reduce (se descuenta) a una tasa que refleja el riesgo. Este DCF (flujo de caja descontado) prevé cinco años de flujo de caja libre, añade un valor para todos los años siguientes y convierte el total en valor por acción. Cada dato se etiqueta como publicado, calculado, supuesto tuyo o resultado del modelo.","formulas":[{"name":"Flujo de caja libre de la empresa","expr":"FCFFₜ = Ingresosₜ × margen EBIT × (1 − impuesto) + D&Aₜ − capexₜ − NWC% × (Ingresosₜ − Ingresosₜ₋₁)","where":[["FCFF","caja que genera el negocio antes de pagar a acreedores y accionistas, millones de USD"],["margen EBIT","beneficio operativo ÷ ingresos, media de 3 años (la remuneración en acciones ya está incluida como gasto)"],["impuesto","tipo efectivo medio de 3 años, limitado a 0–35% (21% si no se conoce)"],["D&A, capex","% medio de los ingresos en 3 años"],["NWC%","capital circulante extra por cada dólar extra de ingresos: mediana de 3 años, limitada a 0–25% (5% si no se conoce)"]]},{"name":"Tasa de descuento (WACC, coste medio ponderado del capital)","expr":"WACC = E ÷ (D + E) × (rf + β × ERP) + D ÷ (D + E) × Rd × (1 − impuesto);  β = 0,67 × β bruta + 0,33","where":[["E","valor de mercado del patrimonio (precio × acciones)"],["D","deuda del último 10-K"],["rf","tipo sin riesgo: rendimiento del bono del Tesoro de EE. UU. a 10 años"],["β","beta, ajustada según Blume a partir de una regresión mensual de 5 años contra SPY (1,0 si no se puede)"],["ERP","prima de riesgo de mercado: la prima implícita del S&P 500 de Damodaran"],["Rd","coste de la deuda: gasto por intereses ÷ deuda media si está entre 1% y 20%; si no, tipo sin riesgo + diferencial de crédito de la calificación implícita en EBIT ÷ intereses; si no, tipo sin riesgo + 1,5 puntos"]]},{"name":"Valor de empresa","expr":"EV = Σₜ₌₁⁵ FCFFₜ ÷ (1 + WACC)ᵗ + [FCFF₅ × (1 + g) ÷ (WACC − g)] ÷ (1 + WACC)⁵","where":[["g","crecimiento terminal, tu dato (por defecto 3%, permitido −2% a 5%)"],["momento","la caja de cada año se descuenta al final del año (sin convención de mitad de año)"]]},{"name":"Valor por acción","expr":"Valor por acción = (EV − deuda − intereses minoritarios + caja) ÷ acciones en circulación","where":[["intereses minoritarios","partes de filiales que pertenecen a otros"],["caja","efectivo y equivalentes"],["acciones","acciones en circulación de la portada (si no, media diluida), ÷ ratio ADR si lo introduces"]]}],"data":[["Ingresos, beneficio operativo, impuestos, beneficio antes de impuestos","cuentas de resultados del 10-K, últimos 3 años (us-gaap:Revenues…, OperatingIncomeLoss, IncomeTaxExpenseBenefit)"],["D&A, capex","estados de flujos de caja del 10-K (us-gaap:DepreciationDepletionAndAmortization, PaymentsToAcquirePropertyPlantAndEquipment)"],["Capital circulante","us-gaap:AssetsCurrent, LiabilitiesCurrent, CashAndCashEquivalentsAtCarryingValue, LongTermDebtCurrent"],["Deuda, caja, minoritarios, gasto por intereses","último 10-K: LongTermDebtNoncurrent + LongTermDebtCurrent, CashAndCashEquivalentsAtCarryingValue, MinorityInterest, InterestExpense"],["Precio, acciones","último cierre de Yahoo Finance; portada dei:EntityCommonStockSharesOutstanding"],["Tipo sin riesgo","serie DGS10 de FRED (Tesoro a 10 años), si no la curva del Tesoro, si no un 4% supuesto"],["Prima de riesgo","prima implícita del S&P 500 de Damodaran (NYU Stern), si no un 5% supuesto"],["Beta","5 años de rentabilidades mensuales de la acción frente a SPY, con cierres ajustados de Yahoo Finance"],["Diferencial de crédito (alternativa)","diferenciales ajustados por opciones ICE BofA de bonos corporativos de EE. UU. en FRED"]],"steps":["Se detiene si la empresa parece un banco o aseguradora (publica depósitos, ingresos por intereses o pasivos por pólizas); usa el modelo bancario.","Fija los supuestos con los últimos 3 años salvo que escribas los tuyos: senda de crecimiento (crecimiento pasado limitado a −10%…30%, que baja en línea recta hacia el crecimiento terminal), margen, impuestos, D&A, capex y circulante.","Construye el WACC con el CAPM (rf + β × ERP) y el coste de la deuda, ponderados por el valor de mercado del patrimonio y la deuda; o usa tu propio WACC. Debe superar al crecimiento terminal en al menos 1 punto.","Prevé y descuenta cinco años de FCFF, suma el valor terminal descontado y pasa del EV al valor del patrimonio y por acción; se detiene si el FCFF del año 5 no es positivo.","Muestra una tabla de sensibilidad (WACC ±2 puntos × crecimiento terminal ±1 punto), el rango de las celdas WACC ±1 × crecimiento ±0,5, el múltiplo de salida implícito (valor terminal ÷ EBITDA del año 5) y medias sectoriales."],"example":"Empresa de ejemplo: tipo sin riesgo 4%, beta bruta 1,15 → ajustada 0,67 × 1,15 + 0,33 ≈ 1,10, ERP 5%: coste del patrimonio ≈ 4% + 1,10 × 5% = 9,5%. El patrimonio es el 90% del capital y la deuda el 10%, a 5% × (1 − 20%) = 4%: WACC ≈ 0,9 × 9,5% + 0,1 × 4% ≈ 9%. Ingresos 1.000, crecimiento que baja del 10% al 4,4%, margen 20%: FCFF del año 1 = 220 × 0,8 + 44 − 55 − 5 = 160, hoy 160 ÷ 1,09 ≈ 147. Cinco años ≈ 716, valor terminal hoy ≈ 2.334, EV ≈ 3.050; menos deuda 200 más caja 100 = 2.950; ÷ 100 acciones ≈ 29,5 por acción. El valor terminal es un 77% del EV aproximadamente.","read":["Lee el rango, no un solo número: mover el WACC 1 punto y el crecimiento terminal 0,5 puntos suele cambiar mucho el valor.","Si el valor terminal supera un 70% del EV, o el WACC está a menos de 3 puntos del crecimiento terminal, el resultado depende de supuestos de largo plazo; tómalo con cautela.","Compara el múltiplo de salida implícito con el EV/EBITDA de los comparables en Comps; si es mucho mayor, los supuestos terminales son generosos.","Una diferencia entre el valor del modelo y el precio significa que el mercado supone otro crecimiento, margen o riesgo; el DCF inverso muestra qué crecimiento implica el precio."],"limits":["Las medias pasadas no son el futuro; crecimiento, margen y senda de bajada son supuestos que debes cuestionar.","Los flujos se descuentan al final del año (algo conservador); no se restan las opciones sin ejercer (el valor puede salir algo alto); los arrendamientos operativos no se tratan como deuda.","Caja significa solo efectivo y equivalentes, así que las grandes carteras de valores negociables quedan fuera del puente.","La beta de 5 años de datos mensuales puede ser ruidosa; el código usa 1,0 si no puede estimarla y tipos supuestos (4% sin riesgo, 5% ERP) si no puede acceder a las fuentes."]}},{"id":"bank_value","number":22,"group":"valuation","group_label":"Valuation","title":"Bank and insurer valuation","next":["dupont","beta","valuation_summary"],"en":{"question":"What is a bank or insurer worth, given how much it earns on its shareholders' money compared with what shareholders require?","idea":"For a bank, borrowed money (deposits) is raw material, not financing, so the usual cash-flow DCF does not fit. Instead you look at book value (shareholders' equity) and at ROE (return on equity): if a bank earns more on each dollar of equity than shareholders demand, it deserves to trade above book value, and below book if it earns less.","formulas":[{"name":"Return on equity (ROE)","expr":"ROE = net income ÷ average of start-of-year and end-of-year equity;  ROE used = average of the last 3 years","where":[["net income","annual profit, USD millions"],["equity","total shareholders' equity (book value), USD millions"]]},{"name":"Cost of equity (CAPM)","expr":"Re = rf + β × ERP;  β = 0.67 × raw β + 0.33","where":[["rf","risk-free rate: 10-year US Treasury yield"],["β","beta, Blume-adjusted from a 5-year monthly regression vs SPY (1.0 if unavailable)"],["ERP","equity risk premium (Damodaran's implied S&P 500 premium)"]]},{"name":"Long-run growth (default)","expr":"g = ROE × (1 − (dividends + buybacks) ÷ net income), limited to 0–4% and to at most Re − 1 pt","where":[["(1 − payout)","retention: the share of profit kept to grow the equity, 3-year average (50% payout assumed if unknown)"]]},{"name":"Justified price-to-book and value per share","expr":"Justified P/B = (ROE − g) ÷ (Re − g);  Value per share = justified P/B × (equity ÷ shares);  DDM = DPS × (1 + g) ÷ (Re − g)","where":[["P/B","price ÷ book value per share"],["DPS","dividends paid in the latest year ÷ shares outstanding"],["DDM","dividend discount model, a second, usually lower, estimate"]]}],"data":[["Net income","10-K income statement (us-gaap:NetIncomeLoss, else ProfitLoss)"],["Shareholders' equity","10-K balance sheet (us-gaap:StockholdersEquity, else including noncontrolling interest)"],["Dividends, buybacks","10-K cash-flow statement (us-gaap:PaymentsOfDividends / PaymentsOfDividendsCommonStock, PaymentsForRepurchaseOfCommonStock)"],["Price, shares","Yahoo Finance latest close; cover page dei:EntityCommonStockSharesOutstanding (else diluted average), ÷ ADR ratio if entered"],["Risk-free rate","FRED DGS10 (else Treasury curve, else 4% assumed)"],["Equity risk premium","Damodaran implied ERP for the S&P 500 (else 5% assumed)"],["Beta","5 years of monthly returns vs SPY (Yahoo adjusted closes)"],["ROE, growth, rf, ERP overrides","your inputs, optional"]],"steps":["Check that equity is positive, then compute ROE for each year and average the last 3 (or use your ROE).","Build the cost of equity from the risk-free rate, adjusted beta and risk premium.","Estimate growth from ROE × retention after dividends and buybacks, capped at 4% and 1 point below the cost of equity (or use your growth); growth must stay 0.5 point below the cost of equity.","Compute book value per share, the justified P/B, the model value per share, the market P/B and the dividend discount value.","Show a table of value per share for cost of equity ±1 point and ROE ±2 points, and ROE year by year against the cost of equity."],"example":"Example company: equity 1,000 and 100 shares, so book value per share = 10. ROE 12%. Risk-free 4% + beta 1.0 × premium 5% = cost of equity 9%. It pays dividends 40 and buys back 20 out of profit 120: payout 50%, retention 50%, ROE × retention = 6%, capped to g = 4%. Justified P/B = (12 − 4) ÷ (9 − 4) = 1.6, so model value = 1.6 × 10 = 16 per share. Dividend model: DPS 0.40 × 1.04 ÷ 0.05 ≈ 8.3.","read":["ROE above the cost of equity supports a price above book value (P/B above 1); ROE below it implies a price below book.","Compare the justified P/B with the market P/B: a market P/B above the justified one means the market expects higher ROE, more growth or lower risk than your inputs.","The sensitivity table shows how fast the value moves when ROE or the cost of equity shifts a little.","The dividend model is usually lower because it ignores buybacks and retained profit."],"limits":["The model is only as good as the book value: loan-loss provisions, securities losses, goodwill and, for insurers, reserve adequacy can make book value misleading.","Total shareholders' equity is used as reported; if the bank has preferred shares, they are not subtracted, so book value per common share can be overstated.","Growth is capped at 4% and the formula breaks down when growth gets close to the cost of equity; a 3-year average ROE may not reflect the future.","The app needs a revenue line in the 10-K to load a company, so some banks and insurers cannot be analysed; for non-financial companies the DCF is usually the better tool."]},"tr":{"question":"Bir banka ya da sigortacı, hissedarlarının parası üzerinde kazandığının hissedarların beklediğiyle karşılaştırılmasına göre ne eder?","idea":"Banka için borç alınan para (mevduat) bir finansman değil, ham maddedir; bu yüzden olağan nakit akışı DCF’si uymaz. Bunun yerine defter değerine (özkaynak) ve ROE’ye (özkaynak kârlılığı) bakarsın: banka her dolar özkaynak üzerinde hissedarların beklediğinden fazla kazanıyorsa defter değerinin üstünde, daha az kazanıyorsa altında işlem görmeyi hak eder.","formulas":[{"name":"Özkaynak kârlılığı (ROE)","expr":"ROE = net kâr ÷ yıl başı ve yıl sonu özkaynağın ortalaması;  kullanılan ROE = son 3 yılın ortalaması","where":[["net kâr","yıllık kâr, milyon USD"],["özkaynak","toplam özkaynak (defter değeri), milyon USD"]]},{"name":"Özkaynak maliyeti (CAPM)","expr":"Rö = rf + β × ERP;  β = 0,67 × ham β + 0,33","where":[["rf","risksiz faiz: 10 yıllık ABD tahvil faizi"],["β","beta; SPY’a karşı 5 yıllık aylık regresyondan Blume düzeltmesiyle (hesaplanamazsa 1,0)"],["ERP","hisse risk primi (Damodaran’ın S&P 500 ima edilen primi)"]]},{"name":"Uzun vadeli büyüme (varsayılan)","expr":"g = ROE × (1 − (temettü + geri alım) ÷ net kâr); %0–4 ile ve en fazla Rö − 1 puanla sınırlı","where":[["(1 − dağıtım oranı)","elde tutma oranı: özkaynağı büyütmek için tutulan kâr payı, 3 yıllık ortalama (bilinmiyorsa %50 dağıtım varsayılır)"]]},{"name":"Gerekçeli PD/DD ve hisse başına değer","expr":"Gerekçeli PD/DD = (ROE − g) ÷ (Rö − g);  Hisse başına değer = gerekçeli PD/DD × (özkaynak ÷ hisse);  DDM = HBT × (1 + g) ÷ (Rö − g)","where":[["PD/DD (P/B)","fiyat ÷ hisse başına defter değeri"],["HBT (DPS)","son yılda ödenen temettü ÷ dolaşımdaki hisse"],["DDM","temettü indirgeme modeli; ikinci ve genelde daha düşük bir tahmin"]]}],"data":[["Net kâr","10-K gelir tablosu (us-gaap:NetIncomeLoss, yoksa ProfitLoss)"],["Özkaynak","10-K bilançosu (us-gaap:StockholdersEquity, yoksa azınlık payları dahil özkaynak)"],["Temettü, geri alım","10-K nakit akış tablosu (us-gaap:PaymentsOfDividends / PaymentsOfDividendsCommonStock, PaymentsForRepurchaseOfCommonStock)"],["Fiyat, hisse sayısı","Yahoo Finance son kapanış; kapak sayfası dei:EntityCommonStockSharesOutstanding (yoksa seyreltilmiş ortalama), ADR oranı girersen ona bölünür"],["Risksiz faiz","FRED DGS10 (yoksa Hazine eğrisi, o da yoksa %4 varsayım)"],["Hisse risk primi","Damodaran S&P 500 ima edilen primi (yoksa %5 varsayım)"],["Beta","SPY’a karşı 5 yıllık aylık getiriler (Yahoo düzeltilmiş kapanışları)"],["ROE, büyüme, rf, ERP","isteğe bağlı senin girdilerin"]],"steps":["Özkaynağın pozitif olduğunu kontrol et; her yıl için ROE’yi hesapla ve son 3 yılın ortalamasını al (ya da senin ROE’ni kullan).","Risksiz faiz, düzeltilmiş beta ve risk priminden özkaynak maliyetini kur.","Büyümeyi ROE × temettü ve geri alım sonrası elde tutma oranından tahmin et; %4 ile ve özkaynak maliyetinin 1 puan altıyla sınırla (ya da senin büyümeni kullan). Büyüme özkaynak maliyetinin en az 0,5 puan altında kalmalı.","Hisse başına defter değerini, gerekçeli PD/DD’yi, hisse başına model değerini, piyasa PD/DD’sini ve temettü indirgeme değerini hesapla.","Özkaynak maliyeti ±1 puan ve ROE ±2 puan için hisse başına değer tablosu ile yıl yıl ROE’yi özkaynak maliyetiyle birlikte göster."],"example":"Örnek şirket: özkaynak 1.000 ve 100 hisse, yani hisse başına defter değeri 10. ROE %12. Risksiz %4 + beta 1,0 × prim %5 = özkaynak maliyeti %9. 120 kârdan 40 temettü dağıtıyor, 20 hisse geri alıyor: dağıtım %50, elde tutma %50, ROE × elde tutma = %6, sınırla g = %4. Gerekçeli PD/DD = (12 − 4) ÷ (9 − 4) = 1,6; model değeri = 1,6 × 10 = hisse başına 16. Temettü modeli: HBT 0,40 × 1,04 ÷ 0,05 ≈ 8,3.","read":["ROE özkaynak maliyetinin üstündeyse defter değerinin üstünde fiyat (PD/DD 1’in üstü) desteklenir; altındaysa defter değerinin altında fiyat beklenir.","Gerekçeli PD/DD’yi piyasa PD/DD’siyle karşılaştır: piyasanınki daha yüksekse piyasa senin girdilerinden daha yüksek ROE, daha çok büyüme veya daha düşük risk bekliyordur.","Duyarlılık tablosu, ROE veya özkaynak maliyeti biraz oynadığında değerin ne kadar hızlı değiştiğini gösterir.","Temettü modeli genelde daha düşük çıkar, çünkü geri alımları ve tutulan kârı görmez."],"limits":["Model ancak defter değeri kadar iyidir: kredi karşılıkları, menkul kıymet zararları, şerefiye ve sigortacılarda rezervlerin yeterliliği defter değerini yanıltıcı yapabilir.","Raporlanan toplam özkaynak kullanılır; bankanın imtiyazlı hisseleri varsa düşülmez, bu yüzden adi hisse başına defter değeri olduğundan yüksek görünebilir.","Büyüme %4 ile sınırlıdır ve büyüme özkaynak maliyetine yaklaştıkça formül bozulur; 3 yıllık ortalama ROE geleceği yansıtmayabilir.","Uygulama bir şirketi yüklemek için 10-K’da gelir satırı ister, bu yüzden bazı banka ve sigortacılar analiz edilemez; finans dışı şirketler için DCF genelde daha uygun araçtır."]},"es":{"question":"¿Cuánto vale un banco o una aseguradora según lo que gana con el dinero de sus accionistas frente a lo que estos exigen?","idea":"Para un banco, el dinero prestado (los depósitos) es materia prima, no financiación, así que el DCF de flujos de caja habitual no encaja. En su lugar miras el valor contable (patrimonio neto) y el ROE (rentabilidad sobre el patrimonio): si el banco gana con cada dólar de patrimonio más de lo que exigen los accionistas, merece cotizar por encima de su valor contable, y por debajo si gana menos.","formulas":[{"name":"Rentabilidad sobre el patrimonio (ROE)","expr":"ROE = beneficio neto ÷ media del patrimonio al inicio y al final del año;  ROE usado = media de los últimos 3 años","where":[["beneficio neto","beneficio anual, millones de USD"],["patrimonio","patrimonio neto total (valor contable), millones de USD"]]},{"name":"Coste del patrimonio (CAPM)","expr":"Re = rf + β × ERP;  β = 0,67 × β bruta + 0,33","where":[["rf","tipo sin riesgo: bono del Tesoro de EE. UU. a 10 años"],["β","beta, ajustada según Blume a partir de una regresión mensual de 5 años contra SPY (1,0 si no se puede)"],["ERP","prima de riesgo de mercado (prima implícita del S&P 500 de Damodaran)"]]},{"name":"Crecimiento a largo plazo (por defecto)","expr":"g = ROE × (1 − (dividendos + recompras) ÷ beneficio neto), limitado a 0–4% y como mucho a Re − 1 punto","where":[["(1 − reparto)","retención: parte del beneficio que se queda para hacer crecer el patrimonio, media de 3 años (se supone 50% de reparto si no se conoce)"]]},{"name":"P/B justificado y valor por acción","expr":"P/B justificado = (ROE − g) ÷ (Re − g);  Valor por acción = P/B justificado × (patrimonio ÷ acciones);  DDM = DPA × (1 + g) ÷ (Re − g)","where":[["P/B","precio ÷ valor contable por acción"],["DPA","dividendos pagados el último año ÷ acciones en circulación"],["DDM","modelo de descuento de dividendos, una segunda estimación, normalmente más baja"]]}],"data":[["Beneficio neto","cuenta de resultados del 10-K (us-gaap:NetIncomeLoss, si no ProfitLoss)"],["Patrimonio neto","balance del 10-K (us-gaap:StockholdersEquity, si no el que incluye minoritarios)"],["Dividendos, recompras","estado de flujos de caja del 10-K (us-gaap:PaymentsOfDividends / PaymentsOfDividendsCommonStock, PaymentsForRepurchaseOfCommonStock)"],["Precio, acciones","último cierre de Yahoo Finance; portada dei:EntityCommonStockSharesOutstanding (si no, media diluida), ÷ ratio ADR si lo introduces"],["Tipo sin riesgo","FRED DGS10 (si no la curva del Tesoro, si no 4% supuesto)"],["Prima de riesgo","prima implícita del S&P 500 de Damodaran (si no 5% supuesto)"],["Beta","5 años de rentabilidades mensuales frente a SPY (cierres ajustados de Yahoo)"],["ROE, crecimiento, rf, ERP","tus datos, opcionales"]],"steps":["Comprueba que el patrimonio es positivo, calcula el ROE de cada año y promedia los últimos 3 (o usa tu ROE).","Construye el coste del patrimonio con el tipo sin riesgo, la beta ajustada y la prima de riesgo.","Estima el crecimiento como ROE × retención después de dividendos y recompras, limitado al 4% y a 1 punto por debajo del coste del patrimonio (o usa tu crecimiento); debe quedar al menos 0,5 puntos por debajo del coste del patrimonio.","Calcula el valor contable por acción, el P/B justificado, el valor por acción del modelo, el P/B de mercado y el valor por descuento de dividendos.","Muestra una tabla de valor por acción con coste del patrimonio ±1 punto y ROE ±2 puntos, y el ROE año a año frente al coste del patrimonio."],"example":"Empresa de ejemplo: patrimonio 1.000 y 100 acciones, así que valor contable por acción = 10. ROE 12%. Tipo sin riesgo 4% + beta 1,0 × prima 5% = coste del patrimonio 9%. De un beneficio de 120 paga 40 en dividendos y recompra 20: reparto 50%, retención 50%, ROE × retención = 6%, limitado a g = 4%. P/B justificado = (12 − 4) ÷ (9 − 4) = 1,6, así que valor del modelo = 1,6 × 10 = 16 por acción. Modelo de dividendos: DPA 0,40 × 1,04 ÷ 0,05 ≈ 8,3.","read":["Un ROE por encima del coste del patrimonio justifica un precio por encima del valor contable (P/B mayor que 1); por debajo, un precio inferior al contable.","Compara el P/B justificado con el de mercado: si el de mercado es mayor, el mercado espera más ROE, más crecimiento o menos riesgo que tus datos.","La tabla de sensibilidad muestra lo rápido que cambia el valor cuando el ROE o el coste del patrimonio se mueven un poco.","El modelo de dividendos suele dar menos porque ignora las recompras y el beneficio retenido."],"limits":["El modelo vale lo que vale el valor contable: provisiones por morosidad, pérdidas en valores, fondo de comercio y, en aseguradoras, la suficiencia de reservas pueden hacerlo engañoso.","Se usa el patrimonio total publicado; si el banco tiene acciones preferentes no se restan, así que el valor contable por acción ordinaria puede salir inflado.","El crecimiento se limita al 4% y la fórmula falla cuando el crecimiento se acerca al coste del patrimonio; un ROE medio de 3 años puede no reflejar el futuro.","La aplicación necesita una línea de ingresos en el 10-K para cargar la empresa, así que algunos bancos y aseguradoras no se pueden analizar; para empresas no financieras el DCF suele ser mejor herramienta."]}},{"id":"implied_move","number":23,"group":"risk","group_label":"Risk and credit","title":"Earnings move priced by options","next":["uncertainty","event_study","options_lab"],"en":{"question":"How big a move around the next results is the options market pricing, compared with how much the stock moved after past results?","idea":"A straddle is a call option (the right to buy) plus a put option (the right to sell) at the same strike price. It pays off when the stock moves a lot in either direction, so its price tells you how big a move the market is paying for. By comparing an expiry just before the results with one just after, the app separates the move priced for the results day alone and puts it next to the stock's own past results-day moves.","formulas":[{"name":"Straddle move to expiry","expr":"Move % = (C + P) ÷ S × 100","where":[["C, P","mid prices of the call and the put at the strike nearest the share price, first expiry after the results, $"],["S","share price (last close), $"]]},{"name":"Implied volatility from the straddle","expr":"find σ so that BS call(S, K, T, r, σ) + BS put(S, K, T, r, σ) = C + P","where":[["σ","implied volatility, % a year, solved by repeated halving between 0.1% and 500%"],["K","strike, $"],["T","calendar days to expiry ÷ 365 (at least 1 day)"],["r","1-month US Treasury yield; dividends are set to zero"]]},{"name":"Results-day move from the term structure","expr":"σ²_event = σₐ²·Tₐ − σ_b²·(Tₐ − 1/365);  event move = √σ²_event × √(2/π)","where":[["σₐ, Tₐ","implied volatility and time of the first expiry after results"],["σ_b","implied volatility of the last expiry before results"],["√(2/π) ≈ 0.80","turns a standard deviation into an expected absolute move under a normal curve"]]},{"name":"Comparison with history","expr":"Ratio = priced move ÷ median |past results-day move|","where":[["priced move","the event move when it exists, else the straddle move"],["reading","above 1.2 larger than history, below 0.8 smaller, otherwise in line"]]}],"data":[["Option quotes (bid, ask, last price, strike)","Yahoo Finance option chain, delayed; only the two expiries the method needs"],["Share price","Yahoo Finance, last close"],["Next results date","Yahoo's earnings calendar; if missing, projected from the spacing of past SEC 8-K Item 2.02 filings"],["Interest rate","1-month US Treasury yield from the Treasury curve (else the 10-year yield, else 4%)"],["Past results-day moves","dates of SEC 8-K Item 2.02 filings and 5 years of adjusted closes, last 12 results"]],"steps":["Find the next results date and whether results usually come after the 4 pm close.","Pick the first expiry that includes the results reaction and, if listed, the last expiry before the results.","For each expiry take the strike listed for both calls and puts that is nearest the share price and add the call and put mid prices.","Solve the implied volatility from each straddle with Black–Scholes; Yahoo's own figure is used only if that fails.","If both expiries exist, separate the results-day move with the term-structure formula.","Compare with the median and mean absolute moves of the last 12 results days."],"example":"Example company at $100: call 4.00 + put 4.00 = straddle 8.00, so about ±8% to expiry. Implied volatility before results 40% (expiry in 10 days), after 60% (expiry in 17 days): σ²_event = 0.36 × 17/365 − 0.16 × 16/365 ≈ 0.0168 − 0.0070 = 0.0098; √0.0098 ≈ 0.099; × 0.80 ≈ 7.9%. If the median past reaction was 6%, the ratio is 7.9 ÷ 6 ≈ 1.3: a larger move than history.","read":["The numbers say how big a move is priced, never which way: a straddle pays the same for a rise or a fall.","The straddle move to expiry also contains ordinary days; the results-day move is the cleaner number to compare with past reactions.","A ratio above 1.2 means options price a bigger results move than usual; below 0.8, a smaller one.","Check the quote-quality column: wide bid-ask spreads or last-trade prices make the estimate rougher."],"limits":["Quotes are free, delayed Yahoo data; when the market is closed, last trades are used and can be stale.","Volatility skew, dividends and early exercise are ignored, and the event formula assumes a normal-shaped move.","Without an expiry before the results the results day cannot be separated; when results are more than 30 days away the estimate is rougher (the app warns).","It uses live data only, so it cannot be run as of a past date, and it needs listed US options (no Borsa Istanbul stocks or indices). Not a forecast or advice."]},"tr":{"question":"Opsiyon piyasası sıradaki bilanço etrafında ne büyüklükte bir hareket fiyatlıyor ve bu, hissenin geçmiş bilançolardan sonraki hareketleriyle nasıl kıyaslanıyor?","idea":"Straddle, aynı kullanım fiyatında bir alım opsiyonu (satın alma hakkı) ile bir satım opsiyonunun (satma hakkı) toplamıdır. Hisse hangi yöne olursa olsun çok hareket ettiğinde kazandırır; bu yüzden fiyatı, piyasanın ne büyüklükte bir harekete para ödediğini söyler. Uygulama bilançodan hemen önceki ve hemen sonraki vadeyi karşılaştırarak yalnızca bilanço günü için fiyatlanan hareketi ayırır ve hissenin geçmiş bilanço günü hareketlerinin yanına koyar.","formulas":[{"name":"Vadeye kadar straddle hareketi","expr":"Hareket % = (C + P) ÷ S × 100","where":[["C, P","bilançodan sonraki ilk vadede, hisse fiyatına en yakın kullanım fiyatındaki alım ve satım opsiyonlarının orta fiyatları, $"],["S","hisse fiyatı (son kapanış), $"]]},{"name":"Straddle'dan örtük oynaklık","expr":"BS alım(S, K, T, r, σ) + BS satım(S, K, T, r, σ) = C + P olacak σ bulunur","where":[["σ","örtük oynaklık (ima edilen oynaklık), yıllık %; %0,1 ile %500 arasında aralığı tekrar tekrar ikiye bölerek çözülür"],["K","kullanım fiyatı, $"],["T","vadeye kalan takvim günü ÷ 365 (en az 1 gün)"],["r","1 aylık ABD Hazine faizi; temettü sıfır alınır"]]},{"name":"Vade yapısından bilanço günü hareketi","expr":"σ²_olay = σₛ²·Tₛ − σₒ²·(Tₛ − 1/365);  olay hareketi = √σ²_olay × √(2/π)","where":[["σₛ, Tₛ","bilançodan sonraki ilk vadenin örtük oynaklığı ve süresi"],["σₒ","bilançodan önceki son vadenin örtük oynaklığı"],["√(2/π) ≈ 0,80","standart sapmayı normal dağılımda beklenen mutlak harekete çevirir"]]},{"name":"Geçmişle karşılaştırma","expr":"Oran = fiyatlanan hareket ÷ geçmiş bilanço günlerinin medyan |hareketi|","where":[["fiyatlanan hareket","varsa olay hareketi, yoksa straddle hareketi"],["okuma","1,2 üstü geçmişten büyük, 0,8 altı küçük, arası geçmişe yakın"]]}],"data":[["Opsiyon kotasyonları (alış, satış, son fiyat, kullanım fiyatı)","Yahoo Finance opsiyon zinciri, gecikmeli; yalnızca yöntemin gerektirdiği iki vade"],["Hisse fiyatı","Yahoo Finance, son kapanış"],["Sıradaki bilanço tarihi","Yahoo'nun bilanço takvimi; yoksa geçmiş SEC 8-K Item 2.02 dosyalarının aralığından tahmin"],["Faiz","Hazine getiri eğrisinden 1 aylık ABD Hazine faizi (yoksa 10 yıllık faiz, o da yoksa %4)"],["Geçmiş bilanço günü hareketleri","SEC 8-K Item 2.02 tarihleri ve 5 yıllık düzeltilmiş kapanışlar, son 12 bilanço"]],"steps":["Sıradaki bilanço tarihini ve sonuçların genelde saat 16:00 kapanışından sonra açıklanıp açıklanmadığını bulur.","Bilanço tepkisini içeren ilk vadeyi ve listelenmişse bilançodan önceki son vadeyi seçer.","Her vadede hem alım hem satım için listelenmiş, hisse fiyatına en yakın kullanım fiyatını alır ve iki opsiyonun orta fiyatlarını toplar.","Her straddle'dan Black–Scholes ile örtük oynaklığı çözer; bu başarısız olursa Yahoo'nun kendi rakamını kullanır.","İki vade de varsa vade yapısı formülüyle bilanço günü hareketini ayırır.","Son 12 bilanço gününün medyan ve ortalama mutlak hareketleriyle karşılaştırır."],"example":"Örnek şirket, 100 $: alım 4,00 + satım 4,00 = straddle 8,00; yani vadeye kadar yaklaşık ±%8. Bilanço öncesi örtük oynaklık %40 (vade 10 gün sonra), sonrası %60 (vade 17 gün sonra): σ²_olay = 0,36 × 17/365 − 0,16 × 16/365 ≈ 0,0168 − 0,0070 = 0,0098; √0,0098 ≈ 0,099; × 0,80 ≈ %7,9. Geçmişteki medyan tepki %6 ise oran 7,9 ÷ 6 ≈ 1,3: geçmişten büyük bir hareket.","read":["Rakamlar hareketin büyüklüğünü söyler, yönünü asla: straddle yükselişte de düşüşte de aynı öder.","Vadeye kadarki straddle hareketi sıradan günleri de içerir; geçmiş tepkilerle kıyaslamak için bilanço günü hareketi daha temiz bir sayıdır.","Oran 1,2'nin üstündeyse opsiyonlar olağandan büyük bir bilanço hareketi fiyatlıyor; 0,8'in altındaysa daha küçük.","Kotasyon kalitesi sütununa bak: geniş alış-satış farkları veya son işlem fiyatları tahmini kabalaştırır."],"limits":["Kotasyonlar ücretsiz ve gecikmeli Yahoo verisidir; piyasa kapalıyken son işlem fiyatları kullanılır ve eski olabilir.","Oynaklık çarpıklığı, temettüler ve erken kullanım hakkı yok sayılır; olay formülü normal biçimli bir hareket varsayar.","Bilançodan önce bir vade yoksa bilanço günü ayrıştırılamaz; bilançoya 30 günden fazla varsa tahmin daha kabadır (uygulama uyarır).","Yalnızca canlı veri kullanır, bu yüzden geçmiş bir tarih itibarıyla çalıştırılamaz ve listelenmiş ABD opsiyonları gerekir (Borsa İstanbul hisseleri ve endeksler olmaz). Tahmin veya tavsiye değildir."]},"es":{"question":"¿Qué tamaño de movimiento en torno a los próximos resultados está valorando el mercado de opciones, comparado con lo que se movió la acción tras resultados anteriores?","idea":"Un straddle es una opción de compra (el derecho a comprar) más una opción de venta (el derecho a vender) con el mismo precio de ejercicio. Gana cuando la acción se mueve mucho en cualquier dirección, así que su precio indica qué tamaño de movimiento está pagando el mercado. Comparando un vencimiento justo antes de los resultados con otro justo después, la app separa el movimiento valorado solo para el día de resultados y lo pone junto a los movimientos pasados de la acción en esos días.","formulas":[{"name":"Movimiento del straddle hasta el vencimiento","expr":"Movimiento % = (C + P) ÷ S × 100","where":[["C, P","precios medios de la opción de compra y de venta en el precio de ejercicio más cercano al precio de la acción, primer vencimiento tras los resultados, $"],["S","precio de la acción (último cierre), $"]]},{"name":"Volatilidad implícita del straddle","expr":"hallar σ tal que BS compra(S, K, T, r, σ) + BS venta(S, K, T, r, σ) = C + P","where":[["σ","volatilidad implícita, % anual, resuelta dividiendo el intervalo por la mitad una y otra vez entre 0,1% y 500%"],["K","precio de ejercicio, $"],["T","días naturales hasta el vencimiento ÷ 365 (al menos 1 día)"],["r","rendimiento del Tesoro de EE. UU. a 1 mes; los dividendos se toman como cero"]]},{"name":"Movimiento del día de resultados según la estructura temporal","expr":"σ²_evento = σₐ²·Tₐ − σ_b²·(Tₐ − 1/365);  movimiento del evento = √σ²_evento × √(2/π)","where":[["σₐ, Tₐ","volatilidad implícita y plazo del primer vencimiento tras los resultados"],["σ_b","volatilidad implícita del último vencimiento antes de los resultados"],["√(2/π) ≈ 0,80","convierte una desviación típica en el movimiento absoluto esperado con una curva normal"]]},{"name":"Comparación con la historia","expr":"Ratio = movimiento valorado ÷ mediana del |movimiento pasado en días de resultados|","where":[["movimiento valorado","el del evento si existe; si no, el del straddle"],["lectura","más de 1,2 mayor que la historia, menos de 0,8 menor, si no en línea"]]}],"data":[["Cotizaciones de opciones (compra, venta, último precio, precio de ejercicio)","cadena de opciones de Yahoo Finance, con retraso; solo los dos vencimientos que necesita el método"],["Precio de la acción","Yahoo Finance, último cierre"],["Fecha de los próximos resultados","el calendario de resultados de Yahoo; si falta, proyectada con la separación de los 8-K Item 2.02 pasados de la SEC"],["Tipo de interés","rendimiento del Tesoro de EE. UU. a 1 mes de la curva del Tesoro (si no, el de 10 años; si no, 4%)"],["Movimientos pasados en días de resultados","fechas de los 8-K Item 2.02 de la SEC y 5 años de cierres ajustados, últimos 12 resultados"]],"steps":["Busca la fecha de los próximos resultados y si suelen publicarse después del cierre de las 16:00.","Elige el primer vencimiento que incluye la reacción a los resultados y, si existe, el último vencimiento anterior a los resultados.","En cada vencimiento toma el precio de ejercicio listado para compras y ventas más cercano al precio de la acción y suma los precios medios de ambas opciones.","Resuelve la volatilidad implícita de cada straddle con Black–Scholes; solo si falla usa la cifra de Yahoo.","Si existen ambos vencimientos, separa el movimiento del día de resultados con la fórmula de la estructura temporal.","Lo compara con la mediana y la media de los movimientos absolutos de los últimos 12 días de resultados."],"example":"Empresa de ejemplo a 100 $: compra 4,00 + venta 4,00 = straddle 8,00, o sea unos ±8% hasta el vencimiento. Volatilidad implícita antes de resultados 40% (vence en 10 días), después 60% (vence en 17 días): σ²_evento = 0,36 × 17/365 − 0,16 × 16/365 ≈ 0,0168 − 0,0070 = 0,0098; √0,0098 ≈ 0,099; × 0,80 ≈ 7,9%. Si la reacción mediana pasada fue 6%, la ratio es 7,9 ÷ 6 ≈ 1,3: un movimiento mayor que el histórico.","read":["Las cifras dicen el tamaño del movimiento valorado, nunca la dirección: un straddle paga lo mismo si sube o si baja.","El movimiento del straddle hasta el vencimiento incluye también días normales; el del día de resultados es la cifra más limpia para comparar con reacciones pasadas.","Una ratio mayor que 1,2 significa que las opciones valoran un movimiento de resultados mayor de lo habitual; menor que 0,8, uno menor.","Mira la columna de calidad de la cotización: diferenciales compra-venta amplios o precios de última operación hacen la estimación más tosca."],"limits":["Las cotizaciones son datos gratuitos de Yahoo con retraso; con el mercado cerrado se usan últimas operaciones que pueden estar desfasadas.","Se ignoran el sesgo de volatilidad, los dividendos y el ejercicio anticipado, y la fórmula del evento supone un movimiento de forma normal.","Sin un vencimiento anterior a los resultados no se puede separar el día de resultados; si faltan más de 30 días, la estimación es más tosca (la app avisa).","Solo usa datos en vivo, así que no puede ejecutarse a una fecha pasada, y necesita opciones cotizadas en EE. UU. (no acciones de Borsa Istanbul ni índices). No es una previsión ni un consejo."]}},{"id":"valuation_summary","number":24,"group":"valuation","group_label":"Valuation","title":"Valuation summary","next":["dcf","comps","scenarios"],"en":{"question":"Where does today's share price sit compared with the value ranges from several valuation methods at once?","idea":"Each valuation method gives a range, not one true number. This analysis puts several ranges side by side on one chart (often called a football field) with a line at today's price. If the price sits inside most ranges, the methods broadly agree with the market; if the ranges hardly overlap, the answer is driven by assumptions.","formulas":[{"name":"Model ranges","expr":"DCF: lowest to highest value for WACC ±1 pt × terminal growth ±0.5 pt;  Scenarios: bear to bull;  Bank model (banks and insurers instead): cost of equity ±1 pt × ROE ±2 pts","where":[["base","the middle point is each method's base-case value per share"],["WACC","the DCF's own CAPM-based WACC; Scenarios reuse it (9% if the DCF could not run)"]]},{"name":"Peer P/E range","expr":"Value per share = peer P/E × net income ÷ shares","where":[["peer P/E","25th to 75th percentile of the peers' P/E if there are 4+ values, else lowest to highest; middle = median"],["net income","the company's own trailing twelve months (else latest year) net income; skipped if not positive"]]},{"name":"Peer EV/EBITDA range (P/B for financials)","expr":"Value per share = (peer EV/EBITDA × EBITDA − net debt) ÷ shares;  financials: peer P/B × equity ÷ shares","where":[["EBITDA","latest-year operating income + depreciation and amortization"],["net debt","debt − cash from the latest 10-K"]]},{"name":"52-week range and overlap","expr":"Trading range = lowest to highest of the last 252 adjusted closes;  Overlap zone = highest of the lows to lowest of the highs (model methods only)","where":[["252","about one year of trading days"],["model methods","every method with a base value, not the trading range"]]}],"data":[["DCF and Scenarios inputs","as in those analyses: 10-K figures, FRED risk-free rate, Damodaran risk premium, beta vs SPY"],["Bank model inputs","net income, equity, dividends, buybacks from the 10-K; CAPM cost of equity"],["Peers","your list (up to 6) or up to 5 suggested from the same SEC industry code (SIC)"],["Peer multiples","each peer's price × shares, net income (TTM), EBIT + D&A, equity, debt and cash from its filings"],["Company figures","net income (TTM else FY: us-gaap:NetIncomeLoss), EBITDA (OperatingIncomeLoss + DepreciationDepletionAndAmortization), debt, cash, equity, shares (dei:EntityCommonStockSharesOutstanding)"],["Price and 52-week range","Yahoo Finance adjusted closes (dividends and splits)"]],"steps":["Decide whether the company is a bank or insurer (deposits, interest income or policy liabilities in its filings).","Non-financials: run the DCF with its defaults and take its sensitivity range, then rerun Scenarios at the DCF's WACC. Financials: run the bank model and take its sensitivity range.","Load the peers and apply their P/E and EV/EBITDA (or P/B for financials) ranges to the company's own earnings, EBITDA or book value.","Add the 52-week trading range; stop if fewer than two methods could be computed.","For each method say whether the price is below, inside or above the range, count them, and show the overall span, the widest range and the zone where all model ranges overlap."],"example":"Example company, price 50, 100 shares. DCF range 40 to 60: price inside. Four peers with P/E 15, 18, 20, 25: middle half 17.25 to 21.25, median 19; net income 250, so earnings per share 2.5 and range 43.1 to 53.1 (base 47.5). Three peers with EV/EBITDA 9, 10, 12 (min to max); EBITDA 500, net debt 100: (9 × 500 − 100) ÷ 100 = 44 up to (12 × 500 − 100) ÷ 100 = 59. Overlap zone = highest low 44 to lowest high 53.1; the price of 50 is inside all three.","read":["Price inside most ranges: the market price is consistent with these methods under their default assumptions.","Price below or above most ranges: the market assumes something different (growth, margins, risk or peer quality); test which with the Reverse DCF.","Ranges that do not overlap mean the choice of method and assumptions decides the answer; say so in your write-up.","The widest bar is the least precise method, not the most important one."],"limits":["It does not combine the methods into one number and it is not a price target; each method runs with its own defaults, so change assumptions in the individual analyses.","Peer ranges depend heavily on which peers are used; automatic peers from a broad industry code can be poor matches.","Periods are mixed: the P/E method uses trailing-twelve-month earnings, the EV/EBITDA method latest-year EBITDA. A method is skipped (with a warning) when the company's earnings or EBITDA are not positive or a model fails.","The 52-week range uses dividend-adjusted closes, so older prices look slightly lower than they really traded."]},"tr":{"question":"Bugünkü hisse fiyatı, birkaç değerleme yönteminin değer aralıklarına göre aynı anda nerede duruyor?","idea":"Her değerleme yöntemi tek bir doğru rakam değil, bir aralık verir. Bu analiz birkaç aralığı tek bir grafikte (genelde “futbol sahası” denir) yan yana koyar ve bugünkü fiyata bir çizgi çeker. Fiyat aralıkların çoğunun içindeyse yöntemler kabaca piyasayla aynı fikirdedir; aralıklar neredeyse hiç örtüşmüyorsa sonucu varsayımlar belirliyordur.","formulas":[{"name":"Model aralıkları","expr":"DCF: WACC ±1 puan × uç büyüme ±0,5 puan için en düşük–en yüksek değer;  Senaryolar: kötü–iyi;  Banka modeli (banka ve sigortacılarda bunların yerine): özkaynak maliyeti ±1 puan × ROE ±2 puan","where":[["baz","orta nokta her yöntemin baz senaryodaki hisse başına değeridir"],["WACC","DCF’nin kendi CAPM tabanlı WACC’si; Senaryolar onu kullanır (DCF çalışmazsa %9)"]]},{"name":"Rakip F/K aralığı","expr":"Hisse başına değer = rakip F/K × net kâr ÷ hisse","where":[["rakip F/K","4 veya daha fazla değer varsa rakiplerin F/K’larının 25. ile 75. yüzdeliği, yoksa en düşük–en yüksek; orta = medyan"],["net kâr","şirketin kendi son 12 ay (yoksa son yıl) net kârı; pozitif değilse atlanır"]]},{"name":"Rakip FD/FAVÖK aralığı (finansallarda PD/DD)","expr":"Hisse başına değer = (rakip FD/FAVÖK × FAVÖK − net borç) ÷ hisse;  finansallarda: rakip PD/DD × özkaynak ÷ hisse","where":[["FAVÖK (EBITDA)","son yılın faaliyet kârı + amortisman"],["net borç","son 10-K’dan borç − nakit"]]},{"name":"52 haftalık aralık ve örtüşme","expr":"İşlem aralığı = son 252 düzeltilmiş kapanışın en düşüğü–en yükseği;  Örtüşme bölgesi = en yüksek alt sınır – en düşük üst sınır (sadece model yöntemleri)","where":[["252","yaklaşık bir yıllık işlem günü"],["model yöntemleri","baz değeri olan her yöntem; işlem aralığı hariç"]]}],"data":[["DCF ve Senaryolar girdileri","o analizlerdeki gibi: 10-K rakamları, FRED risksiz faizi, Damodaran risk primi, SPY’a karşı beta"],["Banka modeli girdileri","10-K’dan net kâr, özkaynak, temettü, geri alım; CAPM özkaynak maliyeti"],["Rakipler","senin listen (en fazla 6) ya da aynı SEC sektör kodundan (SIC) önerilen en fazla 5 şirket"],["Rakip çarpanları","her rakibin fiyat × hisse, net kâr (TTM), FVÖK + amortisman, özkaynak, borç ve nakdi, kendi raporlarından"],["Şirket rakamları","net kâr (TTM yoksa son yıl: us-gaap:NetIncomeLoss), FAVÖK (OperatingIncomeLoss + DepreciationDepletionAndAmortization), borç, nakit, özkaynak, hisse (dei:EntityCommonStockSharesOutstanding)"],["Fiyat ve 52 haftalık aralık","Yahoo Finance düzeltilmiş kapanışlar (temettü ve bölünme)"]],"steps":["Şirketin banka ya da sigortacı olup olmadığına karar ver (raporlarında mevduat, faiz geliri veya poliçe yükümlülüğü var mı).","Finans dışı şirketlerde DCF’yi varsayılanlarıyla çalıştırıp duyarlılık aralığını al, sonra Senaryoları DCF’nin WACC’siyle yeniden çalıştır. Finansallarda banka modelini çalıştırıp duyarlılık aralığını al.","Rakipleri yükle; F/K ve FD/FAVÖK (finansallarda PD/DD) aralıklarını şirketin kendi kârına, FAVÖK’üne veya defter değerine uygula.","52 haftalık işlem aralığını ekle; ikiden az yöntem hesaplanabildiyse dur.","Her yöntem için fiyatın aralığın altında, içinde ya da üstünde olduğunu söyle, bunları say; toplam aralığı, en geniş aralığı ve tüm model aralıklarının örtüştüğü bölgeyi göster."],"example":"Örnek şirket, fiyat 50, 100 hisse. DCF aralığı 40–60: fiyat içinde. F/K’ları 15, 18, 20, 25 olan dört rakip: orta yarı 17,25–21,25, medyan 19; net kâr 250, yani hisse başına kâr 2,5 ve aralık 43,1–53,1 (baz 47,5). FD/FAVÖK’leri 9, 10, 12 olan üç rakip (en düşük–en yüksek); FAVÖK 500, net borç 100: (9 × 500 − 100) ÷ 100 = 44 ile (12 × 500 − 100) ÷ 100 = 59 arası. Örtüşme bölgesi = en yüksek alt sınır 44 ile en düşük üst sınır 53,1 arası; 50’lik fiyat üç aralığın da içinde.","read":["Fiyat aralıkların çoğunun içindeyse piyasa fiyatı bu yöntemlerle, varsayılan varsayımlar altında uyumludur.","Fiyat aralıkların çoğunun altında ya da üstündeyse piyasa farklı bir şey varsayıyordur (büyüme, marj, risk veya rakiplerin kalitesi); hangisi olduğunu Ters DCF ile sına.","Örtüşmeyen aralıklar, sonucu yöntem ve varsayım seçiminin belirlediğini gösterir; bunu yazında açıkça söyle.","En geniş çubuk en önemli değil, en az kesin yöntemdir."],"limits":["Yöntemleri tek bir rakamda birleştirmez ve hedef fiyat değildir; her yöntem kendi varsayılanlarıyla çalışır, varsayımları ilgili analizlerde değiştir.","Rakip aralıkları büyük ölçüde hangi rakiplerin kullanıldığına bağlıdır; geniş bir sektör kodundan gelen otomatik rakipler kötü eşleşebilir.","Dönemler karışıktır: F/K yöntemi son 12 ay kârını, FD/FAVÖK yöntemi son yıl FAVÖK’ünü kullanır. Şirketin kârı veya FAVÖK’ü pozitif değilse ya da bir model çalışmazsa o yöntem uyarıyla atlanır.","52 haftalık aralık temettüye göre düzeltilmiş kapanışları kullanır; eski fiyatlar gerçekte işlem gördüklerinden biraz düşük görünür."]},"es":{"question":"¿Dónde está el precio de hoy frente a los rangos de valor de varios métodos de valoración a la vez?","idea":"Cada método de valoración da un rango, no un único número verdadero. Este análisis pone varios rangos uno al lado del otro en un solo gráfico (a menudo llamado \"campo de fútbol\") con una línea en el precio de hoy. Si el precio está dentro de la mayoría de rangos, los métodos coinciden a grandes rasgos con el mercado; si los rangos apenas se solapan, mandan los supuestos.","formulas":[{"name":"Rangos de los modelos","expr":"DCF: del valor más bajo al más alto con WACC ±1 punto × crecimiento terminal ±0,5 puntos;  Escenarios: de bajista a alcista;  Modelo bancario (en bancos y aseguradoras en su lugar): coste del patrimonio ±1 punto × ROE ±2 puntos","where":[["base","el punto central es el valor por acción del caso base de cada método"],["WACC","el WACC del propio DCF basado en CAPM; Escenarios lo reutiliza (9% si el DCF no pudo calcularse)"]]},{"name":"Rango por P/E de comparables","expr":"Valor por acción = P/E de comparables × beneficio neto ÷ acciones","where":[["P/E de comparables","percentiles 25 a 75 del P/E de los comparables si hay 4 o más valores, si no del más bajo al más alto; centro = mediana"],["beneficio neto","el de la propia empresa en los últimos doce meses (si no, último año); se omite si no es positivo"]]},{"name":"Rango por EV/EBITDA de comparables (P/B en financieras)","expr":"Valor por acción = (EV/EBITDA de comparables × EBITDA − deuda neta) ÷ acciones;  financieras: P/B de comparables × patrimonio ÷ acciones","where":[["EBITDA","beneficio operativo + amortizaciones del último año"],["deuda neta","deuda − caja del último 10-K"]]},{"name":"Rango de 52 semanas y solapamiento","expr":"Rango de cotización = mínimo a máximo de los últimos 252 cierres ajustados;  Zona común = el mayor de los mínimos al menor de los máximos (solo métodos de modelo)","where":[["252","aproximadamente un año de sesiones bursátiles"],["métodos de modelo","todo método con valor base, no el rango de cotización"]]}],"data":[["Datos del DCF y de Escenarios","como en esos análisis: cifras del 10-K, tipo sin riesgo de FRED, prima de riesgo de Damodaran, beta frente a SPY"],["Datos del modelo bancario","beneficio neto, patrimonio, dividendos y recompras del 10-K; coste del patrimonio por CAPM"],["Comparables","tu lista (hasta 6) o hasta 5 sugeridos con el mismo código sectorial de la SEC (SIC)"],["Múltiplos de comparables","precio × acciones, beneficio neto (TTM), EBIT + D&A, patrimonio, deuda y caja de cada comparable, de sus informes"],["Cifras de la empresa","beneficio neto (TTM, si no último año: us-gaap:NetIncomeLoss), EBITDA (OperatingIncomeLoss + DepreciationDepletionAndAmortization), deuda, caja, patrimonio, acciones (dei:EntityCommonStockSharesOutstanding)"],["Precio y rango de 52 semanas","cierres ajustados de Yahoo Finance (dividendos y splits)"]],"steps":["Decide si la empresa es un banco o aseguradora (depósitos, ingresos por intereses o pasivos por pólizas en sus informes).","No financieras: calcula el DCF con sus valores por defecto y toma su rango de sensibilidad; luego repite Escenarios con el WACC del DCF. Financieras: calcula el modelo bancario y toma su rango de sensibilidad.","Carga los comparables y aplica sus rangos de P/E y EV/EBITDA (o P/B en financieras) al beneficio, EBITDA o valor contable de la propia empresa.","Añade el rango de cotización de 52 semanas; se detiene si se pudieron calcular menos de dos métodos.","Para cada método indica si el precio está por debajo, dentro o por encima del rango, cuéntalos y muestra la amplitud total, el rango más ancho y la zona donde se solapan todos los rangos de modelo."],"example":"Empresa de ejemplo, precio 50, 100 acciones. Rango DCF de 40 a 60: precio dentro. Cuatro comparables con P/E 15, 18, 20, 25: mitad central 17,25 a 21,25, mediana 19; beneficio neto 250, así que beneficio por acción 2,5 y rango 43,1 a 53,1 (base 47,5). Tres comparables con EV/EBITDA 9, 10, 12 (mínimo a máximo); EBITDA 500, deuda neta 100: de (9 × 500 − 100) ÷ 100 = 44 a (12 × 500 − 100) ÷ 100 = 59. Zona común = mayor mínimo 44 a menor máximo 53,1; el precio de 50 está dentro de los tres.","read":["Precio dentro de la mayoría de rangos: el precio de mercado es coherente con estos métodos bajo sus supuestos por defecto.","Precio por debajo o por encima de la mayoría: el mercado supone otra cosa (crecimiento, márgenes, riesgo o calidad de los comparables); compruébalo con el DCF inverso.","Rangos que no se solapan significan que la elección del método y de los supuestos decide el resultado; dilo claramente en tu análisis.","La barra más ancha es el método menos preciso, no el más importante."],"limits":["No combina los métodos en un solo número y no es un precio objetivo; cada método usa sus propios valores por defecto, así que cambia los supuestos en cada análisis por separado.","Los rangos de comparables dependen mucho de qué comparables se usen; los automáticos de un código sectorial amplio pueden no parecerse.","Se mezclan periodos: el método P/E usa beneficio de los últimos doce meses y el de EV/EBITDA el EBITDA del último año. Un método se omite (con aviso) si el beneficio o el EBITDA de la empresa no son positivos o si un modelo falla.","El rango de 52 semanas usa cierres ajustados por dividendos, así que los precios antiguos parecen algo más bajos de lo que realmente cotizaron."]}},{"id":"insiders","number":25,"group":"risk","group_label":"Risk and credit","title":"Insider trading (Form 4)","next":["holders","event_study","quarterly"],"en":{"question":"What have the company's directors, executives and big owners done with their own shares over the last 12 months?","idea":"Insiders are a company's officers, board directors and anyone owning more than 10% of the shares. In the US they must report every trade in the company's shares on SEC Form 4 within two business days. The app reads these filings and separates trades the insider chose to make (buying or selling on the open market) from automatic ones such as share awards, option exercises or shares kept back for tax.","formulas":[{"name":"Value of a trade","expr":"Value = shares × reported price per share","where":[["shares","number of shares in the transaction (negative when shares were disposed of)"],["price","price per share on the Form 4, $; the value is shown in $ millions"]]},{"name":"Open-market totals","expr":"Buys = Σ value of code P trades;  Sales = Σ value of code S trades","where":[["P","open-market purchase"],["S","open-market sale"]]},{"name":"Share of sales under a 10b5-1 plan","expr":"Plan share = value of plan sales ÷ value of all sales × 100","where":[["10b5-1 plan","a trading plan set up in advance; the filing's plan box is ticked or a footnote mentions 10b5-1"]]},{"name":"Sold, % of direct holding","expr":"Sold % = shares sold ÷ (shares held after + shares sold) × 100","where":[["shares sold","net shares sold in P and S trades by that person"],["shares held after","shares owned directly after that person's latest reported transaction"]]}],"data":[["List of Form 4 filings","the company's SEC EDGAR submissions file, last 12 months, up to the newest 100 filings"],["Each trade (date, code, shares, price, acquired or disposed, shares held after, name, role, plan flag)","the Form 4 XML document on SEC EDGAR (non-derivative table only); your SEC contact email is needed to download"],["Results dates","the last 8 SEC 8-K filings with Item 2.02 (results announcements)"]],"steps":["List Form 4 filings from the last 12 months (if there are more than 100, read the newest 100 and shorten the window to what they cover).","Read every filing's share transactions: who, role, date, code, shares, price, shares held after, and the 10b5-1 flag.","Treat only codes P and S as discretionary; show grants (A), option exercises (M), tax withholding (F) and gifts (G) but do not read them as signals.","Add up buys and sales overall, per insider and per month.","Flag cluster buying (3 or more different insiders buying within 30 days), trades in the 30 days before a results date, and insiders who sold 20% or more of their direct holding."],"example":"Example company: the CEO sells 10,000 shares at $50, so the value is 10,000 × 50 = $500,000 = $0.5m, and still holds 40,000 shares afterwards; sold % = 10,000 ÷ (40,000 + 10,000) × 100 = 20% of the direct holding. A director buys 2,000 shares at $50 = $0.1m. Totals: buys $0.1m, sales $0.5m. If the CEO's sale was under a 10b5-1 plan, the plan share of sales is 0.5 ÷ 0.5 = 100%.","read":["Purchases tend to say more than sales: people sell for many personal reasons (taxes, a house, diversifying) but usually buy for one.","Several insiders buying within a short time is considered more informative than one purchase.","Sales under 10b5-1 plans were scheduled in advance and carry less information.","No open-market purchases at all is common at large companies, where executives get shares as pay."],"limits":["This is not a trading signal or advice; a trade before results is usually planned and proves nothing on its own.","Only direct share transactions are counted; options and other derivatives are left out, and the holding used for the sold % is the one reported after that person's latest transaction, so it is approximate.","Busy filers are capped at the newest 100 filings and unreadable files are skipped (the app warns). Trades without a reported price, such as gifts, add no value.","The 10b5-1 flag is set for every trade in a filing whose footnotes mention 10b5-1, and the before-results check looks only at past results dates."]},"tr":{"question":"Şirketin yönetim kurulu üyeleri, yöneticileri ve büyük ortakları son 12 ayda kendi hisseleriyle ne yaptı?","idea":"İçeriden kişiler şirketin yöneticileri, yönetim kurulu üyeleri ve hisselerin %10'undan fazlasına sahip olanlardır. ABD'de şirket hisselerindeki her işlemi iki iş günü içinde SEC Form 4 ile bildirmek zorundadırlar. Uygulama bu dosyaları okur ve içeriden işlemleri ikiye ayırır: kişinin kendi seçtiği işlemler (açık piyasadan alım veya satım) ve otomatik olanlar (hisse ödülleri, opsiyon kullanımları, vergi için elde tutulan hisseler gibi).","formulas":[{"name":"Bir işlemin değeri","expr":"Değer = hisse adedi × bildirilen hisse başı fiyat","where":[["hisse adedi","işlemdeki hisse sayısı (elden çıkarıldıysa negatif)"],["fiyat","Form 4'teki hisse başı fiyat, $; değer milyon $ olarak gösterilir"]]},{"name":"Açık piyasa toplamları","expr":"Alımlar = Σ P kodlu işlemlerin değeri;  Satışlar = Σ S kodlu işlemlerin değeri","where":[["P","açık piyasadan alım"],["S","açık piyasada satış"]]},{"name":"Satışların 10b5-1 planlı payı","expr":"Plan payı = planlı satışların değeri ÷ tüm satışların değeri × 100","where":[["10b5-1 planı","önceden kurulmuş bir işlem planı; dosyada plan kutusu işaretli veya dipnotta 10b5-1 geçiyor"]]},{"name":"Satılan, doğrudan payın %'si","expr":"Satılan % = satılan hisse ÷ (sonrasında tutulan hisse + satılan hisse) × 100","where":[["satılan hisse","o kişinin P ve S işlemlerinde net sattığı hisse"],["sonrasında tutulan hisse","o kişinin bildirilen son işleminden sonra doğrudan sahip olduğu hisse"]]}],"data":[["Form 4 dosyalarının listesi","şirketin SEC EDGAR başvuru dosyası, son 12 ay, en yeni 100 dosyaya kadar"],["Her işlem (tarih, kod, hisse, fiyat, alım veya elden çıkarma, sonrasında tutulan hisse, ad, görev, plan işareti)","SEC EDGAR'daki Form 4 XML belgesi (yalnızca türev olmayan tablo); indirmek için SEC iletişim e-postan gerekir"],["Bilanço tarihleri","Item 2.02 içeren son 8 SEC 8-K dosyası (sonuç açıklamaları)"]],"steps":["Son 12 ayın Form 4 dosyalarını listeler (100'den fazlaysa en yeni 100'ünü okur ve dönemi onların kapsadığı aralığa kısaltır).","Her dosyanın hisse işlemlerini okur: kim, görevi, tarih, kod, hisse, fiyat, sonrasında tutulan hisse ve 10b5-1 işareti.","Yalnızca P ve S kodlarını isteğe bağlı sayar; hibeleri (A), opsiyon kullanımlarını (M), vergi için elde tutmayı (F) ve bağışları (G) gösterir ama sinyal olarak okumaz.","Alım ve satışları toplamda, kişi bazında ve ay bazında toplar.","Toplu alımı (30 gün içinde 3 veya daha fazla farklı içeriden kişinin alımı), bir bilanço tarihinden önceki 30 gündeki işlemleri ve doğrudan payının %20'sini veya fazlasını satanları işaretler."],"example":"Örnek şirket: CEO 50 $'dan 10.000 hisse satar; değer 10.000 × 50 = 500.000 $ = 0,5 milyon $; sonrasında hâlâ 40.000 hissesi var. Satılan % = 10.000 ÷ (40.000 + 10.000) × 100 = doğrudan payın %20'si. Bir yönetim kurulu üyesi 50 $'dan 2.000 hisse alır = 0,1 milyon $. Toplamlar: alım 0,1 milyon $, satış 0,5 milyon $. CEO'nun satışı 10b5-1 planıyla yapıldıysa satışların plan payı 0,5 ÷ 0,5 = %100.","read":["Alımlar satışlardan daha çok şey söyler: insanlar birçok kişisel nedenle satar (vergi, ev, çeşitlendirme) ama genelde tek bir nedenle alır.","Kısa sürede birden fazla içeriden kişinin alması, tek bir alımdan daha bilgilendirici kabul edilir.","10b5-1 planlı satışlar önceden takvime bağlanmıştır ve daha az bilgi taşır.","Hiç açık piyasa alımı olmaması büyük şirketlerde sık görülür; yöneticiler hisseyi ücret olarak alır."],"limits":["Bu bir alım-satım sinyali veya tavsiye değildir; bilanço öncesi bir işlem genelde planlıdır ve tek başına bir şey kanıtlamaz.","Yalnızca doğrudan hisse işlemleri sayılır; opsiyonlar ve diğer türevler dışarıda kalır. Satılan % için kullanılan pay, kişinin son işleminden sonra bildirdiği paydır, bu yüzden yaklaşıktır.","Çok dosya veren şirketlerde en yeni 100 dosya okunur, okunamayan dosyalar atlanır (uygulama uyarır). Bağış gibi fiyatı bildirilmeyen işlemler değere eklenmez.","Dipnotlarında 10b5-1 geçen bir dosyadaki tüm işlemler planlı işaretlenir; bilanço öncesi kontrolü yalnızca geçmiş bilanço tarihlerine bakar."]},"es":{"question":"¿Qué han hecho los consejeros, directivos y grandes accionistas de la empresa con sus propias acciones en los últimos 12 meses?","idea":"Los insiders (personas con información privilegiada) son los directivos, los miembros del consejo y quien posee más del 10% de las acciones. En EE. UU. deben declarar cada operación con acciones de la empresa en el Form 4 de la SEC en dos días hábiles. La app lee estas declaraciones y separa las operaciones que la persona eligió hacer (comprar o vender en el mercado) de las automáticas, como acciones recibidas como pago, ejercicio de opciones o acciones retenidas para impuestos.","formulas":[{"name":"Valor de una operación","expr":"Valor = acciones × precio por acción declarado","where":[["acciones","número de acciones de la operación (negativo cuando se entregaron)"],["precio","precio por acción del Form 4, $; el valor se muestra en millones de $"]]},{"name":"Totales de mercado abierto","expr":"Compras = Σ valor de las operaciones con código P;  Ventas = Σ valor de las de código S","where":[["P","compra en mercado abierto"],["S","venta en mercado abierto"]]},{"name":"Parte de las ventas bajo un plan 10b5-1","expr":"Parte del plan = valor de las ventas del plan ÷ valor de todas las ventas × 100","where":[["plan 10b5-1","un plan de operaciones fijado de antemano; la casilla del plan está marcada o una nota menciona 10b5-1"]]},{"name":"Vendido, % de la participación directa","expr":"Vendido % = acciones vendidas ÷ (acciones tras la operación + acciones vendidas) × 100","where":[["acciones vendidas","acciones netas vendidas por esa persona en operaciones P y S"],["acciones tras la operación","acciones en propiedad directa tras la última operación declarada de esa persona"]]}],"data":[["Lista de formularios Form 4","el archivo de presentaciones de la empresa en SEC EDGAR, últimos 12 meses, hasta los 100 más recientes"],["Cada operación (fecha, código, acciones, precio, adquirida o entregada, acciones tras la operación, nombre, cargo, marca de plan)","el documento XML del Form 4 en SEC EDGAR (solo la tabla de valores no derivados); hace falta tu correo de contacto para la SEC"],["Fechas de resultados","los últimos 8 formularios 8-K de la SEC con el Item 2.02 (anuncios de resultados)"]],"steps":["Lista los Form 4 de los últimos 12 meses (si hay más de 100, lee los 100 más recientes y acorta el periodo a lo que cubren).","Lee las operaciones con acciones de cada formulario: quién, cargo, fecha, código, acciones, precio, acciones tras la operación y la marca 10b5-1.","Solo considera discrecionales los códigos P y S; muestra las concesiones (A), los ejercicios de opciones (M), las retenciones fiscales (F) y las donaciones (G), pero no las lee como señales.","Suma compras y ventas en total, por persona y por mes.","Marca las compras en grupo (3 o más insiders distintos comprando en 30 días), las operaciones en los 30 días previos a una fecha de resultados y a quien vendió el 20% o más de su participación directa."],"example":"Empresa de ejemplo: el consejero delegado vende 10.000 acciones a 50 $, así que el valor es 10.000 × 50 = 500.000 $ = 0,5 millones de $, y después conserva 40.000 acciones; vendido % = 10.000 ÷ (40.000 + 10.000) × 100 = 20% de su participación directa. Un consejero compra 2.000 acciones a 50 $ = 0,1 millones de $. Totales: compras 0,1 millones, ventas 0,5 millones. Si la venta fue bajo un plan 10b5-1, la parte del plan en las ventas es 0,5 ÷ 0,5 = 100%.","read":["Las compras suelen decir más que las ventas: se vende por muchas razones personales (impuestos, una casa, diversificar), pero normalmente se compra por una sola.","Varios insiders comprando en poco tiempo se considera más informativo que una compra aislada.","Las ventas bajo planes 10b5-1 se programaron de antemano y aportan menos información.","Que no haya ninguna compra en el mercado es habitual en empresas grandes, donde los directivos reciben acciones como sueldo."],"limits":["No es una señal de compraventa ni un consejo; una operación antes de resultados suele estar planificada y por sí sola no prueba nada.","Solo cuentan las operaciones directas con acciones; quedan fuera las opciones y otros derivados, y la participación usada para el % vendido es la declarada tras la última operación de esa persona, así que es aproximada.","En empresas con muchas declaraciones solo se leen las 100 más recientes y se omiten los archivos ilegibles (la app avisa). Las operaciones sin precio declarado, como donaciones, no suman valor.","La marca 10b5-1 se pone a todas las operaciones de un formulario cuyas notas mencionan 10b5-1, y la comprobación previa a resultados solo mira fechas de resultados pasadas."]}},{"id":"holders","number":26,"group":"risk","group_label":"Risk and credit","title":"Institutional ownership (13F)","next":["insiders","factors","comps"],"en":{"question":"Which big investment firms own the stock, and did they add to or cut their stakes in the latest reporting period?","idea":"In the US, investment managers with more than $100 million must list their stock holdings every quarter on SEC Form 13F. The app reads Yahoo Finance's free summary of these filings: the largest institutional holders, the largest mutual funds, how much of the company each owns and how their share count changed since their previous filing. Counting who added and who cut gives a rough picture of how large holders positioned themselves last quarter.","formulas":[{"name":"Stake of a holder","expr":"% held = holder's shares ÷ shares outstanding × 100 (as reported by Yahoo)","where":[["% held","percentage of the company the holder owns"],["source","Yahoo computes this fraction; the app only multiplies it by 100"]]},{"name":"Change since the prior filing","expr":"Change % = (shares now ÷ shares in the previous filing − 1) × 100 (as reported by Yahoo)","where":[["Change %","percentage change in the number of shares, not in dollar value"],["source","Yahoo computes this fraction; the app only multiplies it by 100"]]},{"name":"Tally of the top institutions","expr":"added if Change > +1%;  cut if Change < −1%;  otherwise about the same","where":[["Top total","Σ % held of the listed top institutions"]]},{"name":"One side clearly ahead","expr":"added ≥ 2 × max(cut, 1)  or  cut ≥ 2 × max(added, 1)","where":[["added, cut","number of top institutions that raised or lowered their stake"]]}],"data":[["Top 10 institutional holders (name, date reported, shares, value, % held, change)","Yahoo Finance holders summary of SEC 13F filings, via yfinance"],["Top 10 mutual fund holders","Yahoo Finance summary of fund filings, via yfinance"],["Ownership summary (insiders %, institutions %, institutions % of float, number of institutions)","Yahoo Finance major holders, via yfinance"]],"steps":["Download the holders summary from Yahoo Finance (US-listed shares only; kept for a day).","For each holder read the stake, the value, the date reported and the change in shares since its previous filing.","Count how many of the top institutions added (more than +1%), cut (less than −1%) or kept their stake about the same.","Find the biggest single change and check whether adders clearly outnumber cutters or the reverse.","Show tables for institutions, funds and the ownership summary, and a bar chart of the changes."],"example":"Example company: its top 10 institutions own 25% of the shares in total. Their changes since the prior filing: four are above +1% (for example +6%, +3%, +2%, +1.5%), two are below −1% (−2%, −4%) and four lie between −1% and +1%. So added = 4, cut = 2, about the same = 4. Since 4 ≥ 2 × max(2, 1) = 4, clearly more holders added than cut. The biggest change is the +6%.","read":["The institutions % shows how much of the company sits with professional investors.","The added versus cut count summarises what the largest holders did in the last reported quarter.","Index funds (for example Vanguard, BlackRock, State Street) usually top the list and change stakes mechanically with index weights, so moves by active managers say more.","A change is measured in shares, so a price rise alone does not count as buying."],"limits":["13F data arrive up to 45 days after the quarter ends and show long positions only; anything traded since then is invisible.","Only the top 10 institutions and top 10 funds are shown, and the figures are Yahoo's summary, not a reading of every SEC filing; holders can report as of different dates.","It uses the current summary only, so it cannot be run as of a past date, and it covers US-listed shares only.","It is not a signal or advice: a fund can buy or sell for reasons that have nothing to do with this company, such as new money coming in or rebalancing."]},"tr":{"question":"Hangi büyük yatırım kuruluşları hisseye sahip ve son raporlama döneminde paylarını artırdılar mı, azalttılar mı?","idea":"ABD'de 100 milyon dolardan fazla yöneten kurumsal yatırımcılar hisse varlıklarını her çeyrek SEC Form 13F ile bildirmek zorundadır. Uygulama Yahoo Finance'in bu dosyalardan derlediği ücretsiz özeti okur: en büyük kurumsal sahipler, en büyük yatırım fonları, her birinin şirketin ne kadarına sahip olduğu ve hisse sayısının önceki raporlarına göre nasıl değiştiği. Kimin artırıp kimin azalttığını saymak, büyük sahiplerin geçen çeyrek nasıl konumlandığına dair kaba bir resim verir.","formulas":[{"name":"Bir sahibin payı","expr":"% pay = sahibin hisseleri ÷ dolaşımdaki hisseler × 100 (Yahoo'nun bildirdiği gibi)","where":[["% pay","sahibin şirketin yüzde kaçına sahip olduğu"],["kaynak","bu oranı Yahoo hesaplar; uygulama yalnızca 100 ile çarpar"]]},{"name":"Önceki rapordan bu yana değişim","expr":"Değişim % = (şimdiki hisse ÷ önceki rapordaki hisse − 1) × 100 (Yahoo'nun bildirdiği gibi)","where":[["Değişim %","dolar değerindeki değil, hisse sayısındaki yüzde değişim"],["kaynak","bu oranı Yahoo hesaplar; uygulama yalnızca 100 ile çarpar"]]},{"name":"En büyük kurumların sayımı","expr":"Değişim > +%1 ise artırdı;  < −%1 ise azalttı;  değilse yaklaşık aynı","where":[["En büyüklerin toplamı","listelenen en büyük kurumların % paylarının toplamı (Σ)"]]},{"name":"Bir tarafın belirgin üstünlüğü","expr":"artıran ≥ 2 × max(azaltan, 1)  veya  azaltan ≥ 2 × max(artıran, 1)","where":[["artıran, azaltan","payını yükselten veya düşüren en büyük kurum sayısı"]]}],"data":[["En büyük 10 kurumsal sahip (ad, rapor tarihi, hisse, değer, % pay, değişim)","Yahoo Finance'in SEC 13F dosyalarından derlediği sahip özeti, yfinance ile"],["En büyük 10 yatırım fonu","Yahoo Finance'in fon raporlarından derlediği özet, yfinance ile"],["Sahiplik özeti (içeriden kişilerin %, kurumların %, kurumların halka açık paydaki %, kurum sayısı)","Yahoo Finance major holders, yfinance ile"]],"steps":["Yahoo Finance'ten sahip özetini indirir (yalnızca ABD'de işlem gören hisseler; bir gün saklanır).","Her sahip için payı, değeri, rapor tarihini ve önceki rapordan bu yana hisse sayısındaki değişimi okur.","En büyük kurumlardan kaçının payını artırdığını (+%1'den fazla), azalttığını (−%1'den az) veya yaklaşık aynı tuttuğunu sayar.","En büyük tek değişimi bulur ve artıranların azaltanlardan belirgin şekilde fazla olup olmadığına (ya da tersine) bakar.","Kurumlar, fonlar ve sahiplik özeti tablolarını ve değişimlerin çubuk grafiğini gösterir."],"example":"Örnek şirket: en büyük 10 kurum toplam hisselerin %25'ine sahip. Önceki rapordan bu yana değişimleri: dördü +%1'in üstünde (örneğin +%6, +%3, +%2, +%1,5), ikisi −%1'in altında (−%2, −%4), dördü −%1 ile +%1 arasında. Yani artıran = 4, azaltan = 2, yaklaşık aynı = 4. 4 ≥ 2 × max(2, 1) = 4 olduğu için artıranlar belirgin şekilde fazla. En büyük değişim +%6.","read":["Kurumların payı, şirketin ne kadarının profesyonel yatırımcılarda olduğunu gösterir.","Artıran ve azaltan sayısı, en büyük sahiplerin son raporlanan çeyrekte ne yaptığını özetler.","Endeks fonları (örneğin Vanguard, BlackRock, State Street) genelde listenin başındadır ve paylarını endeks ağırlığına göre otomatik değiştirir; bu yüzden aktif yöneticilerin hareketi daha anlamlıdır.","Değişim hisse sayısıyla ölçülür; yalnızca fiyatın yükselmesi alım sayılmaz."],"limits":["13F verisi çeyrek sonundan 45 güne kadar gecikmeli gelir ve yalnızca uzun pozisyonları gösterir; o tarihten sonraki işlemler görünmez.","Yalnızca en büyük 10 kurum ve 10 fon gösterilir; rakamlar her SEC dosyasının okunması değil Yahoo'nun özetidir ve sahipler farklı tarihler itibarıyla rapor verebilir.","Yalnızca güncel özeti kullanır, bu yüzden geçmiş bir tarih itibarıyla çalıştırılamaz ve yalnızca ABD'de işlem gören hisseleri kapsar.","Sinyal veya tavsiye değildir: bir fon, yeni para girişi veya portföy dengelemesi gibi bu şirketle ilgisi olmayan nedenlerle alıp satabilir."]},"es":{"question":"¿Qué grandes gestoras tienen la acción, y aumentaron o redujeron su participación en el último periodo declarado?","idea":"En EE. UU., los gestores con más de 100 millones de dólares deben declarar sus acciones cada trimestre en el Form 13F de la SEC. La app lee el resumen gratuito que hace Yahoo Finance de esas declaraciones: los mayores inversores institucionales, los mayores fondos de inversión, qué parte de la empresa tiene cada uno y cómo cambió su número de acciones desde su declaración anterior. Contar quién aumentó y quién redujo da una idea aproximada de cómo se posicionaron los grandes accionistas el último trimestre.","formulas":[{"name":"Participación de un accionista","expr":"% de acciones = acciones del accionista ÷ acciones en circulación × 100 (según Yahoo)","where":[["% de acciones","porcentaje de la empresa que posee el accionista"],["fuente","Yahoo calcula esta fracción; la app solo la multiplica por 100"]]},{"name":"Cambio desde la declaración anterior","expr":"Cambio % = (acciones ahora ÷ acciones en la declaración anterior − 1) × 100 (según Yahoo)","where":[["Cambio %","variación porcentual del número de acciones, no del valor en dólares"],["fuente","Yahoo calcula esta fracción; la app solo la multiplica por 100"]]},{"name":"Recuento de las mayores instituciones","expr":"aumentó si Cambio > +1%;  redujo si Cambio < −1%;  si no, más o menos igual","where":[["Total de las mayores","Σ del % de acciones de las mayores instituciones listadas"]]},{"name":"Un lado claramente por delante","expr":"aumentaron ≥ 2 × máx(redujeron, 1)  o  redujeron ≥ 2 × máx(aumentaron, 1)","where":[["aumentaron, redujeron","número de grandes instituciones que subieron o bajaron su participación"]]}],"data":[["Las 10 mayores instituciones (nombre, fecha declarada, acciones, valor, % de acciones, cambio)","resumen de accionistas de Yahoo Finance basado en los 13F de la SEC, mediante yfinance"],["Los 10 mayores fondos de inversión","resumen de Yahoo Finance de las declaraciones de fondos, mediante yfinance"],["Resumen de propiedad (% de insiders, % de instituciones, % del capital flotante en instituciones, número de instituciones)","major holders de Yahoo Finance, mediante yfinance"]],"steps":["Descarga el resumen de accionistas de Yahoo Finance (solo acciones cotizadas en EE. UU.; se guarda un día).","Para cada accionista lee la participación, el valor, la fecha declarada y el cambio de acciones desde su declaración anterior.","Cuenta cuántas de las mayores instituciones aumentaron (más de +1%), redujeron (menos de −1%) o mantuvieron más o menos su participación.","Busca el mayor cambio individual y comprueba si quienes aumentaron superan claramente a quienes redujeron, o al revés.","Muestra tablas de instituciones, fondos y el resumen de propiedad, y un gráfico de barras de los cambios."],"example":"Empresa de ejemplo: sus 10 mayores instituciones tienen en total el 25% de las acciones. Sus cambios desde la declaración anterior: cuatro superan +1% (por ejemplo +6%, +3%, +2%, +1,5%), dos están por debajo de −1% (−2%, −4%) y cuatro entre −1% y +1%. Así que aumentaron = 4, redujeron = 2, más o menos igual = 4. Como 4 ≥ 2 × máx(2, 1) = 4, claramente más accionistas aumentaron que redujeron. El mayor cambio es el +6%.","read":["El % en manos de instituciones muestra cuánta parte de la empresa está en inversores profesionales.","El recuento de quién aumentó y quién redujo resume lo que hicieron los mayores accionistas en el último trimestre declarado.","Los fondos indexados (por ejemplo Vanguard, BlackRock, State Street) suelen encabezar la lista y cambian su participación de forma mecánica con los pesos del índice, así que los movimientos de los gestores activos dicen más.","El cambio se mide en acciones, así que una subida del precio por sí sola no cuenta como compra."],"limits":["Los datos 13F llegan hasta 45 días después del cierre del trimestre y solo muestran posiciones largas; lo negociado desde entonces no se ve.","Solo se muestran las 10 mayores instituciones y los 10 mayores fondos, y las cifras son el resumen de Yahoo, no una lectura de cada declaración de la SEC; los accionistas pueden declarar en fechas distintas.","Solo usa el resumen actual, así que no puede ejecutarse a una fecha pasada, y solo cubre acciones cotizadas en EE. UU.","No es una señal ni un consejo: un fondo puede comprar o vender por razones ajenas a la empresa, como la entrada de dinero nuevo o un reequilibrio."]}},{"id":"quarterly","number":27,"group":"fundamental","group_label":"Fundamentals","title":"Quarterly results tracker","next":["event_study","implied_move","segments"],"en":{"question":"How did the company's latest quarter compare with the quarter before and with the same quarter a year ago?","idea":"Annual reports come once a year, but US companies also publish results every three months in a 10-Q. This analysis lines up the last nine quarters of revenue, margins, earnings per share and cash flow, then compares the newest quarter with the previous one and with the same quarter a year earlier. The year-ago comparison is usually fairer, because many businesses are seasonal.","formulas":[{"name":"Revenue growth","expr":"Change vs prior = (Revenue this quarter ÷ Revenue previous quarter − 1) × 100; Change vs a year ago = (Revenue this quarter ÷ Revenue same quarter last year − 1) × 100","where":[["same quarter last year","the quarter that ended 350–380 days earlier"],["Change","percent; blank if the earlier value is zero or negative"]]},{"name":"Margins","expr":"Operating margin = Operating income ÷ Revenue × 100; Net margin = Net income ÷ Revenue × 100","where":[["Operating income, Net income","for the three-month quarter (USD millions)"],["Margin change","this quarter's margin − the year-ago margin, in percentage points"]]},{"name":"Fourth quarter (derived)","expr":"Q4 = Full fiscal year (10-K) − Q1 − Q2 − Q3","where":[["Q4","companies file no 10-Q for the fourth quarter, so it is computed and marked “10-K − Q1–Q3”"]]},{"name":"Quarterly cash flow","expr":"Quarter CFO = Year-to-date CFO now − Year-to-date CFO at the previous quarter end; FCF = CFO − Capex","where":[["Year-to-date","a 10-Q reports cash flow from the start of the fiscal year (3, 6, 9 months; the 10-K gives 12)"],["FCF","free cash flow (USD millions)"]]}],"data":[["Revenue","10-Q and 10-K income statements, three-month periods (XBRL us-gaap:RevenueFromContractWithCustomerExcludingAssessedTax, else …IncludingAssessedTax, Revenues, SalesRevenueNet or RevenuesNetOfInterestExpense)"],["Operating income and net income","10-Q and 10-K income statements (us-gaap:OperatingIncomeLoss; NetIncomeLoss, else ProfitLoss)"],["Diluted EPS","10-Q and 10-K (us-gaap:EarningsPerShareDiluted), only reported three-month figures"],["Operating cash flow and capex","10-Q and 10-K cash-flow statements, year-to-date (us-gaap:NetCashProvidedByUsedInOperatingActivities; PaymentsToAcquirePropertyPlantAndEquipment, else PaymentsToAcquireProductiveAssets)"]],"steps":["Read the three-month revenue, operating income and net income facts from SEC filings (US GAAP, US dollars) and keep the latest nine quarters.","Where a fiscal year has a 10-K and three 10-Q quarters, compute Q4 as the year total minus Q1–Q3 and label it as derived.","Turn year-to-date cash-flow figures into single quarters by subtracting the previous year-to-date figure; Q4 cash flow comes from the 10-K total minus nine months.","Compute margins, growth vs the prior quarter and vs a year ago, EPS and its year-ago change, and free cash flow.","Build the comparison table (percent change for amounts, point difference for margins) and describe the trend in year-over-year revenue growth over the last 3–4 quarters (accelerating, slowing or steady, using a 1-point band)."],"example":"Example company: revenue this quarter 1,100, previous quarter 1,000, same quarter last year 880 (USD millions). Change vs prior = 1,100 ÷ 1,000 − 1 = +10%; vs a year ago = 1,100 ÷ 880 − 1 = +25%. Operating income 220, so operating margin = 220 ÷ 1,100 = 20%; a year ago it was 18%, a change of +2 points. Year-to-date CFO was 380 after six months and 600 after nine, so this quarter's CFO = 600 − 380 = 220; with capex of 50, FCF = 170.","read":["Growth vs a year ago removes most seasonal effects; growth vs the prior quarter can swing just because of the time of year.","Rising margins alongside rising revenue suggest the company keeps more from each extra sale; falling margins can mean higher costs or price cuts.","The trend line shows whether year-over-year growth is speeding up or slowing down across recent quarters.","Quarterly free cash flow can be lumpy (tax payments, big purchases), so look at several quarters before drawing conclusions."],"limits":["Q4 is computed by subtraction, so any restatement or difference between the 10-K and the 10-Qs ends up in Q4; Q4 EPS is usually blank because EPS cannot be subtracted.","Only US GAAP filings in US dollars are read; foreign companies that file 20-F reports and no 10-Q usually cannot be analysed here.","Percent changes are left blank when the earlier figure is zero or negative (for example after a loss), and a missing quarter means the 'prior quarter' is simply the previous one available.","One quarter is a short period; it does not tell you how the full year will turn out."]},"tr":{"question":"Şirketin son çeyreği bir önceki çeyrekle ve geçen yılın aynı çeyreğiyle karşılaştırıldığında nasıl?","idea":"Yıllık raporlar yılda bir gelir, ama ABD şirketleri her üç ayda bir 10-Q ile sonuç da açıklar. Bu analiz son dokuz çeyreğin gelirini, marjlarını, hisse başı kârını ve nakit akışını sıralar; sonra en yeni çeyreği bir öncekiyle ve bir yıl önceki aynı çeyrekle karşılaştırır. Birçok iş mevsimsel olduğu için geçen yılla karşılaştırma genelde daha adildir.","formulas":[{"name":"Gelir büyümesi","expr":"Önceki çeyreğe göre değişim = (Bu çeyreğin geliri ÷ Önceki çeyreğin geliri − 1) × 100; Geçen yıla göre değişim = (Bu çeyreğin geliri ÷ Geçen yılın aynı çeyreğinin geliri − 1) × 100","where":[["geçen yılın aynı çeyreği","350–380 gün önce biten çeyrek"],["Değişim","yüzde; önceki değer sıfır veya negatifse boş"]]},{"name":"Marjlar","expr":"Faaliyet marjı = Faaliyet kârı ÷ Gelir × 100; Net marj = Net kâr ÷ Gelir × 100","where":[["Faaliyet kârı, Net kâr","üç aylık çeyrek için (milyon USD)"],["Marj değişimi","bu çeyreğin marjı − bir yıl önceki marj, yüzde puan"]]},{"name":"Dördüncü çeyrek (türetilmiş)","expr":"4. çeyrek = Tüm mali yıl (10-K) − 1. çeyrek − 2. çeyrek − 3. çeyrek","where":[["4. çeyrek","şirketler 4. çeyrek için 10-Q vermez; bu yüzden hesaplanır ve “10-K − Q1–Q3” olarak işaretlenir"]]},{"name":"Çeyreklik nakit akışı","expr":"Çeyrek İNA = Şimdiki yılbaşından bugüne İNA − Önceki çeyrek sonundaki yılbaşından bugüne İNA; SNA = İNA − Yatırım harcaması","where":[["Yılbaşından bugüne","10-Q nakit akışını mali yıl başından itibaren raporlar (3, 6, 9 ay; 10-K 12 ay verir)"],["SNA (FCF)","serbest nakit akışı (milyon USD)"]]}],"data":[["Gelir","10-Q ve 10-K gelir tabloları, üç aylık dönemler (XBRL us-gaap:RevenueFromContractWithCustomerExcludingAssessedTax, yoksa …IncludingAssessedTax, Revenues, SalesRevenueNet veya RevenuesNetOfInterestExpense)"],["Faaliyet kârı ve net kâr","10-Q ve 10-K gelir tabloları (us-gaap:OperatingIncomeLoss; NetIncomeLoss, yoksa ProfitLoss)"],["Seyreltilmiş HBK","10-Q ve 10-K (us-gaap:EarningsPerShareDiluted), sadece raporlanan üç aylık rakamlar"],["İşletme nakit akışı ve yatırım harcaması","10-Q ve 10-K nakit akış tabloları, yılbaşından bugüne (us-gaap:NetCashProvidedByUsedInOperatingActivities; PaymentsToAcquirePropertyPlantAndEquipment, yoksa PaymentsToAcquireProductiveAssets)"]],"steps":["SEC raporlarından üç aylık gelir, faaliyet kârı ve net kâr verilerini oku (US GAAP, ABD doları) ve son dokuz çeyreği tut.","Bir mali yılın 10-K'sı ve üç 10-Q çeyreği varsa 4. çeyreği yıl toplamı eksi 1.–3. çeyrek olarak hesapla ve türetilmiş diye işaretle.","Yılbaşından bugüne nakit akışı rakamlarını, bir önceki yılbaşından bugüne rakamı çıkararak tek çeyreklere çevir; 4. çeyrek nakit akışı 10-K toplamı eksi dokuz aydan gelir.","Marjları, önceki çeyreğe ve geçen yıla göre büyümeyi, HBK'yı ve bir yıl önceye göre değişimini ve serbest nakit akışını hesapla.","Karşılaştırma tablosunu kur (tutarlarda yüzde değişim, marjlarda puan farkı) ve son 3–4 çeyrekte yıllık gelir büyümesinin eğilimini anlat (1 puanlık bantla hızlanıyor, yavaşlıyor veya yatay)."],"example":"Örnek şirket: bu çeyrek gelir 1.100, önceki çeyrek 1.000, geçen yılın aynı çeyreği 880 (milyon USD). Önceki çeyreğe göre = 1.100 ÷ 1.000 − 1 = +%10; geçen yıla göre = 1.100 ÷ 880 − 1 = +%25. Faaliyet kârı 220, yani faaliyet marjı = 220 ÷ 1.100 = %20; bir yıl önce %18'di, değişim +2 puan. Yılbaşından bugüne İNA altı ay sonunda 380, dokuz ay sonunda 600 idi; bu çeyreğin İNA'sı = 600 − 380 = 220; yatırım harcaması 50 ise SNA = 170.","read":["Geçen yıla göre büyüme mevsimsel etkilerin çoğunu ortadan kaldırır; önceki çeyreğe göre büyüme sadece yılın dönemi yüzünden dalgalanabilir.","Gelirle birlikte yükselen marjlar, şirketin her ek satıştan daha fazla tuttuğunu düşündürür; düşen marjlar daha yüksek maliyet veya fiyat indirimi anlamına gelebilir.","Eğilim, yıllık büyümenin son çeyreklerde hızlanıp hızlanmadığını gösterir.","Çeyreklik serbest nakit akışı dalgalı olabilir (vergi ödemeleri, büyük alımlar); sonuç çıkarmadan önce birkaç çeyreğe bak."],"limits":["4. çeyrek çıkarmayla hesaplanır; 10-K ile 10-Q'lar arasındaki her düzeltme veya fark 4. çeyreğe yansır. HBK çıkarılamadığı için 4. çeyrek HBK'si genelde boştur.","Sadece ABD doları cinsinden US GAAP raporları okunur; 20-F veren ve 10-Q vermeyen yabancı şirketler genelde burada analiz edilemez.","Önceki rakam sıfır veya negatifse (ör. zarar sonrası) yüzde değişimler boş kalır; eksik bir çeyrek varsa 'önceki çeyrek' mevcut olan bir önceki çeyrektir.","Bir çeyrek kısa bir dönemdir; tüm yılın nasıl geçeceğini söylemez."]},"es":{"question":"¿Cómo fue el último trimestre de la empresa comparado con el anterior y con el mismo trimestre de hace un año?","idea":"Los informes anuales llegan una vez al año, pero las empresas estadounidenses también publican resultados cada tres meses en un 10-Q. Este análisis ordena los últimos nueve trimestres de ingresos, márgenes, beneficio por acción y flujo de caja, y compara el trimestre más reciente con el anterior y con el mismo trimestre de un año antes. La comparación interanual suele ser más justa, porque muchos negocios son estacionales.","formulas":[{"name":"Crecimiento de ingresos","expr":"Cambio vs anterior = (Ingresos de este trimestre ÷ Ingresos del trimestre anterior − 1) × 100; Cambio interanual = (Ingresos de este trimestre ÷ Ingresos del mismo trimestre del año pasado − 1) × 100","where":[["mismo trimestre del año pasado","el trimestre que terminó 350–380 días antes"],["Cambio","porcentaje; vacío si el valor anterior es cero o negativo"]]},{"name":"Márgenes","expr":"Margen operativo = Resultado operativo ÷ Ingresos × 100; Margen neto = Beneficio neto ÷ Ingresos × 100","where":[["Resultado operativo, Beneficio neto","del trimestre de tres meses (millones de USD)"],["Cambio de margen","margen de este trimestre − margen de hace un año, en puntos porcentuales"]]},{"name":"Cuarto trimestre (derivado)","expr":"T4 = Año fiscal completo (10-K) − T1 − T2 − T3","where":[["T4","las empresas no presentan 10-Q del cuarto trimestre, así que se calcula y se marca “10-K − Q1–Q3”"]]},{"name":"Flujo de caja trimestral","expr":"FCO del trimestre = FCO acumulado en el año ahora − FCO acumulado al cierre del trimestre anterior; FCF = FCO − Capex","where":[["Acumulado en el año","un 10-Q publica el flujo de caja desde el inicio del año fiscal (3, 6, 9 meses; el 10-K da 12)"],["FCF","flujo de caja libre (millones de USD)"]]}],"data":[["Ingresos","cuentas de resultados del 10-Q y 10-K, periodos de tres meses (XBRL us-gaap:RevenueFromContractWithCustomerExcludingAssessedTax, o …IncludingAssessedTax, Revenues, SalesRevenueNet o RevenuesNetOfInterestExpense)"],["Resultado operativo y beneficio neto","cuentas de resultados del 10-Q y 10-K (us-gaap:OperatingIncomeLoss; NetIncomeLoss, o ProfitLoss)"],["BPA diluido","10-Q y 10-K (us-gaap:EarningsPerShareDiluted), solo cifras de tres meses publicadas"],["Flujo de caja operativo y capex","estados de flujos de efectivo del 10-Q y 10-K, acumulados en el año (us-gaap:NetCashProvidedByUsedInOperatingActivities; PaymentsToAcquirePropertyPlantAndEquipment, o PaymentsToAcquireProductiveAssets)"]],"steps":["Leer de los informes de la SEC los datos trimestrales de ingresos, resultado operativo y beneficio neto (US GAAP, dólares) y quedarse con los últimos nueve trimestres.","Cuando un año fiscal tiene un 10-K y tres trimestres en 10-Q, calcular el T4 como el total del año menos T1–T3 y marcarlo como derivado.","Convertir las cifras de flujo de caja acumuladas en trimestres sueltos restando la cifra acumulada anterior; el flujo del T4 sale del total del 10-K menos nueve meses.","Calcular márgenes, crecimiento frente al trimestre anterior y frente a hace un año, el BPA y su cambio interanual, y el flujo de caja libre.","Construir la tabla comparativa (cambio porcentual para importes, diferencia en puntos para márgenes) y describir la tendencia del crecimiento interanual de ingresos en los últimos 3–4 trimestres (acelerando, frenando o estable, con una banda de 1 punto)."],"example":"Empresa de ejemplo: ingresos de este trimestre 1.100, del trimestre anterior 1.000, del mismo trimestre del año pasado 880 (millones de USD). Cambio vs anterior = 1.100 ÷ 1.000 − 1 = +10 %; interanual = 1.100 ÷ 880 − 1 = +25 %. Resultado operativo 220, así que el margen operativo = 220 ÷ 1.100 = 20 %; hace un año era 18 %, un cambio de +2 puntos. El FCO acumulado era 380 tras seis meses y 600 tras nueve, así que el FCO de este trimestre = 600 − 380 = 220; con un capex de 50, FCF = 170.","read":["El crecimiento interanual elimina la mayor parte de los efectos estacionales; el crecimiento frente al trimestre anterior puede oscilar solo por la época del año.","Márgenes que suben junto con los ingresos sugieren que la empresa retiene más de cada venta adicional; márgenes que bajan pueden indicar costes más altos o rebajas de precio.","La tendencia muestra si el crecimiento interanual se acelera o se frena en los últimos trimestres.","El flujo de caja libre trimestral puede ser irregular (pagos de impuestos, grandes compras), así que mira varios trimestres antes de sacar conclusiones."],"limits":["El T4 se calcula por resta, así que cualquier reexpresión o diferencia entre el 10-K y los 10-Q acaba en el T4; el BPA del T4 suele quedar vacío porque el BPA no se puede restar.","Solo se leen informes US GAAP en dólares; las empresas extranjeras que presentan 20-F y no 10-Q normalmente no se pueden analizar aquí.","Los cambios porcentuales quedan vacíos cuando la cifra anterior es cero o negativa (por ejemplo, tras una pérdida), y si falta un trimestre, el 'trimestre anterior' es simplemente el anterior disponible.","Un trimestre es un periodo corto; no te dice cómo acabará el año completo."]}},{"id":"factors","number":28,"group":"risk","group_label":"Risk and credit","title":"Factor exposure (Fama–French + momentum)","next":["beta","portfolio","strategy_multi"],"en":{"question":"Does the stock behave like the market, like small or large companies, cheap or expensive ones, profitable ones, conservative investors or recent winners?","idea":"Researchers Eugene Fama and Kenneth French built daily return series of 'factor' portfolios, for example small companies minus big ones, or cheap (value) stocks minus expensive (growth) ones; a momentum factor (recent winners minus losers) is added. The app fits the stock's daily returns to these six series. Each loading says how strongly the stock moved with a factor, and the alpha is the part of the return none of them explains.","formulas":[{"name":"Six-factor regression (daily)","expr":"Rₛ − R_f = α + b₁·(Mkt−RF) + b₂·SMB + b₃·HML + b₄·RMW + b₅·CMA + b₆·MOM + ε","where":[["Rₛ","the stock's daily return from adjusted closes"],["R_f","daily one-month T-bill return from the French library"],["Mkt−RF","US stock market return minus the T-bill"],["SMB","size: small minus big companies"],["HML","value: high book-to-market (cheap) minus low (expensive)"],["RMW","profitability: robust minus weak"],["CMA","investment: conservative minus aggressive asset growth"],["MOM","momentum: recent winners minus losers"],["b","loadings, estimated by ordinary least squares; ε is what is left over"]]},{"name":"Annual alpha","expr":"α_year = ((1 + α)^252 − 1) × 100","where":[["α","daily intercept of the regression"],["252","trading days in a year"]]},{"name":"Significance","expr":"significant if |t| ≥ 2","where":[["t","loading ÷ its Newey–West standard error (robust to volatility clusters and autocorrelation)"]]},{"name":"Contribution of a factor","expr":"Contribution = b × Σ (factor's daily returns over the window) × 100","where":[["Contribution","approximate percentage points of return linked to that factor"]]}],"data":[["Stock prices","5 years of daily closes adjusted for splits and dividends, Yahoo Finance"],["Factor returns and the T-bill rate","Kenneth R. French Data Library (Dartmouth): Fama/French 5 factors (2x3) daily and the momentum factor daily, kept for 7 days"],["Window","the last 3 years ending on the library's last date, at least 250 overlapping trading days"]],"steps":["Download the daily factor files and the stock's adjusted closes.","Turn closes into daily returns and keep the days that also exist in the factor data, over the 3 years up to the factor file's last date.","Subtract the T-bill return to get the stock's excess return.","Run one regression on all six factors with an intercept and Newey–West t-statistics; report R².","Turn the daily alpha into a yearly figure, mark loadings with |t| ≥ 2 as significant and compute each factor's approximate contribution."],"example":"Example company: the regression gives a daily α of 0.0002 (0.02%), market loading 1.2, HML −0.5 with t = −3, and SMB −0.2 with t = −1. Annual alpha = (1.0002^252 − 1) × 100 ≈ 5.2%. The HML loading is significant (|t| ≥ 2) and negative, so the stock behaved like expensive (growth) stocks; SMB is not significant. If the market factor added up to +30% over the window, its contribution ≈ 1.2 × 30% = 36 percentage points.","read":["A market loading near 1 means the stock moved one-for-one with the market; above 1, more.","Signs: SMB positive like small firms, negative like large; HML positive like value, negative like growth; RMW positive like profitable firms; CMA positive like conservative investors, negative like aggressive growers; MOM positive like recent winners.","R² is the share of the daily excess return the six factors explain.","An alpha with |t| below 2 cannot be told apart from zero: the unexplained part may just be noise."],"limits":["With six factors tested at once, one can look significant by chance; loadings with |t| above 3 are more reliable (the app says so).","The factors describe the US market; foreign listings or thinly traded stocks can show smaller loadings because their prices are not set at the same moment.","The library is updated monthly with a lag, so the window ends before today, and past exposures can change.","The contribution split is approximate, and with daily noise the alpha is rarely distinguishable from zero; this is not a forecast or advice."]},"tr":{"question":"Hisse piyasa gibi mi, küçük ya da büyük şirketler gibi mi, ucuz ya da pahalı hisseler gibi mi, kârlı şirketler, temkinli yatırımcılar ya da son dönemin kazananları gibi mi davranıyor?","idea":"Araştırmacılar Eugene Fama ve Kenneth French, “faktör” portföylerinin günlük getiri serilerini kurdu; örneğin küçük şirketler eksi büyükler ya da ucuz (değer) hisseler eksi pahalı (büyüme) hisseler. Buna bir momentum faktörü (son dönemin kazananları eksi kaybedenleri) eklenir. Uygulama hissenin günlük getirilerini bu altı seriye göre açıklamaya çalışır. Her yük, hissenin bir faktörle ne kadar güçlü hareket ettiğini söyler; alfa ise hiçbirinin açıklamadığı getiri kısmıdır.","formulas":[{"name":"Altı faktörlü regresyon (günlük)","expr":"Rₕ − R_f = α + b₁·(Piy−RF) + b₂·SMB + b₃·HML + b₄·RMW + b₅·CMA + b₆·MOM + ε","where":[["Rₕ","düzeltilmiş kapanışlardan hissenin günlük getirisi"],["R_f","French kütüphanesinden günlük 1 aylık hazine bonosu getirisi"],["Piy−RF","ABD hisse piyasası getirisi eksi hazine bonosu"],["SMB","büyüklük: küçük eksi büyük şirketler"],["HML","değer: defter/piyasa değeri yüksek (ucuz) eksi düşük (pahalı)"],["RMW","kârlılık: güçlü eksi zayıf"],["CMA","yatırım: varlıklarını temkinli büyütenler eksi agresif büyütenler"],["MOM","momentum: son dönemin kazananları eksi kaybedenleri"],["b","yükler, en küçük kareler yöntemiyle tahmin edilir; ε geriye kalandır"]]},{"name":"Yıllık alfa","expr":"α_yıl = ((1 + α)^252 − 1) × 100","where":[["α","regresyonun günlük sabit terimi"],["252","bir yıldaki işlem günü"]]},{"name":"Anlamlılık","expr":"|t| ≥ 2 ise anlamlı","where":[["t","yük ÷ Newey–West standart hatası (oynaklık kümelenmesine ve otokorelasyona dayanıklı)"]]},{"name":"Bir faktörün katkısı","expr":"Katkı = b × Σ (dönem boyunca faktörün günlük getirileri) × 100","where":[["Katkı","o faktöre bağlanan yaklaşık getiri, yüzde puan"]]}],"data":[["Hisse fiyatları","bölünme ve temettüye göre düzeltilmiş 5 yıllık günlük kapanışlar, Yahoo Finance"],["Faktör getirileri ve hazine bonosu faizi","Kenneth R. French Data Library (Dartmouth): günlük Fama/French 5 faktör (2x3) ve günlük momentum faktörü, 7 gün saklanır"],["Dönem","kütüphanenin son tarihinde biten son 3 yıl, en az 250 ortak işlem günü"]],"steps":["Günlük faktör dosyalarını ve hissenin düzeltilmiş kapanışlarını indirir.","Kapanışları günlük getiriye çevirir ve faktör dosyasının son tarihine kadarki 3 yılda faktör verisinde de bulunan günleri tutar.","Hissenin fazla getirisini bulmak için hazine bonosu getirisini çıkarır.","Altı faktörün hepsiyle, sabit terimli ve Newey–West t istatistikli tek bir regresyon kurar; R²'yi raporlar.","Günlük alfayı yıllığa çevirir, |t| ≥ 2 olan yükleri anlamlı işaretler ve her faktörün yaklaşık katkısını hesaplar."],"example":"Örnek şirket: regresyon günlük α = 0,0002 (%0,02), piyasa yükü 1,2, t = −3 ile HML −0,5 ve t = −1 ile SMB −0,2 veriyor. Yıllık alfa = (1,0002^252 − 1) × 100 ≈ %5,2. HML yükü anlamlı (|t| ≥ 2) ve negatif; yani hisse pahalı (büyüme) hisseleri gibi davranmış. SMB anlamlı değil. Piyasa faktörü dönem boyunca toplam +%30 getirdiyse katkısı ≈ 1,2 × %30 = 36 yüzde puan.","read":["Piyasa yükü 1'e yakınsa hisse piyasayla bire bir hareket etmiştir; 1'in üstündeyse daha fazla.","İşaretler: SMB pozitif küçük şirketler gibi, negatif büyükler gibi; HML pozitif değer, negatif büyüme hissesi gibi; RMW pozitif kârlı şirketler gibi; CMA pozitif temkinli yatırım yapanlar, negatif agresif büyüyenler gibi; MOM pozitif son dönemin kazananları gibi.","R², günlük fazla getirinin altı faktörle açıklanan payıdır.","|t| 2'nin altındaki bir alfa sıfırdan ayırt edilemez: açıklanamayan kısım yalnızca gürültü olabilir."],"limits":["Altı faktör birden test edildiği için biri şans eseri anlamlı görünebilir; |t| 3'ün üstündeki yükler daha güvenilirdir (uygulama da söyler).","Faktörler ABD piyasasını anlatır; yabancı hisselerde veya az işlem gören hisselerde fiyatlar aynı anda oluşmadığı için yükler küçük çıkabilir.","Kütüphane aylık ve gecikmeli güncellenir; dönem bugünden önce biter ve geçmişteki eğilimler değişebilir.","Katkı ayrıştırması yaklaşıktır; günlük gürültü yüzünden alfa nadiren sıfırdan ayırt edilir. Tahmin veya tavsiye değildir."]},"es":{"question":"¿Se comporta la acción como el mercado, como empresas pequeñas o grandes, baratas o caras, rentables, inversores prudentes o ganadoras recientes?","idea":"Los investigadores Eugene Fama y Kenneth French construyeron series diarias de rentabilidad de carteras de “factores”, por ejemplo empresas pequeñas menos grandes, o acciones baratas (valor) menos caras (crecimiento); se añade un factor de momentum (ganadoras recientes menos perdedoras). La app ajusta las rentabilidades diarias de la acción a esas seis series. Cada carga indica con cuánta fuerza se movió la acción con un factor, y la alfa es la parte de la rentabilidad que ninguno explica.","formulas":[{"name":"Regresión de seis factores (diaria)","expr":"Rₐ − R_f = α + b₁·(Mkt−RF) + b₂·SMB + b₃·HML + b₄·RMW + b₅·CMA + b₆·MOM + ε","where":[["Rₐ","rentabilidad diaria de la acción con cierres ajustados"],["R_f","rentabilidad diaria de la letra del Tesoro a un mes, de la biblioteca de French"],["Mkt−RF","rentabilidad del mercado de acciones de EE. UU. menos la letra del Tesoro"],["SMB","tamaño: empresas pequeñas menos grandes"],["HML","valor: alto valor contable/mercado (baratas) menos bajo (caras)"],["RMW","rentabilidad: robusta menos débil"],["CMA","inversión: crecimiento de activos prudente menos agresivo"],["MOM","momentum: ganadoras recientes menos perdedoras"],["b","cargas, estimadas por mínimos cuadrados ordinarios; ε es lo que sobra"]]},{"name":"Alfa anual","expr":"α_año = ((1 + α)^252 − 1) × 100","where":[["α","término constante diario de la regresión"],["252","días hábiles de un año"]]},{"name":"Significación","expr":"significativa si |t| ≥ 2","where":[["t","carga ÷ su error estándar de Newey–West (robusto a la agrupación de volatilidad y la autocorrelación)"]]},{"name":"Contribución de un factor","expr":"Contribución = b × Σ (rentabilidades diarias del factor en la ventana) × 100","where":[["Contribución","puntos porcentuales aproximados de rentabilidad ligados a ese factor"]]}],"data":[["Precios de la acción","5 años de cierres diarios ajustados por splits y dividendos, Yahoo Finance"],["Rentabilidades de los factores y tipo de la letra del Tesoro","Kenneth R. French Data Library (Dartmouth): 5 factores de Fama/French (2x3) diarios y factor de momentum diario, guardados 7 días"],["Ventana","los últimos 3 años hasta la última fecha de la biblioteca, al menos 250 días hábiles en común"]],"steps":["Descarga los archivos diarios de factores y los cierres ajustados de la acción.","Convierte los cierres en rentabilidades diarias y se queda con los días que también están en los datos de factores, en los 3 años hasta la última fecha del archivo.","Resta la rentabilidad de la letra del Tesoro para obtener la rentabilidad en exceso de la acción.","Hace una regresión con los seis factores, con término constante y estadísticos t de Newey–West; informa el R².","Pasa la alfa diaria a anual, marca como significativas las cargas con |t| ≥ 2 y calcula la contribución aproximada de cada factor."],"example":"Empresa de ejemplo: la regresión da una α diaria de 0,0002 (0,02%), carga de mercado 1,2, HML −0,5 con t = −3 y SMB −0,2 con t = −1. Alfa anual = (1,0002^252 − 1) × 100 ≈ 5,2%. La carga HML es significativa (|t| ≥ 2) y negativa, así que la acción se comportó como las acciones caras (de crecimiento); SMB no es significativa. Si el factor de mercado sumó +30% en la ventana, su contribución ≈ 1,2 × 30% = 36 puntos porcentuales.","read":["Una carga de mercado cercana a 1 significa que la acción se movió uno a uno con el mercado; por encima de 1, más.","Signos: SMB positiva como empresas pequeñas, negativa como grandes; HML positiva como valor, negativa como crecimiento; RMW positiva como empresas rentables; CMA positiva como inversores prudentes, negativa como empresas de crecimiento agresivo; MOM positiva como ganadoras recientes.","El R² es la parte de la rentabilidad diaria en exceso que explican los seis factores.","Una alfa con |t| menor que 2 no se distingue de cero: la parte no explicada puede ser solo ruido."],"limits":["Al probar seis factores a la vez, uno puede parecer significativo por azar; las cargas con |t| mayor que 3 son más fiables (la app lo dice).","Los factores describen el mercado de EE. UU.; las acciones extranjeras o poco negociadas pueden mostrar cargas menores porque sus precios no se forman en el mismo momento.","La biblioteca se actualiza cada mes con retraso, así que la ventana termina antes de hoy, y las exposiciones pasadas pueden cambiar.","El reparto de contribuciones es aproximado y, con el ruido diario, la alfa rara vez se distingue de cero; no es una previsión ni un consejo."]}},{"id":"ito","number":29,"group":"quant","group_label":"Quant","title":"Brownian motion and Itô’s lemma","next":["options_lab","uncertainty","implied_move"],"en":{"question":"Does the stock move like the textbook random-walk model, and what range of prices does that model give for the coming months?","idea":"The standard model of a stock price is geometric Brownian motion: each day the price gets a random percentage shock of typical size σ (volatility). Itô's lemma, a rule of calculus for random paths, shows that volatility itself drags down compound growth: the typical path grows about σ²/2 a year slower than the average daily return suggests. The analysis fits the model to 3 years of prices, checks that prediction and other assumptions against the data, and draws the model's range of future prices.","formulas":[{"name":"Fitting the model","expr":"rₜ = ln(Pₜ ÷ Pₜ₋₁);   σ = sd(rₜ) × √252;   g = mean(rₜ) × 252;   μ = g + σ²/2","where":[["rₜ","daily log return from adjusted closes, last 3 years"],["σ","annual volatility"],["g","annual log (compound) growth rate"],["252","trading days a year (365 for markets open every day, such as crypto)"]]},{"name":"Itô's prediction (volatility drag)","expr":"mean(simple return) × 252 − mean(log return) × 252 ≈ σ²/2","where":[["simple return","Pₜ ÷ Pₜ₋₁ − 1"],["σ²/2","half the annual variance: the gap between the average return and the compound return"]]},{"name":"Range of prices at the horizon","expr":"S_T = S₀ × exp((μ − σ²/2) × T + σ × √T × z);   mean = S₀ × e^(μT)","where":[["S₀","last adjusted close"],["T","horizon in years (1, 3, 6, 12 or 24 months)"],["z","0 for the median, ±0.674 for the 25th/75th, ±1.645 for the 5th/95th percentile"],["μ","0 by default (\"zero edge\"); the historical μ only if you switch it on"]]},{"name":"Random-walk check (variance ratio)","expr":"VR(k) = Var(k-day log return) ÷ (k × Var(1-day log return))","where":[["k","5, 21 and 63 trading days"],["VR","the model predicts 1; below 1 suggests mean reversion, above 1 trending; |z| ≥ 2 rejects"]]}],"data":[["Prices","daily adjusted closing prices (Yahoo Finance; latest close cross-checked with Stooq): last 3 years to fit the model, up to 10 years for the out-of-sample range test; any Yahoo symbol, including ETFs and BIST .IS stocks"],["Interest rates","US Treasury yield curve matched to 1, 3, 6 and 12 months (else one risk-free rate for all), only for the Black–Scholes rows"],["Your settings","horizon (1, 3, 6, 12 or 24 months) and whether to use the historical drift"]],"steps":["Compute daily log returns over the last 3 years and estimate σ and the growth rate.","Compare the measured gap between average simple and average log returns with Itô's σ²/2.","Draw the model's price range at the horizon from the closed-form formula and check it with 10,000 simulated paths (fixed seed).","Test the assumptions: variance ratios, skewness, fat tails (kurtosis, Jarque–Bera, days beyond 3σ and 4σ), volatility clustering.","Out of sample: for each separate 1-month period in the past, fit σ on the previous year only and count how often the move landed inside the 50% and 90% ranges.","Price at-the-money options with Black–Scholes using the historical σ, as theory to compare with market prices."],"example":"Example company: its daily log returns have a standard deviation of 1.26%, so σ ≈ 1.26% × √252 ≈ 20% a year and σ²/2 = 0.2² ÷ 2 = 2%. If the average simple return is 10% a year and the average log return 8%, the gap of 2 points matches Itô. With S₀ = 100, μ = 0 and T = 1 year: median = 100 × e^(−0.02) ≈ 98.0; 95th percentile = 100 × e^(−0.02 + 0.20 × 1.645) ≈ 136.2; 5th percentile = 100 × e^(−0.02 − 0.329) ≈ 70.5. Mean = 100 × e^0 = 100.","read":["Higher σ means a wider price range and a bigger gap between the mean and the median.","If the data's gap is close to σ²/2, the drag prediction holds; a large difference hints that returns are not normal.","Rejected tests show where the model breaks; fat tails are the usual one: extreme days happen far more often than the normal curve says.","In the out-of-sample test, a 90% range that caught clearly less than 90% means the model understated risk."],"limits":["This is a model test, not a forecast; the range assumes constant volatility and normal log returns, which real stocks violate.","A 3-year average return is very noisy (standard error about σ ÷ √3), which is why the drift is 0 unless you switch the historical drift on.","Black–Scholes values here use historical σ, no dividends and European exercise; they are theory, not market quotes. For BIST stocks prices are in lira but US Treasury rates are used.","Fat tails and volatility clustering mean real crashes are larger and more frequent than the model's 5th percentile suggests."]},"tr":{"question":"Hisse ders kitabındaki rastgele yürüyüş modeli gibi hareket ediyor mu ve bu model önümüzdeki aylar için hangi fiyat aralığını veriyor?","idea":"Hisse fiyatının standart modeli geometrik Brown hareketidir: fiyat her gün tipik büyüklüğü σ (oynaklık) olan rastgele bir yüzde şoku alır. Rastgele yollar için bir analiz kuralı olan Itô lemması (Itô’s lemma), oynaklığın bileşik büyümeyi aşağı çektiğini gösterir: tipik yol, ortalama günlük getirinin düşündürdüğünden yılda yaklaşık σ²/2 daha yavaş büyür. Analiz modeli 3 yıllık fiyatlara uydurur, bu öngörüyü ve diğer varsayımları veriyle test eder ve modelin gelecekteki fiyat aralığını çizer.","formulas":[{"name":"Modeli uydurmak","expr":"rₜ = ln(Pₜ ÷ Pₜ₋₁);   σ = ss(rₜ) × √252;   g = ort(rₜ) × 252;   μ = g + σ²/2","where":[["rₜ","düzeltilmiş kapanışlardan günlük log getiri, son 3 yıl"],["σ","yıllık oynaklık"],["g","yıllık log (bileşik) büyüme oranı"],["252","yıldaki işlem günü (kripto gibi her gün açık piyasalarda 365)"]]},{"name":"Itô’nun öngörüsü (volatilite sürtünmesi)","expr":"ort(basit getiri) × 252 − ort(log getiri) × 252 ≈ σ²/2","where":[["basit getiri","Pₜ ÷ Pₜ₋₁ − 1"],["σ²/2","yıllık varyansın yarısı: ortalama getiri ile bileşik getiri arasındaki fark"]]},{"name":"Vade sonundaki fiyat aralığı","expr":"S_T = S₀ × exp((μ − σ²/2) × T + σ × √T × z);   ortalama = S₀ × e^(μT)","where":[["S₀","son düzeltilmiş kapanış"],["T","yıl cinsinden vade (1, 3, 6, 12 veya 24 ay)"],["z","medyan için 0, 25./75. yüzdelik için ±0,674, 5./95. yüzdelik için ±1,645"],["μ","varsayılan 0 (\"sıfır avantaj\"); yalnızca açarsan geçmiş μ"]]},{"name":"Rastgele yürüyüş kontrolü (varyans oranı)","expr":"VO(k) = Var(k günlük log getiri) ÷ (k × Var(1 günlük log getiri))","where":[["k","5, 21 ve 63 işlem günü"],["VO","model 1 öngörür; 1’in altı ortalamaya dönüşe, üstü trende işaret eder; |z| ≥ 2 reddeder"]]}],"data":[["Fiyatlar","günlük düzeltilmiş kapanışlar (Yahoo Finance; son kapanış Stooq ile karşılaştırılır): modeli uydurmak için son 3 yıl, örneklem dışı aralık testi için 10 yıla kadar; ETF’ler ve BIST .IS hisseleri dahil her Yahoo kodu"],["Faizler","1, 3, 6 ve 12 aya eşlenen ABD Hazine getiri eğrisi (yoksa tüm vadeler için tek risksiz faiz); yalnızca Black–Scholes satırları için"],["Ayarların","vade (1, 3, 6, 12 veya 24 ay) ve geçmiş sürüklenmenin kullanılıp kullanılmayacağı"]],"steps":["Son 3 yılın günlük log getirilerini hesapla; σ’yı ve büyüme oranını tahmin et.","Ortalama basit getiri ile ortalama log getiri arasındaki ölçülen farkı Itô’nun σ²/2’siyle karşılaştır.","Vade sonundaki model fiyat aralığını kapalı formülden çiz ve 10.000 simüle yolla (sabit tohum) kontrol et.","Varsayımları test et: varyans oranları, çarpıklık, kalın kuyruklar (basıklık, Jarque–Bera, 3σ ve 4σ ötesindeki günler), oynaklık kümelenmesi.","Örneklem dışı: geçmişteki her ayrı 1 aylık dönem için σ’yı yalnızca önceki yıldan hesapla ve hareketin %50 ve %90 aralıklarına ne sıklıkla düştüğünü say.","Başa baş opsiyonları geçmiş σ ile Black–Scholes’la fiyatla; piyasa fiyatlarıyla karşılaştırmak için teorik değer."],"example":"Örnek şirket: günlük log getirilerinin standart sapması %1,26; σ ≈ %1,26 × √252 ≈ yıllık %20 ve σ²/2 = 0,2² ÷ 2 = %2. Ortalama basit getiri yılda %10, ortalama log getiri %8 ise 2 puanlık fark Itô ile uyumlu. S₀ = 100, μ = 0 ve T = 1 yıl için: medyan = 100 × e^(−0,02) ≈ 98,0; 95. yüzdelik = 100 × e^(−0,02 + 0,20 × 1,645) ≈ 136,2; 5. yüzdelik = 100 × e^(−0,02 − 0,329) ≈ 70,5. Ortalama = 100 × e^0 = 100.","read":["Yüksek σ daha geniş bir fiyat aralığı ve ortalama ile medyan arasında daha büyük bir fark demektir.","Verideki fark σ²/2’ye yakınsa sürtünme öngörüsü tutuyor; büyük bir fark getirilerin normal dağılmadığına işaret eder.","Reddedilen testler modelin nerede bozulduğunu gösterir; genelde kalın kuyruklar: uç günler normal eğrinin söylediğinden çok daha sık olur.","Örneklem dışı testte %90 aralığı belirgin şekilde %90’dan azını yakaladıysa model riski küçümsemiş demektir."],"limits":["Bu bir model testidir, tahmin değil; aralık sabit oynaklık ve normal log getiri varsayar, gerçek hisseler buna uymaz.","3 yıllık ortalama getiri çok gürültülüdür (standart hatası yaklaşık σ ÷ √3); bu yüzden geçmiş sürüklenmeyi açmadıkça μ = 0’dır.","Buradaki Black–Scholes değerleri geçmiş σ kullanır, temettü yok ve Avrupa tipi kullanım varsayılır; teoridir, piyasa kotasyonu değildir. BIST hisselerinde fiyatlar TL’dir ama ABD Hazine faizleri kullanılır.","Kalın kuyruklar ve oynaklık kümelenmesi, gerçek çöküşlerin modelin 5. yüzdeliğinin düşündürdüğünden daha büyük ve sık olduğu anlamına gelir."]},"es":{"question":"¿Se mueve la acción como el modelo de paseo aleatorio de los libros, y qué rango de precios da ese modelo para los próximos meses?","idea":"El modelo estándar del precio de una acción es el movimiento browniano geométrico: cada día el precio recibe un choque porcentual aleatorio de tamaño típico σ (volatilidad). El lema de Itô (Itô’s lemma), una regla de cálculo para trayectorias aleatorias, muestra que la propia volatilidad frena el crecimiento compuesto: la trayectoria típica crece unos σ²/2 al año menos de lo que sugiere la rentabilidad diaria media. El análisis ajusta el modelo a 3 años de precios, contrasta esa predicción y otros supuestos con los datos y dibuja el rango de precios futuros del modelo.","formulas":[{"name":"Ajuste del modelo","expr":"rₜ = ln(Pₜ ÷ Pₜ₋₁);   σ = dt(rₜ) × √252;   g = media(rₜ) × 252;   μ = g + σ²/2","where":[["rₜ","rentabilidad logarítmica diaria con cierres ajustados, últimos 3 años"],["σ","volatilidad anual"],["g","tasa anual de crecimiento logarítmico (compuesto)"],["252","sesiones al año (365 en mercados abiertos todos los días, como las cripto)"]]},{"name":"Predicción de Itô (lastre de la volatilidad)","expr":"media(rentabilidad simple) × 252 − media(rentabilidad log) × 252 ≈ σ²/2","where":[["rentabilidad simple","Pₜ ÷ Pₜ₋₁ − 1"],["σ²/2","la mitad de la varianza anual: la diferencia entre la rentabilidad media y la compuesta"]]},{"name":"Rango de precios al horizonte","expr":"S_T = S₀ × exp((μ − σ²/2) × T + σ × √T × z);   media = S₀ × e^(μT)","where":[["S₀","último cierre ajustado"],["T","horizonte en años (1, 3, 6, 12 o 24 meses)"],["z","0 para la mediana, ±0,674 para los percentiles 25/75, ±1,645 para los percentiles 5/95"],["μ","0 por defecto (\"sin ventaja\"); el μ histórico solo si lo activas"]]},{"name":"Control del paseo aleatorio (ratio de varianzas)","expr":"RV(k) = Var(rentabilidad log a k días) ÷ (k × Var(rentabilidad log a 1 día))","where":[["k","5, 21 y 63 sesiones"],["RV","el modelo predice 1; por debajo de 1 sugiere reversión a la media, por encima tendencia; |z| ≥ 2 rechaza"]]}],"data":[["Precios","cierres diarios ajustados (Yahoo Finance; el último cierre se contrasta con Stooq): últimos 3 años para ajustar el modelo, hasta 10 años para la prueba de rangos fuera de muestra; cualquier símbolo de Yahoo, incluidos ETF y acciones .IS de BIST"],["Tipos de interés","curva de rendimientos del Tesoro de EE. UU. a 1, 3, 6 y 12 meses (si no, un único tipo libre de riesgo); solo para las filas de Black–Scholes"],["Tus ajustes","horizonte (1, 3, 6, 12 o 24 meses) y si se usa la deriva histórica"]],"steps":["Calcula las rentabilidades logarítmicas diarias de los últimos 3 años y estima σ y la tasa de crecimiento.","Compara la diferencia medida entre la rentabilidad simple media y la logarítmica media con el σ²/2 de Itô.","Dibuja el rango de precios del modelo al horizonte con la fórmula cerrada y compruébalo con 10.000 trayectorias simuladas (semilla fija).","Contrasta los supuestos: ratios de varianzas, asimetría, colas gruesas (curtosis, Jarque–Bera, días más allá de 3σ y 4σ), agrupamiento de volatilidad.","Fuera de muestra: para cada mes separado del pasado, estima σ solo con el año anterior y cuenta cuántas veces el movimiento cayó dentro de los rangos del 50 % y del 90 %.","Valora opciones at-the-money con Black–Scholes y la σ histórica, como teoría para comparar con los precios de mercado."],"example":"Empresa de ejemplo: sus rentabilidades logarítmicas diarias tienen una desviación típica del 1,26 %, así que σ ≈ 1,26 % × √252 ≈ 20 % anual y σ²/2 = 0,2² ÷ 2 = 2 %. Si la rentabilidad simple media es 10 % anual y la logarítmica 8 %, la diferencia de 2 puntos encaja con Itô. Con S₀ = 100, μ = 0 y T = 1 año: mediana = 100 × e^(−0,02) ≈ 98,0; percentil 95 = 100 × e^(−0,02 + 0,20 × 1,645) ≈ 136,2; percentil 5 = 100 × e^(−0,02 − 0,329) ≈ 70,5. Media = 100 × e^0 = 100.","read":["Una σ más alta significa un rango de precios más ancho y más distancia entre la media y la mediana.","Si la diferencia en los datos está cerca de σ²/2, la predicción del lastre se cumple; una diferencia grande sugiere que las rentabilidades no son normales.","Las pruebas rechazadas muestran dónde falla el modelo; lo habitual son las colas gruesas: los días extremos ocurren mucho más a menudo de lo que dice la curva normal.","En la prueba fuera de muestra, si el rango del 90 % capturó claramente menos del 90 %, el modelo subestimó el riesgo."],"limits":["Es una prueba del modelo, no una previsión; el rango supone volatilidad constante y rentabilidades logarítmicas normales, algo que las acciones reales no cumplen.","Una rentabilidad media de 3 años es muy ruidosa (error típico de unos σ ÷ √3); por eso la deriva es 0 salvo que actives la deriva histórica.","Los valores de Black–Scholes usan la σ histórica, sin dividendos y con ejercicio europeo; son teoría, no cotizaciones. En acciones de BIST los precios están en liras pero se usan tipos del Tesoro de EE. UU.","Las colas gruesas y el agrupamiento de volatilidad hacen que los desplomes reales sean mayores y más frecuentes de lo que sugiere el percentil 5 del modelo."]}},{"id":"options_lab","number":30,"group":"quant","group_label":"Quant","title":"Options lab: Black–Scholes, the smile and stochastic volatility (live)","next":["implied_move","ito","uncertainty"],"en":{"question":"How are this stock's options priced right now, and how far is that from the simple Black–Scholes model?","idea":"A call option is the right to buy a share at a fixed strike price until the expiry date; a put is the right to sell. Black–Scholes prices them assuming the stock's volatility (how much it swings) never changes. Turning the formula around on a real market price gives the implied volatility, and when every strike gets its own implied volatility the values form a curve called the smile, which shows the market does not believe in one constant volatility. The Heston model lets volatility itself move randomly and is fitted to the whole smile.","formulas":[{"name":"Black–Scholes price (with dividend yield)","expr":"C = S·e^(−qT)·N(d₁) − K·e^(−rT)·N(d₂);  P = K·e^(−rT)·N(−d₂) − S·e^(−qT)·N(−d₁)","where":[["d₁","[ln(S ÷ K) + (r − q + σ²/2)·T] ÷ (σ·√T)"],["d₂","d₁ − σ·√T"],["S","share price implied by the option quotes, $"],["K","strike price, $"],["T","time to expiry in years (calendar time ÷ 365 days, up to the market close on the expiry day)"],["r","risk-free rate: US Treasury yield for that maturity, continuous compounding"],["q","dividend yield = annual dividend ÷ price"],["σ","volatility, % a year"],["N","the standard normal cumulative probability"]]},{"name":"Implied volatility","expr":"find σ so that e^(−rT)·[F·N(d₁) − K·N(d₂)] = market mid price (Black-76, a call; puts likewise)","where":[["F","forward price from put–call parity: F = K + e^(rT)·(C − P), at the strikes where call and put are closest"],["mid price","(bid + ask) ÷ 2, or the last trade when there is no quote"]]},{"name":"Heston model (stochastic volatility)","expr":"dS = (r − q)·S·dt + √v·S·dW₁;  dv = κ·(θ − v)·dt + ξ·√v·dW₂;  corr(dW₁, dW₂) = ρ","where":[["v","variance (volatility squared); v₀ is today's value, so √v₀ is today's volatility"],["θ","long-run variance that v drifts back to"],["κ","speed of that return (half-life = ln 2 ÷ κ years)"],["ξ","volatility of volatility: how much v itself jumps around; it bends the smile's wings"],["ρ","correlation between price moves and volatility moves; negative means falls come with higher volatility"]]},{"name":"Heston fit error","expr":"RMSE = √(mean of (model implied vol − market implied vol)²)","where":[["RMSE","typical error in volatility points; compared with the error of one flat Black–Scholes volatility"]]}],"data":[["Option quotes (bid, ask, last, strike, open interest) for the chosen and several other expiries","Yahoo Finance option chains, free, about 15 minutes delayed"],["Stock price and annual dividend","Yahoo Finance quote"],["Risk-free rate","US Treasury yield curve, interpolated to each expiry (fallback: 10-year yield)"],["Realised volatility over 21, 63 and 252 days","2 years of daily adjusted closes"],["Your choices","call or put (default call), expiry (default: nearest 30 days), strike (default: nearest the forward), Heston on or off (default on)"]],"steps":["Take a live snapshot: the forward from put–call parity, each option's implied volatility from its mid price, the smile from out-of-the-money options (puts below the forward, calls above), the at-the-money volatility and the term structure across expiries.","Price the chosen contract several ways and compare with the market mid: Black–Scholes at the at-the-money volatility, Black–Scholes at the 21-day realised volatility, an American binomial tree (early exercise), Monte Carlo with 100,000 paths, and Heston.","Fit Heston to every expiry with at least 5 usable strikes (two-sided quotes, not deep in the wings; very short expiries left out when longer ones exist) by minimising volatility errors.","Show the Greeks (delta, gamma, vega, theta, rho), the smile against flat Black–Scholes and Heston, the risk-neutral chance of finishing in the money and the ±1σ move S·σ·√T.","Write findings such as implied minus realised volatility, the 25-delta risk reversal (skew) and how much better Heston fits than one volatility."],"example":"Example company: S = 100, K = 100, T = 0.25 years, r = 4%, q = 0, σ = 20%. d₁ = (ln 1 + (0.04 + 0.02) × 0.25) ÷ (0.2 × 0.5) = 0.015 ÷ 0.1 = 0.15; d₂ = 0.15 − 0.10 = 0.05. N(0.15) ≈ 0.560 and N(0.05) ≈ 0.520. Call = 100 × 0.560 − 100 × e^(−0.01) × 0.520 ≈ 55.96 − 51.47 ≈ 4.49. If the market mid for this call were 5.00 instead, the implied volatility would be about 22.6%: the market is paying for more swing than 20%.","read":["Implied volatility is the market's price of future swings; compare it with realised volatility (implied minus realised is a rough gauge of the extra paid for protection).","If Black–Scholes were exactly right, the smile would be a flat line; a smile that is higher on the left (negative risk reversal) means downside protection costs more.","Heston in words: √v₀ is today's volatility, √θ where it tends to settle, κ how fast it gets there, ξ how wild volatility itself is, ρ whether falls and rising volatility go together. A much lower RMSE than flat Black–Scholes means the stochastic-volatility story fits the prices better.","Risk-neutral probabilities and model values are pricing quantities, not forecasts of where the stock will go."],"limits":["Quotes are free Yahoo data about 15 minutes delayed and, outside regular hours, from the last session; wide spreads make implied volatilities noisy. It runs on live data only.","Black–Scholes is exact for European options, but US stock options are American (they can be exercised early); the app handles this with a tree and an approximate early-exercise adjustment.","Heston cannot produce the steep smiles of the last days before expiry, the Feller condition (2κθ ≥ ξ²) is often violated in market fits, and with only one expiry κ is fixed at 2.","The online showcase does not use a real stock: it uses a fictional stock (DEMO, price 100, rate 4%, dividend 1%) whose option prices come from a known Heston model (v₀ 0.05, κ 1.8, θ 0.06, ξ 0.7, ρ −0.65), so the fit should find those numbers again. Real stocks need the installed app. Not advice."]},"tr":{"question":"Bu hissenin opsiyonları şu anda nasıl fiyatlanıyor ve bu, basit Black–Scholes modelinden ne kadar uzak?","idea":"Alım opsiyonu, bir hisseyi vade tarihine kadar sabit bir kullanım fiyatından satın alma hakkıdır; satım opsiyonu ise satma hakkı. Black–Scholes bunları, hissenin oynaklığının (ne kadar dalgalandığının) hiç değişmediğini varsayarak fiyatlar. Formülü gerçek bir piyasa fiyatına göre tersine çözmek örtük oynaklığı (ima edilen oynaklık) verir. Her kullanım fiyatı kendi örtük oynaklığını alınca değerler gülümseme denen bir eğri oluşturur; bu da piyasanın tek ve sabit bir oynaklığa inanmadığını gösterir. Heston modeli oynaklığın kendisinin de rastgele hareket etmesine izin verir ve gülümsemenin tamamına uydurulur.","formulas":[{"name":"Black–Scholes fiyatı (temettü verimiyle)","expr":"C = S·e^(−qT)·N(d₁) − K·e^(−rT)·N(d₂);  P = K·e^(−rT)·N(−d₂) − S·e^(−qT)·N(−d₁)","where":[["d₁","[ln(S ÷ K) + (r − q + σ²/2)·T] ÷ (σ·√T)"],["d₂","d₁ − σ·√T"],["S","opsiyon kotasyonlarının ima ettiği hisse fiyatı, $"],["K","kullanım fiyatı, $"],["T","vadeye kalan süre, yıl (takvim süresi ÷ 365 gün, vade günündeki piyasa kapanışına kadar)"],["r","risksiz faiz: o vadeye denk gelen ABD Hazine faizi, sürekli bileşik"],["q","temettü verimi = yıllık temettü ÷ fiyat"],["σ","oynaklık, yıllık %"],["N","standart normal birikimli olasılık"]]},{"name":"Örtük oynaklık","expr":"e^(−rT)·[F·N(d₁) − K·N(d₂)] = piyasa orta fiyatı olacak σ bulunur (Black-76, alım opsiyonu; satım için benzeri)","where":[["F","alım–satım paritesinden forward fiyat: F = K + e^(rT)·(C − P), alım ve satımın en yakın olduğu kullanım fiyatlarında"],["orta fiyat","(alış + satış) ÷ 2; kotasyon yoksa son işlem fiyatı"]]},{"name":"Heston modeli (stokastik oynaklık)","expr":"dS = (r − q)·S·dt + √v·S·dW₁;  dv = κ·(θ − v)·dt + ξ·√v·dW₂;  kor(dW₁, dW₂) = ρ","where":[["v","varyans (oynaklığın karesi); v₀ bugünkü değeridir, yani √v₀ bugünkü oynaklık"],["θ","v'nin döndüğü uzun vadeli varyans"],["κ","bu dönüşün hızı (yarı ömür = ln 2 ÷ κ yıl)"],["ξ","oynaklığın oynaklığı: v'nin kendisinin ne kadar dalgalandığı; gülümsemenin kanatlarını büker"],["ρ","fiyat hareketleriyle oynaklık hareketleri arasındaki korelasyon; negatifse düşüşler yüksek oynaklıkla gelir"]]},{"name":"Heston uyum hatası","expr":"RMSE = √(ortalama (model örtük oynaklığı − piyasa örtük oynaklığı)²)","where":[["RMSE","oynaklık puanı cinsinden tipik hata; tek ve sabit Black–Scholes oynaklığının hatasıyla karşılaştırılır"]]}],"data":[["Seçilen ve birkaç başka vadenin opsiyon kotasyonları (alış, satış, son fiyat, kullanım fiyatı, açık pozisyon)","Yahoo Finance opsiyon zincirleri, ücretsiz, yaklaşık 15 dakika gecikmeli"],["Hisse fiyatı ve yıllık temettü","Yahoo Finance kotasyonu"],["Risksiz faiz","ABD Hazine getiri eğrisi, her vadeye göre ara değer (yedek: 10 yıllık faiz)"],["21, 63 ve 252 günlük gerçekleşen oynaklık","2 yıllık günlük düzeltilmiş kapanışlar"],["Senin seçimlerin","alım veya satım (varsayılan alım), vade (varsayılan: 30 güne en yakın), kullanım fiyatı (varsayılan: forward'a en yakın), Heston açık/kapalı (varsayılan açık)"]],"steps":["Canlı bir anlık görüntü alır: alım–satım paritesinden forward, her opsiyonun orta fiyatından örtük oynaklığı, başa göre para dışındaki opsiyonlardan gülümseme (forward altında satımlar, üstünde alımlar), başa baş oynaklık ve vadeler boyunca vade yapısı.","Seçilen kontratı birkaç yolla fiyatlar ve piyasa orta fiyatıyla karşılaştırır: başa baş oynaklıkla Black–Scholes, 21 günlük gerçekleşen oynaklıkla Black–Scholes, Amerikan binom ağacı (erken kullanım), 100.000 yollu Monte Carlo ve Heston.","Heston'u, en az 5 kullanılabilir kullanım fiyatı olan her vadeye (iki yönlü kotasyon, kanatların çok ucunda olmayan; daha uzunları varsa çok kısa vadeler dışarıda) oynaklık hatalarını en aza indirerek uydurur.","Yunanları (delta, gamma, vega, theta, rho), sabit Black–Scholes ve Heston'a karşı gülümsemeyi, riske nötr para içinde bitme olasılığını ve ±1σ hareketi S·σ·√T'yi gösterir.","Örtük eksi gerçekleşen oynaklık, 25-delta risk reversal (çarpıklık) ve Heston'un tek oynaklıktan ne kadar iyi uyduğu gibi bulgular yazar."],"example":"Örnek şirket: S = 100, K = 100, T = 0,25 yıl, r = %4, q = 0, σ = %20. d₁ = (ln 1 + (0,04 + 0,02) × 0,25) ÷ (0,2 × 0,5) = 0,015 ÷ 0,1 = 0,15; d₂ = 0,15 − 0,10 = 0,05. N(0,15) ≈ 0,560 ve N(0,05) ≈ 0,520. Alım = 100 × 0,560 − 100 × e^(−0,01) × 0,520 ≈ 55,96 − 51,47 ≈ 4,49. Bu alım opsiyonunun piyasa orta fiyatı 5,00 olsaydı örtük oynaklık yaklaşık %22,6 olurdu: piyasa %20'den fazla dalgalanmaya para ödüyor.","read":["Örtük oynaklık, piyasanın gelecekteki dalgalanmaya biçtiği fiyattır; gerçekleşen oynaklıkla karşılaştır (örtük eksi gerçekleşen, korunma için ödenen fazlanın kaba bir göstergesidir).","Black–Scholes tam doğru olsaydı gülümseme düz bir çizgi olurdu; solda daha yüksek bir gülümseme (negatif risk reversal) düşüş korumasının daha pahalı olduğunu gösterir.","Heston'u sözle anlatırsak: √v₀ bugünkü oynaklık, √θ yerleşme eğiliminde olduğu seviye, κ oraya ne kadar hızlı gittiği, ξ oynaklığın kendisinin ne kadar çılgın olduğu, ρ düşüşlerle artan oynaklığın birlikte gelip gelmediği. Sabit Black–Scholes'tan çok daha düşük bir RMSE, stokastik oynaklık hikâyesinin fiyatlara daha iyi uyduğu anlamına gelir.","Riske nötr olasılıklar ve model değerleri fiyatlama büyüklükleridir; hissenin nereye gideceğinin tahmini değildir."],"limits":["Kotasyonlar yaklaşık 15 dakika gecikmeli ücretsiz Yahoo verisidir ve normal seans dışında son seansa aittir; geniş alış-satış farkları örtük oynaklıkları gürültülü yapar. Yalnızca canlı veriyle çalışır.","Black–Scholes Avrupa tipi opsiyonlar için kesindir, ama ABD hisse opsiyonları Amerikan tipidir (erken kullanılabilir); uygulama bunu bir ağaçla ve yaklaşık bir erken kullanım düzeltmesiyle ele alır.","Heston vadeden önceki son günlerin dik gülümsemelerini üretemez, piyasa kalibrasyonlarında Feller koşulu (2κθ ≥ ξ²) sık sık sağlanmaz ve tek bir vade varsa κ 2'ye sabitlenir.","Çevrimiçi vitrin gerçek bir hisse kullanmaz: opsiyon fiyatları bilinen bir Heston modelinden (v₀ 0,05, κ 1,8, θ 0,06, ξ 0,7, ρ −0,65) gelen kurgusal bir hisse (DEMO, fiyat 100, faiz %4, temettü %1) kullanır; bu yüzden uyum o sayıları yeniden bulmalıdır. Gerçek hisseler için kurulu uygulama gerekir. Tavsiye değildir."]},"es":{"question":"¿Cómo se valoran ahora mismo las opciones de esta acción, y cuánto se alejan del modelo sencillo de Black–Scholes?","idea":"Una opción de compra (call) es el derecho a comprar una acción a un precio de ejercicio fijo hasta el vencimiento; una opción de venta (put) es el derecho a venderla. Black–Scholes las valora suponiendo que la volatilidad de la acción (cuánto oscila) nunca cambia. Despejar la fórmula a partir de un precio real de mercado da la volatilidad implícita, y cuando cada precio de ejercicio tiene la suya los valores forman una curva llamada sonrisa, que muestra que el mercado no cree en una volatilidad única y constante. El modelo de Heston deja que la propia volatilidad se mueva al azar y se ajusta a toda la sonrisa.","formulas":[{"name":"Precio de Black–Scholes (con rendimiento por dividendo)","expr":"C = S·e^(−qT)·N(d₁) − K·e^(−rT)·N(d₂);  P = K·e^(−rT)·N(−d₂) − S·e^(−qT)·N(−d₁)","where":[["d₁","[ln(S ÷ K) + (r − q + σ²/2)·T] ÷ (σ·√T)"],["d₂","d₁ − σ·√T"],["S","precio de la acción implícito en las cotizaciones de opciones, $"],["K","precio de ejercicio, $"],["T","tiempo hasta el vencimiento en años (tiempo natural ÷ 365 días, hasta el cierre del mercado el día del vencimiento)"],["r","tipo sin riesgo: rendimiento del Tesoro de EE. UU. para ese plazo, capitalización continua"],["q","rendimiento por dividendo = dividendo anual ÷ precio"],["σ","volatilidad, % anual"],["N","probabilidad acumulada de la normal estándar"]]},{"name":"Volatilidad implícita","expr":"hallar σ tal que e^(−rT)·[F·N(d₁) − K·N(d₂)] = precio medio de mercado (Black-76, una call; las puts igual)","where":[["F","precio a plazo según la paridad put–call: F = K + e^(rT)·(C − P), en los precios de ejercicio donde call y put están más cerca"],["precio medio","(compra + venta) ÷ 2, o la última operación si no hay cotización"]]},{"name":"Modelo de Heston (volatilidad estocástica)","expr":"dS = (r − q)·S·dt + √v·S·dW₁;  dv = κ·(θ − v)·dt + ξ·√v·dW₂;  corr(dW₁, dW₂) = ρ","where":[["v","varianza (volatilidad al cuadrado); v₀ es su valor de hoy, así que √v₀ es la volatilidad actual"],["θ","varianza de largo plazo a la que vuelve v"],["κ","velocidad de esa vuelta (vida media = ln 2 ÷ κ años)"],["ξ","volatilidad de la volatilidad: cuánto oscila la propia v; curva las alas de la sonrisa"],["ρ","correlación entre los movimientos del precio y los de la volatilidad; negativa significa que las caídas llegan con más volatilidad"]]},{"name":"Error de ajuste de Heston","expr":"RMSE = √(media de (vol. implícita del modelo − vol. implícita del mercado)²)","where":[["RMSE","error típico en puntos de volatilidad; se compara con el error de una sola volatilidad plana de Black–Scholes"]]}],"data":[["Cotizaciones de opciones (compra, venta, última, precio de ejercicio, interés abierto) del vencimiento elegido y de varios más","cadenas de opciones de Yahoo Finance, gratuitas, con unos 15 minutos de retraso"],["Precio de la acción y dividendo anual","cotización de Yahoo Finance"],["Tipo sin riesgo","curva de tipos del Tesoro de EE. UU., interpolada a cada vencimiento (alternativa: rendimiento a 10 años)"],["Volatilidad realizada a 21, 63 y 252 días","2 años de cierres diarios ajustados"],["Tus elecciones","call o put (call por defecto), vencimiento (por defecto el más cercano a 30 días), precio de ejercicio (por defecto el más cercano al precio a plazo), Heston sí/no (sí por defecto)"]],"steps":["Toma una instantánea en vivo: el precio a plazo según la paridad put–call, la volatilidad implícita de cada opción a partir de su precio medio, la sonrisa con opciones fuera del dinero (puts por debajo del precio a plazo, calls por encima), la volatilidad en el dinero y la estructura temporal entre vencimientos.","Valora el contrato elegido de varias formas y lo compara con el precio medio de mercado: Black–Scholes con la volatilidad en el dinero, Black–Scholes con la volatilidad realizada de 21 días, un árbol binomial americano (ejercicio anticipado), Monte Carlo con 100.000 trayectorias y Heston.","Ajusta Heston a cada vencimiento con al menos 5 precios de ejercicio útiles (cotización a dos lados, no muy en las alas; los vencimientos muy cortos se dejan fuera si hay otros más largos) minimizando los errores de volatilidad.","Muestra las griegas (delta, gamma, vega, theta, rho), la sonrisa frente a Black–Scholes plano y Heston, la probabilidad neutral al riesgo de terminar en el dinero y el movimiento de ±1σ S·σ·√T.","Escribe conclusiones como la volatilidad implícita menos la realizada, el risk reversal de 25 delta (sesgo) y cuánto mejor ajusta Heston que una sola volatilidad."],"example":"Empresa de ejemplo: S = 100, K = 100, T = 0,25 años, r = 4%, q = 0, σ = 20%. d₁ = (ln 1 + (0,04 + 0,02) × 0,25) ÷ (0,2 × 0,5) = 0,015 ÷ 0,1 = 0,15; d₂ = 0,15 − 0,10 = 0,05. N(0,15) ≈ 0,560 y N(0,05) ≈ 0,520. Call = 100 × 0,560 − 100 × e^(−0,01) × 0,520 ≈ 55,96 − 51,47 ≈ 4,49. Si el precio medio de mercado de esta call fuera 5,00, la volatilidad implícita sería de un 22,6%: el mercado paga por más oscilación que un 20%.","read":["La volatilidad implícita es el precio que pone el mercado a las oscilaciones futuras; compárala con la realizada (implícita menos realizada es una medida aproximada de lo que se paga de más por protegerse).","Si Black–Scholes fuera exacto, la sonrisa sería una línea plana; una sonrisa más alta a la izquierda (risk reversal negativo) indica que la protección contra caídas cuesta más.","Heston en palabras: √v₀ es la volatilidad de hoy, √θ donde tiende a asentarse, κ lo rápido que llega, ξ lo agitada que es la propia volatilidad, ρ si las caídas y el aumento de volatilidad van juntos. Un RMSE mucho menor que el de Black–Scholes plano significa que la idea de volatilidad estocástica encaja mejor con los precios.","Las probabilidades neutrales al riesgo y los valores de los modelos son magnitudes de valoración, no previsiones de adónde irá la acción."],"limits":["Las cotizaciones son datos gratuitos de Yahoo con unos 15 minutos de retraso y, fuera del horario normal, de la última sesión; los diferenciales amplios hacen ruidosas las volatilidades implícitas. Solo funciona con datos en vivo.","Black–Scholes es exacto para opciones europeas, pero las opciones sobre acciones de EE. UU. son americanas (se pueden ejercer antes); la app lo trata con un árbol y un ajuste aproximado por ejercicio anticipado.","Heston no puede reproducir las sonrisas empinadas de los últimos días antes del vencimiento, la condición de Feller (2κθ ≥ ξ²) a menudo no se cumple en los ajustes de mercado y, con un solo vencimiento, κ se fija en 2.","La demo en línea no usa una acción real: usa una acción ficticia (DEMO, precio 100, tipo 4%, dividendo 1%) cuyos precios de opciones salen de un modelo de Heston conocido (v₀ 0,05, κ 1,8, θ 0,06, ξ 0,7, ρ −0,65), así que el ajuste debería volver a encontrar esos números. Para acciones reales hace falta la app instalada. No es un consejo."]}}],"path_intro":{"en":"No finance background is needed. Go through the steps in order; each one builds on the one before. Tap an analysis to read how it works.","tr":"Finans bilgisi gerekmiyor. Adımları sırayla izle; her adım bir öncekinin üstüne kurulur. Nasıl çalıştığını okumak için bir analize dokun.","es":"No necesitas saber de finanzas. Sigue los pasos en orden; cada uno se apoya en el anterior. Toca un análisis para leer cómo funciona."},"path":[{"title":{"en":"1. The company’s own numbers","tr":"1. Şirketin kendi rakamları","es":"1. Las cifras de la propia empresa"},"text":{"en":"Start with what the company reports: how sales and profit move each quarter, where the return on equity comes from, how fast cash comes back and whether profit is backed by cash.","tr":"Şirketin açıkladıklarıyla başla: satışlar ve kâr her çeyrek nasıl değişiyor, özkaynak kârlılığı nereden geliyor, nakit ne kadar hızlı geri dönüyor ve kâr nakitle destekleniyor mu?","es":"Empieza por lo que publica la empresa: cómo cambian las ventas y el beneficio cada trimestre, de dónde sale la rentabilidad sobre el patrimonio, qué tan rápido vuelve el efectivo y si el beneficio está respaldado por caja."},"ids":["quarterly","dupont","cash_cycle","earnings_quality","cycle_compare"]},{"title":{"en":"2. Is it creating value?","tr":"2. Değer yaratıyor mu?","es":"2. ¿Está creando valor?"},"text":{"en":"Next, ask whether the business earns more on its capital than that capital costs, what it does with its cash, which divisions drive it and how its financial health score moves.","tr":"Sonra şunu sor: işletme sermayesinden, o sermayenin maliyetinden fazla kazanıyor mu? Nakdini ne yapıyor, hangi bölümler sürüklüyor ve finansal sağlık puanı nasıl değişiyor?","es":"Después pregúntate si el negocio gana con su capital más de lo que ese capital cuesta, qué hace con su efectivo, qué divisiones lo impulsan y cómo cambia su puntuación de salud financiera."},"ids":["roic_wacc","capital_allocation","segments","piotroski"]},{"title":{"en":"3. What could it be worth?","tr":"3. Ne kadar değerli olabilir?","es":"3. ¿Cuánto podría valer?"},"text":{"en":"Valuation turns those numbers into a range of values. Each method depends on assumptions you can change; comparing methods shows how wide the range really is.","tr":"Değerleme bu rakamları bir değer aralığına çevirir. Her yöntem değiştirebileceğin varsayımlara dayanır; yöntemleri karşılaştırmak aralığın gerçekte ne kadar geniş olduğunu gösterir.","es":"La valoración convierte esas cifras en un rango de valores. Cada método depende de supuestos que puedes cambiar; comparar métodos muestra lo amplio que es realmente el rango."},"ids":["dcf","reverse_dcf","scenarios","comps","valuation_summary","bank_value","deal_case"]},{"title":{"en":"4. How risky is it?","tr":"4. Ne kadar riskli?","es":"4. ¿Qué tan arriesgada es?"},"text":{"en":"Look at debt and credit, how the share moves with the market, how it behaved in past crises, the range of possible outcomes and who is buying or selling.","tr":"Borca ve kredi durumuna, hissenin piyasayla nasıl hareket ettiğine, geçmiş krizlerde nasıl davrandığına, olası sonuçların aralığına ve kimin alıp sattığına bak.","es":"Mira la deuda y el crédito, cómo se mueve la acción con el mercado, cómo se comportó en crisis pasadas, el rango de resultados posibles y quién compra o vende."},"ids":["credit_altman","beta","crisis","uncertainty","insiders","holders"]},{"title":{"en":"5. Markets, statistics and models","tr":"5. Piyasalar, istatistik ve modeller","es":"5. Mercados, estadística y modelos"},"text":{"en":"Finally, test ideas on prices: market reactions, honest strategy tests, portfolios, factor models, random-walk models and options. These need the most care with statistics.","tr":"Son olarak fikirleri fiyatlar üzerinde test et: piyasa tepkileri, dürüst strateji testleri, portföyler, faktör modelleri, rastgele yürüyüş modelleri ve opsiyonlar. İstatistik açısından en çok dikkat isteyenler bunlar.","es":"Por último, prueba ideas con precios: reacciones del mercado, pruebas honestas de estrategias, carteras, modelos de factores, modelos de paseo aleatorio y opciones. Son los que más cuidado estadístico exigen."},"ids":["event_study","implied_move","strategy_multi","portfolio","factors","ito","options_lab","turkey_fx"]}],"sources_intro":{"en":"QuantEdge uses free, public sources only. Every result lists the sources it used and, for company figures, links to the filing they came from.","tr":"QuantEdge yalnızca ücretsiz ve herkese açık kaynakları kullanır. Her sonuç kullandığı kaynakları listeler; şirket rakamlarında ise rakamın alındığı belgeye bağlantı verir.","es":"QuantEdge solo usa fuentes gratuitas y públicas. Cada resultado indica las fuentes que usó y, en las cifras de empresa, enlaza al documento del que salen."},"sources":[{"name":{"en":"SEC filings: 10-K, 10-Q and XBRL","tr":"SEC belgeleri: 10-K, 10-Q ve XBRL","es":"Documentos de la SEC: 10-K, 10-Q y XBRL"},"what":{"en":"US companies file an annual report (10-K) and quarterly reports (10-Q) with the SEC, the US market regulator. Inside them, every figure is tagged in a machine-readable format called XBRL, so a program can read revenue or debt without guessing. Foreign companies file a 20-F instead.","tr":"ABD şirketleri, ABD piyasa düzenleyicisi SEC’e yıllık rapor (10-K) ve çeyreklik raporlar (10-Q) verir. Bu raporlardaki her rakam XBRL denen, bilgisayarın okuyabildiği bir biçimde etiketlenir; böylece bir program geliri ya da borcu tahmin etmeden okuyabilir. Yabancı şirketler bunun yerine 20-F verir.","es":"Las empresas de EE. UU. presentan a la SEC, el regulador del mercado, un informe anual (10-K) e informes trimestrales (10-Q). Dentro, cada cifra está etiquetada en un formato legible por máquina llamado XBRL, así un programa puede leer los ingresos o la deuda sin adivinar. Las empresas extranjeras presentan un 20-F."},"used":{"en":"Revenue, profit, cash flow, balance-sheet items and share counts in almost every analysis; SEC “frames” give industry medians.","tr":"Neredeyse her analizde gelir, kâr, nakit akışı, bilanço kalemleri ve hisse sayısı; SEC “frames” verisi sektör medyanlarını verir.","es":"Ingresos, beneficio, flujo de caja, partidas del balance y número de acciones en casi todos los análisis; los “frames” de la SEC dan medianas del sector."},"care":{"en":"Companies sometimes use different tags for the same item, restate past years or change fiscal year-ends. QuantEdge tries several tags and says when a figure is missing, but check important numbers against the filing.","tr":"Şirketler aynı kalem için bazen farklı etiketler kullanır, geçmiş yılları yeniden düzenler ya da mali yıl sonunu değiştirir. QuantEdge birkaç etiketi dener ve eksik rakamı söyler; yine de önemli rakamları belgenin kendisiyle karşılaştır.","es":"A veces las empresas usan etiquetas distintas para la misma partida, reexpresan años anteriores o cambian el cierre del ejercicio. QuantEdge prueba varias etiquetas y avisa cuando falta una cifra, pero contrasta las cifras importantes con el documento."}},{"name":{"en":"SEC filings: 8-K, Form 4 and 13F","tr":"SEC belgeleri: 8-K, Form 4 ve 13F","es":"Documentos de la SEC: 8-K, Form 4 y 13F"},"what":{"en":"An 8-K announces an important event, such as quarterly results. A Form 4 reports a trade by a company insider (a director or officer). A 13F lists the US shares held by a large investment manager at the end of a quarter; QuantEdge reads Yahoo Finance’s free summary of these filings (top institutions and funds) rather than every 13F.","tr":"8-K, çeyrek sonuçları gibi önemli bir olayı duyurur. Form 4, şirket içinden birinin (yönetici ya da yönetim kurulu üyesi) yaptığı alım satımı bildirir. 13F, büyük bir yatırım yöneticisinin çeyrek sonunda elinde tuttuğu ABD hisselerini listeler; QuantEdge her 13F’yi tek tek okumak yerine Yahoo Finance’in bu belgelerden derlediği ücretsiz özeti (en büyük kurumlar ve fonlar) kullanır.","es":"Un 8-K anuncia un hecho importante, como los resultados trimestrales. Un Form 4 informa de una operación de un directivo o consejero de la empresa. Un 13F enumera las acciones de EE. UU. que tiene un gran gestor de inversiones al cierre de un trimestre; QuantEdge usa el resumen gratuito de Yahoo Finance de estos documentos (principales instituciones y fondos) en lugar de leer cada 13F."},"used":{"en":"Earnings dates for the event study and the earnings move, insider trades, institutional ownership.","tr":"Olay çalışması ve bilanço hareketi için sonuç açıklama tarihleri, içeriden işlemler, kurumsal sahiplik.","es":"Fechas de resultados para el estudio de eventos y el movimiento por resultados, operaciones de directivos y propiedad institucional."},"care":{"en":"13F data arrives up to 45 days after the quarter ends and shows long US positions only. Many insider sales are planned in advance or used to pay taxes.","tr":"13F verisi çeyrek bittikten 45 güne kadar sonra gelir ve yalnızca ABD hisselerindeki alım (uzun) pozisyonlarını gösterir. İçeriden satışların çoğu önceden planlanmıştır ya da vergi ödemek içindir.","es":"Los datos 13F llegan hasta 45 días después del cierre del trimestre y solo muestran posiciones largas en EE. UU. Muchas ventas de directivos están planificadas de antemano o sirven para pagar impuestos."}},{"name":{"en":"Share prices","tr":"Hisse fiyatları","es":"Precios de las acciones"},"what":{"en":"Daily historical prices from Yahoo Finance, adjusted for stock splits and dividends so that returns are comparable over time. If Yahoo cannot be reached, the last saved copy is used (marked as old), and for US shares Stooq daily closes as a last resort. Borsa İstanbul shares use the .IS suffix.","tr":"Yahoo Finance’ten günlük geçmiş fiyatlar; getiriler zaman içinde karşılaştırılabilsin diye hisse bölünmeleri ve temettülere göre düzeltilmiştir. Yahoo’ya ulaşılamazsa son kaydedilen kopya (eski olarak işaretlenir), ABD hisseleri için en son çare olarak Stooq günlük kapanışları kullanılır. Borsa İstanbul hisseleri .IS uzantısıyla gelir.","es":"Precios diarios históricos de Yahoo Finance, ajustados por desdoblamientos y dividendos para que las rentabilidades sean comparables en el tiempo. Si no se puede acceder a Yahoo, se usa la última copia guardada (marcada como antigua) y, para acciones de EE. UU., como último recurso los cierres diarios de Stooq. Las acciones de Borsa İstanbul usan el sufijo .IS."},"used":{"en":"Returns, beta, volatility, event studies, crises, portfolios, strategy tests, market values and multiples.","tr":"Getiriler, beta, oynaklık, olay çalışmaları, krizler, portföyler, strateji testleri, piyasa değerleri ve çarpanlar.","es":"Rentabilidades, beta, volatilidad, estudios de eventos, crisis, carteras, pruebas de estrategias, valores de mercado y múltiplos."},"care":{"en":"Companies that were delisted are missing (survivorship bias), so tests on today’s companies look better than reality. Yahoo is a free source without guarantees.","tr":"Borsadan çıkmış şirketler listede yoktur (hayatta kalma yanılgısı); bu yüzden bugünkü şirketlerle yapılan testler gerçekte olduğundan daha iyi görünür. Yahoo garantisi olmayan ücretsiz bir kaynaktır.","es":"Faltan las empresas que dejaron de cotizar (sesgo de supervivencia), así que las pruebas con las empresas de hoy parecen mejores que la realidad. Yahoo es una fuente gratuita sin garantías."}},{"name":{"en":"Option prices","tr":"Opsiyon fiyatları","es":"Precios de opciones"},"what":{"en":"Listed option chains (calls and puts for each strike and expiry) from Yahoo Finance, delayed by about 15 minutes. The Cboe white paper gives the VIX method.","tr":"Yahoo Finance’ten borsada işlem gören opsiyon zincirleri (her kullanım fiyatı ve vade için alım ve satım opsiyonları), yaklaşık 15 dakika gecikmeli. VIX yöntemi Cboe’nin teknik belgesinden gelir.","es":"Cadenas de opciones cotizadas (calls y puts por precio de ejercicio y vencimiento) de Yahoo Finance, con unos 15 minutos de retraso. El método del VIX sale del documento técnico de Cboe."},"used":{"en":"The Options tab, the earnings move priced by options and the VIX card. The online showcase uses a fictional stock instead.","tr":"Opsiyonlar sekmesi, opsiyonlara yansıyan bilanço hareketi ve VIX kartı. Çevrimiçi vitrin bunun yerine kurgusal bir hisse kullanır.","es":"La pestaña Opciones, el movimiento por resultados que descuentan las opciones y la tarjeta del VIX. La vitrina en línea usa en su lugar una acción ficticia."},"care":{"en":"Quotes for far-from-the-money or rarely traded options can be stale or have wide bid–ask spreads; those strikes are filtered or flagged.","tr":"Kullanım fiyatı uzak ya da az işlem gören opsiyonların fiyatları eski kalmış olabilir veya alış–satış farkı geniş olabilir; bu kullanım fiyatları elenir ya da işaretlenir.","es":"Las cotizaciones de opciones muy alejadas del dinero o poco negociadas pueden estar desfasadas o tener diferenciales amplios; esos precios de ejercicio se filtran o se marcan."}},{"name":{"en":"Interest rates","tr":"Faiz oranları","es":"Tipos de interés"},"what":{"en":"US Treasury yields from FRED (the St. Louis Fed’s free database) and the US Treasury, plus corporate bond spreads from FRED. The 10-year Treasury yield is the usual “risk-free” rate.","tr":"FRED’den (St. Louis Fed’in ücretsiz veritabanı) ve ABD Hazinesi’nden ABD devlet tahvili getirileri, ayrıca FRED’den şirket tahvili getiri farkları (spread). 10 yıllık ABD tahvil getirisi genelde “risksiz” faiz olarak kullanılır.","es":"Rentabilidades de los bonos del Tesoro de EE. UU. de FRED (la base de datos gratuita de la Fed de San Luis) y del Tesoro, además de diferenciales de bonos corporativos de FRED. La rentabilidad del bono a 10 años es el tipo “sin riesgo” habitual."},"used":{"en":"The risk-free rate in CAPM, WACC and DCF, the cost of debt, Sharpe ratios and option pricing.","tr":"CAPM, WACC ve DCF’deki risksiz faiz, borç maliyeti, Sharpe oranları ve opsiyon fiyatlama.","es":"El tipo sin riesgo en CAPM, WACC y DCF, el coste de la deuda, los ratios de Sharpe y la valoración de opciones."},"care":{"en":"Rates change every day, and a small change in the discount rate can move a valuation a lot. You can type your own rate.","tr":"Faizler her gün değişir ve iskonto oranındaki küçük bir değişiklik değerlemeyi çok oynatabilir. İstersen kendi oranını yazabilirsin.","es":"Los tipos cambian cada día y un pequeño cambio en la tasa de descuento puede mover mucho una valoración. Puedes escribir tu propio tipo."}},{"name":{"en":"Research datasets","tr":"Akademik veri setleri","es":"Bases de datos académicas"},"what":{"en":"Professor Aswath Damodaran’s datasets (NYU Stern): the implied equity risk premium and industry betas, costs of capital and margins. The Kenneth French Data Library (Dartmouth): the Fama–French factor and momentum returns.","tr":"Profesör Aswath Damodaran’ın veri setleri (NYU Stern): örtük hisse senedi risk primi, sektör betaları, sermaye maliyetleri ve marjlar. Kenneth French Veri Kütüphanesi (Dartmouth): Fama–French faktör ve momentum getirileri.","es":"Las bases de datos del profesor Aswath Damodaran (NYU Stern): la prima de riesgo implícita de la renta variable y las betas, costes de capital y márgenes por sector. La Kenneth French Data Library (Dartmouth): los rendimientos de los factores Fama–French y de momentum."},"used":{"en":"Equity risk premium and industry comparisons in valuation and WACC; the factor exposure analysis.","tr":"Değerleme ve WACC’ta hisse senedi risk primi ve sektör karşılaştırmaları; faktör maruziyeti analizi.","es":"Prima de riesgo y comparaciones sectoriales en valoración y WACC; el análisis de exposición a factores."},"care":{"en":"They are updated once a year or once a month, so they can lag the market. Industry averages hide large differences between companies.","tr":"Yılda ya da ayda bir güncellenirler, bu yüzden piyasanın gerisinde kalabilirler. Sektör ortalamaları şirketler arasındaki büyük farkları gizler.","es":"Se actualizan una vez al año o al mes, así que pueden ir por detrás del mercado. Los promedios sectoriales esconden grandes diferencias entre empresas."}},{"name":{"en":"Turkey: TCMB EVDS and KAP","tr":"Türkiye: TCMB EVDS ve KAP","es":"Turquía: TCMB EVDS y KAP"},"what":{"en":"The Central Bank of the Republic of Türkiye’s data service (EVDS) for exchange rates and inflation, used with your own free key. KAP, the Public Disclosure Platform, holds the annual reports of Borsa İstanbul companies.","tr":"Türkiye Cumhuriyet Merkez Bankası’nın veri servisi (EVDS): döviz kurları ve enflasyon için, kendi ücretsiz anahtarınla kullanılır. KAP (Kamuyu Aydınlatma Platformu) Borsa İstanbul şirketlerinin faaliyet raporlarını barındırır.","es":"El servicio de datos del Banco Central de la República de Turquía (EVDS) para tipos de cambio e inflación, con tu propia clave gratuita. KAP, la plataforma pública de información, guarda los informes anuales de las empresas de Borsa İstanbul."},"used":{"en":"The Turkey lira-versus-dollar returns analysis.","tr":"Türkiye için lira ve dolar bazında getiri analizi.","es":"El análisis de Turquía de rentabilidades en liras frente a dólares."},"care":{"en":"With high inflation, returns in lira and in dollars can tell very different stories; always compare both.","tr":"Yüksek enflasyonda lira ve dolar bazındaki getiriler çok farklı hikâyeler anlatabilir; ikisini her zaman birlikte karşılaştır.","es":"Con inflación alta, las rentabilidades en liras y en dólares pueden contar historias muy distintas; compara siempre ambas."}},{"name":{"en":"You","tr":"Sen","es":"Tú"},"what":{"en":"Your assumptions (growth, margins, discount rate), your thesis and risks, and any price you type yourself.","tr":"Senin varsayımların (büyüme, marjlar, iskonto oranı), tezin ve riskler, ayrıca kendin yazdığın fiyatlar.","es":"Tus supuestos (crecimiento, márgenes, tasa de descuento), tu tesis y riesgos, y cualquier precio que escribas tú."},"used":{"en":"Valuation inputs and every note you write.","tr":"Değerleme girdileri ve yazdığın her not.","es":"Las entradas de valoración y cada nota que escribes."},"care":{"en":"These are always labelled as yours, never as official data. Be ready to explain each assumption.","tr":"Bunlar her zaman senin girdin olarak etiketlenir, asla resmî veri olarak gösterilmez. Her varsayımı açıklayabilmeye hazır ol.","es":"Siempre se marcan como tuyos, nunca como datos oficiales. Prepárate para explicar cada supuesto."}}]};
